// Chapter Summaries - Format: "Book Chapter": "Summary Text"
const chapterSummaries = {
    // ===========================
    // OLD TESTAMENT
    // ===========================
    "Genesis 1": "ஆதியிலே தேவன் வானத்தையும் பூமியையும் சிருஷ்டித்தார். ஆறு நாட்களில் வெளிச்சம், ஆகாயவிரிவு, தரை, தாவரங்கள், சூரியன் சந்திரன் நட்சத்திரங்கள், மீன்கள், பறவைகள், மிருகங்கள் ஆகியவற்றை உண்டாக்கி, தம்முடைய சாயலாக மனுஷனை ஆணும் பெண்ணுமாகச் சிருஷ்டித்தார். தாம் உண்டாக்கின யாவையும் தேவன் பார்த்தபோது, அது மிகவும் நன்றாயிருந்தது.",
    "Genesis 2": "ஏழாம் நாளில் தேவன் தம்முடைய கிரியைகளை முடித்து ஓய்ந்திருந்து, அந்த நாளை ஆசீர்வதித்துப் பரிசுத்தமாக்கினார். கர்த்தராகிய தேவன் மண்ணினால் மனுஷனை உருவாக்கி, ஜீவசுவாசத்தை ஊதி, ஏதேன் தோட்டத்தில் வைத்தார்; நன்மை தீமை அறியத்தக்க விருட்சத்தின் கனியைப் புசிக்க வேண்டாம் என்று கட்டளையிட்டார். ஆதாமின் விலா எலும்பிலிருந்து ஸ்திரீயை உண்டாக்கி அவனிடத்தில் கொண்டுவந்தார்.",
    "Genesis 3": "சர்ப்பத்தின் வஞ்சகத்தால் ஸ்திரீ விலக்கப்பட்ட கனியைப் புசித்து, தன் புருஷனுக்கும் கொடுத்தாள்; அவர்கள் கண்கள் திறக்கப்பட்டு, தாங்கள் நிர்வாணிகள் என்று அறிந்தார்கள். தேவன் சர்ப்பத்தையும் பூமியையும் சபித்து, ஸ்திரீயின் வித்து சர்ப்பத்தின் தலையை நசுக்கும் என்று வாக்குரைத்தார். ஆதாமும் ஏவாளும் ஏதேன் தோட்டத்திலிருந்து துரத்திவிடப்பட்டார்கள்.",
    "Genesis 4": "ஆதாமின் குமாரர்களாகிய காயீனும் ஆபேலும் கர்த்தருக்குக் காணிக்கை செலுத்தினார்கள்; கர்த்தர் ஆபேலின் காணிக்கையை அங்கீகரித்தார். பொறாமையடைந்த காயீன் தன் சகோதரன் ஆபேலைக் கொலை செய்தான்; அதனால் பூமியில் நிலையற்று அலைகிறவனாகச் சபிக்கப்பட்டான். பின்பு ஆதாமுக்குச் சேத் பிறந்தான்; அக்காலத்தில் மனுஷர் கர்த்தருடைய நாமத்தைத் தொழுதுகொள்ளத் தொடங்கினார்கள்.",
    "Genesis 5": "ஆதாம் முதல் நோவா வரையிலான தலைமுறைகள் விவரிக்கப்பட்டுள்ளன. ஏனோக்கு தேவனோடு சஞ்சரித்துக்கொண்டிருந்தான்; தேவன் அவனை எடுத்துக்கொண்டதால் அவன் காணப்படாமற்போனான். மெத்தூசலா 969 வருஷம் உயிரோடிருந்தான்; லாமேக்கின் குமாரனாக நோவா பிறந்தான்.",
    "Genesis 6": "பூமியிலே மனுஷருடைய அக்கிரமம் பெருகினதைக் கண்டு, மனுஷனை உண்டாக்கினதற்காகக் கர்த்தர் மனஸ்தாபப்பட்டார். ஆனால் நோவாவுக்குக் கர்த்தருடைய கண்களில் கிருபை கிடைத்தது. ஜலப்பிரளயத்தினால் பூமியை அழிக்கப்போவதாகச் சொல்லி, தேவன் நோவாவுக்குப் பேழையைக் கட்டக் கட்டளையிட்டார்; நோவா தேவன் கட்டளையிட்டபடியெல்லாம் செய்தான்.",
    "Genesis 7": "நோவாவும் அவன் குடும்பத்தாரும், எல்லா ஜீவஜந்துக்களிலும் ஜோடு ஜோடாகப் பேழைக்குள் பிரவேசித்தார்கள்; கர்த்தர் கதவை அடைத்தார். நாற்பது நாள் இரவும் பகலும் பெருமழை பெய்து, உயர்ந்த மலைகளையெல்லாம் ஜலம் மூடியது. பேழையில் இருந்தவர்கள் தவிர பூமியிலிருந்த சகல ஜீவன்களும் அழிந்தன.",
    "Genesis 8": "தேவன் நோவாவை நினைத்தருளினதால் ஜலம் வடியத் தொடங்கியது; பேழை அரராத் மலைகளின்மேல் தங்கியது. நோவா காகத்தையும் புறாவையும் வெளியே அனுப்பினான்; புறா ஒலிவ இலையைக் கொண்டுவந்தது. பேழையிலிருந்து வெளியே வந்த நோவா கர்த்தருக்குப் பலிபீடம் கட்டிப் பலியிட்டான்; இனி பூமியை ஜலப்பிரளயத்தால் அழிப்பதில்லை என்று கர்த்தர் தீர்மானித்தார்.",
    "Genesis 9": "தேவன் நோவாவையும் அவன் குமாரரையும் ஆசீர்வதித்து, 'பலுகிப் பெருகி பூமியை நிரப்புங்கள்' என்றார்; வானவில்லைத் தம்முடைய உடன்படிக்கையின் அடையாளமாக வைத்தார். நோவா திராட்சரசம் குடித்து வெறித்தபோது, காம் தன் தகப்பனின் நிர்வாணத்தைக் கண்டு வெளியே சொன்னான்; சேமும் யாப்பேத்தும் அதை மூடினார்கள். நோவா கானானைச் சபித்து, சேமையும் யாப்பேத்தையும் ஆசீர்வதித்தான்.",
    "Genesis 10": "நோவாவின் குமாரராகிய சேம், காம், யாப்பேத் ஆகியோரின் சந்ததியார் விவரிக்கப்பட்டுள்ளனர். ஜலப்பிரளயத்திற்குப் பின் இவர்களிலிருந்து ஜாதிகள் பூமியெங்கும் பிரிந்து பரவினார்கள். காமின் சந்ததியில் வந்த நிம்ரோது பூமியில் பலவானான வேட்டைக்காரனாக இருந்தான்.",
    "Genesis 11": "பூமியெங்கும் ஒரே பாஷை இருந்தபோது, மனுஷர் வானத்தை அளாவும் கோபுரத்தைக் கட்டத் தொடங்கினார்கள். கர்த்தர் அவர்கள் பாஷையைத் தாறுமாறாக்கி, அவர்களைப் பூமியெங்கும் சிதறடித்தார்; ஆகையால் அந்த இடம் பாபேல் எனப்பட்டது. சேம் முதல் ஆபிராம் வரையிலான தலைமுறைகளும், தேராகு ஆபிராமோடு ஊர் என்னும் பட்டணத்திலிருந்து ஆரானுக்குப் போனதும் சொல்லப்பட்டுள்ளன.",
    "Genesis 12": "கர்த்தர் ஆபிராமை அழைத்து, 'நீ உன் தேசத்தைவிட்டுப் புறப்பட்டுப் போ; உன்னைப் பெரிய ஜாதியாக்குவேன், உனக்குள் பூமியின் வம்சங்களெல்லாம் ஆசீர்வதிக்கப்படும்' என்றார். ஆபிராம் கானான் தேசத்திற்கு வந்து கர்த்தருக்குப் பலிபீடம் கட்டினான். பஞ்சத்தினால் எகிப்துக்குப் போனபோது சாராயைத் தன் சகோதரி என்று சொன்னான்; கர்த்தர் பார்வோனை வாதித்ததால் அவள் திருப்பிக் கொடுக்கப்பட்டாள்.",
    "Genesis 13": "ஆபிராமுக்கும் லோத்துக்கும் மிகுந்த சம்பத்து இருந்ததால், அவர்களுடைய மேய்ப்பர்களுக்குள் வாக்குவாதம் உண்டானது. லோத்து யோர்தானின் சமபூமியைத் தெரிந்துகொண்டு சோதோமுக்கு அருகே கூடாரம் போட்டான். கர்த்தர் ஆபிராமிடம், 'நீ காண்கிற தேசம் முழுவதையும் உனக்கும் உன் சந்ததிக்கும் கொடுப்பேன்' என்று வாக்களித்தார்; ஆபிராம் எபிரோனில் குடியேறினான்.",
    "Genesis 14": "ராஜாக்களுக்குள் நடந்த யுத்தத்தில் லோத்து சிறைபிடிக்கப்பட்டான்; ஆபிராம் தன் வீட்டில் பிறந்த 318 பேரோடு போய் அவனை மீட்டான். சாலேமின் ராஜாவும் உன்னதமான தேவனுடைய ஆசாரியனுமாகிய மெல்கிசேதேக்கு ஆபிராமை ஆசீர்வதித்தான்; ஆபிராம் அவனுக்கு எல்லாவற்றிலும் தசமபாகம் கொடுத்தான். சோதோமின் ராஜா கொடுத்த பொருட்களை ஆபிராம் ஏற்க மறுத்தான்.",
    "Genesis 15": "கர்த்தர் ஆபிராமுக்குத் தரிசனமாகி, 'நானே உனக்குக் கேடகமும், உனக்கு மகா பெரிய பலனுமாயிருக்கிறேன்' என்றார்; உன் சந்ததி வானத்து நட்சத்திரங்களைப் போல இருக்கும் என்று வாக்களித்தார். ஆபிராம் கர்த்தரை விசுவாசித்தான்; அதை அவர் அவனுக்கு நீதியாக எண்ணினார். கர்த்தர் ஆபிராமோடு உடன்படிக்கை பண்ணி, அவன் சந்ததி அந்நிய தேசத்தில் நானூறு வருஷம் உபத்திரவப்படும் என்றும் முன்னறிவித்தார்.",
    "Genesis 16": "பிள்ளையில்லாத சாராய் தன் அடிமைப்பெண்ணாகிய ஆகாரை ஆபிராமுக்கு மனைவியாகக் கொடுத்தாள். ஆகார் கர்ப்பவதியானபோது சாராயை அற்பமாக எண்ணினதால், சாராய் அவளைக் கடினமாக நடத்தினாள்; ஆகார் ஓடிப்போனாள். கர்த்தருடைய தூதன் வனாந்தரத்தில் அவளைச் சந்தித்துத் திரும்பிப்போகச் சொன்னார்; அவள் இஸ்மவேலைப் பெற்றாள்.",
    "Genesis 17": "ஆபிராமுக்குத் தொண்ணூற்றொன்பது வயதானபோது, கர்த்தர் தம்மைச் சர்வவல்லமையுள்ள தேவன் என்று வெளிப்படுத்தி, அவனோடு நித்திய உடன்படிக்கை பண்ணினார். அவன் பேர் ஆபிரகாம் என்றும், சாராயின் பேர் சாராள் என்றும் மாற்றப்பட்டது; விருத்தசேதனம் உடன்படிக்கையின் அடையாளமாகக் கொடுக்கப்பட்டது. சாராள் ஒரு குமாரனைப் பெறுவாள், அவனுக்கு 'ஈசாக்கு' என்று பேரிட வேண்டும் என்று தேவன் சொன்னார்.",
    "Genesis 18": "மம்ரேயின் சமபூமியில் மூன்று புருஷர் ஆபிரகாமிடம் வந்தார்கள்; அவன் அவர்களை அன்போடு உபசரித்தான். அடுத்த வருஷம் சாராளுக்கு ஒரு குமாரன் பிறப்பான் என்று கர்த்தர் சொன்னபோது சாராள் நகைத்தாள்; 'கர்த்தரால் ஆகாத காரியம் ஏதாகிலும் உண்டோ?' என்று அவர் கேட்டார். சோதோமை அழிக்கப்போவதை அறிந்த ஆபிரகாம், பத்து நீதிமான்களாவது இருந்தால் அதை அழிக்க வேண்டாம் என்று கர்த்தரிடம் மன்றாடினான்.",
    "Genesis 19": "இரண்டு தூதர்கள் சோதோமுக்கு வந்தபோது லோத்து அவர்களைத் தன் வீட்டில் ஏற்றுக்கொண்டான்; பட்டணத்தின் மனுஷர் பொல்லாங்கு செய்ய வீட்டை வளைந்துகொண்டார்கள். தூதர்கள் லோத்தையும் அவன் குடும்பத்தையும் வெளியே கொண்டுபோனார்கள்; கர்த்தர் சோதோமையும் கொமோராவையும் அக்கினியினாலும் கந்தகத்தினாலும் அழித்தார். திரும்பிப் பார்த்த லோத்தின் மனைவி உப்புத்தூண் ஆனாள்; பின்பு லோத்தின் குமாரத்திகள் மூலம் மோவாபியரும் அம்மோனியரும் தோன்றினார்கள்.",
    "Genesis 20": "ஆபிரகாம் கேராரில் தங்கியிருந்தபோது, சாராளைத் தன் சகோதரி என்று மறுபடியும் சொன்னான்; கேராரின் ராஜாவாகிய அபிமெலேக்கு அவளை அழைப்பித்துக்கொண்டான். தேவன் அபிமெலேக்குக்குச் சொப்பனத்தில் தோன்றி எச்சரித்ததால், அவன் சாராளைத் தொடாமல் ஆபிரகாமிடம் திருப்பிக் கொடுத்தான். ஆபிரகாம் ஜெபம் பண்ணினபோது, தேவன் அபிமெலேக்கின் வீட்டாரைக் குணமாக்கினார்.",
    "Genesis 21": "கர்த்தர் சொன்னபடியே சாராள் முதிர்வயதில் ஆபிரகாமுக்கு ஈசாக்கைப் பெற்றாள். ஆகாரும் இஸ்மவேலும் அனுப்பிவிடப்பட்டு வனாந்தரத்தில் அலைந்தபோது, தேவன் ஒரு துரவைக் காண்பித்து அவர்களைக் காப்பாற்றினார். ஆபிரகாம் அபிமெலேக்கோடு பெயெர்செபாவில் உடன்படிக்கை பண்ணி, அங்கே நித்திய தேவனாகிய கர்த்தருடைய நாமத்தைத் தொழுதுகொண்டான்.",
    "Genesis 22": "தேவன் ஆபிரகாமைச் சோதித்து, அவனுடைய ஏக சுதனாகிய ஈசாக்கை மோரியா மலையில் தகனபலியாகச் செலுத்தச் சொன்னார். ஆபிரகாம் கீழ்ப்படிந்து கத்தியை ஓங்கினபோது, கர்த்தருடைய தூதன் அவனைத் தடுத்தார்; ஈசாக்குக்குப் பதிலாகத் தேவன் ஒரு ஆட்டுக்கடாவை அருளினார். ஆபிரகாம் அந்த இடத்துக்கு 'யேகோவாயீரே' என்று பேரிட்டான்; உன் சந்ததிக்குள் பூமியின் ஜாதிகளெல்லாம் ஆசீர்வதிக்கப்படும் என்று கர்த்தர் மறுபடியும் வாக்களித்தார்.",
    "Genesis 23": "சாராள் நூற்றிருபத்தேழு வயதில் எபிரோனில் மரித்தாள்; ஆபிரகாம் அவளுக்காகத் துக்கங்கொண்டாடி அழுதான். அவன் ஏத்தின் புத்திரரிடம் மக்பேலா குகையையும் அதைச் சேர்ந்த நிலத்தையும் நானூறு சேக்கல் வெள்ளிக்கு வாங்கினான். அங்கே சாராளை அடக்கம் பண்ணினான்.",
    "Genesis 24": "ஆபிரகாம் தன் வேலைக்காரனை, ஈசாக்குக்குத் தன் இனத்தாரிடமிருந்து பெண்கொள்ளும்படி மெசொப்பொத்தாமியாவுக்கு அனுப்பினான். வேலைக்காரன் துரவண்டை ஜெபித்தபோது, தனக்கும் ஒட்டகங்களுக்கும் தண்ணீர் கொடுத்த ரெபெக்காளைக் கர்த்தர் அடையாளமாகக் காண்பித்தார். ரெபெக்காள் மனப்பூர்வமாக அவனோடு புறப்பட்டு வந்தாள்; ஈசாக்கு அவளை மனைவியாக்கி நேசித்தான்.",
    "Genesis 25": "ஆபிரகாம் கேத்தூராளை மணந்து பிள்ளைகளைப் பெற்றான்; நூற்றெழுபத்தைந்து வயதில் மரித்து, மக்பேலா குகையில் அடக்கம் பண்ணப்பட்டான். இஸ்மவேலின் சந்ததியாரும் விவரிக்கப்பட்டுள்ளனர். ரெபெக்காள் ஏசா, யாக்கோபு என்னும் இரட்டைப் பிள்ளைகளைப் பெற்றாள்; பசியாயிருந்த ஏசா ஒரு கூழுக்காகத் தன் சேஷ்டபுத்திரபாகத்தை யாக்கோபுக்கு விற்றுப்போட்டான்.",
    "Genesis 26": "பஞ்சத்தின்போது ஈசாக்கு கேராருக்குப் போனான்; கர்த்தர் ஆபிரகாமுக்குக் கொடுத்த வாக்குத்தத்தத்தை அவனுக்கும் உறுதிப்படுத்தினார். ஈசாக்கு ரெபெக்காளைத் தன் சகோதரி என்று சொன்னான்; பின்பு அது வெளிப்பட்டது. கர்த்தர் அவனை ஆசீர்வதித்ததால் அவன் மிகவும் பெருகினான்; கிணறுகளுக்காக வாக்குவாதம் வந்தபோதும் சமாதானமாக விலகிப்போய், பெயெர்செபாவில் அபிமெலேக்கோடு உடன்படிக்கை பண்ணினான்.",
    "Genesis 27": "ஈசாக்கு முதிர்வயதாகிக் கண் இருண்டுபோனபோது, ஏசாவை ஆசீர்வதிக்க விரும்பினான். ரெபெக்காளின் ஆலோசனைப்படி யாக்கோபு ஏசாவைப் போல வேஷம் மாறி, தகப்பனை ஏமாற்றி ஆசீர்வாதத்தைப் பெற்றுக்கொண்டான். ஏசா மிகுந்த கோபங்கொண்டு யாக்கோபைக் கொல்ல நினைத்ததால், ரெபெக்காள் அவனை ஆரானிலிருக்கும் தன் சகோதரன் லாபானிடம் அனுப்ப ஏற்பாடு செய்தாள்.",
    "Genesis 28": "ஈசாக்கு யாக்கோபை ஆசீர்வதித்து, கானானியப் பெண்ணை மணக்காமல் லாபானின் குமாரத்திகளில் ஒருத்தியை மணக்கும்படி பதான் அராமுக்கு அனுப்பினான். வழியில் யாக்கோபு, பூமியிலிருந்து வானம் வரை எட்டிய ஒரு ஏணியையும், அதில் தேவதூதர் ஏறி இறங்குவதையும் சொப்பனத்தில் கண்டான். கர்த்தர் அவனோடிருப்பதாக வாக்களித்தார்; யாக்கோபு அந்த இடத்துக்குப் 'பெத்தேல்' என்று பேரிட்டு, தசமபாகம் செலுத்துவதாகப் பொருத்தனை பண்ணினான்.",
    "Genesis 29": "யாக்கோபு ஆரானுக்கு வந்து, துரவண்டை ராகேலைச் சந்தித்தான். ராகேலுக்காக லாபானிடம் ஏழு வருஷம் வேலை செய்தான்; ஆனால் லாபான் அவனை ஏமாற்றி லேயாளைக் கொடுத்தான். இன்னும் ஏழு வருஷம் வேலை செய்ய ஒப்புக்கொண்டு ராகேலையும் மணந்தான்; அற்பமாக எண்ணப்பட்ட லேயாளுக்குக் கர்த்தர் ரூபன், சிமியோன், லேவி, யூதா ஆகிய குமாரரைக் கொடுத்தார்.",
    "Genesis 30": "பிள்ளையில்லாத ராகேல் தன் அடிமைப்பெண் பில்காளை யாக்கோபுக்குக் கொடுத்தாள்; லேயாளும் சில்பாளைக் கொடுத்தாள்; இவர்கள் மூலம் தாண், நப்தலி, காத், ஆசேர் பிறந்தார்கள். லேயாள் இசக்கார், செபுலோன், தீனாள் ஆகியோரைப் பெற்றாள்; பின்பு தேவன் ராகேலை நினைத்தருளினதால் அவள் யோசேப்பைப் பெற்றாள். யாக்கோபு லாபானோடு கூலியைக் குறித்து ஒப்பந்தம் பண்ணினான்; தேவன் அவனுடைய மந்தையை மிகவும் பெருகப்பண்ணினார்.",
    "Genesis 31": "தேவன் யாக்கோபைத் தன் பிதாக்களின் தேசத்துக்குத் திரும்பிப்போகச் சொன்னதால், அவன் லாபானுக்குத் தெரியாமல் குடும்பத்தோடு புறப்பட்டான். லாபான் அவனைப் பின்தொடர்ந்து வந்தான்; ஆனால் யாக்கோபுக்குத் தீங்கு செய்யாதபடி தேவன் சொப்பனத்தில் லாபானை எச்சரித்தார். யாக்கோபும் லாபானும் கற்குவியலைச் சாட்சியாக வைத்து உடன்படிக்கை பண்ணி, சமாதானமாகப் பிரிந்தார்கள்.",
    "Genesis 32": "ஏசா நானூறு பேரோடு வருகிறான் என்று கேட்டு யாக்கோபு மிகவும் பயந்து, தேவனிடம் ஜெபம் பண்ணி, ஏசாவுக்கு வெகுமதிகளை முன்னதாக அனுப்பினான். இரவில் ஒரு புருஷன் விடியற்காலம் வரை அவனோடு போராடினார்; 'நீர் என்னை ஆசீர்வதித்தாலொழிய உம்மைப் போகவிடேன்' என்று யாக்கோபு சொன்னான். அவன் பேர் இஸ்ரவேல் என்று மாற்றப்பட்டது; தேவனை முகமுகமாய்க் கண்டேன் என்று அந்த இடத்துக்குப் 'பெனியேல்' என்று பேரிட்டான்.",
    "Genesis 33": "யாக்கோபு ஏழுதரம் தரைமட்டும் குனிந்து வணங்கி ஏசாவைச் சந்தித்தான்; ஏசா ஓடிவந்து அவனைக் கட்டித்தழுவி முத்தமிட்டான், இருவரும் அழுதார்கள். யாக்கோபு வருந்திக் கேட்டுக்கொண்டதால் ஏசா வெகுமதிகளை ஏற்றுக்கொண்டான். பின்பு யாக்கோபு சீகேமுக்கு வந்து நிலம் வாங்கி, அங்கே பலிபீடம் கட்டினான்.",
    "Genesis 34": "யாக்கோபின் குமாரத்தி தீனாளை, ஏவியனான சீகேம் என்பவன் தீட்டுப்படுத்தினான்; பின்பு அவளை மணக்க விரும்பினான். யாக்கோபின் குமாரர் கபடமாக விருத்தசேதனம் செய்யும் நிபந்தனை வைத்தார்கள்; சிமியோனும் லேவியும் பட்டணத்தின் ஆண்களையெல்லாம் கொன்றுபோட்டார்கள். இதனால் தேசத்தாருக்குள் தன்னை வெறுக்கப்பண்ணினீர்கள் என்று யாக்கோபு அவர்களைக் கடிந்துகொண்டான்.",
    "Genesis 35": "தேவன் சொன்னபடி யாக்கோபு அந்நிய தெய்வங்களை அகற்றி, பெத்தேலுக்குப் போய்ப் பலிபீடம் கட்டினான்; தேவன் அவனுக்கு இஸ்ரவேல் என்ற பேரையும் வாக்குத்தத்தத்தையும் உறுதிப்படுத்தினார். பெத்லகேமுக்குப் போகும் வழியில் ராகேல் பென்யமீனைப் பெற்று மரித்தாள். யாக்கோபின் பன்னிரண்டு குமாரரின் பேர்கள் சொல்லப்பட்டுள்ளன; ஈசாக்கு நூற்றெண்பது வயதில் மரித்து, ஏசாவாலும் யாக்கோபாலும் அடக்கம் பண்ணப்பட்டான்.",
    "Genesis 36": "ஏதோம் என்னப்பட்ட ஏசாவின் சந்ததியார் விவரிக்கப்பட்டுள்ளனர். ஏசா தன் சகோதரனாகிய யாக்கோபை விட்டு விலகி, சேயீர் மலைநாட்டில் குடியேறினான். ஏதோமியரின் பிரபுக்களும், இஸ்ரவேலில் ராஜா அரசாளுவதற்கு முன்பு ஏதோமை அரசாண்ட ராஜாக்களும் சொல்லப்பட்டுள்ளனர்.",
    "Genesis 37": "யாக்கோபு யோசேப்பை மற்றப் பிள்ளைகளைவிட அதிகமாக நேசித்து, அவனுக்குப் பலவர்ண அங்கியைச் செய்து கொடுத்தான். தன் சகோதரர் தன்னை வணங்குவதுபோல யோசேப்பு சொப்பனங்கள் கண்டு சொன்னதால், அவர்கள் அவனை அதிகமாய்ப் பகைத்தார்கள். அவர்கள் அவனைக் குழியிலே போட்டு, பின்பு இஸ்மவேலருக்கு விற்றுப்போட்டு, துஷ்டமிருகம் அவனைக் கொன்றது என்று தகப்பனை நம்பவைத்தார்கள்; யோசேப்பு எகிப்தில் போத்திபாரிடம் விற்கப்பட்டான்.",
    "Genesis 38": "யூதா கானானியப் பெண்ணை மணந்து ஏர், ஓனான், சேலா என்னும் குமாரரைப் பெற்றான்; ஏரும் ஓனானும் கர்த்தருடைய பார்வைக்குப் பொல்லாதவர்களாயிருந்ததால் மரித்தார்கள். யூதா தன் மருமகள் தாமாருக்குச் சேலாவைக் கொடுக்காததால், அவள் வேஷம் மாறி யூதாவினால் கர்ப்பவதியானாள். உண்மை வெளிப்பட்டபோது, 'என்னைப் பார்க்கிலும் அவள் நீதியுள்ளவள்' என்று யூதா ஒப்புக்கொண்டான்; தாமார் பாரேசையும் சாராவையும் பெற்றாள்.",
    "Genesis 39": "கர்த்தர் யோசேப்போடே இருந்ததால், போத்திபார் அவனைத் தன் வீட்டுக்கெல்லாம் விசாரணைக்காரனாக்கினான். போத்திபாரின் மனைவி யோசேப்பைப் பாவத்துக்கு இழுக்க முயன்றபோது, 'நான் தேவனுக்கு விரோதமாய்ப் பாவம் செய்வது எப்படி?' என்று மறுத்து ஓடினான். அவள் பொய்க் குற்றம் சாட்டியதால் யோசேப்பு சிறைச்சாலையில் அடைக்கப்பட்டான்; அங்கேயும் கர்த்தர் அவனோடிருந்து அவனுக்குத் தயவு கிடைக்கப்பண்ணினார்.",
    "Genesis 40": "பார்வோனின் பானபாத்திரக்காரரின் தலைவனும் சுயம்பாகிகளின் தலைவனும் சிறையில் சொப்பனங்கள் கண்டார்கள். 'சொப்பனங்களின் அர்த்தம் தேவனுக்கே உரியது' என்று சொல்லி யோசேப்பு அவைகளுக்கு அர்த்தம் சொன்னான். அவன் சொன்னபடியே பானபாத்திரக்காரன் திரும்ப நியமிக்கப்பட்டான், சுயம்பாகி தூக்கிலிடப்பட்டான்; ஆனால் பானபாத்திரக்காரன் யோசேப்பை மறந்துபோனான்.",
    "Genesis 41": "இரண்டு வருஷத்துக்குப் பின் பார்வோன் கொழுத்த பசுக்களையும் கேவலமான பசுக்களையும், நிறைந்த கதிர்களையும் பதரான கதிர்களையும் குறித்துச் சொப்பனம் கண்டான். யோசேப்பு அழைக்கப்பட்டு, ஏழு வருஷ பரிபூரணமும் அதன்பின் ஏழு வருஷ பஞ்சமும் வரும் என்று அர்த்தம் சொன்னான். பார்வோன் யோசேப்பை எகிப்து தேசம் முழுவதற்கும் அதிகாரியாக்கினான்; அவன் தானியத்தைச் சேர்த்து வைத்தான், மனாசே, எப்பிராயீம் என்னும் குமாரரையும் பெற்றான்.",
    "Genesis 42": "பஞ்சத்தின்போது யாக்கோபு தானியம் வாங்கத் தன் பத்துக் குமாரரை எகிப்துக்கு அனுப்பினான். யோசேப்பு தன் சகோதரரை அறிந்துகொண்டான், அவர்களோ அவனை அறியவில்லை; அவன் அவர்களை வேவுகாரர் என்று சொல்லி, சிமியோனைக் காவலில் வைத்து, பென்யமீனைக் கொண்டுவரச் சொன்னான். தாங்கள் யோசேப்புக்குச் செய்த பாவத்தின் நிமித்தமே இந்த இக்கட்டு வந்தது என்று சகோதரர் தங்களுக்குள் பேசிக்கொண்டார்கள்.",
    "Genesis 43": "பஞ்சம் கொடியதாயிருந்ததால், பென்யமீனுக்காகத் தானே பிணையாளியாக இருப்பதாக யூதா வாக்களித்தான்; யாக்கோபு பென்யமீனை அனுப்ப ஒப்புக்கொண்டான். சகோதரர் வெகுமதிகளோடு எகிப்துக்கு வந்தபோது, யோசேப்பு சிமியோனை விடுவித்து, அவர்களைத் தன் வீட்டில் விருந்துக்கு அழைத்தான். தன் சகோதரனாகிய பென்யமீனைக் கண்டபோது யோசேப்பு மனதுருகி, தனியறைக்குள் போய் அழுதான்.",
    "Genesis 44": "யோசேப்பு தன் வெள்ளிப் பாத்திரத்தைப் பென்யமீனுடைய சாக்கில் வைக்கச் சொல்லி, தன் சகோதரரைச் சோதித்தான். பாத்திரம் பென்யமீனிடம் கண்டுபிடிக்கப்பட்டபோது, அவர்கள் தங்கள் வஸ்திரங்களைக் கிழித்துக்கொண்டு திரும்பி வந்தார்கள். பென்யமீனுக்குப் பதிலாகத் தானே அடிமையாக இருப்பதாக யூதா யோசேப்பிடம் மன்றாடினான்.",
    "Genesis 45": "யோசேப்பு தன்னை அடக்கிக்கொள்ள முடியாமல், 'நான் யோசேப்பு' என்று தன் சகோதரருக்குத் தன்னை வெளிப்படுத்தினான். 'நீங்கள் அல்ல, ஜீவனைக் காக்கும்படி தேவனே என்னை உங்களுக்கு முன்னே அனுப்பினார்' என்று சொல்லி அவர்களைத் தேற்றினான். யோசேப்பு உயிரோடிருக்கிறான் என்று கேட்டபோது யாக்கோபின் ஆவி உயிர்த்தது; நான் மரிக்குமுன் அவனைக் காணப் போவேன் என்றான்.",
    "Genesis 46": "யாக்கோபு குடும்பத்தோடு புறப்பட்டு, பெயெர்செபாவில் பலியிட்டான்; 'எகிப்துக்குப் போகப் பயப்படாதே, அங்கே உன்னைப் பெரிய ஜாதியாக்குவேன்' என்று தேவன் இராத்திரி தரிசனத்தில் சொன்னார். எகிப்துக்கு வந்த யாக்கோபின் குடும்பத்தார் எழுபது பேர் என்று பட்டியலிடப்பட்டுள்ளனர். யோசேப்பு கோசேனில் தன் தகப்பனைச் சந்தித்து, அவன் கழுத்தைக் கட்டிக்கொண்டு வெகுநேரம் அழுதான்.",
    "Genesis 47": "யோசேப்பு தன் தகப்பனையும் சகோதரரையும் பார்வோனுக்கு முன்பாக நிறுத்தினான்; யாக்கோபு பார்வோனை ஆசீர்வதித்தான், அவர்களுக்குக் கோசேன் நாடு கொடுக்கப்பட்டது. பஞ்சம் கடுமையானபோது, யோசேப்பு எகிப்தியரின் பணம், மந்தைகள், நிலங்களுக்குப் பதிலாகத் தானியம் கொடுத்து ஜனங்களை உயிரோடே காப்பாற்றினான். மரணகாலம் நெருங்கியபோது, தன்னைத் தன் பிதாக்களின் கல்லறையில் அடக்கம் பண்ணும்படி யாக்கோபு யோசேப்பிடம் ஆணையிடச் சொன்னான்.",
    "Genesis 48": "யாக்கோபு வியாதிப்பட்டிருந்தபோது, யோசேப்பு தன் குமாரராகிய மனாசேயையும் எப்பிராயீமையும் அவனிடம் அழைத்து வந்தான். யாக்கோபு அவர்களைத் தன் சொந்தப் பிள்ளைகளாக ஏற்றுக்கொண்டு ஆசீர்வதித்தான். அவன் தன் கைகளை மாற்றி வைத்து, இளையவனாகிய எப்பிராயீமை மூத்தவனாகிய மனாசேக்கு மேலாக உயர்த்தினான்.",
    "Genesis 49": "யாக்கோபு தன் பன்னிரண்டு குமாரரையும் கூட்டி, கடைசி நாட்களில் அவர்களுக்கு நேரிடப்போவதை முன்னறிவித்து, அவரவருக்கேற்ற ஆசீர்வாதம் கூறினான். 'சீலோ வருமளவும் செங்கோல் யூதாவை விட்டு நீங்குவதில்லை' என்றும், யோசேப்பு கனிதரும் செடியாயிருப்பான் என்றும் சொன்னான். தன்னை மக்பேலா குகையில் அடக்கம் பண்ணக் கட்டளையிட்டு, யாக்கோபு மரித்தான்.",
    "Genesis 50": "யோசேப்பும் எகிப்தியரும் யாக்கோபுக்காகத் துக்கங்கொண்டாடி, அவனைக் கானானிலுள்ள மக்பேலா குகையில் அடக்கம் பண்ணினார்கள். யோசேப்பு பழிவாங்குவான் என்று சகோதரர் பயந்தபோது, 'நீங்கள் எனக்குத் தீமை செய்ய நினைத்தீர்கள்; தேவனோ அதை நன்மையாக முடியப்பண்ணினார்' என்று சொல்லி அவர்களைத் தேற்றினான். தேவன் உங்களைச் சந்தித்து வாக்களித்த தேசத்துக்குக் கொண்டுபோவார் என்று சொல்லி, தன் எலும்புகளை அங்கே கொண்டுபோகும்படி ஆணையிடச் சொல்லி, யோசேப்பு நூற்றுப்பத்து வயதில் மரித்தான்.",

    "Exodus 1": "யாக்கோபின் சந்ததியார் எகிப்தில் மிகவும் பலுகிப் பெருகினார்கள். யோசேப்பை அறியாத புதிய ராஜா எழும்பி, இஸ்ரவேலரைக் கடினமான அடிமைவேலையால் ஒடுக்கினான். மருத்துவச்சிகள் தேவனுக்குப் பயந்து ஆண்பிள்ளைகளைக் கொல்லாததால், பிறக்கும் ஆண்பிள்ளைகளையெல்லாம் நதியிலே போடும்படி பார்வோன் கட்டளையிட்டான்.",
    "Exodus 2": "லேவி கோத்திரத்தைச் சேர்ந்த ஒரு ஸ்திரீ தன் குழந்தையை நாணல் பெட்டியில் வைத்து நதியோரத்தில் விட்டாள்; பார்வோனின் குமாரத்தி அதைக் கண்டு எடுத்து, 'மோசே' என்று பேரிட்டாள். மோசே பெரியவனானபின், ஒரு எபிரெயனை அடித்த எகிப்தியனைக் கொன்று, மீதியான் தேசத்துக்கு ஓடிப்போய், சிப்போராளை மணந்தான். இஸ்ரவேலரின் பெருமூச்சைத் தேவன் கேட்டு, ஆபிரகாம், ஈசாக்கு, யாக்கோபுடன் பண்ணின உடன்படிக்கையை நினைவுகூர்ந்தார்.",
    "Exodus 3": "ஓரேப் மலையில் எரிந்தும் வெந்துபோகாத முட்செடியிலிருந்து கர்த்தர் மோசேயை அழைத்து, தம்முடைய ஜனத்தை எகிப்திலிருந்து விடுவிக்க அவனை அனுப்புவதாகச் சொன்னார். உம்முடைய நாமம் என்ன என்று மோசே கேட்டபோது, 'இருக்கிறவராக இருக்கிறேன்' என்று தேவன் சொன்னார். பார்வோன் எளிதில் விடமாட்டான் என்றும், தம்முடைய அதிசயங்களால் எகிப்தை வாதித்தபின் அவர்கள் வெறுமையாய்ப் போகமாட்டார்கள் என்றும் சொன்னார்.",
    "Exodus 4": "மோசே தயங்கியபோது, கர்த்தர் கோல் சர்ப்பமாக மாறுதல், கை குஷ்டமாகுதல் போன்ற அடையாளங்களைக் கொடுத்தார். 'நான் வாக்குவல்லவன் அல்ல' என்று மோசே சொன்னதால், அவன் சகோதரன் ஆரோனை அவனுக்கு வாயாக நியமித்தார். மோசே எகிப்துக்குத் திரும்பினான்; ஆரோன் ஜனங்களுக்கு முன்பாக அடையாளங்களைச் செய்தபோது, ஜனங்கள் விசுவாசித்துத் தலைகுனிந்து பணிந்துகொண்டார்கள்.",
    "Exodus 5": "மோசேயும் ஆரோனும் பார்வோனிடம், 'என் ஜனங்களைப் போகவிடு' என்று கர்த்தர் சொல்லுகிறார் என்றார்கள்; 'கர்த்தர் யார்?' என்று சொல்லிப் பார்வோன் மறுத்தான். அவன் இஸ்ரவேலருக்கு வைக்கோல் கொடுக்காமல் அதே அளவு செங்கல் அறுக்கச் சொல்லி வேலையை இன்னும் கடினமாக்கினான். இஸ்ரவேலின் அதிகாரிகள் மோசேயைக் குறைசொன்னதால், மோசே கர்த்தரிடம் முறையிட்டான்.",
    "Exodus 6": "கர்த்தர் மோசேயிடம், 'நான் கர்த்தர்; உங்களை எகிப்தியரின் சுமைகளிலிருந்து விடுவித்து, உங்களை எனக்கு ஜனமாக்கிக்கொள்வேன்' என்று வாக்களித்தார். ஆனால் மனமடிவினாலும் கொடுமையான வேலையினாலும் இஸ்ரவேலர் மோசேக்குச் செவிகொடுக்கவில்லை. ரூபன், சிமியோன், லேவி ஆகியோரின் வம்சவரலாறும், மோசே ஆரோனின் வம்சமும் சொல்லப்பட்டுள்ளன.",
    "Exodus 7": "கர்த்தர் பார்வோனின் இருதயத்தைக் கடினப்படுத்தி, எகிப்தில் தம்முடைய அடையாளங்களைப் பெருகப்பண்ணுவேன் என்றார். ஆரோனின் கோல் சர்ப்பமானது; மந்திரவாதிகளின் கோல்களும் சர்ப்பமானபோது, ஆரோனின் கோல் அவைகளை விழுங்கிப்போட்டது. முதல் வாதையாக நைல் நதியின் தண்ணீர் இரத்தமாக மாறியது; ஆனாலும் பார்வோனின் இருதயம் கடினமாயிருந்தது.",
    "Exodus 8": "இரண்டாம் வாதையாகத் தவளைகள் தேசத்தை மூடின; பார்வோன் ஜனங்களைப் போகவிடுவதாகச் சொல்லி, பின்பு தன் இருதயத்தைக் கடினப்படுத்தினான். மூன்றாம் வாதையாகப் பேன்கள் வந்தன; 'இது தேவனுடைய விரல்' என்று மந்திரவாதிகளே ஒப்புக்கொண்டார்கள். நான்காம் வாதையாக வண்டுகள் வந்தன; ஆனால் இஸ்ரவேலர் இருந்த கோசேன் நாட்டில் அவை இல்லை.",
    "Exodus 9": "ஐந்தாம் வாதையாக எகிப்தியரின் மிருகஜீவன்கள் கொள்ளைநோயால் செத்தன; இஸ்ரவேலரின் மிருகங்களோ ஒன்றும் சாகவில்லை. ஆறாம் வாதையாக மனுஷர்மேலும் மிருகங்கள்மேலும் எரிபுண்ணான கொப்புளங்கள் எழும்பின. ஏழாம் வாதையாகக் கல்மழை பெய்தது; பார்வோன் 'நான் பாவம் செய்தேன்' என்று சொன்னாலும், கல்மழை நின்றதும் மறுபடியும் இருதயத்தைக் கடினப்படுத்தினான்.",
    "Exodus 10": "எட்டாம் வாதையாக வெட்டுக்கிளிகள் வந்து, கல்மழைக்குத் தப்பின பயிர்களையெல்லாம் தின்றுபோட்டன. ஒன்பதாம் வாதையாக மூன்று நாள் தேசமெங்கும் காரிருள் உண்டாயிற்று; இஸ்ரவேலரின் வாசஸ்தலங்களிலோ வெளிச்சம் இருந்தது. பார்வோன் மோசேயிடம், 'இனி என் முகத்தைக் காணாதே' என்று சொல்லி அவனைத் துரத்தினான்.",
    "Exodus 11": "இன்னும் ஒரு வாதையைக் கொண்டுவருவேன் என்று கர்த்தர் சொன்னார்: நடுராத்திரியில் எகிப்திலுள்ள முதற்பேறெல்லாம் சாகும். இஸ்ரவேலர் எகிப்தியரிடம் பொன் வெள்ளி நகைகளைக் கேட்டு வாங்கும்படி சொல்லப்பட்டது; கர்த்தர் எகிப்தியரின் கண்களில் ஜனங்களுக்குத் தயவு கிடைக்கப்பண்ணினார். ஆனாலும் பார்வோனின் இருதயம் கடினமாயிருந்தது.",
    "Exodus 12": "கர்த்தர் பஸ்காவை ஏற்படுத்தினார்: ஒவ்வொரு வீட்டாரும் பழுதற்ற ஆட்டுக்குட்டியை அடித்து, அதின் இரத்தத்தை வாசல் நிலைக்கால்களில் பூசி, புளிப்பில்லா அப்பத்தோடு புசிக்க வேண்டும். 'நான் இரத்தத்தைக் கண்டு உங்களைக் கடந்துபோவேன்' என்று கர்த்தர் சொன்னார்; நடுராத்திரியில் எகிப்தின் முதற்பேறெல்லாம் சங்கரிக்கப்பட்டது. பார்வோன் இஸ்ரவேலரைப் போகச் சொன்னான்; நானூற்று முப்பது வருஷம் முடிந்த நாளில் அவர்கள் எகிப்தைவிட்டுப் புறப்பட்டார்கள்.",
    "Exodus 13": "இஸ்ரவேலரின் முதற்பேறெல்லாம் கர்த்தருக்குப் பரிசுத்தமாக்கப்பட வேண்டும் என்றும், புளிப்பில்லா அப்பப் பண்டிகையை நினைவுகூர வேண்டும் என்றும் கட்டளையிடப்பட்டது. தேவன் ஜனங்களைப் பெலிஸ்தரின் தேசவழியாய் அல்ல, வனாந்தரவழியாய் நடத்தினார்; மோசே யோசேப்பின் எலும்புகளை எடுத்துக்கொண்டு போனான். கர்த்தர் பகலில் மேகஸ்தம்பத்திலும் இரவில் அக்கினிஸ்தம்பத்திலும் அவர்களுக்கு முன்பாகச் சென்றார்.",
    "Exodus 14": "பார்வோன் மனம் மாறி, தன் இரதங்களோடு இஸ்ரவேலரைப் பின்தொடர்ந்தான்; ஜனங்கள் பயந்து முறுமுறுத்தார்கள். 'பயப்படாதிருங்கள்; நின்றுகொண்டு கர்த்தர் உங்களுக்குச் செய்யும் இரட்சிப்பைப் பாருங்கள்' என்று மோசே சொன்னான். மோசே கையை நீட்டினபோது சிவந்த சமுத்திரம் பிளந்தது; இஸ்ரவேலர் உலர்ந்த தரையில் கடந்துபோனார்கள், பின்தொடர்ந்த எகிப்தியரோ ஜலத்தில் மூழ்கி அழிந்தார்கள்.",
    "Exodus 15": "மோசேயும் இஸ்ரவேலரும் கர்த்தருக்கு ஜெயகீதம் பாடினார்கள்; தீர்க்கதரிசியாகிய மிரியாம் தம்புரு எடுத்து ஸ்திரீகளோடு நடனமாடிப் பாடினாள். மாராவில் கசப்பான தண்ணீரைக் கர்த்தர் மதுரமாக்கி, 'நானே உன் பரிகாரியாகிய கர்த்தர்' என்றார். பின்பு பன்னிரண்டு நீரூற்றுகளும் எழுபது பேரீச்சமரங்களும் இருந்த ஏலிமுக்கு வந்து பாளயமிறங்கினார்கள்.",
    "Exodus 16": "சீன் வனாந்தரத்தில் ஜனங்கள் உணவுக்காக முறுமுறுத்தார்கள்; கர்த்தர் மாலையில் காடைகளையும் காலையில் வானத்திலிருந்து மன்னாவையும் கொடுத்தார். ஒவ்வொருவரும் தினமும் தேவையான அளவு சேர்க்க வேண்டும், ஆறாம் நாளில் இரட்டிப்பாகச் சேர்த்து ஓய்வுநாளில் ஓய்ந்திருக்க வேண்டும் என்று கட்டளையிடப்பட்டது. கானான் தேசத்தின் எல்லைக்கு வருமட்டும் நாற்பது வருஷம் இஸ்ரவேலர் மன்னாவைப் புசித்தார்கள்.",
    "Exodus 17": "ரெவிதீமில் தண்ணீர் இல்லாததால் ஜனங்கள் மோசேயோடு வாக்குவாதம் பண்ணினார்கள்; கர்த்தர் சொன்னபடி மோசே ஓரேபிலுள்ள கன்மலையை அடித்தபோது தண்ணீர் புறப்பட்டது. அமலேக்கியர் யுத்தம் பண்ண வந்தபோது யோசுவா யுத்தம் செய்தான்; மோசே கைகளை உயர்த்தியிருந்தபோது இஸ்ரவேலர் மேற்கொண்டார்கள், ஆரோனும் ஊரும் அவன் கைகளைத் தாங்கினார்கள். மோசே பலிபீடம் கட்டி, அதற்கு 'யேகோவாநிசி' என்று பேரிட்டான்.",
    "Exodus 18": "மோசேயின் மாமனாகிய எத்திரோ சிப்போராளையும் பிள்ளைகளையும் அழைத்துக்கொண்டு மோசேயிடம் வந்து, கர்த்தர் செய்த யாவையும் கேட்டு மகிழ்ந்து, தேவனுக்குப் பலியிட்டான். மோசே காலைமுதல் மாலைவரை தனியாக ஜனங்களுக்கு நியாயம் விசாரிப்பதைக் கண்டு, திறமையும் தேவபயமுமுள்ள மனுஷரை அதிகாரிகளாக நியமிக்க ஆலோசனை சொன்னான். மோசே தன் மாமனுடைய சொல்லுக்குச் செவிகொடுத்து அப்படியே செய்தான்.",
    "Exodus 19": "இஸ்ரவேலர் எகிப்திலிருந்து புறப்பட்ட மூன்றாம் மாதத்தில் சீனாய் வனாந்தரத்துக்கு வந்து மலைக்கு எதிரே பாளயமிறங்கினார்கள். 'நீங்கள் எனக்கு ஆசாரிய ராஜ்யமும் பரிசுத்த ஜாதியுமாயிருப்பீர்கள்' என்று கர்த்தர் சொன்னார். ஜனங்கள் தங்களைப் பரிசுத்தப்படுத்திக்கொண்டார்கள்; மூன்றாம் நாளில் இடிமுழக்கம், மின்னல், கார்மேகம், எக்காளசத்தத்தோடு கர்த்தர் சீனாய் மலையின்மேல் அக்கினியில் இறங்கினார்.",
    "Exodus 20": "தேவன் சீனாய் மலையிலிருந்து பத்துக் கற்பனைகளைக் கொடுத்தார்; 'என்னையன்றி உனக்கு வேறே தேவர்கள் உண்டாயிருக்க வேண்டாம்' என்பதுமுதல் பிறனுடையதை இச்சியாதிருப்பதுவரை அவை அடங்கியிருந்தன. ஜனங்கள் இடிமுழக்கங்களைக் கண்டு பயந்து தூரத்தில் நின்று, தேவன் தங்களோடு பேசாமல் மோசே பேசும்படி கேட்டார்கள். விக்கிரகங்களை உண்டாக்காமல், மண்ணினால் அல்லது வெட்டாத கல்லினால் பலிபீடம் கட்டும்படி கர்த்தர் கட்டளையிட்டார்.",
    "Exodus 21": "எபிரெய அடிமைகளை நடத்துவது பற்றிய நியாயங்கள் கொடுக்கப்பட்டன; ஏழாம் வருஷத்தில் அவர்கள் விடுதலையாகிப் போகலாம். கொலை, தாய் தகப்பனை அடித்தல், மனுஷனைத் திருடுதல் ஆகியவற்றுக்கு மரணதண்டனை விதிக்கப்பட்டது. 'கண்ணுக்குக் கண், பல்லுக்குப் பல்' என்ற நியாயமும், மாடுகள் உண்டாக்கும் சேதத்துக்கான பொறுப்புகளும் சொல்லப்பட்டுள்ளன.",
    "Exodus 22": "திருட்டு, சொத்துச் சேதம், ஒப்படைக்கப்பட்ட பொருட்கள் ஆகியவற்றுக்கான நஷ்டஈடு பற்றிய நியாயங்கள் கொடுக்கப்பட்டன. பரதேசியையும் விதவையையும் திக்கற்ற பிள்ளையையும் ஒடுக்கக்கூடாது, ஏழைகளிடம் வட்டி வாங்கக்கூடாது என்று கட்டளையிடப்பட்டது. முதற்பலன்களையும் முதற்பேறுகளையும் தேவனுக்குச் செலுத்த வேண்டும் என்றும் சொல்லப்பட்டது.",
    "Exodus 23": "பொய்ச்சாட்சி சொல்லாமலும், நியாயத்தைப் புரட்டாமலும், லஞ்சம் வாங்காமலும் இருக்க வேண்டும் என்று கட்டளையிடப்பட்டது. ஏழாம் வருஷ ஓய்வும், வாராந்திர ஓய்வுநாளும், வருஷத்தில் மூன்று பண்டிகைகளும் ஏற்படுத்தப்பட்டன. கர்த்தர் தம்முடைய தூதனை அவர்களுக்கு முன்பாக அனுப்பி, கானானியரைக் கொஞ்சம் கொஞ்சமாகத் துரத்தி, தேசத்தைக் கொடுப்பதாக வாக்களித்தார்.",
    "Exodus 24": "மோசே கர்த்தருடைய வார்த்தைகளை ஜனங்களுக்குச் சொன்னபோது, 'கர்த்தர் சொன்னபடியெல்லாம் செய்வோம்' என்றார்கள்; மோசே உடன்படிக்கையின் இரத்தத்தை அவர்கள்மேல் தெளித்தான். மோசே, ஆரோன், நாதாப், அபியூ, இஸ்ரவேலின் மூப்பரில் எழுபது பேர் மலையில் ஏறி இஸ்ரவேலின் தேவனைத் தரிசித்தார்கள். மோசே மேகத்துக்குள் பிரவேசித்து, நாற்பது நாள் இரவும் பகலும் மலையில் இருந்தான்.",
    "Exodus 25": "ஆசரிப்புக்கூடாரத்துக்காக ஜனங்கள் மனப்பூர்வமாகக் காணிக்கை கொண்டுவர வேண்டும் என்று கர்த்தர் சொன்னார்; 'நான் அவர்கள் நடுவிலே வாசம்பண்ணும்படி எனக்கு ஒரு பரிசுத்த ஸ்தலத்தை உண்டாக்குவார்களாக' என்றார். உடன்படிக்கைப் பெட்டி, கிருபாசனம், கேருபீன்கள் ஆகியவற்றின் அளவுகள் கொடுக்கப்பட்டன. சமுகத்தப்ப மேஜையும் பொன் குத்துவிளக்கும் மலையில் காண்பிக்கப்பட்ட மாதிரியின்படியே செய்யப்பட வேண்டும்.",
    "Exodus 26": "வாசஸ்தலத்தின் மெல்லிய பஞ்சுநூல் மூடுதிரைகள், ஆட்டுமயிர்த் தொங்கல்கள், மேல் மூடிகள் பற்றிய விவரங்கள் கொடுக்கப்பட்டன. அதின் பலகைகள், வெள்ளிப் பாதங்கள், தாழ்ப்பாள்கள் ஆகியவற்றின் அமைப்பு சொல்லப்பட்டது. பரிசுத்த ஸ்தலத்தையும் மகா பரிசுத்த ஸ்தலத்தையும் பிரிக்கும் கேருபீன்கள் சித்திரிக்கப்பட்ட திரைச்சீலையும் விவரிக்கப்பட்டுள்ளது.",
    "Exodus 27": "சீத்திம் மரத்தால் செய்து வெண்கலம் பொதிந்த தகனபலிபீடம் செய்யப்பட வேண்டும் என்று கட்டளையிடப்பட்டது. வாசஸ்தலத்தைச் சுற்றியுள்ள பிராகாரம், அதன் தொங்குதிரைகள், வாசல் ஆகியவற்றின் அளவுகள் கொடுக்கப்பட்டன. குத்துவிளக்கு எப்போதும் எரிந்துகொண்டிருக்கும்படி, இஸ்ரவேலர் இடித்துப் பிழிந்த தெளிவான ஒலிவ எண்ணெயைக் கொண்டுவர வேண்டும்.",
    "Exodus 28": "ஆரோனும் அவன் குமாரரும் ஆசாரிய ஊழியத்துக்குப் பிரித்தெடுக்கப்பட்டார்கள். ஏபோத், மார்ப்பதக்கம், அங்கி, தலைப்பாகை உட்பட ஆசாரியனுக்குரிய மகிமையும் அலங்காரமுமான பரிசுத்த வஸ்திரங்கள் விவரிக்கப்பட்டுள்ளன. மார்ப்பதக்கத்தில் இஸ்ரவேலின் பன்னிரண்டு கோத்திரங்களின் பேர்களும், தலைப்பாகையின் பொற்பட்டத்தில் 'கர்த்தருக்குப் பரிசுத்தம்' என்றும் பொறிக்கப்பட வேண்டும்.",
    "Exodus 29": "ஆரோனையும் அவன் குமாரரையும் பலிகளாலும் அபிஷேகத் தைலத்தாலும் ஏழு நாள் பிரதிஷ்டை செய்யும் முறை கொடுக்கப்பட்டது. தினமும் காலையிலும் மாலையிலும் ஒவ்வொரு ஆட்டுக்குட்டியை நித்திய தகனபலியாகச் செலுத்த வேண்டும். 'நான் இஸ்ரவேல் புத்திரரின் நடுவே வாசம்பண்ணி, அவர்களுக்குத் தேவனாயிருப்பேன்' என்று கர்த்தர் வாக்களித்தார்.",
    "Exodus 30": "தூபங்காட்டும் பொற்பீடம் செய்யப்பட வேண்டும் என்றும், பாவநிவிர்த்தியின் பணமாக ஒவ்வொருவரும் அரைச்சேக்கல் கொடுக்க வேண்டும் என்றும் கட்டளையிடப்பட்டது. ஆசாரியர் கைகால் கழுவ வெண்கலத் தொட்டி செய்யப்பட வேண்டும். பரிசுத்த அபிஷேகத் தைலமும் தூபவர்க்கமும் செய்யும் முறை கொடுக்கப்பட்டது; அவைகளைப் போன்றவற்றைச் சாதாரண உபயோகத்துக்குச் செய்யக்கூடாது.",
    "Exodus 31": "வாசஸ்தலத்தின் வேலைகளைச் செய்யக் கர்த்தர் பெசலெயேலை ஞானமும் விவேகமும் உள்ள தேவஆவியினால் நிரப்பி, அகோலியாபை அவனுக்குத் துணையாக நியமித்தார். ஓய்வுநாள் கர்த்தருக்கும் இஸ்ரவேலருக்கும் இடையிலான நித்திய உடன்படிக்கையின் அடையாளம் என்று சொல்லப்பட்டது. கர்த்தர் தம்முடைய விரலினால் எழுதப்பட்ட இரண்டு சாட்சிப் பலகைகளை மோசேக்குக் கொடுத்தார்.",
    "Exodus 32": "மோசே மலையிலிருந்து இறங்கத் தாமதித்ததால் ஜனங்கள் ஆரோனிடம் வற்புறுத்த, அவன் பொன் கன்றுக்குட்டியை வார்ப்பித்தான்; ஜனங்கள் அதை வணங்கிக் களியாட்டம் பண்ணினார்கள். கர்த்தர் அவர்களை அழிக்கப்போவதாகச் சொன்னபோது மோசே மன்றாடினான்; பின்பு இறங்கி வந்து அதைக் கண்டு, கற்பலகைகளை உடைத்து, கன்றுக்குட்டியைச் சுட்டெரித்தான். லேவியர் கர்த்தருடைய பக்கமாக நின்றார்கள்; 'இவர்கள் பாவத்தை மன்னியும்; இல்லாவிட்டால் நீர் எழுதின உம்முடைய புஸ்தகத்திலிருந்து என் பேரைக் கிறுக்கிப்போடும்' என்று மோசே பரிந்துபேசினான்.",
    "Exodus 33": "ஜனங்கள் வணங்காக் கழுத்துள்ளவர்கள் என்பதால் தாம் அவர்கள் நடுவே போவதில்லை என்று கர்த்தர் சொன்னார்; ஜனங்கள் துக்கித்துத் தங்கள் ஆபரணங்களைக் களைந்தார்கள். மோசே பாளயத்துக்கு வெளியே ஆசரிப்புக்கூடாரத்தில், சிநேகிதனோடு பேசுவதுபோலக் கர்த்தரோடு முகமுகமாய்ப் பேசினான். 'என் சமுகம் உனக்கு முன்பாகச் செல்லும்' என்று கர்த்தர் வாக்களித்தார்; தம்முடைய மகிமையைக் காண்பிக்கக் கேட்ட மோசேயைக் கன்மலையின் வெடிப்பில் வைத்துத் தம்முடைய மகிமையோடு கடந்துபோனார்.",
    "Exodus 34": "கர்த்தர் மறுபடியும் இரண்டு கற்பலகைகளில் எழுதிக் கொடுத்து, தம்மை இரக்கமும் கிருபையும் நீடிய சாந்தமும் மிகுந்த தயையும் சத்தியமுமுள்ள தேவன் என்று அறிவித்தார். அவர் உடன்படிக்கையைப் புதுப்பித்து, கானானியரோடு உடன்படிக்கை பண்ணாமலும் அந்நிய தேவர்களை வணங்காமலும் இருக்கக் கட்டளையிட்டார். மோசே மலையிலிருந்து இறங்கியபோது அவன் முகம் பிரகாசித்ததால், ஜனங்களோடு பேசினபின் முக்காடு போட்டுக்கொண்டான்.",
    "Exodus 35": "மோசே ஓய்வுநாள் கட்டளையை நினைப்பூட்டி, வாசஸ்தலத்துக்காகக் காணிக்கை கேட்டான். மனப்பூர்வமுள்ள ஆண்களும் பெண்களும் பொன், வெள்ளி, வெண்கலம், நூல், மரம், இரத்தினங்கள் ஆகியவற்றைக் கொண்டுவந்தார்கள்; ஞான இருதயமுள்ள ஸ்திரீகள் நூல் நூற்றார்கள். பெசலெயேலும் அகோலியாபும் வேலைகளைச் செய்யவும் மற்றவர்களுக்குக் கற்றுக்கொடுக்கவும் நியமிக்கப்பட்டார்கள்.",
    "Exodus 36": "ஜனங்கள் தேவைக்கு அதிகமாகக் காணிக்கை கொண்டுவந்ததால், இனி கொண்டுவர வேண்டாம் என்று மோசே பாளயமெங்கும் அறிவிக்கச் செய்தான். ஞானமுள்ள கலைஞர்கள் வாசஸ்தலத்தின் மூடுதிரைகளையும் தொங்கல்களையும் செய்தார்கள். பலகைகளும், பாதங்களும், திரைச்சீலையும், வாசல் தொங்குதிரையும் கர்த்தர் கட்டளையிட்டபடியே செய்யப்பட்டன.",
    "Exodus 37": "பெசலெயேல் சீத்திம் மரத்தால் உடன்படிக்கைப் பெட்டியைச் செய்து, பசும்பொன்னால் கிருபாசனத்தையும் இரண்டு கேருபீன்களையும் செய்தான். சமுகத்தப்ப மேஜையும், பொன் குத்துவிளக்கும் செய்யப்பட்டன. தூபபீடமும், பரிசுத்த அபிஷேகத் தைலமும், சுத்தமான சுகந்த தூபவர்க்கமும் செய்யப்பட்டன.",
    "Exodus 38": "தகனபலிபீடமும், ஆசரிப்புக்கூடார வாசலில் ஊழியம் செய்த ஸ்திரீகளின் வெண்கலக் கண்ணாடிகளால் வெண்கலத் தொட்டியும் செய்யப்பட்டன. பிராகாரத்தின் தொங்குதிரைகளும், தூண்களும், வாசலும் செய்யப்பட்டன. வாசஸ்தலத்துக்காகச் செலவான பொன், வெள்ளி, வெண்கலத்தின் கணக்கு எழுதப்பட்டது.",
    "Exodus 39": "ஆரோனுக்கு ஏபோத், மார்ப்பதக்கம், அங்கி, தலைப்பாகை, 'கர்த்தருக்குப் பரிசுத்தம்' என்று எழுதிய பொற்பட்டம் ஆகிய பரிசுத்த வஸ்திரங்கள் செய்யப்பட்டன. வேலைகளெல்லாம் முடிந்தபின் அவைகளை மோசேயிடம் கொண்டுவந்தார்கள். கர்த்தர் கட்டளையிட்டபடியே எல்லாம் செய்யப்பட்டதைக் கண்டு, மோசே அவர்களை ஆசீர்வதித்தான்.",
    "Exodus 40": "இரண்டாம் வருஷம் முதலாம் மாதம் முதல் தேதியில் மோசே வாசஸ்தலத்தை ஸ்தாபித்து, அதின் பொருட்களையெல்லாம் வைத்து, அபிஷேகம் பண்ணினான். ஆரோனும் அவன் குமாரரும் ஆசாரியர்களாகப் பிரதிஷ்டை செய்யப்பட்டார்கள். அப்பொழுது மேகம் ஆசரிப்புக்கூடாரத்தை மூடியது, கர்த்தருடைய மகிமை வாசஸ்தலத்தை நிரப்பியது; மேகம் எழும்பும்போதெல்லாம் இஸ்ரவேலர் பிரயாணம் புறப்பட்டார்கள்.",

    "Leviticus 1": "கர்த்தர் ஆசரிப்புக்கூடாரத்திலிருந்து மோசேயை அழைத்து, தகனபலியின் முறைமைகளைக் கொடுத்தார். மாடு, ஆடு அல்லது பறவைகளில் பழுதற்றதைச் செலுத்த வேண்டும்; காணிக்கை செலுத்துகிறவன் அதின் தலையின்மேல் தன் கையை வைக்க வேண்டும். ஆசாரியர் இரத்தத்தைப் பலிபீடத்தைச் சுற்றித் தெளித்து, முழுவதையும் கர்த்தருக்குச் சுகந்த வாசனையான தகனமாகத் தகிக்க வேண்டும்.",
    "Leviticus 2": "போஜனபலியாக மெல்லிய மாவோடு எண்ணெயும் தூபவர்க்கமும் சேர்த்துக் கொண்டுவர வேண்டும்; அதில் ஒரு பிடி ஞாபகக்குறியாகத் தகனிக்கப்பட்டு, மீதியானது ஆரோனுக்கும் அவன் குமாரருக்கும் உரியது. புளித்தமாவையும் தேனையும் கர்த்தருக்குத் தகனிக்கக்கூடாது. எல்லாப் போஜனபலிகளிலும் உன் தேவனுடைய உடன்படிக்கையின் உப்பைச் சேர்க்க வேண்டும்.",
    "Leviticus 3": "சமாதானபலியாக மாடு, செம்மறியாடு அல்லது வெள்ளாடுகளில் பழுதற்றதைச் செலுத்த வேண்டும். அதின் கொழுப்பும் குண்டிக்காய்களும் பலிபீடத்தின்மேல் கர்த்தருக்குத் தகனிக்கப்பட வேண்டும். கொழுப்பெல்லாம் கர்த்தருடையது; கொழுப்பையும் இரத்தத்தையும் புசிக்கக்கூடாது என்பது தலைமுறைதோறும் நித்திய கட்டளை.",
    "Leviticus 4": "அறியாமையினால் செய்த பாவத்துக்காகச் செலுத்த வேண்டிய பாவநிவாரணபலியின் முறைகள் கொடுக்கப்பட்டன. அபிஷேகம் பெற்ற ஆசாரியன், முழுச்சபை, அதிபதி, சாதாரண ஜனங்களில் ஒருவன் என ஒவ்வொருவருக்கும் உரிய பலி வெவ்வேறாகச் சொல்லப்பட்டுள்ளது. ஆசாரியன் அவர்களுக்காகப் பாவநிவிர்த்தி செய்யும்போது, அது அவர்களுக்கு மன்னிக்கப்படும்.",
    "Leviticus 5": "சாட்சி சொல்லாதிருத்தல், தீட்டானதைத் தொடுதல், யோசனையின்றி ஆணையிடுதல் போன்ற பாவங்களை அறிக்கையிட்டுப் பலி செலுத்த வேண்டும். ஆட்டுக்குட்டி கொடுக்க வசதியில்லாதவன் இரண்டு காட்டுப்புறாக்களையோ, மெல்லிய மாவையோ கொண்டுவரலாம். கர்த்தருக்குப் பரிசுத்தமானவைகளில் குற்றம் செய்தவன், ஐந்தில் ஒரு பங்கு கூட்டிக் கொடுத்து, குற்றநிவாரணபலி செலுத்த வேண்டும்.",
    "Leviticus 6": "பிறனை வஞ்சித்தல், திருடுதல், பொய்யாணையிடுதல் போன்ற குற்றம் செய்தவன், முழுவதையும் ஐந்தில் ஒரு பங்கு கூட்டித் திரும்பக் கொடுத்து, குற்றநிவாரணபலி செலுத்த வேண்டும். பலிபீடத்தின்மேல் அக்கினி அவிந்துபோகாமல் எப்போதும் எரிந்துகொண்டிருக்க வேண்டும். தகனபலி, போஜனபலி, பாவநிவாரணபலி பற்றி ஆசாரியருக்குரிய பிரமாணங்கள் கொடுக்கப்பட்டன.",
    "Leviticus 7": "குற்றநிவாரணபலி மற்றும் சமாதானபலியின் பிரமாணங்கள் கொடுக்கப்பட்டன; சமாதானபலி ஸ்தோத்திரபலியாகவோ, பொருத்தனைபலியாகவோ, உற்சாகபலியாகவோ செலுத்தப்படலாம். தீட்டுள்ளவன் சமாதானபலியின் மாம்சத்தைப் புசித்தால் ஜனத்திலிருந்து அறுப்புண்டுபோவான். அசைவாட்டும் மார்க்கண்டமும் ஏறெடுக்கும் முன்னந்தொடையும் ஆசாரியருக்கு நித்திய பங்காகக் கொடுக்கப்பட்டன.",
    "Leviticus 8": "மோசே சபைக்கு முன்பாக ஆரோனையும் அவன் குமாரரையும் ஜலத்தினால் கழுவி, பரிசுத்த வஸ்திரங்களை உடுத்தி, அபிஷேகத் தைலத்தால் அபிஷேகம் பண்ணினான். பாவநிவாரணக் காளையும், தகனபலிக் கடாவும், பிரதிஷ்டையின் கடாவும் செலுத்தப்பட்டன; பிரதிஷ்டைக் கடாவின் இரத்தம் அவர்கள் வலதுகாது மடலிலும், வலதுகைப் பெருவிரலிலும், வலதுகால் பெருவிரலிலும் பூசப்பட்டது. அவர்கள் ஏழு நாள் ஆசரிப்புக்கூடாரத்தின் வாசலில் தங்கியிருந்தார்கள்.",
    "Leviticus 9": "எட்டாம் நாளில் ஆரோன் தனக்காகவும் ஜனங்களுக்காகவும் பலிகளைச் செலுத்தி, ஜனங்களை ஆசீர்வதித்தான். கர்த்தருடைய மகிமை ஜனங்களெல்லாருக்கும் காணப்பட்டது. கர்த்தருடைய சந்நிதியிலிருந்து அக்கினி புறப்பட்டுப் பலிபீடத்தின்மேல் இருந்தவைகளைப் பட்சித்தது; ஜனங்கள் அதைக் கண்டு ஆரவாரித்து முகங்குப்புற விழுந்தார்கள்.",
    "Leviticus 10": "ஆரோனின் குமாரராகிய நாதாபும் அபியூவும் கர்த்தர் கட்டளையிடாத அந்நிய அக்கினியைக் கொண்டுவந்ததால், கர்த்தருடைய சந்நிதியிலிருந்து அக்கினி புறப்பட்டு அவர்களைப் பட்சித்தது. 'என்னிடத்தில் சேருகிறவர்களுக்குள்ளே நான் பரிசுத்தம் பண்ணப்படுவேன்' என்று கர்த்தர் சொன்னார்; ஆரோன் மௌனமாயிருந்தான். ஆசாரியர் ஆசரிப்புக்கூடாரத்துக்குள் பிரவேசிக்கும்போது மதுபானம் குடிக்காமல், பரிசுத்தமானதற்கும் பரிசுத்தமல்லாததற்கும் வித்தியாசம் பண்ண வேண்டும் என்று கட்டளையிடப்பட்டது.",
    "Leviticus 11": "புசிக்கத்தக்க சுத்தமான மிருகங்களும் புசிக்கக்கூடாத தீட்டான மிருகங்களும் வேறுபடுத்திக் காட்டப்பட்டன: விரிகுளம்புள்ளதும் அசைபோடுகிறதுமானவை சுத்தமானவை. ஜலத்தில் செட்டையும் செதிளுமுள்ளவை மட்டும் புசிக்கத்தக்கவை; தீட்டான பறவைகளும் ஊரும் பிராணிகளும் பட்டியலிடப்பட்டுள்ளன. 'நான் பரிசுத்தர், ஆகையால் நீங்களும் பரிசுத்தராயிருப்பீர்களாக' என்று கர்த்தர் சொன்னார்.",
    "Leviticus 12": "பிள்ளை பெற்ற ஸ்திரீயின் சுத்திகரிப்பு நாட்கள் பற்றிய பிரமாணம் கொடுக்கப்பட்டது; ஆண்பிள்ளைக்கு எட்டாம் நாளில் விருத்தசேதனம் பண்ணப்பட வேண்டும். சுத்திகரிப்பின் நாட்கள் முடிந்தபின், அவள் ஒரு ஆட்டுக்குட்டியைத் தகனபலியாகவும் ஒரு புறாவைப் பாவநிவாரணபலியாகவும் கொண்டுவர வேண்டும். ஆட்டுக்குட்டிக்கு வசதியில்லாவிட்டால் இரண்டு காட்டுப்புறாக்களையோ புறாக்குஞ்சுகளையோ கொண்டுவரலாம்.",
    "Leviticus 13": "தோலில் உண்டாகும் குஷ்டரோகத்தை ஆசாரியன் பரிசோதித்து, அது தீட்டா சுத்தமா என்று தீர்மானிக்க வேண்டும்; சந்தேகமானால் ஏழு நாள் அடைத்து வைக்க வேண்டும். குஷ்டரோகி தன் வஸ்திரத்தைக் கிழித்து, 'தீட்டு, தீட்டு' என்று சத்தமிட்டு, பாளயத்துக்குப் புறம்பே தனியாக வாசம்பண்ண வேண்டும். வஸ்திரங்களில் உண்டாகும் பூசணம் பற்றிய பிரமாணமும் கொடுக்கப்பட்டது.",
    "Leviticus 14": "குஷ்டம் நீங்கினவனின் சுத்திகரிப்புக்காக இரண்டு பறவைகள் கொண்டுவரப்பட வேண்டும்; ஒன்று கொல்லப்பட்டு, மற்றது அதின் இரத்தத்தில் தோய்க்கப்பட்டு வெளியிலே விடப்படும். எட்டாம் நாளில் பலிகள் செலுத்தப்பட்டு, இரத்தமும் எண்ணெயும் அவன் வலதுகாது மடலிலும் கைகால் பெருவிரல்களிலும் பூசப்படும். வீடுகளில் உண்டாகும் பூசணத்தைச் சோதித்துச் சுத்திகரிக்கும் முறையும் சொல்லப்பட்டுள்ளது.",
    "Leviticus 15": "ஆண் பெண் சரீரத்திலிருந்து உண்டாகும் கழிவினால் ஏற்படும் தீட்டைப் பற்றிய பிரமாணங்கள் கொடுக்கப்பட்டன. தீட்டுள்ளவன் தொட்டவைகளும் படுத்த படுக்கையும் தீட்டாகும்; அவைகளைத் தொட்டவர்கள் குளித்து வஸ்திரங்களைத் துவைக்க வேண்டும். தம்முடைய வாசஸ்தலத்தைத் தீட்டுப்படுத்தி அவர்கள் சாகாதபடிக்கு, இஸ்ரவேலரைத் தீட்டுக்கு விலக்கி வைக்கக் கர்த்தர் கட்டளையிட்டார்.",
    "Leviticus 16": "பாவநிவிர்த்தி நாளில் மட்டும் ஆரோன் வருஷத்துக்கு ஒருமுறை திரைக்கு உட்புறமான மகா பரிசுத்த ஸ்தலத்துக்குள் பிரவேசிக்க வேண்டும். இரண்டு வெள்ளாட்டுக்கடாக்களில் ஒன்று பாவநிவாரணபலியாகச் செலுத்தப்படும்; மற்றதின் தலையின்மேல் இஸ்ரவேலரின் அக்கிரமங்களையெல்லாம் அறிக்கையிட்டு, அதைப் போக்காடாக வனாந்தரத்துக்கு அனுப்ப வேண்டும். ஏழாம் மாதம் பத்தாம் தேதியில் ஆத்துமாக்களைத் தாழ்மைப்படுத்தி ஓய்ந்திருப்பது நித்திய கட்டளை.",
    "Leviticus 17": "எல்லாப் பலிகளையும் ஆசரிப்புக்கூடாரத்தின் வாசலுக்கே கொண்டுவர வேண்டும்; வெளியிலே பேய்களுக்குப் பலியிடக்கூடாது. 'மாம்சத்தின் உயிர் இரத்தத்தில் இருக்கிறது'; இரத்தமே ஆத்துமாவுக்காகப் பாவநிவிர்த்தி செய்கிறது. ஆகையால் இஸ்ரவேலரும் அவர்களுக்குள் தங்கும் அந்நியரும் இரத்தத்தைப் புசிக்கக்கூடாது.",
    "Leviticus 18": "எகிப்தியர் மற்றும் கானானியரின் செய்கைகளின்படி செய்யாமல், கர்த்தருடைய நியாயங்களின்படி நடக்க வேண்டும். நெருங்கிய உறவினரோடு முறைகேடான உறவு, விபசாரம், மோளேகுக்குப் பிள்ளைகளைப் பலியிடுதல், ஆணோடு ஆண் சயனித்தல், மிருகப்புணர்ச்சி ஆகியவை தடை செய்யப்பட்டன. இவைகளினால் தீட்டுப்பட்ட தேசம் தன் குடிகளைக் கக்கிப்போட்டது என்று கர்த்தர் எச்சரித்தார்.",
    "Leviticus 19": "'உங்கள் தேவனாகிய கர்த்தராயிருக்கிற நான் பரிசுத்தர், ஆகையால் நீங்களும் பரிசுத்தராயிருப்பீர்களாக' என்று கர்த்தர் சொன்னார். தாய் தகப்பனுக்குப் பயப்படுதல், ஓய்வுநாளை ஆசரித்தல், அறுப்பில் ஏழைகளுக்கு விட்டுவைத்தல், கூலியைத் தாமதியாதிருத்தல், நீதியான தராசு வைத்திருத்தல் போன்ற கட்டளைகள் கொடுக்கப்பட்டன. 'உன்னிடத்தில் நீ அன்புகூருவதுபோல் பிறனிடத்திலும் அன்புகூருவாயாக' என்றும், அந்நியனிடத்திலும் அப்படியே அன்புகூர வேண்டும் என்றும் சொல்லப்பட்டது.",
    "Leviticus 20": "மோளேகுக்குப் பிள்ளைகளைக் கொடுத்தல், அஞ்சனக்காரரிடம் போதல், தாய் தகப்பனைச் சபித்தல், விபசாரம் போன்றவற்றுக்கு மரணதண்டனை விதிக்கப்பட்டது. 'உங்களைப் பரிசுத்தமாக்குகிற கர்த்தர் நானே' என்று சொல்லி, தம்முடைய கட்டளைகளைக் கைக்கொள்ளச் சொன்னார். தம்முடையவர்களாயிருக்கும்படி கர்த்தர் இஸ்ரவேலரை மற்ற ஜனங்களிலிருந்து பிரித்தெடுத்தார்.",
    "Leviticus 21": "ஆசாரியர் பரிசுத்தமாயிருக்க வேண்டும்; நெருங்கிய உறவினர் தவிர மற்றப் பிணங்களினால் தங்களைத் தீட்டுப்படுத்தக்கூடாது. பிரதான ஆசாரியன் தன் ஜனத்திலுள்ள கன்னிகையை மாத்திரம் மணக்க வேண்டும். ஊனமுள்ள ஆரோனின் சந்ததியார் பலி செலுத்தக்கூடாது; ஆனாலும் பரிசுத்தமானவைகளைப் புசிக்கலாம்.",
    "Leviticus 22": "தீட்டுள்ள ஆசாரியன் பரிசுத்த வஸ்துக்களைப் புசிக்கக்கூடாது; அந்நியனும் புசிக்கக்கூடாது, ஆனால் ஆசாரியன் பணம் கொடுத்துக் கொண்ட அடிமை புசிக்கலாம். கர்த்தருக்குச் செலுத்தும் பலிகள் பழுதற்றவைகளாக இருக்க வேண்டும். 'என் பரிசுத்த நாமத்தைப் பரிசுத்தக்குலைச்சலாக்காதிருங்கள்' என்று கர்த்தர் கட்டளையிட்டார்.",
    "Leviticus 23": "கர்த்தருடைய பண்டிகைகள் விவரிக்கப்பட்டுள்ளன: ஓய்வுநாள், பஸ்கா, புளிப்பில்லா அப்பப் பண்டிகை, முதற்பலன், ஏழு வாரங்களுக்குப் பின் வரும் வாரங்களின் பண்டிகை, எக்காளப் பண்டிகை, பாவநிவிர்த்தி நாள், கூடாரப்பண்டிகை. அறுப்பு அறுக்கும்போது வயலின் ஓரங்களை ஏழைக்கும் பரதேசிக்கும் விட்டுவைக்க வேண்டும். எகிப்திலிருந்து கொண்டுவந்ததை நினைக்கும்படி, கூடாரப்பண்டிகையில் ஏழு நாள் கூடாரங்களில் வாசம்பண்ண வேண்டும்.",
    "Leviticus 24": "குத்துவிளக்குக்குத் தெளிவான ஒலிவ எண்ணெயும், ஓய்வுநாள்தோறும் பரிசுத்த மேஜையின்மேல் பன்னிரண்டு அப்பங்களும் வைக்கப்பட வேண்டும். ஒரு இஸ்ரவேல் ஸ்திரீயின் குமாரன் கர்த்தருடைய நாமத்தைத் தூஷித்ததால், சபையார் அவனைக் கல்லெறிந்து கொன்றார்கள். கொலைக்கும் சேதத்துக்குமான நியாயங்கள் கொடுக்கப்பட்டன; பரதேசிக்கும் சுதேசிக்கும் ஒரே நியாயம் இருக்க வேண்டும்.",
    "Leviticus 25": "ஏழாம் வருஷம் நிலத்துக்கு ஓய்வுவருஷமாக இருக்க வேண்டும். ஐம்பதாம் வருஷம் யூபிலி வருஷம்; அதில் தேசமெங்கும் விடுதலை கூறப்பட்டு, விற்கப்பட்ட நிலங்கள் சுதந்தரத்தாருக்குத் திரும்ப வேண்டும்; 'தேசம் என்னுடையது, நீங்கள் என்னிடத்தில் பரதேசிகள்' என்று கர்த்தர் சொன்னார். ஏழை சகோதரனுக்கு வட்டியில்லாமல் உதவ வேண்டும்; இஸ்ரவேலர் கர்த்தருடைய ஊழியக்காரர் என்பதால் அடிமைகளாக விற்கப்படக்கூடாது.",
    "Leviticus 26": "கட்டளைகளுக்குக் கீழ்ப்படிந்தால் மழை, விளைச்சல், சமாதானம், சத்துருக்கள்மேல் ஜெயம் ஆகிய ஆசீர்வாதங்கள் கிடைக்கும்; 'நான் உங்கள் நடுவிலே உலாவி, உங்கள் தேவனாயிருப்பேன்' என்று கர்த்தர் வாக்களித்தார். கீழ்ப்படியாவிட்டால் நோய், பஞ்சம், தோல்வி, தேசங்களுக்குள் சிதறடிக்கப்படுதல் ஆகியவை வரும். ஆனாலும் அவர்கள் தங்கள் அக்கிரமத்தை அறிக்கையிட்டுத் தாழ்த்தினால், யாக்கோபு, ஈசாக்கு, ஆபிரகாமோடு பண்ணின உடன்படிக்கையை நினைப்பேன் என்றார்.",
    "Leviticus 27": "கர்த்தருக்குப் பொருத்தனை பண்ணப்பட்ட மனுஷர், மிருகங்கள், வீடுகள், நிலங்கள் ஆகியவற்றின் மதிப்பும் அவைகளை மீட்கும் முறையும் கொடுக்கப்பட்டன. கர்த்தருக்குச் சாபத்தீடாக நேர்ந்துகொள்ளப்பட்டவை மீட்கப்படக்கூடாது. நிலத்தின் தசமபாகமும் மந்தையின் தசமபாகமும் கர்த்தருக்குப் பரிசுத்தமானவை; இவைகளே கர்த்தர் சீனாய் மலையில் மோசேக்குக் கொடுத்த கற்பனைகள்.",

    "Numbers 1": "இஸ்ரவேலர் எகிப்திலிருந்து புறப்பட்ட இரண்டாம் வருஷத்தில், சீனாய் வனாந்தரத்தில், இருபது வயதுமுதல் யுத்தத்துக்குப் போகத்தக்க ஆண்களைக் கோத்திரவாரியாக எண்ணும்படி கர்த்தர் மோசேக்குக் கட்டளையிட்டார். எண்ணப்பட்டவர்கள் மொத்தம் 6,03,550 பேர். லேவியர் அவர்களோடு எண்ணப்படாமல், வாசஸ்தலத்தின் ஊழியத்துக்கு நியமிக்கப்பட்டு, அதைச் சுற்றிப் பாளயமிறங்கினார்கள்.",
    "Numbers 2": "பன்னிரண்டு கோத்திரங்களும் தங்கள் தங்கள் கொடிகளின்கீழ் ஆசரிப்புக்கூடாரத்தைச் சுற்றி நான்கு பக்கங்களிலும் பாளயமிறங்க வேண்டும் என்று கட்டளையிடப்பட்டது. கிழக்கே யூதாவும், தெற்கே ரூபனும், மேற்கே எப்பிராயீமும், வடக்கே தாணும் தலைமை தாங்கின. பிரயாணம் செய்யும்போதும் அதே ஒழுங்கின்படி புறப்பட்டார்கள்.",
    "Numbers 3": "ஆரோனின் குமாரராகிய எலெயாசாரும் இத்தாமாரும் ஆசாரிய ஊழியம் செய்தார்கள்; லேவியர் ஆசாரியருக்கு உதவியாக நியமிக்கப்பட்டார்கள். இஸ்ரவேலின் முதற்பேறுகளுக்குப் பதிலாகக் கர்த்தர் லேவியரைத் தமக்கென்று எடுத்துக்கொண்டார். கெர்சோன், கோகாத், மெராரி வம்சங்களின் பொறுப்புகள் கொடுக்கப்பட்டன; லேவியரைவிட அதிகமான 273 முதற்பேறுகள் தலைக்கு ஐந்து சேக்கல் கொடுத்து மீட்கப்பட்டார்கள்.",
    "Numbers 4": "முப்பது வயதுமுதல் ஐம்பது வயதுவரையுள்ள லேவியர் ஊழியத்துக்காக எண்ணப்பட்டார்கள். ஆரோனும் அவன் குமாரரும் மகா பரிசுத்தமான பொருட்களை மூடின பின்பு, கோகாத்தியர் அவைகளைச் சுமக்க வேண்டும்; அவைகளைத் தொட்டால் சாவார்கள். கெர்சோனியர் திரைகளையும் மூடிகளையும், மெராரியர் பலகைகளையும் தூண்களையும் சுமந்தார்கள்.",
    "Numbers 5": "குஷ்டரோகிகளும் தீட்டுள்ளவர்களும் பாளயத்துக்குப் புறம்பே வைக்கப்பட வேண்டும். பிறனுக்குக் குற்றம் செய்தவன் தன் பாவத்தை அறிக்கையிட்டு, ஐந்தில் ஒரு பங்கு கூட்டித் திரும்பக் கொடுக்க வேண்டும். தன் மனைவியைக் குறித்துப் புருஷனுக்கு எரிச்சலின் சந்தேகம் உண்டானால், சாபத்தைக் கொண்டுவரும் கசப்பான ஜலத்தினால் அவளைச் சோதிக்கும் முறை கொடுக்கப்பட்டது.",
    "Numbers 6": "நசரேய விரதம் பண்ணுகிறவன் திராட்சரசமும் திராட்சப்பழமும் விலக்கி, தலையில் சவரகன் கத்தி படாமலும், பிணத்தண்டை போகாமலும் இருக்க வேண்டும். விரதநாட்கள் முடிந்ததும் பலிகளைச் செலுத்தி, தன் தலைமயிரைச் சிரைக்க வேண்டும். ஆரோனும் அவன் குமாரரும் 'கர்த்தர் உன்னை ஆசீர்வதித்து உன்னைக் காக்கக்கடவர்' என்று தொடங்கும் ஆசீர்வாதத்தினால் இஸ்ரவேலரை ஆசீர்வதிக்க வேண்டும்.",
    "Numbers 7": "வாசஸ்தலம் அபிஷேகம் பண்ணப்பட்ட நாளில் இஸ்ரவேலின் பிரபுக்கள் ஆறு வண்டிகளையும் பன்னிரண்டு மாடுகளையும் லேவியரின் ஊழியத்துக்காகக் கொண்டுவந்தார்கள். பன்னிரண்டு நாட்களில் ஒவ்வொரு கோத்திரப் பிரபுவும் ஒரே மாதிரியான காணிக்கையைப் பலிபீடப் பிரதிஷ்டைக்காகச் செலுத்தினான். மோசே ஆசரிப்புக்கூடாரத்தில் பேசப் பிரவேசித்தபோது, கிருபாசனத்தின்மேல் இரண்டு கேருபீன்களின் நடுவிலிருந்து தன்னோடு பேசுகிற சத்தத்தைக் கேட்டான்.",
    "Numbers 8": "கர்த்தர் கட்டளையிட்டபடி ஆரோன் குத்துவிளக்கின் ஏழு அகல்களையும் ஏற்றினான். லேவியர் சுத்திகரிக்கப்பட்டு, இஸ்ரவேலர் அவர்கள்மேல் கைகளை வைத்து, அவர்கள் அசைவாட்டும் காணிக்கையாகக் கர்த்தருக்குச் செலுத்தப்பட்டார்கள். லேவியர் இருபத்தைந்து வயதுமுதல் ஐம்பது வயதுவரை ஊழியம் செய்ய வேண்டும் என்று கட்டளையிடப்பட்டது.",
    "Numbers 9": "இரண்டாம் வருஷத்தில் இஸ்ரவேலர் சீனாய் வனாந்தரத்தில் பஸ்காவை ஆசரித்தார்கள்; பிணத்தால் தீட்டுப்பட்டவர்களும் தூரப்பிரயாணத்தில் இருந்தவர்களும் இரண்டாம் மாதத்தில் ஆசரிக்கலாம் என்று கட்டளையிடப்பட்டது. மேகம் பகலில் வாசஸ்தலத்தை மூடியிருந்து, இரவில் அக்கினித் தோற்றமாயிருந்தது. மேகம் எழும்பும்போது பிரயாணம் புறப்பட்டு, தங்கும்போது பாளயமிறங்கி, கர்த்தருடைய கட்டளையின்படியே நடந்தார்கள்.",
    "Numbers 10": "சபையைக் கூட்டவும், பிரயாணம் புறப்படவும், யுத்தத்துக்கும் பண்டிகைகளுக்கும் ஊதும்படி இரண்டு வெள்ளி எக்காளங்கள் செய்யப்பட்டன. இரண்டாம் வருஷம் இரண்டாம் மாதம் இருபதாம் தேதியில் மேகம் எழும்பியது; இஸ்ரவேலர் சீனாயிலிருந்து பாரான் வனாந்தரத்துக்குப் புறப்பட்டார்கள். உடன்படிக்கைப் பெட்டி அவர்களுக்கு முன்பாகச் சென்றது; பெட்டி புறப்படும்போது 'கர்த்தாவே, எழுந்தருளும்' என்று மோசே சொல்லுவான்.",
    "Numbers 11": "ஜனங்கள் முறுமுறுத்ததால் கர்த்தருடைய அக்கினி பாளயத்தின் கடையாந்தரத்தில் பற்றியெரிந்தது; அந்த இடம் தபேரா எனப்பட்டது. ஜனங்கள் மாம்சத்துக்காக அழுதபோது, இந்தப் பாரத்தைத் தனியாகச் சுமக்க முடியாது என்று மோசே முறையிட்டான்; கர்த்தர் தம்முடைய ஆவியை எழுபது மூப்பர்மேலும் வைத்தார். கர்த்தர் காடைகளை அனுப்பினார்; ஆனால் இச்சித்த ஜனங்களை மகா வாதையால் அடித்தார், அந்த இடம் கிப்ரோத் அத்தாவா எனப்பட்டது.",
    "Numbers 12": "மோசே மணந்த எத்தியோப்பிய ஸ்திரீயினிமித்தம் மிரியாமும் ஆரோனும் மோசேக்கு விரோதமாய்ப் பேசினார்கள். மோசே பூமியிலுள்ள மனுஷரெல்லாரிலும் மிகுந்த சாந்தகுணமுள்ளவன்; 'அவனோடே நான் முகமுகமாய்ப் பேசுகிறேன்' என்று கர்த்தர் சொன்னார். மிரியாம் குஷ்டரோகியானாள்; மோசே மன்றாடினதால், அவள் ஏழு நாள் பாளயத்துக்குப் புறம்பே இருந்தபின் மறுபடியும் சேர்த்துக்கொள்ளப்பட்டாள்.",
    "Numbers 13": "கர்த்தருடைய கட்டளைப்படி மோசே ஒவ்வொரு கோத்திரத்திலிருந்தும் ஒருவனாகப் பன்னிரண்டு பேரைக் கானான் தேசத்தை வேவுபார்க்க அனுப்பினான். அவர்கள் நாற்பது நாளுக்குப் பின் எஸ்கோல் பள்ளத்தாக்கின் திராட்சக்குலையோடு திரும்பி, தேசம் பாலும் தேனும் ஓடுகிறது, ஆனால் அங்குள்ள ஜனங்கள் பலவான்களும் இராட்சதருமாயிருக்கிறார்கள் என்றார்கள். 'நாம் உடனே போய் அதைச் சுதந்தரித்துக்கொள்வோம்' என்று காலேப் சொன்னான்; மற்றவர்களோ துர்ச்செய்தியைப் பரப்பினார்கள்.",
    "Numbers 14": "ஜனங்கள் இராமுழுவதும் அழுது, ஒரு தலைவனை ஏற்படுத்தி எகிப்துக்குத் திரும்பிப்போக நினைத்தார்கள். யோசுவாவும் காலேபும் 'கர்த்தருக்கு விரோதமாகக் கலகம் பண்ணாதிருங்கள்; அந்த ஜனங்களுக்குப் பயப்படாதிருங்கள்' என்றார்கள்; மோசே பரிந்துபேசினதால் கர்த்தர் மன்னித்தார். ஆனாலும் இருபது வயதுக்கு மேற்பட்டவர்கள் காலேபும் யோசுவாவும் தவிர வனாந்தரத்தில் விழுவார்கள் என்றும், நாற்பது வருஷம் அலைவார்கள் என்றும் தீர்ப்பானது; கட்டளையை மீறிப் போனவர்கள் சத்துருக்களால் முறியடிக்கப்பட்டார்கள்.",
    "Numbers 15": "கானான் தேசத்தில் பிரவேசித்தபின் செலுத்த வேண்டிய போஜனபலி, பானபலி முறைகள் கொடுக்கப்பட்டன. அறியாமல் செய்த பாவத்துக்குப் பாவநிவிர்த்தி உண்டு; துணிகரமாய்ப் பாவம் செய்கிறவனோ ஜனத்திலிருந்து அறுப்புண்டுபோவான். ஓய்வுநாளில் விறகு பொறுக்கினவன் கல்லெறியப்பட்டான்; கர்த்தருடைய கற்பனைகளை நினைக்கும்படி வஸ்திரங்களின் தொங்கல்களில் நீலநாடா கட்ட வேண்டும் என்று கட்டளையிடப்பட்டது.",
    "Numbers 16": "கோராகும், தாத்தானும், அபிராமும் சபையின் 250 பிரபுக்களோடு மோசேக்கும் ஆரோனுக்கும் விரோதமாக எழும்பினார்கள். பூமி தன் வாயைத் திறந்து கோராகின் கூட்டத்தையும் அவர்கள் வீடுகளையும் விழுங்கியது; தூபங்காட்டின 250 பேரையும் அக்கினி பட்சித்தது. மறுநாள் ஜனங்கள் முறுமுறுத்ததால் வாதை தொடங்கியது; ஆரோன் தூபகலசத்தோடு மரித்தோருக்கும் உயிரோடிருப்போருக்கும் நடுவே நின்றபோது வாதை நின்றது.",
    "Numbers 17": "பன்னிரண்டு கோத்திரங்களுக்காகப் பன்னிரண்டு கோல்கள் ஆசரிப்புக்கூடாரத்தில் சாட்சிப் பெட்டிக்கு முன்பாக வைக்கப்பட்டன. மறுநாளில் லேவி கோத்திரத்துக்குரிய ஆரோனின் கோல் துளிர்த்து, பூத்து, வாதுமைப்பழங்களைக் கொடுத்தது. கலகக்காரருக்கு அடையாளமாக அந்தக் கோல் சாட்சிப் பெட்டிக்கு முன்பாக வைக்கப்பட்டது.",
    "Numbers 18": "ஆசாரியரும் லேவியரும் பரிசுத்த ஸ்தலத்தின் ஊழியத்தையும் அதின் குற்றத்தையும் சுமக்க வேண்டும். ஆசாரியருக்குப் பலிகளிலும் முதற்பலன்களிலும் பங்கு கொடுக்கப்பட்டது; 'நானே உன் பங்கும் உன் சுதந்தரமுமாயிருக்கிறேன்' என்று கர்த்தர் ஆரோனிடம் சொன்னார். இஸ்ரவேலரின் தசமபாகம் லேவியருக்குக் கொடுக்கப்பட்டது; லேவியரும் தாங்கள் பெற்றதில் தசமபாகத்தைக் கர்த்தருக்குச் செலுத்த வேண்டும்.",
    "Numbers 19": "பழுதற்ற சிவப்புக் கிடாரியைப் பாளயத்துக்குப் புறம்பே சுட்டெரித்து, அதின் சாம்பலைத் தீட்டுக்கழிக்கும் ஜலத்துக்காக வைக்க வேண்டும். பிணத்தைத் தொட்டவன் ஏழு நாள் தீட்டாயிருப்பான்; மூன்றாம் நாளிலும் ஏழாம் நாளிலும் அந்த ஜலத்தால் சுத்திகரிக்கப்பட வேண்டும். தன்னைச் சுத்திகரிக்காதவன் கர்த்தருடைய வாசஸ்தலத்தைத் தீட்டுப்படுத்துவதால் சபையிலிருந்து அறுப்புண்டுபோவான்.",
    "Numbers 20": "மிரியாம் காதேசில் மரித்தாள். தண்ணீர் இல்லாததால் ஜனங்கள் வாக்குவாதம் பண்ணினபோது, கன்மலையோடு பேசும்படி கர்த்தர் சொன்னார்; மோசேயோ 'கலகக்காரரே, கேளுங்கள்' என்று சொல்லி கன்மலையை இரண்டுதரம் அடித்தான்; அவர்கள் தம்மை விசுவாசியாததால் சபையைக் கானானுக்குள் கொண்டுபோவதில்லை என்று கர்த்தர் சொன்னார். ஏதோம் இஸ்ரவேலருக்கு வழிவிட மறுத்தது; ஆரோன் ஓர் என்னும் மலையில் மரித்தான், அவன் குமாரன் எலெயாசார் ஆசாரியனானான்.",
    "Numbers 21": "இஸ்ரவேலர் ஆராத் என்னும் கானானிய ராஜாவை முறியடித்தார்கள். ஜனங்கள் தேவனுக்கும் மோசேக்கும் விரோதமாகப் பேசினதால் கொள்ளிவாய்ச் சர்ப்பங்கள் அனுப்பப்பட்டன; மோசே வெண்கலச் சர்ப்பத்தைச் செய்து கம்பத்தின்மேல் வைத்தான், அதை நோக்கிப் பார்த்தவர்கள் பிழைத்தார்கள். எமோரியரின் ராஜாவாகிய சீகோனையும் பாசானின் ராஜாவாகிய ஓகையும் முறியடித்து, அவர்கள் தேசங்களைக் கைப்பற்றினார்கள்.",
    "Numbers 22": "மோவாபின் ராஜாவாகிய பாலாக் இஸ்ரவேலரைக் கண்டு பயந்து, அவர்களைச் சபிக்கும்படி பிலேயாமை அழைப்பித்தான். 'அவர்களோடே போகவேண்டாம்' என்று தேவன் முதலில் சொன்னார்; பின்பு, நான் சொல்வதைமட்டும் சொல் என்று போக அனுமதித்தார். வழியில் கர்த்தருடைய தூதன் நின்றதைக் கண்ட கழுதை விலகிப்போனது; பிலேயாம் அதை அடித்தபோது கர்த்தர் கழுதையின் வாயைத் திறந்தார், பின்பு பிலேயாமின் கண்களையும் திறந்தார்.",
    "Numbers 23": "பிலேயாம் ஏழு பலிபீடங்களைக் கட்டிப் பலியிட்டு, 'தேவன் சபிக்காதவனை நான் எப்படிச் சபிப்பேன்?' என்று சொல்லி இஸ்ரவேலை ஆசீர்வதித்தான். பாலாக் அவனை வேறொரு இடத்துக்குக் கூட்டிக்கொண்டுபோனான். 'பொய் சொல்ல தேவன் ஒரு மனுஷன் அல்ல' என்று சொல்லி, பிலேயாம் இரண்டாம் முறையும் இஸ்ரவேலை ஆசீர்வதித்தான்.",
    "Numbers 24": "மூன்றாம் முறை தேவனுடைய ஆவி பிலேயாமின்மேல் வந்தது; அவன் 'யாக்கோபே, உன் கூடாரங்கள் எவ்வளவு அழகானவைகள்' என்று இஸ்ரவேலை ஆசீர்வதித்தான். பாலாக் மிகவும் கோபங்கொண்டு அவனைத் துரத்தினான். 'யாக்கோபிலிருந்து ஒரு நட்சத்திரம் உதிக்கும், இஸ்ரவேலிலிருந்து ஒரு செங்கோல் எழும்பும்' என்று பிலேயாம் முன்னறிவித்தான்.",
    "Numbers 25": "சித்தீமில் இஸ்ரவேலர் மோவாபிய ஸ்திரீகளோடு வேசித்தனம் பண்ணி, பாகால்பேயோரைப் பணிந்துகொண்டதால் கர்த்தருடைய கோபம் மூண்டது. ஆசாரியனாகிய பினெகாஸ் ஒரு இஸ்ரவேலனையும் மீதியானிய ஸ்திரீயையும் ஈட்டியால் குத்தினபோது வாதை நின்றது; வாதையால் இருபத்து நாலாயிரம் பேர் செத்தார்கள். பினெகாஸ் தேவனுக்காக வைராக்கியம் காட்டினதால், அவனுக்கும் அவன் சந்ததிக்கும் நித்திய ஆசாரிய உடன்படிக்கை கொடுக்கப்பட்டது.",
    "Numbers 26": "வாதைக்குப் பின் மோவாபின் சமவெளிகளில் இரண்டாம் ஜனத்தொகை எடுக்கப்பட்டது; எண்ணப்பட்டவர்கள் 6,01,730 பேர். தேசம் ஜனத்தொகைக்கேற்பச் சீட்டுப்போட்டுப் பங்கிடப்பட வேண்டும் என்று கர்த்தர் சொன்னார். காலேபும் யோசுவாவும் தவிர, சீனாயில் முதலில் எண்ணப்பட்டவர்களில் ஒருவனும் அவர்களுக்குள் இல்லை.",
    "Numbers 27": "செலொப்பியாத்தின் குமாரத்திகள் தங்கள் தகப்பனுக்குக் குமாரன் இல்லாததால் அவனுடைய சுதந்தரத்தைக் கேட்டார்கள்; அவர்கள் சொல்வது நியாயம் என்று கர்த்தர் சுதந்தரப் பிரமாணத்தைக் கொடுத்தார். மோசே அபாரீம் மலையிலிருந்து தேசத்தைப் பார்த்தபின் மரிப்பான் என்று கர்த்தர் சொன்னார். சபை மேய்ப்பனில்லாத ஆடுகளைப்போல் இராதபடி, ஆவியைப் பெற்ற யோசுவாவின்மேல் மோசே கைகளை வைத்து அவனைத் தலைவனாக நியமித்தான்.",
    "Numbers 28": "தினந்தோறும் காலையிலும் மாலையிலும் செலுத்த வேண்டிய நித்திய தகனபலியின் முறை கொடுக்கப்பட்டது. ஓய்வுநாள் பலிகளும் மாதப்பிறப்பின் பலிகளும் சொல்லப்பட்டுள்ளன. பஸ்கா, புளிப்பில்லா அப்பப் பண்டிகை, முதற்பலன் நாளாகிய வாரங்களின் பண்டிகை ஆகியவற்றின் பலிகளும் விவரிக்கப்பட்டுள்ளன.",
    "Numbers 29": "ஏழாம் மாதம் முதலாம் தேதி எக்காளம் ஊதும் நாளாகவும், பத்தாம் தேதி பாவநிவிர்த்தி நாளாகவும் ஆசரிக்கப்பட வேண்டும். பதினைந்தாம் தேதிமுதல் ஏழு நாள் கூடாரப்பண்டிகை; அதில் தினந்தோறும் குறைந்துகொண்டே போகும் எண்ணிக்கையில் காளைகள் பலியிடப்பட வேண்டும். எட்டாம் நாளில் பரிசுத்த சபைக்கூட்டம் கூட வேண்டும்.",
    "Numbers 30": "கர்த்தருக்குப் பொருத்தனை பண்ணினவன் தன் வார்த்தையை மீறாமல் அதின்படி செய்ய வேண்டும். தகப்பன் வீட்டிலிருக்கும் பெண்ணின் அல்லது மனைவியின் பொருத்தனையைக் கேட்ட நாளில் தகப்பனோ புருஷனோ தடுத்தால், அது நிலைநிற்காது. விதவையும் தள்ளப்பட்டவளும் பண்ணின பொருத்தனைகள் நிலைநிற்கும்.",
    "Numbers 31": "மீதியானியருக்குப் பழிவாங்கும்படி ஒவ்வொரு கோத்திரத்திலிருந்தும் ஆயிரம் பேர் ஆசாரியனாகிய பினெகாசோடு அனுப்பப்பட்டார்கள். அவர்கள் மீதியானின் ஐந்து ராஜாக்களையும் பிலேயாமையும் கொன்றார்கள். கொள்ளைப்பொருள் யுத்தவீரருக்கும் சபைக்கும் பங்கிடப்பட்டது; தங்களில் ஒருவனும் குறையவில்லை என்று அதிபதிகள் பொன் ஆபரணங்களைக் கர்த்தருக்குக் காணிக்கையாகக் கொண்டுவந்தார்கள்.",
    "Numbers 32": "ரூபன், காத் புத்திரர் மிகுந்த மந்தைகள் வைத்திருந்ததால், யோர்தானுக்கு இக்கரையிலுள்ள யாசேர், கீலேயாத் தேசத்தைக் கேட்டார்கள். மோசே அவர்களைக் கடிந்துகொண்டபோது, தங்கள் சகோதரருக்கு முன்பாக யுத்தத்துக்குப் போவதாக வாக்களித்தார்கள். 'உங்கள் பாவம் உங்களைத் தொடர்ந்து பிடிக்கும் என்று அறியுங்கள்' என்று மோசே எச்சரித்து, ரூபன், காத், மனாசேயின் பாதிக் கோத்திரத்துக்கு அந்தத் தேசத்தைக் கொடுத்தான்.",
    "Numbers 33": "ராமசேஸ் முதல் மோவாபின் சமவெளிகள் வரையிலான இஸ்ரவேலரின் பிரயாண இடங்கள் பட்டியலிடப்பட்டுள்ளன. ஆரோன் நூற்றிருபத்துமூன்று வயதில் ஓர் என்னும் மலையில் மரித்தான். கானானியரைத் துரத்தி அவர்கள் விக்கிரகங்களை அழிக்க வேண்டும்; இல்லாவிட்டால் அவர்கள் இஸ்ரவேலரின் கண்களில் முள்ளும் விலாக்களில் கூர்களுமாயிருப்பார்கள் என்று கர்த்தர் எச்சரித்தார்.",
    "Numbers 34": "இஸ்ரவேலருக்குச் சுதந்தரமாகக் கொடுக்கப்படும் கானான் தேசத்தின் எல்லைகள் வரையறுக்கப்பட்டன. ஒன்பதரைக் கோத்திரங்களுக்கும் சீட்டுப்போட்டுத் தேசம் பங்கிடப்பட வேண்டும். ஆசாரியனாகிய எலெயாசாரும், யோசுவாவும், ஒவ்வொரு கோத்திரத்திலிருந்தும் ஒரு பிரபுவும் தேசத்தைப் பங்கிட நியமிக்கப்பட்டார்கள்.",
    "Numbers 35": "லேவியருக்கு வெளிநிலங்களோடுகூட நாற்பத்தெட்டுப் பட்டணங்கள் கொடுக்கப்பட வேண்டும். அவற்றில் ஆறு பட்டணங்கள், அறியாமல் ஒருவனைக் கொன்றவன் ஓடிப்போய்த் தப்பும்படி அடைக்கலப் பட்டணங்களாக இருக்க வேண்டும். வேண்டுமென்று கொலைசெய்தவன் கொல்லப்பட வேண்டும்; ஒரே சாட்சியினால் அல்ல, சாட்சிகளின் வாக்கினால் தீர்ப்பு செய்ய வேண்டும், ஏனெனில் இரத்தம் தேசத்தைத் தீட்டுப்படுத்தும்.",
    "Numbers 36": "செலொப்பியாத்தின் குமாரத்திகள் வேறு கோத்திரத்தாரை மணந்தால் அவர்கள் சுதந்தரம் வேறு கோத்திரத்துக்குப் போய்விடும் என்று கீலேயாத்தின் வம்சத்தார் மோசேயிடம் சொன்னார்கள். அவர்கள் தங்கள் தகப்பனுடைய கோத்திரத்துக்குள்ளேயே மணக்க வேண்டும் என்று கர்த்தர் கட்டளையிட்டார். அதின்படியே அவர்கள் தங்கள் தகப்பனுடைய சகோதரரின் குமாரரை மணந்தார்கள்; இவைகளே மோவாபின் சமவெளிகளில் கர்த்தர் கொடுத்த கட்டளைகள்.",

    "Deuteronomy 1": "இஸ்ரவேலர் எகிப்திலிருந்து புறப்பட்ட நாற்பதாம் வருஷத்தில், யோர்தானுக்கு அப்புறத்திலுள்ள மோவாப் தேசத்தில், கர்த்தர் கட்டளையிட்டவைகளையெல்லாம் மோசே ஜனங்களுக்கு விவரித்தான். ஓரேபிலிருந்து புறப்படக் கர்த்தர் சொன்னதையும், ஜனங்களைத் தனியே சுமக்க முடியாததால் நியாயாதிபதிகளை நியமித்ததையும் நினைவுகூர்ந்தான். வேவுகாரரின் துர்ச்செய்தியால் ஜனங்கள் கலகம் பண்ணினதையும், அதனால் அந்தச் சந்ததி நல்ல தேசத்தைக் காண்பதில்லை என்று கர்த்தர் ஆணையிட்டதையும் நினைப்பூட்டினான்.",
    "Deuteronomy 2": "இஸ்ரவேலர் சேயீர் மலையைச் சுற்றி அநேக நாள் அலைந்தார்கள்; ஏதோம், மோவாப், அம்மோன் புத்திரருடைய தேசங்களைப் பிடிக்க வேண்டாம் என்று கர்த்தர் சொன்னார். காதேஸ்பர்னேயா முதல் சேரேத் ஆற்றைக் கடக்கும் வரை முப்பத்தெட்டு வருஷம் சென்றது; அதற்குள் அந்தச் சந்ததியின் யுத்தமனுஷர் எல்லாரும் அழிந்தார்கள். எஸ்போனின் ராஜாவாகிய சீகோன் வழிவிட மறுத்ததால், கர்த்தர் அவனையும் அவன் தேசத்தையும் இஸ்ரவேலர் கையில் ஒப்புக்கொடுத்தார்.",
    "Deuteronomy 3": "பாசானின் ராஜாவாகிய ஓகையும் முறியடித்து, அவனுடைய அறுபது பட்டணங்களைப் பிடித்தார்கள். யோர்தானுக்கு இக்கரையிலுள்ள தேசத்தை மோசே ரூபன், காத், மனாசேயின் பாதிக் கோத்திரத்துக்குக் கொடுத்தான். தான் யோர்தானைக் கடந்து நல்ல தேசத்தைக் காண மோசே வேண்டிக்கொண்டான்; கர்த்தர் மறுத்து, பிஸ்காவின் கொடுமுடியிலிருந்து பார்க்கச் சொல்லி, யோசுவாவைத் திடப்படுத்தும்படி கட்டளையிட்டார்.",
    "Deuteronomy 4": "கர்த்தருடைய கட்டளைகளோடு கூட்டவும் குறைக்கவும் கூடாது என்று மோசே எச்சரித்தான்; நாம் நோக்கிக் கூப்பிடும்போதெல்லாம் சமீபமாயிருக்கிற தேவனையுடைய ஜாதி வேறு எது என்று கேட்டான். ஓரேபில் அவர்கள் ஒரு ரூபத்தையும் காணாததால் விக்கிரகம் செய்யக்கூடாது; அவர்கள் தேவனாகிய கர்த்தர் பட்சிக்கிற அக்கினியும் எரிச்சலுள்ள தேவனுமாயிருக்கிறார். ஜாதிகளுக்குள் சிதறடிக்கப்பட்டாலும் முழு இருதயத்தோடும் தேடினால் அவரைக் கண்டடைவார்கள்; மோசே யோர்தானுக்கு இக்கரையில் மூன்று அடைக்கலப் பட்டணங்களைப் பிரித்தான்.",
    "Deuteronomy 5": "மோசே ஓரேபில் கர்த்தர் கொடுத்த பத்துக் கற்பனைகளை ஜனங்களுக்கு மறுபடியும் சொன்னான். அவர்கள் எகிப்தில் அடிமைகளாயிருந்ததை நினைத்து ஓய்வுநாளை ஆசரிக்க வேண்டும் என்று சொல்லப்பட்டது. ஜனங்கள் அக்கினியின் நடுவிலிருந்து வந்த சத்தத்துக்குப் பயந்ததால், மோசே அவர்களுக்கும் கர்த்தருக்கும் நடுவே மத்தியஸ்தனாக நின்றான்; அவர்கள் எப்பொழுதும் தமக்குப் பயந்திருக்கும் இருதயம் அவர்களுக்கு இருந்தால் நலமாயிருக்கும் என்று கர்த்தர் சொன்னார்.",
    "Deuteronomy 6": "'இஸ்ரவேலே, கேள்: நம்முடைய தேவனாகிய கர்த்தர் ஒருவரே கர்த்தர்' என்று மோசே அறிவித்தான். உன் தேவனாகிய கர்த்தரிடத்தில் முழு இருதயத்தோடும் முழு ஆத்துமாவோடும் முழுப் பலத்தோடும் அன்புகூர வேண்டும்; இந்த வார்த்தைகளைப் பிள்ளைகளுக்குக் கருத்தாய்ப் போதித்து, கையில் அடையாளமாகக் கட்டி, வீட்டு நிலைகளில் எழுத வேண்டும். தேசத்தில் செழிப்படைந்தபின் கர்த்தரை மறவாமலும், அவரைப் பரீட்சை பாராமலும் இருக்க வேண்டும் என்று எச்சரித்தான்.",
    "Deuteronomy 7": "கானானிலுள்ள ஏழு ஜாதிகளோடு உடன்படிக்கை பண்ணாமலும், சம்பந்தம் கலவாமலும், அவர்கள் விக்கிரகங்களை உடைத்து அழிக்க வேண்டும் என்று கட்டளையிடப்பட்டது. நீங்கள் திரளானவர்கள் என்பதற்காக அல்ல, கர்த்தர் உங்களில் அன்புகூர்ந்ததினாலும் பிதாக்களுக்கு இட்ட ஆணையைக் காக்கிறதினாலும் உங்களைத் தெரிந்துகொண்டார். அவர் உண்மையுள்ள தேவன்; அந்த ஜாதிகளைக் கொஞ்சம் கொஞ்சமாக உங்களுக்கு முன்பாகத் துரத்திவிடுவார்.",
    "Deuteronomy 8": "கர்த்தர் வனாந்தரத்தில் நாற்பது வருஷம் உங்களைத் தாழ்மைப்படுத்திச் சோதித்து, மன்னாவால் போஷித்தார்; 'மனுஷன் அப்பத்தினாலே மாத்திரமல்ல, கர்த்தருடைய வாயிலிருந்து புறப்படுகிற ஒவ்வொரு வார்த்தையினாலும் பிழைப்பான்' என்று அறியப்பண்ணினார். அந்த நாற்பது வருஷமும் அவர்கள் வஸ்திரம் பழசாகவுமில்லை, கால் வீங்கவுமில்லை. நல்ல தேசத்தில் திருப்தியடைந்தபின், 'என் கைப்பெலனே இந்த ஐசுவரியத்தைச் சம்பாதித்தது' என்று சொல்லாமல், ஐசுவரியத்தைச் சம்பாதிக்கப் பெலன் கொடுக்கிறவர் கர்த்தரே என்று நினைக்க வேண்டும்.",
    "Deuteronomy 9": "தேசம் உங்கள் நீதியினிமித்தம் அல்ல, அந்த ஜாதிகளின் ஆகாமியத்தினிமித்தமே உங்களுக்குக் கொடுக்கப்படுகிறது; நீங்கள் வணங்காக் கழுத்துள்ள ஜனம் என்று மோசே சொன்னான். ஓரேபில் பொன் கன்றுக்குட்டியைச் செய்ததையும், தபேரா, மாசா, கிப்ரோத் அத்தாவா, காதேஸ்பர்னேயாவில் கலகம் பண்ணினதையும் நினைப்பூட்டினான். அவர்களுக்காக மோசே நாற்பது நாள் கர்த்தருக்கு முன்பாக முகங்குப்புற விழுந்து பரிந்துபேசினான்.",
    "Deuteronomy 10": "கர்த்தர் இரண்டாம் முறை கற்பலகைகளில் பத்துக் கற்பனைகளை எழுதிக் கொடுத்தார்; அவை சீத்திம் மரப்பெட்டியில் வைக்கப்பட்டன; லேவி கோத்திரம் பரிசுத்த ஊழியத்துக்குப் பிரித்தெடுக்கப்பட்டது. 'உன் தேவனாகிய கர்த்தர் உன்னிடத்தில் கேட்கிறது என்ன? அவருக்குப் பயந்து, அவர் வழிகளில் நடந்து, அவரில் அன்புகூர்ந்து, அவரைச் சேவிப்பதே' என்று மோசே சொன்னான். இருதயத்தின் நுனித்தோலை விருத்தசேதனம் பண்ணி, பரதேசியைச் சிநேகிக்க வேண்டும்; எழுபது பேராக எகிப்துக்குப் போனவர்களைக் கர்த்தர் வானத்து நட்சத்திரங்களைப்போல் பெருகப்பண்ணினார்.",
    "Deuteronomy 11": "எகிப்திலும், சிவந்த சமுத்திரத்திலும், வனாந்தரத்திலும் கர்த்தர் செய்த பெரிய கிரியைகளைக் கண்டவர்கள் நீங்களே என்று மோசே நினைப்பூட்டினான். கானான் வானத்து மழையினால் தண்ணீர் குடிக்கும் தேசம்; கர்த்தருடைய கண்கள் வருஷத்தின் துவக்கம் முதல் முடிவுவரை எப்பொழுதும் அதின்மேல் இருக்கின்றன. 'இதோ, இன்று ஆசீர்வாதத்தையும் சாபத்தையும் உங்களுக்கு முன்பாக வைக்கிறேன்' என்று சொல்லி, ஆசீர்வாதத்தைக் கெரிசீம் மலையிலும் சாபத்தை ஏபால் மலையிலும் கூறும்படி கட்டளையிட்டான்.",
    "Deuteronomy 12": "கானானியர் தங்கள் தேவர்களைச் சேவித்த ஸ்தலங்களையெல்லாம் அழிக்க வேண்டும். கர்த்தர் தம்முடைய நாமம் விளங்கும்படி தெரிந்துகொள்ளும் இடத்தில் மாத்திரம் பலிகளையும் தசமபாகங்களையும் கொண்டுவர வேண்டும்; லேவியனைக் கைவிடக்கூடாது, இரத்தத்தைப் புசிக்கக்கூடாது. அந்த ஜாதிகள் தங்கள் பிள்ளைகளை அக்கினியில் சுட்டெரித்ததுபோல, அவர்கள் வழியில் கர்த்தரைச் சேவிக்கக்கூடாது.",
    "Deuteronomy 13": "அடையாளம் காட்டி வேறே தேவர்களைச் சேவிக்கச் சொல்லும் தீர்க்கதரிசிக்குச் செவிகொடுக்கக்கூடாது; அதினால் கர்த்தர் உங்களைச் சோதிக்கிறார். சகோதரனோ, பிள்ளையோ, மனைவியோ, நண்பனோ இரகசியமாய் இழுத்தாலும் இணங்கக்கூடாது. விக்கிரகாராதனைக்குத் திரும்பின பட்டணத்தை விசாரித்து, உண்மையானால் அதைச் சாபத்தீடாக அழிக்க வேண்டும்.",
    "Deuteronomy 14": "நீங்கள் உங்கள் தேவனாகிய கர்த்தருக்குப் பரிசுத்த ஜனம்; மரித்தவனுக்காக உங்களைக் கீறிக்கொள்ளக்கூடாது. புசிக்கத்தக்க சுத்தமான மிருகங்கள், மீன்கள், பறவைகளும், தீட்டானவைகளும் சொல்லப்பட்டுள்ளன. வருஷந்தோறும் தசமபாகம் செலுத்த வேண்டும்; மூன்றாம் வருஷத்தின் தசமபாகம் லேவியனுக்கும் பரதேசிக்கும் திக்கற்ற பிள்ளைக்கும் விதவைக்கும் உரியது.",
    "Deuteronomy 15": "ஏழாம் வருஷத்தின் முடிவில் விடுதலை செய்ய வேண்டும்; சகோதரனுக்குக் கொடுத்த கடனை விட்டுவிட வேண்டும். தரித்திரர் தேசத்தில் இல்லாமற்போவதில்லை, ஆகையால் ஏழைச் சகோதரனுக்கு உன் கையைத் தாராளமாகத் திறக்க வேண்டும். எபிரெய அடிமையை ஏழாம் வருஷத்தில் விடுதலையாக்கும்போது வெறுங்கையோடு அனுப்பக்கூடாது; மந்தையின் தலையீற்றுகள் கர்த்தருக்குப் பரிசுத்தமாக்கப்பட வேண்டும்.",
    "Deuteronomy 16": "பஸ்காவும் புளிப்பில்லா அப்பப் பண்டிகையும், வாரங்களின் பண்டிகையும், கூடாரப்பண்டிகையும் ஆசரிக்கப்பட வேண்டும். வருஷத்தில் மூன்றுதரம் ஆண்மக்கள் எல்லாரும் கர்த்தர் தெரிந்துகொள்ளும் இடத்தில் வர வேண்டும்; ஒருவனும் வெறுங்கையோடே வரக்கூடாது. நியாயாதிபதிகள் பட்சபாதமும் லஞ்சமும் இல்லாமல் நியாயம் விசாரிக்க வேண்டும்; 'நீதியையே பின்பற்றுவாயாக' என்று கட்டளையிடப்பட்டது.",
    "Deuteronomy 17": "பழுதுள்ள மிருகத்தைப் பலியிடக்கூடாது; விக்கிரகாராதனை செய்தவன் இரண்டு மூன்று சாட்சிகளின் வாக்கினால் நிரூபிக்கப்பட்டால் கொல்லப்பட வேண்டும். கடினமான வழக்குகள் ஆசாரியரிடத்திலும் நியாயாதிபதியிடத்திலும் கொண்டுபோகப்பட வேண்டும். ராஜா சகோதரரில் ஒருவனாயிருந்து, குதிரைகளையும் மனைவிகளையும் பொன் வெள்ளியையும் மிகுதியாய்ப் பெருக்காமல், நியாயப்பிரமாணத்தின் பிரதியை எழுதித் தன் வாழ்நாளெல்லாம் வாசிக்க வேண்டும்.",
    "Deuteronomy 18": "ஆசாரியருக்கும் லேவியருக்கும் கர்த்தரே சுதந்தரம்; அவர்களுக்குப் பலிகளில் பங்கு உண்டு. குறிசொல்லுதல், நாள்பார்த்தல், சூனியம், அஞ்சனம், செத்தவர்களிடத்தில் குறிகேட்டல் ஆகியவை கர்த்தருக்கு அருவருப்பானவை. 'உன்னைப்போல ஒரு தீர்க்கதரிசியை அவர்கள் சகோதரரிலிருந்து எழும்பப்பண்ணுவேன்' என்று கர்த்தர் வாக்களித்தார்; அவர் நாமத்தில் சொன்னது நடவாவிட்டால் அவன் கள்ளத்தீர்க்கதரிசி.",
    "Deuteronomy 19": "கானானில் மூன்று அடைக்கலப் பட்டணங்கள் பிரிக்கப்பட வேண்டும்; அறியாமல் கொன்றவன் அங்கே ஓடித் தப்பலாம், வேண்டுமென்று கொன்றவனோ பழிவாங்குகிறவன் கையில் ஒப்புக்கொடுக்கப்பட வேண்டும். பிறனுடைய எல்லைக்கல்லை மாற்றக்கூடாது. இரண்டு மூன்று சாட்சிகளின் வாக்கினால் காரியம் நிலைநிற்க வேண்டும்; பொய்ச்சாட்சி சொன்னவனுக்கு, அவன் தன் சகோதரனுக்குச் செய்ய நினைத்ததையே செய்ய வேண்டும்.",
    "Deuteronomy 20": "யுத்தத்துக்குப் போகும்போது சத்துருக்களுக்குப் பயப்படக்கூடாது, கர்த்தர் உங்களோடே இருக்கிறார் என்று ஆசாரியன் ஜனங்களைத் திடப்படுத்த வேண்டும். புது வீடு கட்டினவன், திராட்சத்தோட்டம் நட்டவன், மணம்பேசினவன், பயமுள்ளவன் ஆகியோர் வீட்டுக்குத் திரும்பிப்போகலாம். தூரமான பட்டணங்களுக்கு முதலில் சமாதானம் கூற வேண்டும்; முற்றுகையின்போது கனிதரும் மரங்களை வெட்டக்கூடாது.",
    "Deuteronomy 21": "வயலில் கொலையுண்டவன் காணப்பட்டு கொன்றவன் தெரியாவிட்டால், மூப்பர் ஒரு கிடாரியின் கழுத்தை முறித்து, அதின்மேல் கைகழுவிப் பாவநிவிர்த்தி செய்ய வேண்டும். சிறைப்பிடிக்கப்பட்ட ஸ்திரீயை மனைவியாக்குதல் பற்றியும், வெறுக்கப்பட்ட மனைவியின் மூத்த குமாரனுக்கு இரட்டிப்பான பங்கு கொடுப்பது பற்றியும் நியாயங்கள் கொடுக்கப்பட்டன. அடங்காத துஷ்ட குமாரன் கல்லெறியப்பட வேண்டும்; மரத்திலே தூக்கிப்போடப்பட்டவன் தேவனால் சபிக்கப்பட்டவன், அவனை அன்றே அடக்கம் பண்ண வேண்டும்.",
    "Deuteronomy 22": "சகோதரனுடைய காணாமற்போன மிருகத்தைக் கண்டால் அதைத் திரும்பக் கொண்டுபோய்க் கொடுக்க வேண்டும்; ஸ்திரீ புருஷனுடைய உடையையும் புருஷன் ஸ்திரீயின் உடையையும் தரிக்கக்கூடாது. புது வீட்டின் மேல்தளத்துக்குக் கைப்பிடிச்சுவர் கட்ட வேண்டும்; விதைகள், மிருகங்கள், வஸ்திரங்கள் ஆகியவற்றைக் கலக்கக்கூடாது. விவாகம், கற்பு, விபசாரம், பலவந்தம் ஆகியவை பற்றிய நியாயங்கள் கொடுக்கப்பட்டன.",
    "Deuteronomy 23": "பிலேயாமைக் கூலிக்கு அமர்த்தி இஸ்ரவேலைச் சபிக்கப் பார்த்ததால் அம்மோனியரும் மோவாபியரும் கர்த்தருடைய சபையில் சேரக்கூடாது; ஏதோமியரும் எகிப்தியரும் மூன்றாம் தலைமுறையில் சேரலாம். கர்த்தர் பாளயத்தின் நடுவே உலாவுகிறதால் பாளயம் பரிசுத்தமாயிருக்க வேண்டும். தப்பி ஓடிவந்த அடிமையை எஜமானிடம் ஒப்புக்கொடுக்கக்கூடாது; சகோதரனிடம் வட்டி வாங்கக்கூடாது; பொருத்தனையைச் செலுத்தத் தாமதிக்கக்கூடாது.",
    "Deuteronomy 24": "தள்ளுதல் சீட்டு பற்றிய நியாயம் கொடுக்கப்பட்டது; புதிதாக மணந்தவன் ஒரு வருஷம் யுத்தத்துக்குப் போகாமல் வீட்டிலிருந்து தன் மனைவியை மகிழ்ச்சியாக்க வேண்டும். ஏழைக் கூலியாளுக்கு அன்றன்றே கூலி கொடுக்க வேண்டும்; பிள்ளைகளுக்காகப் பிதாக்களும் பிதாக்களுக்காகப் பிள்ளைகளும் கொல்லப்படக்கூடாது. பரதேசிக்கும் திக்கற்றவனுக்கும் விதவைக்கும் நியாயம் புரட்டக்கூடாது; அறுப்பில் மறந்துவிட்ட அரிக்கட்டு அவர்களுக்கு உரியது, ஏனெனில் நீங்களும் எகிப்தில் அடிமைகளாயிருந்தீர்கள்.",
    "Deuteronomy 25": "குற்றவாளிக்கு நாற்பது அடிகளுக்கு மேல் அடிக்கக்கூடாது; போரடிக்கிற மாட்டின் வாயைக் கட்டக்கூடாது. சகோதரன் பிள்ளையில்லாமல் மரித்தால், அவன் சகோதரன் விதவையை மணந்து மரித்தவனுடைய பேரை இஸ்ரவேலில் நிலைநிறுத்த வேண்டும். நியாயமான நிறைகல்லும் மரக்காலும் வைத்திருக்க வேண்டும்; வழியில் இஸ்ரவேலைத் தாக்கின அமலேக்கின் பேரை வானத்தின் கீழிருந்து குலைத்துப்போட வேண்டும்.",
    "Deuteronomy 26": "தேசத்தில் பிரவேசித்தபின் முதற்பலனைக் கூடையில் வைத்துக் கர்த்தருக்கு முன்பாகக் கொண்டுவந்து, 'என் தகப்பன் அழிந்துபோகிற சீரியனாயிருந்தான்' என்று தொடங்கி, கர்த்தர் செய்த மீட்பை அறிக்கையிட வேண்டும். மூன்றாம் வருஷத்தின் தசமபாகத்தைக் கொடுத்தபின், கட்டளைகளுக்குக் கீழ்ப்படிந்ததை அறிக்கையிட்டு, ஜனத்தை ஆசீர்வதிக்கும்படி கேட்க வேண்டும். இன்று கர்த்தர் உங்களைத் தம்முடைய சொந்த ஜனமாக ஏற்றுக்கொண்டார் என்று மோசே சொன்னான்.",
    "Deuteronomy 27": "யோர்தானைக் கடந்தபின் ஏபால் மலையில் பெரிய கற்களை நாட்டி, சாந்து பூசி, அவைகளில் நியாயப்பிரமாணத்தின் வார்த்தைகளை எழுதி, வெட்டாத கற்களால் பலிபீடம் கட்ட வேண்டும். ஆறு கோத்திரங்கள் கெரிசீம் மலையில் ஆசீர்வதிக்கவும், ஆறு கோத்திரங்கள் ஏபால் மலையில் சபிக்கவும் நிற்க வேண்டும். லேவியர் பன்னிரண்டு சாபங்களைச் சொல்லும்போது, ஜனங்களெல்லாரும் 'ஆமென்' என்று சொல்ல வேண்டும்.",
    "Deuteronomy 28": "கர்த்தருடைய சத்தத்துக்குக் கீழ்ப்படிந்தால் பட்டணத்திலும் வயலிலும் ஆசீர்வதிக்கப்படுவீர்கள்; கர்த்தர் உங்களை வாலாக்காமல் தலையாக்குவார். கீழ்ப்படியாவிட்டால் நோய், வறட்சி, சத்துருக்களுக்கு முன்பாகத் தோல்வி, சிறையிருப்பு, முற்றுகையில் கொடிய பஞ்சம் ஆகிய சாபங்கள் வரும். ஜாதிகளுக்குள் சிதறடிக்கப்பட்டு இளைப்பாறுதல் இல்லாமல் அலைவீர்கள் என்றும், கப்பல்களில் எகிப்துக்கே திரும்பக் கொண்டுபோகப்படுவீர்கள் என்றும் மோசே எச்சரித்தான்.",
    "Deuteronomy 29": "ஓரேபில் பண்ணின உடன்படிக்கையைத் தவிர, மோவாப் தேசத்தில் கர்த்தர் இஸ்ரவேலரோடு மறுபடியும் உடன்படிக்கை பண்ணினார். எகிப்திலும் வனாந்தரத்திலும் அவர்கள் கண்ட அதிசயங்களை நினைப்பூட்டி, கசப்பான விஷத்தைக் கொடுக்கும் வேர் அவர்களுக்குள் இருக்கக்கூடாது என்று எச்சரித்தான். 'மறைவானவைகள் நம்முடைய தேவனாகிய கர்த்தருக்கே உரியவைகள்; வெளிப்படுத்தப்பட்டவைகளோ நமக்கும் நம்முடைய பிள்ளைகளுக்கும் உரியவைகள்' என்று சொன்னான்.",
    "Deuteronomy 30": "ஜாதிகளுக்குள் சிதறடிக்கப்பட்டாலும், கர்த்தரிடத்தில் திரும்பினால் அவர் அவர்களைச் சேர்த்து, அவர்கள் இருதயத்தை விருத்தசேதனம் பண்ணுவார். இந்தக் கற்பனை தூரமானதல்ல; நீ அதின்படி செய்யும்படி அந்த வார்த்தை உன் வாயிலும் உன் இருதயத்திலும் இருக்கிறது. 'ஜீவனையும் மரணத்தையும், ஆசீர்வாதத்தையும் சாபத்தையும் உனக்கு முன்பாக வைத்தேன்; ஆகையால் நீயும் உன் சந்ததியும் பிழைக்கும்படி ஜீவனைத் தெரிந்துகொள்' என்று மோசே சொன்னான்.",
    "Deuteronomy 31": "நூற்றிருபது வயதான மோசே யோசுவாவை எல்லாருக்கும் முன்பாக அழைத்து, 'பலங்கொண்டு திடமனதாயிரு; கர்த்தர் உன்னைக் கைவிடுவதுமில்லை, உன்னை விட்டு விலகுவதுமில்லை' என்றான். மோசே நியாயப்பிரமாணத்தை எழுதி லேவியரிடம் கொடுத்து, ஏழு வருஷத்துக்கு ஒருமுறை கூடாரப்பண்டிகையில் ஜனங்களெல்லாருக்கும் முன்பாக வாசிக்கக் கட்டளையிட்டான். ஜனங்கள் பின்பு விலகி அந்நிய தேவர்களைப் பின்பற்றுவார்கள் என்று கர்த்தர் சொல்லி, சாட்சியாக ஒரு பாட்டை எழுதச் சொன்னார்.",
    "Deuteronomy 32": "மோசேயின் பாட்டு: 'அவர் கன்மலை; அவர் கிரியை உத்தமமானது'; கழுகு தன் குஞ்சுகளைச் செட்டைகளில் சுமப்பதுபோலக் கர்த்தர் யாக்கோபை நடத்தினார். யெஷுரூன் கொழுத்தபோது தன்னை உண்டாக்கின தேவனைக் கைவிட்டு அந்நிய தேவர்களைச் சேவித்ததால் நியாயத்தீர்ப்பு வரும்; ஆனாலும் கர்த்தர் தம்முடைய ஜனத்துக்கு நியாயம் செய்து இரங்குவார். பாட்டு முடிந்தபின், நேபோ மலையில் ஏறி கானான் தேசத்தைப் பார்த்து அங்கே மரிக்கும்படி கர்த்தர் மோசேயிடம் சொன்னார்.",
    "Deuteronomy 33": "தேவனுடைய மனுஷனாகிய மோசே தன் மரணத்துக்கு முன் இஸ்ரவேல் கோத்திரங்களை ஒவ்வொன்றாக ஆசீர்வதித்தான். லேவிக்குத் தும்மீமும் ஊரீமும், யோசேப்புக்குத் தேசத்தின் உச்சிதமான பலன்களும் வாக்களிக்கப்பட்டன. 'அநாதி தேவனே உனக்கு அடைக்கலம்; அவருடைய நித்திய புயங்கள் உன் ஆதாரம்' என்றும், 'இஸ்ரவேலே, நீ பாக்கியவான்' என்றும் சொல்லி முடித்தான்.",
    "Deuteronomy 34": "மோசே நேபோ மலையிலுள்ள பிஸ்காவின் கொடுமுடியில் ஏறினான்; கர்த்தர் அவனுக்குத் தேசம் முழுவதையும் காண்பித்தார். மோசே நூற்றிருபது வயதில் மரித்தான்; அவன் கண் இருளவுமில்லை, பெலன் குறையவுமில்லை; கர்த்தர் அவனை மோவாப் தேசத்தில் அடக்கம் பண்ணினார், அவன் கல்லறை இந்நாள்வரை ஒருவனுக்கும் தெரியாது; இஸ்ரவேலர் முப்பது நாள் அழுதார்கள். மோசே கைகளை வைத்ததால் யோசுவா ஞானத்தின் ஆவியினால் நிறைந்தான்; கர்த்தரை முகமுகமாய் அறிந்த மோசேயைப்போன்ற தீர்க்கதரிசி இஸ்ரவேலில் பின்பு எழும்பவில்லை.",

    "Joshua 1": "மோசே மரித்தபின் கர்த்தர் யோசுவாவிடம், ஜனங்களோடு யோர்தானைக் கடந்து தாம் கொடுக்கும் தேசத்துக்குப் போகச் சொன்னார்; 'நான் மோசேயோடே இருந்ததுபோல உன்னோடும் இருப்பேன்' என்றார். 'பலங்கொண்டு திடமனதாயிரு' என்று சொல்லி, நியாயப்பிரமாணம் அவன் வாயைவிட்டுப் பிரியாமல் இரவும் பகலும் அதைத் தியானிக்கக் கட்டளையிட்டார். ரூபன், காத், மனாசேயின் பாதிக் கோத்திரத்து வீரர் தங்கள் சகோதரருக்கு முன்பாக ஆயுதம் தரித்துப் போவதாக வாக்களித்தார்கள்.",
    "Joshua 2": "யோசுவா இரண்டு வேவுகாரரை எரிகோவுக்கு அனுப்பினான்; ராகாப் என்னும் வேசி அவர்களைத் தன் வீட்டின் மேல்தளத்தில் சணல் தட்டைகளுக்குள் ஒளித்து வைத்தாள். கர்த்தர் இந்தத் தேசத்தை உங்களுக்குக் கொடுத்தார் என்று அறிவேன் என்று சொல்லி, தன் குடும்பத்தைக் காப்பாற்றும்படி ஆணையிடக் கேட்டாள். ஜன்னலில் சிவப்புநூல் கயிற்றைக் கட்டும்படி அவளுக்குச் சொல்லி, வேவுகாரர் தப்பி யோசுவாவிடம் திரும்பி வந்தார்கள்.",
    "Joshua 3": "ஆசாரியர்கள் உடன்படிக்கைப் பெட்டியைச் சுமந்து ஜனங்களுக்கு முன்பாகச் சென்றார்கள்; 'இன்றைக்கு உன்னை இஸ்ரவேலர் எல்லாருடைய கண்களுக்கு முன்பாகப் பெரியவனாக்கத் தொடங்குவேன்' என்று கர்த்தர் யோசுவாவிடம் சொன்னார். அறுப்புக்காலத்தில் கரைபுரண்டோடின யோர்தானில் ஆசாரியர்களின் கால்கள் பட்டதும், மேலிருந்து வந்த ஜலம் ஒரு குவியலாக நின்றது. ஜனங்கள் எல்லாரும் உலர்ந்த தரையில் யோர்தானைக் கடந்தார்கள்.",
    "Joshua 4": "ஒவ்வொரு கோத்திரத்திலிருந்தும் ஒருவனாகப் பன்னிரண்டு பேர் யோர்தானின் நடுவிலிருந்து பன்னிரண்டு கற்களை எடுத்தார்கள். உடன்படிக்கைப் பெட்டியைச் சுமந்த ஆசாரியர் கரையேறினதும், யோர்தானின் ஜலம் முன்போலத் திரும்பி ஓடியது. கில்காலில் அந்தக் கற்கள் நினைவுக்குறியாக நாட்டப்பட்டன; 'இந்தக் கற்கள் என்ன?' என்று பிள்ளைகள் கேட்கும்போது, கர்த்தர் யோர்தானை வற்றப்பண்ணினதைச் சொல்ல வேண்டும்.",
    "Joshua 5": "கர்த்தர் யோர்தானை வற்றப்பண்ணினதைக் கேட்ட கானானிய ராஜாக்களின் இருதயம் கரைந்தது. கில்காலில் வனாந்தரத்தில் பிறந்தவர்கள் விருத்தசேதனம் பண்ணப்பட்டார்கள்; அவர்கள் பஸ்காவை ஆசரித்து தேசத்தின் விளைச்சலைப் புசித்த மறுநாள் மன்னா நின்றுபோனது. கர்த்தருடைய சேனையின் அதிபதி உருவின பட்டயத்தோடு யோசுவாவுக்குத் தோன்றி, 'நீ நிற்கிற இடம் பரிசுத்தமானது, உன் கால்களிலிருந்து பாதரட்சையைக் கழற்றிப்போடு' என்றார்.",
    "Joshua 6": "கர்த்தருடைய கட்டளைப்படி இஸ்ரவேலர் ஆறு நாள் தினமும் ஒருதரமும், ஏழாம் நாள் ஏழுதரமும் எரிகோவைச் சுற்றிவந்தார்கள்; ஆசாரியர்கள் எக்காளங்களை ஊதினார்கள். ஜனங்கள் மகா ஆரவாரத்தோடே ஆர்ப்பரித்தபோது அலங்கம் இடிந்து விழுந்தது; பட்டணம் சாபத்தீடாக அழிக்கப்பட்டது. ராகாபும் அவள் குடும்பத்தாரும் காப்பாற்றப்பட்டார்கள்; எரிகோவைத் திரும்பக் கட்டுகிறவன் சபிக்கப்பட்டவன் என்று யோசுவா ஆணையிட்டான்.",
    "Joshua 7": "ஆகான் சாபத்தீடானவைகளில் சிலவற்றை எடுத்துக்கொண்டதால், ஆயீ பட்டணத்துக்கு விரோதமாகப் போன இஸ்ரவேலர் தோற்றுப்போனார்கள். யோசுவா முகங்குப்புற விழுந்தபோது, இஸ்ரவேல் பாவம் செய்தது என்று கர்த்தர் சொன்னார்; சீட்டுப்போட்டபோது ஆகான் பிடிபட்டான். அவன் பாபிலோனிய சால்வையையும் வெள்ளியையும் பொன்பாளத்தையும் எடுத்து ஒளித்ததை அறிக்கையிட்டான்; ஆகோர் பள்ளத்தாக்கில் அவன் கல்லெறியப்பட்டான்.",
    "Joshua 8": "'பயப்படாதே' என்று கர்த்தர் சொல்லி, ஆயீயைப் பிடிக்கும் வழியைக் காண்பித்தார்; யோசுவா பட்டணத்துக்குப் பின்னே பதிவிருக்கும் சேனையை வைத்து அதைப் பிடித்து அழித்தான். ஆயீயின் ராஜா மரத்திலே தூக்கிலிடப்பட்டான். பின்பு யோசுவா ஏபால் மலையில் பலிபீடம் கட்டி, மோசேயின் நியாயப்பிரமாணத்தைக் கற்களில் எழுதி, ஆசீர்வாதங்களையும் சாபங்களையும் சபையார் எல்லாருக்கும் முன்பாக வாசித்தான்.",
    "Joshua 9": "கிபியோனின் குடிகள் கிழிந்த வஸ்திரங்களும் பூசணம் பிடித்த அப்பமுமாய், தூரதேசத்திலிருந்து வந்தவர்கள்போல வேஷம் போட்டு வந்தார்கள். இஸ்ரவேலர் கர்த்தரிடத்தில் விசாரியாமல் அவர்களோடு சமாதான உடன்படிக்கை பண்ணி ஆணையிட்டார்கள். அவர்கள் அருகிலிருப்பவர்கள் என்று தெரிந்தபோதும் ஆணையினிமித்தம் அவர்களைக் கொல்லாமல், சபைக்கு விறகு வெட்டுகிறவர்களாகவும் தண்ணீர் எடுக்கிறவர்களாகவும் ஆக்கினார்கள்.",
    "Joshua 10": "எருசலேமின் ராஜாவாகிய அதோனிசேதேக்கு உட்பட ஐந்து எமோரிய ராஜாக்கள் கிபியோனுக்கு விரோதமாக வந்தார்கள்; யோசுவா கிபியோனுக்கு உதவியாகப் போனான். கர்த்தர் வானத்திலிருந்து பெரிய கல்மழையைப் பெய்யப்பண்ணினார்; 'சூரியனே, நீ கிபியோன்மேல் தரித்து நில்' என்று யோசுவா சொன்னபோது, சூரியன் ஏறக்குறைய ஒரு நாள் முழுவதும் அஸ்தமிக்கவில்லை. ஐந்து ராஜாக்களும் மக்கெதா குகையில் பிடிபட்டுக் கொல்லப்பட்டார்கள்; யோசுவா தென்தேசம் முழுவதையும் கைப்பற்றினான்.",
    "Joshua 11": "ஆத்சோரின் ராஜாவாகிய யாபீன் வடதேசத்து ராஜாக்களைக் கூட்டி, கடற்கரை மணலைப்போலத் திரளான சேனையோடு மேரோம் தண்ணீர்களண்டை வந்தான். 'அவர்களுக்குப் பயப்படாதே' என்று கர்த்தர் சொன்னார்; யோசுவா அவர்களை முறியடித்து ஆத்சோரை அக்கினியால் சுட்டெரித்தான். இப்படி யோசுவா கர்த்தர் மோசேக்குச் சொன்னபடியே தேசம் முழுவதையும் பிடித்துக் கோத்திரங்களுக்குச் சுதந்தரமாகக் கொடுத்தான்; தேசம் யுத்தமில்லாமல் அமைதலாயிருந்தது.",
    "Joshua 12": "யோர்தானுக்குக் கிழக்கே மோசே முறியடித்த எமோரியரின் ராஜாவாகிய சீகோனும் பாசானின் ராஜாவாகிய ஓகும் குறிப்பிடப்பட்டுள்ளனர். அவர்கள் தேசத்தை மோசே ரூபன், காத், மனாசேயின் பாதிக் கோத்திரத்துக்குக் கொடுத்தான். யோர்தானுக்கு மேற்கே யோசுவா முறியடித்த முப்பத்தொரு ராஜாக்களின் பட்டியலும் கொடுக்கப்பட்டுள்ளது.",
    "Joshua 13": "யோசுவா வயதுசென்றவனானபோது, சுதந்தரிக்க வேண்டிய தேசம் இன்னும் மிகுதியாயிருக்கிறது என்று கர்த்தர் சொல்லி, பெலிஸ்தியர் தேசம் முதலியவற்றைக் குறிப்பிட்டார். தேசத்தை ஒன்பது கோத்திரங்களுக்கும் மனாசேயின் பாதிக் கோத்திரத்துக்கும் பங்கிடும்படி கட்டளையிட்டார். யோர்தானுக்குக் கிழக்கே மோசே ரூபன், காத், மனாசேயின் பாதிக்குக் கொடுத்த பங்குகள் விவரிக்கப்பட்டுள்ளன; லேவி கோத்திரத்துக்கோ கர்த்தரே சுதந்தரம்.",
    "Joshua 14": "கானான் தேசம் கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே சீட்டுப்போட்டுக் கோத்திரங்களுக்குப் பங்கிடப்படத் தொடங்கியது. எண்பத்தைந்து வயதான காலேப், 'மோசே என்னை அனுப்பின நாளில் இருந்ததுபோல இன்றும் பலமாயிருக்கிறேன்' என்று சொல்லி, கர்த்தர் வாக்களித்த மலைநாட்டைக் கேட்டான். அவன் கர்த்தரை உத்தமமாய்ப் பின்பற்றினதால், யோசுவா அவனை ஆசீர்வதித்து எபிரோனை அவனுக்குச் சுதந்தரமாகக் கொடுத்தான்.",
    "Joshua 15": "யூதா கோத்திரத்துக்குக் கிடைத்த சுதந்தரத்தின் எல்லைகளும் பட்டணங்களும் விவரிக்கப்பட்டுள்ளன. காலேப் ஏனாக்கின் மூன்று குமாரரை எபிரோனிலிருந்து துரத்தி, கீரியாத்செப்பேரைப் பிடித்த ஒத்னியேலுக்குத் தன் குமாரத்தி அக்சாளை மனைவியாகக் கொடுத்தான்; அவள் தன் தகப்பனிடம் நீரூற்றுகளையும் கேட்டுப் பெற்றாள். எருசலேமில் குடியிருந்த எபூசியரை யூதா புத்திரரால் துரத்திவிட முடியவில்லை.",
    "Joshua 16": "யோசேப்பின் புத்திரருக்கு விழுந்த சீட்டின் எல்லைகள் விவரிக்கப்பட்டுள்ளன. எப்பிராயீம் புத்திரரின் சுதந்தரமும், மனாசேயின் சுதந்தரத்துக்குள் அவர்களுக்குப் பிரிக்கப்பட்ட பட்டணங்களும் சொல்லப்பட்டுள்ளன. கேசேரில் குடியிருந்த கானானியரை அவர்கள் துரத்திவிடாமல், அவர்களைப் பகுதிகட்டுகிறவர்களாக வைத்துக்கொண்டார்கள்.",
    "Joshua 17": "மனாசே கோத்திரத்தின் சுதந்தரம் விவரிக்கப்பட்டுள்ளது; செலொப்பியாத்தின் குமாரத்திகள் மோசேக்குக் கொடுக்கப்பட்ட கட்டளையின்படியே தங்கள் பங்கைப் பெற்றார்கள். மனாசே புத்திரர் சில பட்டணங்களிலிருந்து கானானியரைத் துரத்த முடியாமல், அவர்களைப் பகுதிகட்டுகிறவர்களாக்கினார்கள். யோசேப்பின் புத்திரர் அதிகப் பங்கு கேட்டபோது, காட்டை வெட்டித் திருத்திக்கொள்ளுங்கள், இருப்பு இரதங்களுள்ள கானானியரையும் துரத்திவிடுவீர்கள் என்று யோசுவா சொன்னான்.",
    "Joshua 18": "இஸ்ரவேல் புத்திரரின் சபை சீலோவில் கூடி, அங்கே ஆசரிப்புக்கூடாரத்தை நிறுத்தினார்கள். இன்னும் ஏழு கோத்திரங்கள் சுதந்தரம் பெறாதிருந்ததால், 'எதுவரைக்கும் அசதியாயிருப்பீர்கள்?' என்று யோசுவா கேட்டு, ஒவ்வொரு கோத்திரத்திலிருந்தும் மூன்று பேரை அனுப்பி தேசத்தை ஏழு பங்காக எழுதச் செய்தான். சீலோவில் கர்த்தருக்கு முன்பாகச் சீட்டுப்போட்டபோது, முதலாவது பென்யமீன் கோத்திரத்துக்குப் பங்கு விழுந்தது.",
    "Joshua 19": "சிமியோன் கோத்திரத்தின் சுதந்தரம் யூதாவின் பங்குக்குள்ளே இருந்தது; செபுலோன், இசக்கார், ஆசேர், நப்தலி, தாண் கோத்திரங்களின் பங்குகளும் விவரிக்கப்பட்டுள்ளன. தாண் புத்திரர் லேசேம் பட்டணத்தைப் பிடித்து அதற்குத் தாண் என்று பேரிட்டார்கள். கடைசியில் இஸ்ரவேலர் யோசுவாவுக்கு எப்பிராயீம் மலையிலுள்ள திம்னாத்சேரா பட்டணத்தைச் சுதந்தரமாகக் கொடுத்தார்கள்.",
    "Joshua 20": "கர்த்தர் மோசேயைக்கொண்டு சொன்னபடியே அடைக்கலப் பட்டணங்கள் ஏற்படுத்தப்பட்டன: கேதேஸ், சீகேம், எபிரோன், பேசேர், ராமோத், கோலான். அறியாமல் ஒருவனைக் கொன்றவன் அங்கே ஓடிப்போய், பழிவாங்குகிறவனுக்குத் தப்பலாம். சபைக்கு முன்பாக நியாயம் விசாரிக்கப்படுமளவும், அந்நாட்களிலிருக்கும் பிரதான ஆசாரியன் மரிக்குமளவும் அவன் அந்தப் பட்டணத்திலேயே தங்க வேண்டும்.",
    "Joshua 21": "லேவியருக்கு வெளிநிலங்களோடுகூட நாற்பத்தெட்டுப் பட்டணங்கள் கோத்திரங்களின் சுதந்தரங்களிலிருந்து கொடுக்கப்பட்டன. அவை கோகாத், கெர்சோன், மெராரி வம்சங்களுக்குச் சீட்டுப்போட்டுப் பங்கிடப்பட்டன. கர்த்தர் பிதாக்களுக்கு ஆணையிட்ட தேசம் முழுவதையும் கொடுத்து, சுற்றிலும் இளைப்பாறுதல் அருளினார்; இஸ்ரவேல் வம்சத்துக்குக் கர்த்தர் சொன்ன நல்வார்த்தைகளில் ஒன்றும் தவறவில்லை, எல்லாம் நிறைவேறிற்று.",
    "Joshua 22": "யோசுவா ரூபன், காத், மனாசேயின் பாதிக் கோத்திரத்தாரை ஆசீர்வதித்து, அவர்கள் சுதந்தரத்துக்குத் திரும்ப அனுப்பினான். அவர்கள் யோர்தானண்டையில் பார்வைக்குப் பெரிய ஒரு பலிபீடத்தைக் கட்டினதால், மற்றக் கோத்திரங்கள் அவர்களோடு யுத்தம் பண்ணக் கூடினார்கள்; ஆசாரியனாகிய பினெகாஸ் விசாரிக்க அனுப்பப்பட்டான். அது பலிக்காக அல்ல, தாங்களும் கர்த்தருடைய ஜனம் என்பதற்குச் சாட்சியாகவே கட்டப்பட்டது என்று அவர்கள் சொன்னதால் சமாதானம் உண்டானது; அதற்கு 'ஏத்' (சாட்சி) என்று பேரிட்டார்கள்.",
    "Joshua 23": "யோசுவா வயதுசென்றவனானபோது இஸ்ரவேலின் மூப்பரையும் தலைவரையும் கூட்டி, உங்கள் தேவனாகிய கர்த்தரே உங்களுக்காக யுத்தம் பண்ணினார் என்று நினைப்பூட்டினான். நியாயப்பிரமாணத்தை விட்டு விலகாமலும், மீந்திருக்கும் ஜாதிகளோடு கலவாமலும், கர்த்தரைப் பற்றிக்கொண்டு அவரில் அன்புகூரும்படி எச்சரிக்கையாயிருக்கச் சொன்னான். இல்லாவிட்டால் அந்த ஜாதிகள் அவர்களுக்குக் கண்ணியும் முள்ளுமாயிருப்பார்கள், அவர்கள் நல்ல தேசத்திலிருந்து அழிந்துபோவார்கள் என்று எச்சரித்தான்.",
    "Joshua 24": "யோசுவா சீகேமில் இஸ்ரவேல் கோத்திரங்களையெல்லாம் கூட்டி, ஆபிரகாம் முதல் கர்த்தர் அவர்களுக்குச் செய்த யாவையும் நினைப்பூட்டினான். 'யாரைச் சேவிப்பீர்கள் என்பதை இன்று தெரிந்துகொள்ளுங்கள்; நானும் என் வீட்டாருமோ கர்த்தரையே சேவிப்போம்' என்று சொன்னான்; ஜனங்கள் கர்த்தரையே சேவிப்போம் என்று உடன்படிக்கை பண்ணினார்கள், சாட்சியாக ஒரு பெரிய கல் நாட்டப்பட்டது. யோசுவா நூற்றுப்பத்து வயதில் மரித்தான்; எகிப்திலிருந்து கொண்டுவரப்பட்ட யோசேப்பின் எலும்புகள் சீகேமில் அடக்கம் பண்ணப்பட்டன.",

    "Judges 1": "யோசுவா மரித்தபின், கர்த்தருடைய கட்டளைப்படி யூதா கோத்திரம் முதலாவது கானானியருக்கு விரோதமாக யுத்தம் பண்ணி, அதோனிபேசேக்கைப் பிடித்தது. காலேப் கீரியாத்செப்பேரைப் பிடித்த ஒத்னியேலுக்குத் தன் குமாரத்தி அக்சாளைக் கொடுத்தான். ஆனால் பல கோத்திரங்கள் கானானியரை முழுதும் துரத்தாமல், அவர்களோடுகூடக் குடியிருந்து அவர்களைப் பகுதிகட்டுகிறவர்களாக வைத்துக்கொண்டார்கள்.",
    "Judges 2": "கர்த்தருடைய தூதன் போகீமில், 'நீங்கள் என் சத்தத்துக்குச் செவிகொடுக்கவில்லை; ஆகையால் அவர்களைத் துரத்திவிடமாட்டேன், அவர்கள் உங்களுக்கு முள்ளாயிருப்பார்கள்' என்றார்; ஜனங்கள் சத்தமிட்டு அழுதார்கள். யோசுவாவின் சந்ததிக்குப் பின் கர்த்தரை அறியாத சந்ததி எழும்பி பாகால்களைச் சேவித்தது; கர்த்தர் அவர்களைச் சத்துருக்கள் கையில் ஒப்புக்கொடுத்தார். அவர்கள் கூப்பிட்டபோது கர்த்தர் நியாயாதிபதிகளை எழும்பப்பண்ணி இரட்சித்தார்; ஆனால் நியாயாதிபதி மரித்தபின் அவர்கள் மறுபடியும் கெட்டுப்போனார்கள்.",
    "Judges 3": "இஸ்ரவேலரைச் சோதிக்கும்படி கர்த்தர் சில ஜாதிகளைத் தேசத்தில் விட்டுவைத்தார். இஸ்ரவேலர் கூசான்ரிஷதாயீமுக்கு எட்டு வருஷம் அடிமைப்பட்டபோது ஒத்னியேல் அவர்களை விடுவித்தான்; மோவாபின் ராஜாவாகிய எக்லோனுக்குப் பதினெட்டு வருஷம் அடிமைப்பட்டபோது, இடதுகைப் பழக்கமுள்ள ஏகூத் தன் கத்தியால் எக்லோனைக் கொன்று இஸ்ரவேலை விடுவித்தான். அவனுக்குப் பின் சம்கார் தாற்றுக்கோலினால் அறுநூறு பெலிஸ்தரைக் கொன்று இஸ்ரவேலை இரட்சித்தான்.",
    "Judges 4": "கானானிய ராஜாவாகிய யாபீனும் அவன் சேனாபதி சிசெராவும் தொள்ளாயிரம் இருப்பு இரதங்களோடு இஸ்ரவேலரை இருபது வருஷம் ஒடுக்கினார்கள். தீர்க்கதரிசியாகிய தெபொராள் பாராக்கை அழைத்து யுத்தத்துக்குப் போகச் சொன்னாள்; அவன் நீ வந்தால் போவேன் என்றதால், மேன்மை ஒரு ஸ்திரீக்குக் கிடைக்கும் என்றாள். கர்த்தர் சிசெராவின் சேனையைக் கலங்கடித்தார்; சிசெரா ஓடி யாகேலின் கூடாரத்தில் ஒளிந்தபோது, யாகேல் கூடார முளையை அவன் நெற்றியில் அடித்து அவனைக் கொன்றாள்.",
    "Judges 5": "தெபொராளும் பாராக்கும் கர்த்தருக்கு ஜெயப்பாட்டுப் பாடினார்கள். மனப்பூர்வமாய் முன்வந்த கோத்திரங்களைப் புகழ்ந்து, வராத கோத்திரங்களைக் கடிந்துகொண்டார்கள்; வானத்திலிருந்து நட்சத்திரங்களும் சிசெராவோடு யுத்தம் பண்ணின, கீசோன் நதி சத்துருக்களை அடித்துக்கொண்டுபோனது. யாகேல் ஸ்திரீகளுக்குள் ஆசீர்வதிக்கப்பட்டவள் என்று புகழப்பட்டாள்; தேசம் நாற்பது வருஷம் அமைதலாயிருந்தது.",
    "Judges 6": "மீதியானியர் ஏழு வருஷம் இஸ்ரவேலரை ஒடுக்கி, அவர்கள் விளைச்சலையெல்லாம் அழித்தார்கள். கர்த்தருடைய தூதன் ஆலைக்குழியில் கோதுமையைப் போரடித்துக்கொண்டிருந்த கிதியோனுக்குத் தோன்றி, 'பராக்கிரமசாலியே, கர்த்தர் உன்னோடே இருக்கிறார்' என்றார். கிதியோன் தன் தகப்பனுடைய பாகாலின் பலிபீடத்தை இடித்ததால் யெருபாகால் எனப்பட்டான்; ஆட்டுமயிர்த் தோலைக் கொண்டு இரண்டுதரம் அடையாளம் கேட்டு உறுதிப்பட்டான்.",
    "Judges 7": "'உன்னோடிருக்கிற ஜனங்கள் அதிகம்' என்று கர்த்தர் சொல்லி, பயமுள்ளவர்களைத் திரும்ப அனுப்பி, தண்ணீரை நக்கிக் குடித்த முந்நூறு பேரை மாத்திரம் வைத்தார். கிதியோன் மீதியானியரின் பாளயத்தில் ஒருவன் சொன்ன சொப்பனத்தைக் கேட்டுத் திடப்பட்டான். முந்நூறு பேரும் எக்காளங்களை ஊதி, பானைகளை உடைத்து, தீவட்டிகளைப் பிடித்து, 'கர்த்தருடைய பட்டயம், கிதியோனுடைய பட்டயம்' என்று ஆர்ப்பரித்தபோது, மீதியானியர் ஒருவரையொருவர் வெட்டிக்கொண்டு ஓடினார்கள்.",
    "Judges 8": "கிதியோன் கோபங்கொண்ட எப்பிராயீமரைச் சாந்தமான வார்த்தையால் அமர்த்தி, மீதியானிய ராஜாக்களாகிய சேபாவையும் சல்முன்னாவையும் பின்தொடர்ந்து பிடித்தான்; உதவி மறுத்த சுக்கோத், பெனுவேல் பட்டணத்தாரைத் தண்டித்தான். ஜனங்கள் தங்களை ஆளும்படி கேட்டபோது, 'கர்த்தரே உங்களை ஆளுவார்' என்றான். ஆனால் அவன் பொன்னால் செய்த ஏபோத் இஸ்ரவேலுக்குக் கண்ணியானது; கிதியோன் மரித்தபின் ஜனங்கள் மறுபடியும் பாகால்களைச் சேவித்தார்கள்.",
    "Judges 9": "கிதியோனின் குமாரனாகிய அபிமெலேக்கு தன் சகோதரராகிய எழுபது பேரைக் கொன்று சீகேமில் ராஜாவானான்; தப்பின யோதாம் மரங்கள் தங்களுக்கு ராஜாவைத் தேடின உவமையைச் சொல்லி சீகேமியரை எச்சரித்தான். பின்பு சீகேமியர் அபிமெலேக்குக்குத் துரோகம் பண்ணினார்கள்; அவன் சீகேமை அழித்துப்போட்டான். தேபேசில் ஒரு ஸ்திரீ எந்திரக்கல்லின் துண்டை அவன் தலையின்மேல் போட்டு மண்டையை உடைத்தாள்; இப்படித் தேவன் அவன் செய்த பொல்லாப்புக்குப் பதில் அளித்தார்.",
    "Judges 10": "அபிமெலேக்குக்குப் பின் தோலா இருபத்துமூன்று வருஷமும், யாவீர் இருபத்திரண்டு வருஷமும் இஸ்ரவேலுக்கு நியாயம் விசாரித்தார்கள். இஸ்ரவேலர் மறுபடியும் அநேக அந்நிய தேவர்களைச் சேவித்ததால், பெலிஸ்தரும் அம்மோனியரும் அவர்களைப் பதினெட்டு வருஷம் ஒடுக்கினார்கள். அவர்கள் அந்நிய தேவர்களை அகற்றி கர்த்தரைச் சேவித்து அவரிடம் கூப்பிட்டபோது, கர்த்தருடைய ஆத்துமா இஸ்ரவேலின் வருத்தத்தைக் கண்டு மனதுருகியது.",
    "Judges 11": "கீலேயாத்தியனாகிய யெப்தா பராக்கிரமசாலி; தன் சகோதரரால் துரத்திவிடப்பட்டவன்; அம்மோனியர் யுத்தம் பண்ண வந்தபோது கீலேயாத்தின் மூப்பர் அவனைத் தலைவனாக அழைத்தார்கள். அவன் அம்மோனிய ராஜாவுக்கு இஸ்ரவேலின் வரலாற்றை விளக்கிச் செய்தி அனுப்பினான்; அவனோ கேட்கவில்லை. ஜெயித்துத் திரும்பும்போது தன் வீட்டிலிருந்து முதலில் எதிர்கொண்டுவருவதைச் சர்வாங்க தகனமாக்குவேன் என்று யெப்தா பொருத்தனை பண்ணினான்; அவன் ஒரே மகள் தம்புருவோடு எதிர்கொண்டுவந்தாள், இரண்டு மாதத்துக்குப் பின் அவன் தன் பொருத்தனையின்படி அவளுக்குச் செய்தான்.",
    "Judges 12": "தங்களை யுத்தத்துக்கு அழைக்கவில்லை என்று எப்பிராயீமர் யெப்தாவோடு சண்டையிட வந்தார்கள்; கீலேயாத்தியர் அவர்களை முறியடித்தார்கள். யோர்தானின் துறைகளில் தப்பி ஓட வந்தவர்களை 'ஷிபோலேத்' என்று சொல்லச் சொன்னார்கள்; 'சிபோலேத்' என்று உச்சரித்தவர்கள் கொல்லப்பட்டார்கள். யெப்தா ஆறு வருஷம் நியாயம் விசாரித்தான்; அவனுக்குப் பின் இப்சான், ஏலோன், அப்தோன் நியாயாதிபதிகளாயிருந்தார்கள்.",
    "Judges 13": "இஸ்ரவேலர் மறுபடியும் பொல்லாப்புச் செய்ததால் பெலிஸ்தர் அவர்களை நாற்பது வருஷம் ஒடுக்கினார்கள். கர்த்தருடைய தூதன் மனோவாவின் மலடியான மனைவிக்குத் தோன்றி, அவள் ஒரு குமாரனைப் பெறுவாள் என்றும், அவன் பிறப்பிலிருந்தே நசரேயனாயிருந்து இஸ்ரவேலைப் பெலிஸ்தரின் கையிலிருந்து இரட்சிக்கத் தொடங்குவான் என்றும் சொன்னார். தூதன் பலிபீடத்தின் அக்கினிஜுவாலையில் ஏறிப்போனார்; சிம்சோன் பிறந்தான், கர்த்தருடைய ஆவி அவனை ஏவத் தொடங்கியது.",
    "Judges 14": "சிம்சோன் திம்னாத்திலுள்ள ஒரு பெலிஸ்தியப் பெண்ணை மணக்க விரும்பினான்; வழியில் தன்மேல் கர்ஜித்த சிங்கத்தைக் கையினால் கிழித்துப்போட்டான், பின்பு அதின் உடலில் தேன் கண்டான். கலியாண விருந்தில் முப்பது பேருக்கு விடுகதை சொன்னான்; அவன் மனைவி அழுது வற்புறுத்தி அதின் அர்த்தத்தை அறிந்து அவர்களுக்குச் சொல்லிவிட்டாள். கர்த்தருடைய ஆவி அவன்மேல் இறங்கியபோது, அவன் அஸ்கலோனில் முப்பது பேரைக் கொன்று பந்தயத்தைச் செலுத்தினான்; அவன் மனைவியோ வேறொருவனுக்குக் கொடுக்கப்பட்டாள்.",
    "Judges 15": "சிம்சோன் முந்நூறு நரிகளின் வால்களில் தீவட்டிகளைக் கட்டி, பெலிஸ்தரின் வயல்களையும் திராட்சத்தோட்டங்களையும் சுட்டெரித்தான்; பெலிஸ்தர் அவன் மனைவியையும் அவள் தகப்பனையும் சுட்டெரித்தார்கள். யூதா மனுஷர் அவனைக் கட்டிப் பெலிஸ்தரிடம் ஒப்புக்கொடுத்தார்கள்; கர்த்தருடைய ஆவி இறங்கியதும் கட்டுகள் அறுந்தன, அவன் கழுதையின் பச்சைத் தாடையெலும்பினால் ஆயிரம் பேரைக் கொன்றான். அவன் தாகமாயிருந்தபோது தேவன் தண்ணீர் புறப்படப்பண்ணினார்; சிம்சோன் இருபது வருஷம் இஸ்ரவேலுக்கு நியாயம் விசாரித்தான்.",
    "Judges 16": "சிம்சோன் காசாவின் பட்டணவாசல் கதவுகளைப் பெயர்த்து மலையுச்சிக்குச் சுமந்துகொண்டுபோனான். தெலீலாள் பணத்துக்காக அவனை மூன்றுதரம் வற்புறுத்தி ஏமாற்றப்பட்டு, கடைசியில் அவன் பலத்தின் இரகசியம் தலைமயிர் என்று அறிந்து அதைச் சிரைக்கச் செய்தாள்; கர்த்தர் அவனை விட்டு விலகினார், பெலிஸ்தர் அவன் கண்களைப் பிடுங்கினார்கள். தாகோனின் கோவிலில் 'இந்த ஒருவிசை மாத்திரம் என்னைப் பலப்படுத்தும்' என்று ஜெபித்து, தூண்களைத் தள்ளினான்; அவன் சாகும்போது கொன்றவர்கள், உயிரோடிருக்கையில் கொன்றவர்களைவிட அதிகமாயிருந்தார்கள்.",
    "Judges 17": "எப்பிராயீம் மலைநாட்டானாகிய மீகா தன் தாயின் வெள்ளியைத் திருடி, பின்பு திருப்பிக்கொடுத்தான்; அந்த வெள்ளியினால் ஒரு விக்கிரகம் செய்யப்பட்டது. மீகா தன் வீட்டில் தேவர்களின் வீட்டை உண்டாக்கி, ஏபோத்தையும் சுரூபங்களையும் செய்து, லேவியனான ஒரு வாலிபனைக் கூலிக்குத் தன் ஆசாரியனாக வைத்துக்கொண்டான். அந்நாட்களில் இஸ்ரவேலில் ராஜா இல்லை; அவனவன் தன் பார்வைக்குச் செம்மையாய்த் தோன்றினபடி செய்தான்.",
    "Judges 18": "தாண் கோத்திரத்தார் குடியிருக்க இடம் தேடி வேவுகாரரை அனுப்பினார்கள்; அவர்கள் மீகாவின் வீட்டில் லேவியனைச் சந்தித்து விசாரித்தார்கள். பின்பு அறுநூறு யுத்தவீரர் வந்து மீகாவின் விக்கிரகங்களையும் ஆசாரியனையும் எடுத்துக்கொண்டுபோனார்கள். அவர்கள் அமைதியாய்க் குடியிருந்த லாயீசைத் தாக்கி அழித்து, அதற்குத் தாண் என்று பேரிட்டு, அங்கே சுரூபத்தை நிறுத்தினார்கள்.",
    "Judges 19": "ஒரு லேவியன் தன் மறுமனையாட்டியைப் பெத்லகேமிலிருந்து அழைத்துக்கொண்டு திரும்பும்போது, பென்யமீனருடைய கிபியாவில் ஒரு கிழவனுடைய வீட்டில் தங்கினான். பட்டணத்தின் பேலியாளின் மக்கள் வீட்டை வளைந்துகொண்டார்கள்; அவன் மறுமனையாட்டியை இராமுழுவதும் கொடுமைப்படுத்தினார்கள், அவள் விடியற்காலத்தில் வாசற்படியில் செத்துக்கிடந்தாள். லேவியன் அவள் உடலைப் பன்னிரண்டு துண்டாக்கி இஸ்ரவேலின் எல்லைகளுக்கெல்லாம் அனுப்பினான்.",
    "Judges 20": "இஸ்ரவேலர் மிஸ்பாவில் ஒன்றுகூடி, கிபியாவின் குற்றவாளிகளை ஒப்புக்கொடுக்கும்படி கேட்டார்கள்; பென்யமீனியரோ மறுத்து யுத்தத்துக்கு வந்தார்கள். இரண்டு நாள் இஸ்ரவேலர் தோற்றுப்போய், கர்த்தருக்கு முன்பாக அழுது உபவாசித்து விசாரித்தார்கள். மூன்றாம் நாள் பதிவிருக்கும் சேனையைக் கொண்டு பென்யமீனை முறியடித்தார்கள்; அறுநூறு பேர் மாத்திரம் ரிம்மோன் கன்மலைக்குத் தப்பி ஓடினார்கள்.",
    "Judges 21": "தங்கள் குமாரத்திகளைப் பென்யமீனருக்குக் கொடுப்பதில்லை என்று ஆணையிட்டிருந்ததால், இஸ்ரவேலில் ஒரு கோத்திரம் அழிந்துபோகுமே என்று ஜனங்கள் அழுதார்கள். யாபேஸ் கீலேயாத்திலிருந்து நானூறு கன்னிகைகள் பென்யமீனருக்குக் கொடுக்கப்பட்டார்கள்; மற்றவர்கள் சீலோவின் பண்டிகையில் நடனமாடின பெண்களைப் பிடித்துக்கொண்டார்கள். அந்நாட்களில் இஸ்ரவேலில் ராஜா இல்லை; அவனவன் தன் பார்வைக்குச் செம்மையாய்த் தோன்றினபடி செய்தான்.",

    "Ruth 1": "நியாயாதிபதிகள் காலத்தில் உண்டான பஞ்சத்தினால், எலிமெலேக்கும் அவன் மனைவி நகோமியும் இரண்டு குமாரரும் பெத்லகேமிலிருந்து மோவாப் தேசத்துக்குப் போனார்கள்; அங்கே எலிமெலேக்கும் இரண்டு குமாரரும் மரித்தார்கள். நகோமி திரும்பிப்போகும்போது ஒர்பாள் தன் ஜனத்தண்டைக்குத் திரும்பினாள்; ரூத்தோ, 'நீர் போகும் இடத்துக்கு நானும் வருவேன்; உம்முடைய ஜனம் என் ஜனம், உம்முடைய தேவன் என் தேவன்' என்று சொல்லி அவளைப் பற்றிக்கொண்டாள். அவர்கள் வாற்கோதுமை அறுப்பின் துவக்கத்தில் பெத்லகேமுக்கு வந்தார்கள்; 'என்னை மாராள் என்று சொல்லுங்கள்' என்று நகோமி சொன்னாள்.",
    "Ruth 2": "ரூத் எலிமெலேக்கின் இனத்தானாகிய போவாசின் வயலில் கதிர் பொறுக்கினாள். அவள் தன் மாமிக்குக் காட்டின அன்பைக் கேள்விப்பட்ட போவாஸ், 'இஸ்ரவேலின் தேவனுடைய செட்டைகளின் கீழ் அடைக்கலமாய் வந்த உனக்கு அவர் பூரண பலனைக் கொடுப்பாராக' என்று சொல்லி, அவளுக்குத் தயவு காட்டினான். போவாஸ் நம்மை மீட்கத்தக்க சுதந்தரவாளிகளில் ஒருவன் என்று நகோமி ரூத்திடம் சொன்னாள்.",
    "Ruth 3": "நகோமியின் ஆலோசனைப்படி ரூத் இரவில் களத்துக்குப் போய், போவாசின் கால்மாட்டில் படுத்துக்கொண்டாள். 'நீர் சுதந்தரவாளியானபடியால் உம்முடைய போர்வையை உமது அடியாள்மேல் போடும்' என்று கேட்டாள். போவாஸ் அவளைக் குணசாலியான ஸ்திரீ என்று சொல்லி, தன்னைவிட நெருங்கிய சுதந்தரவாளி மீட்காவிட்டால் தானே மீட்பதாக வாக்களித்து, ஆறுபடி வாற்கோதுமையைக் கொடுத்தனுப்பினான்.",
    "Ruth 4": "போவாஸ் பட்டணவாசலில் பத்து மூப்பருக்கு முன்பாக நெருங்கிய சுதந்தரவாளியோடு பேசினான்; அவன் மீட்க மறுத்து, அடையாளமாகத் தன் பாதரட்சையைக் கழற்றிக் கொடுத்தான். போவாஸ் ரூத்தை மணந்தான்; அவள் ஓபேதைப் பெற்றாள், 'நகோமிக்கு ஒரு குமாரன் பிறந்தான்' என்று ஸ்திரீகள் சொன்னார்கள். ஓபேத் ஈசாயைப் பெற்றான், ஈசாய் தாவீதைப் பெற்றான்; பாரேஸ் முதல் தாவீது வரையிலான வம்ச அட்டவணையும் கொடுக்கப்பட்டுள்ளது.",

    "1 Samuel 1": "எல்க்கானாவின் மனைவியாகிய அன்னாள் பிள்ளையில்லாதிருந்தாள்; அவன் மற்ற மனைவியாகிய பெனின்னாள் அவளை மிகவும் விசனப்படுத்தினாள். அன்னாள் சீலோவில் மனங்கசந்து அழுது ஜெபித்து, தனக்கு ஒரு ஆண்பிள்ளையைக் கொடுத்தால் அவனைக் கர்த்தருக்கு ஒப்புக்கொடுப்பேன் என்று பொருத்தனை பண்ணினாள்; அவள் வெறித்திருக்கிறாள் என்று நினைத்த ஆசாரியனாகிய ஏலி, பின்பு அவளை ஆசீர்வதித்து அனுப்பினான். அன்னாள் சாமுவேலைப் பெற்று, அவன் பால் மறந்தபின் சீலோவில் கர்த்தருக்கு ஒப்புக்கொடுத்தாள்.",
    "1 Samuel 2": "அன்னாள், 'என் இருதயம் கர்த்தருக்குள் களிகூருகிறது' என்று ஜெபப்பாட்டுப் பாடி, சிறியவனைப் புழுதியிலிருந்து உயர்த்துகிற தேவனைத் துதித்தாள். ஏலியின் குமாரராகிய ஓப்னியும் பினெகாசும் பேலியாளின் மக்களாயிருந்து, கர்த்தருடைய காணிக்கைகளை அசட்டைபண்ணினார்கள்; சிறுவனாகிய சாமுவேலோ கர்த்தருக்கு முன்பாக வளர்ந்தான். ஒரு தேவனுடைய மனுஷன் ஏலியின் வீட்டுக்கு வரும் நியாயத்தீர்ப்பை முன்னறிவித்து, 'என்னைக் கனம்பண்ணுகிறவர்களை நான் கனம்பண்ணுவேன்' என்று கர்த்தர் சொல்லுகிறார் என்றான்.",
    "1 Samuel 3": "அந்நாட்களில் கர்த்தருடைய வசனம் அபூர்வமாயிருந்தது. கர்த்தர் இரவில் சாமுவேலை மூன்றுதரம் அழைத்தார்; 'கர்த்தாவே சொல்லும், அடியேன் கேட்கிறேன்' என்று சொல்லும்படி ஏலி அவனுக்குக் கற்றுக்கொடுத்தான். கர்த்தர் ஏலியின் வீட்டுக்கு வரும் நியாயத்தீர்ப்பைச் சாமுவேலுக்கு அறிவித்தார்; சாமுவேல் கர்த்தருடைய தீர்க்கதரிசி என்று தாண்முதல் பெயெர்செபாமட்டுமுள்ள இஸ்ரவேலர் எல்லாரும் அறிந்தார்கள்.",
    "1 Samuel 4": "இஸ்ரவேலர் பெலிஸ்தரிடம் தோற்றுப்போனபோது, சீலோவிலிருந்து உடன்படிக்கைப் பெட்டியை யுத்தத்துக்குக் கொண்டுவந்தார்கள். அவர்கள் மறுபடியும் தோற்றுப்போனார்கள்; தேவனுடைய பெட்டி பிடிக்கப்பட்டது, ஓப்னியும் பினெகாசும் கொல்லப்பட்டார்கள். அதைக் கேட்ட ஏலி ஆசனத்திலிருந்து விழுந்து பிடரி முறிந்து மரித்தான்; பினெகாசின் மனைவி பிரசவித்து, 'மகிமை இஸ்ரவேலை விட்டுப் போயிற்று' என்று சொல்லி, பிள்ளைக்கு 'இக்கபோத்' என்று பேரிட்டாள்.",
    "1 Samuel 5": "பெலிஸ்தர் தேவனுடைய பெட்டியை அஸ்தோத்திலுள்ள தாகோனின் கோவிலில் வைத்தார்கள்; மறுநாள் தாகோன் பெட்டிக்கு முன்பாக முகங்குப்புற விழுந்துகிடந்தது, பின்பு அதின் தலையும் கைகளும் உடைந்துகிடந்தன. கர்த்தருடைய கை அஸ்தோத், காத், எக்ரோன் பட்டணத்தாரை மூலவியாதியால் வாதித்தது. இஸ்ரவேலின் தேவனுடைய பெட்டியைத் திருப்பி அனுப்பிவிட வேண்டும் என்று பெலிஸ்தர் சொன்னார்கள்.",
    "1 Samuel 6": "ஏழு மாதத்துக்குப் பின், பெலிஸ்தர் குற்றநிவாரணமாக ஐந்து பொன் மூலவியாதி சுரூபங்களையும் ஐந்து பொன் எலிகளையும் வைத்து, இரண்டு கறவைப் பசுக்கள் பூட்டின புது வண்டியில் பெட்டியை அனுப்பினார்கள். பசுக்கள் வலதுபுறம் இடதுபுறம் விலகாமல் நேராகப் பெத்ஷிமேசுக்குப் போயின. பெட்டிக்குள் பார்த்ததினால் பெத்ஷிமேசின் மனுஷர் அடிக்கப்பட்டார்கள்; அவர்கள் பெட்டியைக் கீரியாத்யாரீமுக்கு அனுப்பினார்கள்.",
    "1 Samuel 7": "பெட்டி கீரியாத்யாரீமில் இருபது வருஷம் இருந்தது. சாமுவேல் அந்நிய தேவர்களை அகற்றும்படி சொல்லி, ஜனங்களை மிஸ்பாவில் கூட்டி அவர்களுக்காக ஜெபித்தான்; பெலிஸ்தர் யுத்தத்துக்கு வந்தபோது கர்த்தர் பெரிய இடிமுழக்கத்தால் அவர்களைக் கலங்கடித்தார். சாமுவேல் ஒரு கல்லை நிறுத்தி, 'இம்மட்டும் கர்த்தர் நமக்கு உதவி செய்தார்' என்று சொல்லி அதற்கு 'எபெனேசர்' என்று பேரிட்டான்; அவன் தன் வாழ்நாளெல்லாம் இஸ்ரவேலுக்கு நியாயம் விசாரித்தான்.",
    "1 Samuel 8": "சாமுவேலின் குமாரர் லஞ்சம் வாங்கி நியாயத்தைப் புரட்டினதால், இஸ்ரவேலின் மூப்பர் 'எல்லா ஜாதிகளுக்கும் இருக்கிறதுபோல எங்களுக்கும் ஒரு ராஜாவை ஏற்படுத்தும்' என்று கேட்டார்கள். 'அவர்கள் உன்னை அல்ல, தங்களை நான் ஆளாதபடிக்கு என்னையே புறக்கணித்தார்கள்' என்று கர்த்தர் சாமுவேலிடம் சொன்னார். ராஜா அவர்கள்மேல் சுமத்தும் பாரங்களைச் சாமுவேல் எச்சரித்தும் ஜனங்கள் கேட்கவில்லை; அவர்களுக்கு ராஜாவை ஏற்படுத்தும்படி கர்த்தர் சொன்னார்.",
    "1 Samuel 9": "பென்யமீனனாகிய கீசின் குமாரன் சவுல் அழகும் உயரமுமான வாலிபன்; அவன் தன் தகப்பனுடைய காணாமற்போன கழுதைகளைத் தேடிப் புறப்பட்டான். அவைகளைக் காணாததால் ஞானதிருஷ்டிக்காரனாகிய சாமுவேலிடம் விசாரிக்க வந்தான்; முந்தின நாளே கர்த்தர் அவனைக் குறித்துச் சாமுவேலுக்கு அறிவித்திருந்தார். சாமுவேல் சவுலை விருந்துக்கு அழைத்து மரியாதை செய்து, தேவனுடைய வார்த்தையை அவனுக்குத் தெரிவிக்கும்படி நிறுத்தினான்.",
    "1 Samuel 10": "சாமுவேல் சவுலின் தலையில் தைலத்தை வார்த்து அவனை அபிஷேகம் பண்ணி, நடக்கப்போகும் அடையாளங்களைச் சொன்னான்; தேவன் அவனுக்கு வேறே இருதயத்தைக் கொடுத்தார், அவன் தீர்க்கதரிசிகளோடு தீர்க்கதரிசனம் சொன்னான். மிஸ்பாவில் சீட்டுப்போட்டபோது சீட்டு சவுலின் பேரில் விழுந்தது; அவனோ தளவாடங்களுக்குள் ஒளிந்திருந்தான். ஜனங்கள் 'ராஜா வாழ்க' என்று ஆர்ப்பரித்தார்கள்; சில பேலியாளின் மக்கள் மாத்திரம் அவனை அசட்டைபண்ணினார்கள்.",
    "1 Samuel 11": "அம்மோனியனாகிய நாகாஸ் யாபேஸ் கீலேயாத்தை முற்றுகையிட்டு, அவர்கள் வலதுகண்களைப் பிடுங்கினால் மாத்திரம் உடன்படிக்கை பண்ணுவேன் என்றான். தேவனுடைய ஆவி சவுலின்மேல் இறங்கியது; அவன் இஸ்ரவேலரைக் கூட்டி அம்மோனியரை முறியடித்தான். பின்பு ஜனங்கள் கில்காலுக்குப் போய், அங்கே கர்த்தருக்கு முன்பாக சவுலை ராஜாவாக்கி ராஜ்யத்தைப் புதுப்பித்தார்கள்.",
    "1 Samuel 12": "சாமுவேல் தன் உத்தமத்துக்கு ஜனங்களைச் சாட்சியாக்கி, கர்த்தர் அவர்கள் பிதாக்களுக்குச் செய்த நீதியான செயல்களை நினைப்பூட்டினான்; ராஜாவைக் கேட்டது பொல்லாப்பு என்பதற்கு அடையாளமாக, கோதுமை அறுப்புக்காலத்தில் இடிமுழக்கமும் மழையும் வரப்பண்ணினான். ஜனங்கள் பயந்தபோது, 'பயப்படாதிருங்கள்; உங்கள் முழு இருதயத்தோடும் கர்த்தரைச் சேவியுங்கள்' என்றான். 'நான் உங்களுக்காக ஜெபம் பண்ணாமல் கர்த்தருக்கு விரோதமாய்ப் பாவஞ்செய்வது எனக்குத் தூரமாயிருப்பதாக' என்றும் சொன்னான்.",
    "1 Samuel 13": "யோனத்தான் பெலிஸ்தரின் தாணையத்தை முறியடித்தான்; பெலிஸ்தர் திரளான சேனையோடு வந்ததால் இஸ்ரவேலர் பயந்து குகைகளில் ஒளிந்தார்கள். சாமுவேல் வரத் தாமதித்ததால், சவுல் தானே தகனபலியைச் செலுத்தினான். 'நீ மதியீனமாய்ச் செய்தாய்; உன் ராஜ்யம் நிலைநிற்காது; கர்த்தர் தம்முடைய இருதயத்துக்கு ஏற்ற ஒரு மனுஷனைத் தேடியிருக்கிறார்' என்று சாமுவேல் சொன்னான்.",
    "1 Samuel 14": "'அநேகம் பேரைக் கொண்டாகிலும் கொஞ்சம் பேரைக் கொண்டாகிலும் இரட்சிக்கக் கர்த்தருக்குத் தடையில்லை' என்று சொல்லி, யோனத்தானும் அவன் ஆயுததாரியும் பெலிஸ்தரின் தாணையத்தை ஏறித் தாக்கினார்கள்; பூமி அதிர்ந்து பெலிஸ்தர் கலங்கினார்கள். ஜனங்கள் சாயங்காலம் வரை புசிக்கக்கூடாது என்று சவுல் இட்ட ஆணையை அறியாமல் யோனத்தான் தேனை ருசித்தான்; சவுல் அவனைக் கொல்லப் பார்த்தபோது ஜனங்கள் அவனை மீட்டுக்கொண்டார்கள். சவுல் சுற்றிலுமுள்ள சத்துருக்கள் எல்லாரோடும் யுத்தம் பண்ணினான்.",
    "1 Samuel 15": "அமலேக்கியரை முற்றிலும் அழிக்கும்படி கர்த்தர் கட்டளையிட்டார்; சவுலோ அவர்கள் ராஜாவாகிய ஆகாகையும் நல்ல ஆடுமாடுகளையும் தப்பவைத்தான். 'பலியைப் பார்க்கிலும் கீழ்ப்படிதலும், ஆட்டுக்கடாக்களின் நிணத்தைப் பார்க்கிலும் செவிகொடுத்தலும் உத்தமம்' என்றும், நீ கர்த்தருடைய வார்த்தையைப் புறக்கணித்தபடியால் அவர் உன்னை ராஜாவாயிராதபடிக்குப் புறக்கணித்தார் என்றும் சாமுவேல் சொன்னான். சாமுவேல் ஆகாகைக் கொன்றான்; அதன்பின் சவுலைக் காணாமல், அவனுக்காகத் துக்கித்துக்கொண்டிருந்தான்.",
    "1 Samuel 16": "கர்த்தர் சாமுவேலைப் பெத்லகேமிலுள்ள ஈசாயினிடத்துக்கு அனுப்பி, 'மனுஷன் முகத்தைப் பார்க்கிறான்; கர்த்தரோ இருதயத்தைப் பார்க்கிறார்' என்றார். ஈசாயின் ஏழு குமாரரில் ஒருவனையும் கர்த்தர் தெரிந்துகொள்ளவில்லை; ஆடுமேய்த்துக்கொண்டிருந்த இளையவனாகிய தாவீதைச் சாமுவேல் அபிஷேகம் பண்ணினான், அன்றுமுதல் கர்த்தருடைய ஆவி தாவீதின்மேல் இறங்கியிருந்தது. கர்த்தருடைய ஆவி சவுலை விட்டு விலகி, பொல்லாத ஆவி அவனைக் கலங்கப்பண்ணியது; தாவீது சுரமண்டலம் வாசித்து அவனுக்கு ஆறுதல் கொடுத்து, அவனுடைய ஆயுததாரியானான்.",
    "1 Samuel 17": "பெலிஸ்திய இராட்சதனாகிய கோலியாத் நாற்பது நாள் இஸ்ரவேலின் சேனைகளை நிந்தித்தான்; எல்லாரும் பயந்தார்கள். 'ஜீவனுள்ள தேவனுடைய சேனைகளை நிந்திக்க இந்த விருத்தசேதனமில்லாத பெலிஸ்தன் யார்?' என்று தாவீது கேட்டு, சிங்கத்தின் கைக்கும் கரடியின் கைக்கும் தப்புவித்த கர்த்தர் இவன் கைக்கும் தப்புவிப்பார் என்றான். 'நீ பட்டயத்தோடும் ஈட்டியோடும் வருகிறாய்; நானோ சேனைகளின் கர்த்தருடைய நாமத்திலே வருகிறேன்' என்று சொல்லி, கவணில் கல்லை வைத்து அவனை அடித்து வீழ்த்தி, அவன் பட்டயத்தினாலேயே அவன் தலையை வெட்டினான்.",
    "1 Samuel 18": "யோனத்தானின் ஆத்துமா தாவீதின் ஆத்துமாவோடே ஒன்றாய் இசைந்தது; அவன் தாவீதோடு உடன்படிக்கை பண்ணி, தன் சால்வையையும் ஆயுதங்களையும் அவனுக்குக் கொடுத்தான். 'சவுல் கொன்றது ஆயிரம், தாவீது கொன்றது பதினாயிரம்' என்று ஸ்திரீகள் பாடினதால், சவுல் எரிச்சலடைந்து தாவீதின்மேல் ஈட்டியை எறிந்தான். பெலிஸ்தரின் கையால் அவன் சாகட்டும் என்று சவுல் தன் குமாரத்தி மீகாளுக்காக நூறு பெலிஸ்தரின் நுனித்தோல்களைக் கேட்டான்; தாவீது இருநூறு கொண்டுவந்து மீகாளை மணந்தான், கர்த்தர் அவனோடிருந்தார்.",
    "1 Samuel 19": "சவுல் தாவீதைக் கொல்லும்படி சொன்னபோது, யோனத்தான் தன் தகப்பனோடு பேசி அவனை அமர்த்தினான். சவுல் மறுபடியும் ஈட்டியை எறிந்தபோது, மீகாள் தாவீதை ஜன்னல் வழியாய் இறக்கிவிட்டு, ஒரு சுரூபத்தைக் கட்டிலில் வைத்து ஆட்களை ஏமாற்றினாள். தாவீது ராமாவிலிருந்த சாமுவேலிடம் ஓடிப்போனான்; அவனைப் பிடிக்க சவுல் அனுப்பின ஆட்களும், பின்பு சவுலுமே தேவனுடைய ஆவியினால் தீர்க்கதரிசனம் சொன்னார்கள்.",
    "1 Samuel 20": "யோனத்தான் தாவீதோடு உடன்படிக்கை பண்ணி, சவுலின் மனதை அறிவிக்க அம்பெய்யும் அடையாளத்தை ஏற்படுத்தினான். அமாவாசை விருந்தில் தாவீது வராததைக் குறித்து யோனத்தான் பேசினபோது, சவுல் கோபங்கொண்டு அவன்மேல் ஈட்டியை எறிந்தான். யோனத்தான் அம்புகளால் அடையாளம் காட்டினான்; இருவரும் ஒருவரையொருவர் முத்தமிட்டு அழுது, கர்த்தருடைய நாமத்தில் ஆணையிட்டுப் பிரிந்தார்கள்.",
    "1 Samuel 21": "தாவீது நோபிலுள்ள ஆசாரியனாகிய அகிமெலேக்கிடம் போய், பரிசுத்த அப்பத்தையும் கோலியாத்தின் பட்டயத்தையும் பெற்றுக்கொண்டான்; சவுலின் மேய்ப்பர் தலைவனாகிய ஏதோமியன் தோவேக் அதைக் கண்டான். தாவீது காத்தின் ராஜாவாகிய ஆகீசிடம் ஓடிப்போனான். அங்கே அவனை அடையாளம் கண்டபோது, அவன் பயந்து பித்தங்கொண்டவன்போல் நடித்துத் தப்பினான்.",
    "1 Samuel 22": "தாவீது அதுல்லாம் குகைக்குத் தப்பிப்போனான்; நெருக்கப்பட்டவர்களும் கடன்பட்டவர்களும் முறுமுறுப்புள்ளவர்களுமாகிய ஏறக்குறைய நானூறு பேர் அவனிடம் கூடிவந்தார்கள். தோவேக் நோபில் நடந்ததைச் சவுலிடம் அறிவித்தான்; சவுலின் கட்டளைப்படி தோவேக் எண்பத்தைந்து ஆசாரியர்களைக் கொன்று, நோப் பட்டணத்தை அழித்தான். அகிமெலேக்கின் குமாரனாகிய அபியத்தார் மாத்திரம் தப்பி தாவீதிடம் வந்தான்.",
    "1 Samuel 23": "தாவீது கர்த்தரிடம் விசாரித்து, கேகிலா பட்டணத்தைப் பெலிஸ்தரிடமிருந்து காப்பாற்றினான்; கேகிலாவின் குடிகள் தன்னைச் சவுலுக்கு ஒப்புக்கொடுப்பார்கள் என்று அறிந்து அங்கிருந்து விலகினான். சீப் வனாந்தரத்தில் யோனத்தான் வந்து தாவீதைத் தேவனுக்குள் திடப்படுத்தினான். சீப்பூரார் அவனைக் காட்டிக்கொடுத்தார்கள்; சவுல் நெருங்கி வந்தபோது, பெலிஸ்தர் தேசத்தில் படையெடுத்தார்கள் என்ற செய்தி வந்ததால் அவன் திரும்பிப்போனான்.",
    "1 Samuel 24": "என்கேதியிலுள்ள குகைக்குள் சவுல் தனியாக வந்தபோது, தாவீது அவனைக் கொல்லாமல் அவன் சால்வையின் தொங்கலை மாத்திரம் அறுத்துக்கொண்டான். 'கர்த்தருடைய அபிஷேகம் பெற்றவன்மேல் என் கையைப் போடமாட்டேன்' என்று தாவீது தன் ஆட்களிடம் சொன்னான். சவுல் சத்தமிட்டு அழுது, 'நீ என்னைப் பார்க்கிலும் நீதிமான்; நீ நிச்சயமாய் ராஜாவாவாய்' என்று சொல்லி, தன் சந்ததியை அழிக்காதபடி ஆணையிடும்படி கேட்டான்.",
    "1 Samuel 25": "சாமுவேல் மரித்தான்; இஸ்ரவேலர் எல்லாரும் கூடி அவனுக்காகப் புலம்பினார்கள். ஐசுவரியவானும் மூடனுமாகிய நாபால் தாவீதின் ஆட்களுக்கு உதவி செய்ய மறுத்து அவர்களை நிந்தித்தான்; தாவீது பழிவாங்கப் புறப்பட்டான். நாபாலின் மனைவியாகிய புத்திசாலியான அபிகாயில் உணவுப்பொருட்களோடு வந்து, இரத்தம் சிந்தாதபடி தாவீதைத் தடுத்தாள்; பத்து நாளுக்குப் பின் கர்த்தர் நாபாலை அடித்தார், தாவீது அபிகாயிலை மனைவியாக்கிக்கொண்டான்.",
    "1 Samuel 26": "சீப்பூரார் மறுபடியும் தாவீது இருக்கும் இடத்தைச் சவுலுக்கு அறிவித்தார்கள். தாவீதும் அபிசாயும் இரவில் சவுலின் பாளயத்துக்குள் போய், அவன் தலைமாட்டிலிருந்த ஈட்டியையும் தண்ணீர்ச் செம்பையும் எடுத்துக்கொண்டார்கள்; கர்த்தருடைய அபிஷேகம் பெற்றவனைக் கொல்லத் தாவீது மறுத்தான். சவுல் 'நான் பாவஞ்செய்தேன்' என்று ஒப்புக்கொண்டு, தாவீதை ஆசீர்வதித்தான்.",
    "1 Samuel 27": "என்றாவது ஒருநாள் சவுலின் கையால் அழிவேன் என்று பயந்து, தாவீது அறுநூறு பேரோடு பெலிஸ்தரின் ராஜாவாகிய ஆகீசிடம் போனான்; ஆகீஸ் அவனுக்குச் சிக்லாகைக் கொடுத்தான். தாவீது அங்கே ஒரு வருஷமும் நாலு மாதமும் இருந்து, கெசூரியர், கிர்சியர், அமலேக்கியர் ஆகியோரைத் தாக்கினான். தாவீது தன் ஜனத்துக்கு வெறுப்பானவனானான் என்று ஆகீஸ் நம்பினான்.",
    "1 Samuel 28": "பெலிஸ்தர் இஸ்ரவேலுக்கு விரோதமாக யுத்தத்துக்குக் கூடினபோது சவுல் மிகவும் பயந்தான்; கர்த்தர் சொப்பனங்களினாலும் ஊரீமினாலும் தீர்க்கதரிசிகளினாலும் அவனுக்கு உத்தரவு கொடுக்கவில்லை. தானே தேசத்திலிருந்து அகற்றின அஞ்சனக்காரரில் ஒருத்தியிடம் சவுல் வேஷம் மாறி எந்தோருக்குப் போனான்; அவள் சாமுவேல் எழும்பி வருவதைக் கண்டாள். கர்த்தர் ராஜ்யத்தைத் தாவீதுக்குக் கொடுத்தார் என்றும், நாளைக்கு சவுலும் அவன் குமாரரும் தன்னோடே இருப்பார்கள் என்றும் சாமுவேல் சொன்னதைக் கேட்டு, சவுல் தரையிலே விழுந்தான்.",
    "1 Samuel 29": "பெலிஸ்தரின் பிரபுக்கள் தாவீதைக் கண்டு, யுத்தத்தில் அவன் தங்களுக்கு விரோதியாவான் என்று சந்தேகப்பட்டார்கள். தாவீது உத்தமன் என்று ஆகீஸ் சொன்னாலும், பிரபுக்களின் வார்த்தையினிமித்தம் அவனைத் திரும்பிப்போகச் சொன்னான். தாவீதும் அவன் ஆட்களும் விடியற்காலத்தில் பெலிஸ்தரின் தேசத்துக்குத் திரும்பிப்போனார்கள்.",
    "1 Samuel 30": "தாவீதும் அவன் ஆட்களும் சிக்லாகுக்கு வந்தபோது, அமலேக்கியர் பட்டணத்தைச் சுட்டெரித்து அவர்கள் மனைவிகளையும் பிள்ளைகளையும் சிறைபிடித்துக்கொண்டுபோயிருந்தார்கள்; ஜனங்கள் தாவீதைக் கல்லெறியப் பார்த்தார்கள். தாவீதோ தன் தேவனாகிய கர்த்தருக்குள் தன்னைத் திடப்படுத்திக்கொண்டு, கர்த்தரிடம் விசாரித்து, அமலேக்கியரைப் பின்தொடர்ந்து எல்லாவற்றையும் மீட்டுக்கொண்டான். யுத்தத்துக்குப் போனவர்களுக்கும் சாமான்களண்டை இருந்தவர்களுக்கும் சரிபங்கு என்று இஸ்ரவேலுக்கு ஒரு கட்டளையை ஏற்படுத்தினான்.",
    "1 Samuel 31": "கில்போவா மலையில் பெலிஸ்தர் இஸ்ரவேலரை முறியடித்தார்கள்; யோனத்தானும் சவுலின் மற்ற இரண்டு குமாரரும் கொல்லப்பட்டார்கள். வில்வீரரால் காயப்பட்ட சவுல் தன் பட்டயத்தின்மேல் விழுந்து மரித்தான். பெலிஸ்தர் அவன் உடலைப் பெத்சானின் அலங்கத்தில் தொங்கவிட்டார்கள்; யாபேஸ் கீலேயாத்தின் பராக்கிரமசாலிகள் இரவில் போய் அதை எடுத்து அடக்கம் பண்ணி, ஏழு நாள் உபவாசித்தார்கள்.",

    "2 Samuel 1": "சவுல் மரித்தபின், ஒரு அமலேக்கியன் சவுலின் கிரீடத்தையும் கடகத்தையும் கொண்டுவந்து, தானே சவுலைக் கொன்றதாகத் தாவீதிடம் சொன்னான். தாவீதும் அவன் ஆட்களும் தங்கள் வஸ்திரங்களைக் கிழித்து, சாயங்காலம் மட்டும் அழுது உபவாசித்தார்கள்; கர்த்தருடைய அபிஷேகம் பெற்றவனைக் கொன்றதாகச் சொன்ன அந்த அமலேக்கியனைத் தாவீது கொல்லுவித்தான். 'பராக்கிரமசாலிகள் எப்படி விழுந்தார்கள்!' என்று தாவீது சவுலுக்காகவும் யோனத்தானுக்காகவும் புலம்பல் பாட்டுப் பாடினான்.",
    "2 Samuel 2": "தாவீது கர்த்தரிடம் விசாரித்து எபிரோனுக்குப் போனான்; யூதா மனுஷர் அங்கே அவனை யூதா வம்சத்தின்மேல் ராஜாவாக அபிஷேகம் பண்ணினார்கள். சவுலின் சேனாபதியாகிய அப்னேர் சவுலின் குமாரன் இஸ்போசேத்தை இஸ்ரவேலின்மேல் ராஜாவாக்கினான். கிபியோனில் இரு தரப்பாருக்கும் யுத்தம் நடந்தது; அதில் அப்னேர் யோவாபின் சகோதரனாகிய ஆசகேலைக் கொன்றான்.",
    "2 Samuel 3": "சவுலின் வீட்டாருக்கும் தாவீதின் வீட்டாருக்கும் நீண்டகாலம் யுத்தம் நடந்தது; தாவீது பலத்துக்கொண்டே வந்தான், சவுலின் வீடு பலவீனப்பட்டது. அப்னேர் இஸ்போசேத்தோடு பிணங்கி, தாவீதிடம் வந்து இஸ்ரவேலை அவன் பக்கம் திருப்புவதாக உடன்படிக்கை பண்ணினான். யோவாப் தன் சகோதரன் ஆசகேலினிமித்தம் அப்னேரை வஞ்சகமாய்க் கொன்றான்; தாவீது அழுது, 'இன்று இஸ்ரவேலில் ஒரு பிரபுவும் பெரியவனும் விழுந்தான்' என்றான்.",
    "2 Samuel 4": "அப்னேர் மரித்ததைக் கேட்டு இஸ்போசேத்தின் கைகள் தளர்ந்தன, இஸ்ரவேலர் எல்லாரும் கலங்கினார்கள். யோனத்தானின் குமாரனாகிய மேவிபோசேத் ஐந்து வயதில் தாதி தூக்கிக்கொண்டு ஓடும்போது விழுந்து முடவனானான். ரேகாபும் பானாவும் இஸ்போசேத்தை அவன் படுக்கையிலேயே கொன்று, அவன் தலையைத் தாவீதிடம் கொண்டுவந்தார்கள்; நீதிமானைக் கொன்ற அவர்களைத் தாவீது கொல்லுவித்தான்.",
    "2 Samuel 5": "இஸ்ரவேல் கோத்திரங்கள் எல்லாம் எபிரோனுக்கு வந்து தாவீதை இஸ்ரவேலின்மேல் ராஜாவாக அபிஷேகம் பண்ணினார்கள்; அவன் முப்பது வயதில் ராஜாவாகி நாற்பது வருஷம் அரசாண்டான். தாவீது எபூசியரிடமிருந்து சீயோன் கோட்டையைப் பிடித்தான்; அது தாவீதின் நகரம் எனப்பட்டது; தீருவின் ராஜாவாகிய ஈராம் அவனுக்கு ஒரு அரமனையைக் கட்டினான். தாவீது கர்த்தரிடம் விசாரித்து, பெலிஸ்தரை இரண்டுதரம் முறியடித்தான்.",
    "2 Samuel 6": "தாவீது தேவனுடைய பெட்டியை ஒரு புது வண்டியில் ஏற்றிக் கொண்டுவந்தான்; மாடுகள் இடறினபோது ஊசா பெட்டியைப் பிடித்ததால், தேவன் அவனை அடித்தார், அவன் அங்கே செத்தான். பெட்டி ஓபேத்ஏதோமின் வீட்டில் மூன்று மாதம் இருந்தது; கர்த்தர் அவன் வீட்டையெல்லாம் ஆசீர்வதித்தார். பின்பு தாவீது மகிழ்ச்சியோடு பெட்டியை எருசலேமுக்குக் கொண்டுவந்து, கர்த்தருக்கு முன்பாகத் தன் முழுப் பலத்தோடும் நடனம்பண்ணினான்; அதைக் கண்டு அசட்டைபண்ணின மீகாள் மரணமட்டும் பிள்ளையில்லாதிருந்தாள்.",
    "2 Samuel 7": "தான் கேதுரு மரத்தால் கட்டப்பட்ட வீட்டில் இருக்க, தேவனுடைய பெட்டி திரைகளுக்குள் இருக்கிறதே என்று தாவீது ஆலயம் கட்ட விரும்பினான். நீ அல்ல, உன் சந்ததியான குமாரனே என் நாமத்துக்கு ஆலயத்தைக் கட்டுவான் என்றும், 'கர்த்தர் உனக்கு ஒரு வீட்டை உண்டுபண்ணுவார்', உன் ராஜ்யம் என்றென்றைக்கும் நிலைநிற்கும் என்றும் கர்த்தர் நாத்தான் மூலம் சொன்னார். தாவீது கர்த்தருக்கு முன்பாக உட்கார்ந்து, 'நான் எம்மாத்திரம்?' என்று நன்றியோடு ஜெபம் பண்ணினான்.",
    "2 Samuel 8": "தாவீது பெலிஸ்தரையும் மோவாபியரையும், சோபாவின் ராஜாவாகிய ஆதாதேசரையும், சீரியரையும், ஏதோமியரையும் முறியடித்தான். தாவீது போன இடமெல்லாம் கர்த்தர் அவனுக்கு ஜெயம் கொடுத்தார். தாவீது தன் ஜனங்கள் எல்லாருக்கும் நியாயமும் நீதியும் செய்தான்; அவனுடைய பிரதான அதிகாரிகளின் பேர்களும் சொல்லப்பட்டுள்ளன.",
    "2 Samuel 9": "யோனத்தானினிமித்தம் தயவு காட்டும்படி சவுலின் வீட்டில் யாராவது மீந்திருக்கிறார்களா என்று தாவீது கேட்டான். சவுலின் வேலைக்காரனாகிய சீபா மூலம் முடவனான மேவிபோசேத்தைக் கண்டு அழைப்பித்தான். 'பயப்படாதே' என்று சொல்லி, சவுலின் நிலங்களையெல்லாம் அவனுக்குத் திரும்பக் கொடுத்து, அவன் எப்போதும் ராஜாவின் பந்தியில் புசிக்கும்படி செய்தான்.",
    "2 Samuel 10": "அம்மோனியரின் ராஜாவாகிய ஆனூன் தாவீது அனுப்பின ஆறுதல் தூதர்களை அவமானப்படுத்தி, அவர்கள் தாடியில் பாதியைச் சிரைத்து வஸ்திரங்களைக் கத்தரித்தான். அம்மோனியர் சீரியரைக் கூலிக்கு அமர்த்தி யுத்தத்துக்கு வந்தார்கள்; 'திடன்கொள், நம்முடைய ஜனத்துக்காகவும் தேவனுடைய பட்டணங்களுக்காகவும் பலங்கொள்வோம்' என்று யோவாப் சொன்னான். அம்மோனியரும் சீரியரும் முறியடிக்கப்பட்டார்கள்; சீரியர் இனி அம்மோனியருக்கு உதவி செய்யப் பயந்தார்கள்.",
    "2 Samuel 11": "ராஜாக்கள் யுத்தத்துக்குப் புறப்படும் காலத்தில் தாவீது எருசலேமில் இருந்தான்; உப்பரிகையிலிருந்து பத்சேபாளைக் கண்டு அவளை அழைப்பித்து அவளோடே சயனித்தான், அவள் கர்ப்பவதியானாள். அவள் புருஷனாகிய உரியாவை யுத்தத்திலிருந்து வரவழைத்தும் அவன் தன் வீட்டுக்குப் போகாததால், அவன் யுத்தமுனையில் கொல்லப்படும்படி யோவாப்புக்குக் கடிதம் எழுதி அவன் கையிலேயே கொடுத்தனுப்பினான். உரியா மரித்தபின் தாவீது பத்சேபாளை மனைவியாக்கிக்கொண்டான்; தாவீது செய்த காரியம் கர்த்தருடைய பார்வைக்குப் பொல்லாப்பாயிருந்தது.",
    "2 Samuel 12": "நாத்தான் தீர்க்கதரிசி ஏழையின் ஒரே ஆட்டுக்குட்டியைப் பறித்த ஐசுவரியவானின் உவமையைச் சொன்னான்; தாவீது கோபங்கொண்டபோது, 'நீயே அந்த மனுஷன்' என்றான்; பட்டயம் உன் வீட்டை விட்டு நீங்காது என்றும் சொன்னான். 'நான் கர்த்தருக்கு விரோதமாகப் பாவஞ்செய்தேன்' என்று தாவீது அறிக்கையிட்டான்; கர்த்தர் அவன் பாவத்தை நீக்கினார், ஆனாலும் பிறந்த பிள்ளை சாகும் என்றார், அப்படியே பிள்ளை மரித்தது. பின்பு பத்சேபாள் சாலொமோனைப் பெற்றாள், கர்த்தர் அவனில் அன்புகூர்ந்தார்; தாவீது அம்மோனியரின் ரப்பா பட்டணத்தைப் பிடித்தான்.",
    "2 Samuel 13": "தாவீதின் குமாரனாகிய அம்னோன் தன் சகோதரியாகிய தாமாரை வஞ்சகமாய் அழைத்து பலவந்தம் பண்ணி, பின்பு அவளை மிகவும் வெறுத்துத் துரத்திவிட்டான். தாவீது அதைக் கேட்டு மிகவும் கோபங்கொண்டும் அவனைத் தண்டிக்கவில்லை. இரண்டு வருஷத்துக்குப் பின் தாமாரின் சகோதரனாகிய அப்சலோம் அம்னோனைக் கொல்லுவித்து, கேசூருக்கு ஓடிப்போய் மூன்று வருஷம் அங்கே இருந்தான்.",
    "2 Samuel 14": "யோவாப் தெக்கோவாவிலிருந்து ஒரு ஞானமுள்ள ஸ்திரீயை அனுப்பி, ஒரு உவமையின் மூலம் அப்சலோமைத் திரும்ப அழைக்கும்படி ராஜாவை இணங்கச் செய்தான். அப்சலோம் எருசலேமுக்குத் திரும்பி வந்தும் இரண்டு வருஷம் ராஜாவின் முகத்தைக் காணவில்லை. அவன் யோவாபின் வயலுக்குத் தீ வைத்து அவனை வரவழைத்தான்; பின்பு ராஜா அப்சலோமை அழைத்து முத்தமிட்டான்.",
    "2 Samuel 15": "அப்சலோம் பட்டணவாசலில் நின்று, நியாயத்துக்காக வந்தவர்களிடம் இனிமையாய்ப் பேசி, இஸ்ரவேல் மனுஷரின் இருதயத்தைக் கவர்ந்துகொண்டான். எபிரோனில் தன்னை ராஜாவாக அறிவித்தான்; தாவீதின் ஆலோசனைக்காரனாகிய அகித்தோப்பேலும் அவனோடு சேர்ந்தான். தாவீது எருசலேமைவிட்டு ஓடி, தேவனுடைய பெட்டியைத் திரும்ப அனுப்பி, அழுதுகொண்டே ஒலிவமலையில் ஏறினான்; அகித்தோப்பேலின் ஆலோசனையை அபத்தமாக்கும்படி ஊசாயைத் திரும்ப அனுப்பினான்.",
    "2 Samuel 16": "சீபா மேவிபோசேத்தைக் குறித்துப் பொய் சொல்லி, தாவீதிடமிருந்து அவனுடைய சொத்தைப் பெற்றுக்கொண்டான். சவுலின் வம்சத்தானாகிய சீமேயி தாவீதைச் சபித்து அவன்மேல் கற்களை எறிந்தான்; 'கர்த்தர் அவனைச் சபிக்கச் சொன்னார்' என்று சொல்லி, தாவீது அவனைத் தண்டிக்காமல் விட்டுவிட்டான். அகித்தோப்பேலின் ஆலோசனைப்படி அப்சலோம் எல்லா இஸ்ரவேலுக்கும் முன்பாகத் தன் தகப்பனுடைய மறுமனையாட்டிகளிடம் பிரவேசித்தான்.",
    "2 Samuel 17": "தாவீதை உடனே பின்தொடர்ந்து அவனை மாத்திரம் கொல்லும்படி அகித்தோப்பேல் ஆலோசனை சொன்னான்; ஊசாய் அதற்கு மாறான ஆலோசனை சொன்னான், அப்சலோம் அதையே ஏற்றுக்கொண்டான், ஏனெனில் கர்த்தர் அகித்தோப்பேலின் ஆலோசனையை அபத்தமாக்கத் தீர்மானித்திருந்தார். செய்தி தாவீதுக்கு அனுப்பப்பட்டது; அவன் இரவோடே யோர்தானைக் கடந்தான். தன் ஆலோசனை நடக்கவில்லை என்று கண்ட அகித்தோப்பேல் தன் வீட்டுக்குப் போய் நான்றுகொண்டு செத்தான்; மக்னாயீமில் சிலர் தாவீதுக்கும் அவன் ஜனங்களுக்கும் உணவுப்பொருட்களைக் கொண்டுவந்தார்கள்.",
    "2 Samuel 18": "'வாலிபனாகிய அப்சலோமை எனக்காக மெதுவாய் நடத்துங்கள்' என்று தாவீது சேனாபதிகளுக்குக் கட்டளையிட்டான்; எப்பிராயீம் காட்டில் அப்சலோமின் சேனை முறியடிக்கப்பட்டது. அப்சலோமின் தலை ஒரு கர்வாலிமரத்தின் கொப்புகளில் சிக்கிக்கொண்டது; யோவாப் மூன்று ஈட்டிகளால் அவனைக் குத்தினான். செய்தி கேட்ட தாவீது, 'என் மகனே, அப்சலோமே, நான் உனக்குப் பதிலாகச் செத்தேனானால் நலமாயிருக்கும்' என்று புலம்பி அழுதான்.",
    "2 Samuel 19": "ராஜா தன் குமாரனுக்காகத் துக்கித்ததால், அன்று ஜெயம் துக்கமாக மாறியது; யோவாப் கடிந்துகொண்டதால் ராஜா எழுந்து வாசலில் உட்கார்ந்தான். யூதா மனுஷர் ராஜாவைத் திரும்ப அழைத்தார்கள்; சீமேயி மன்னிப்புக் கேட்டான், மேவிபோசேத் எதிர்கொண்டுவந்தான், உதவி செய்த முதியவனாகிய பர்சிலாயைத் தாவீது பாராட்டினான். ராஜாவைத் திரும்ப அழைப்பதைக் குறித்து இஸ்ரவேல் மனுஷருக்கும் யூதா மனுஷருக்கும் வாக்குவாதம் உண்டானது.",
    "2 Samuel 20": "பென்யமீனனாகிய சேபா, 'தாவீதிடத்தில் எங்களுக்குப் பங்கில்லை' என்று சொல்லிக் கலகம் எழுப்பினான்; இஸ்ரவேலர் அவன் பின்னே போனார்கள். யோவாப் தாவீது நியமித்த சேனாபதியாகிய அமாசாவை வஞ்சகமாய்க் கொன்றான். சேபா அடைக்கலம் புகுந்த ஆபேல் பட்டணத்தில், ஞானமுள்ள ஒரு ஸ்திரீயின் ஆலோசனைப்படி சேபாவின் தலை வெட்டி அலங்கத்துக்கு வெளியே எறியப்பட்டது; பட்டணம் அழிவுக்குத் தப்பியது.",
    "2 Samuel 21": "சவுல் கிபியோனியரைக் கொன்றதினிமித்தம் தேசத்தில் மூன்று வருஷம் பஞ்சம் உண்டானது; கிபியோனியர் கேட்டபடி சவுலின் சந்ததியில் ஏழு பேர் ஒப்புக்கொடுக்கப்பட்டுத் தூக்கிலிடப்பட்டார்கள். ரிஸ்பாள் அவர்கள் உடல்களை இரவும் பகலும் காத்தாள்; தாவீது சவுல், யோனத்தானின் எலும்புகளோடு அவர்களையும் அடக்கம் பண்ணினான், அதன்பின் தேவன் தேசத்துக்காக இரங்கினார். பெலிஸ்தரோடு நடந்த யுத்தங்களில் இராட்சதர்களைத் தாவீதின் வீரர்கள் கொன்றார்கள்.",
    "2 Samuel 22": "கர்த்தர் தாவீதை எல்லா சத்துருக்களின் கைக்கும் சவுலின் கைக்கும் தப்புவித்த நாளில் அவன் பாடின பாட்டு இது: 'கர்த்தர் என் கன்மலையும், என் கோட்டையும், என் இரட்சகருமானவர்'. நெருக்கத்தில் கர்த்தரை நோக்கிக் கூப்பிட்டேன், அவர் கேட்டு என்னை விடுவித்தார் என்று பாடினான். தேவனுடைய வழி உத்தமமானது; அவர் தம்முடைய ராஜாவுக்கு மகா இரட்சிப்பைக் கட்டளையிட்டு, தம்முடைய அபிஷேகம் பெற்றவனுக்குக் கிருபை செய்கிறார்.",
    "2 Samuel 23": "தாவீதின் கடைசி வார்த்தைகள்: மனுஷர்மேல் நீதியாய் ஆளுகிறவன் மேகமில்லாத விடியற்கால வெளிச்சத்தைப்போல் இருப்பான்; கர்த்தர் தன்னோடே நித்திய உடன்படிக்கை பண்ணினார். தாவீதின் பராக்கிரமசாலிகளின் பட்டியல் கொடுக்கப்பட்டுள்ளது; அவர்களில் மூவர் பெலிஸ்தரின் பாளயத்தை ஊடுருவி பெத்லகேமின் கிணற்றுத் தண்ணீரைக் கொண்டுவந்தார்கள், தாவீதோ அதைக் குடிக்காமல் கர்த்தருக்கு ஊற்றினான். அந்தப் பட்டியலில் ஏத்தியனாகிய உரியாவின் பேரும் இருக்கிறது.",
    "2 Samuel 24": "தாவீது இஸ்ரவேலையும் யூதாவையும் எண்ணச் சொன்னான்; பின்பு அவன் இருதயம் அவனை வாதித்தது, 'நான் பெரிய பாவஞ்செய்தேன்' என்று அறிக்கையிட்டான். காத் தீர்க்கதரிசி மூன்று தண்டனைகளில் ஒன்றைத் தெரிந்துகொள்ளச் சொன்னபோது, 'கர்த்தருடைய இரக்கங்கள் மிகுதியானபடியால் அவர் கையிலே விழுவோமாக' என்றான்; கொள்ளைநோயினால் எழுபதாயிரம் பேர் செத்தார்கள். தாவீது அர்வனாவின் போரடிக்கும் களத்தை விலைக்கு வாங்கி, 'செலவில்லாமல் கர்த்தருக்குத் தகனபலி செலுத்தமாட்டேன்' என்று சொல்லி அங்கே பலிபீடம் கட்டினான்; வாதை நின்றது.",

    "1 Kings 1": "தாவீது ராஜா வயதுசென்றவனானபோது, சூனேமியாளாகிய அபிஷாக் அவனுக்குப் பணிவிடை செய்தாள். தாவீதின் குமாரனாகிய அதோனியா, 'நான் ராஜாவாவேன்' என்று சொல்லி, யோவாபையும் ஆசாரியனாகிய அபியத்தாரையும் சேர்த்துக்கொண்டான். நாத்தானும் பத்சேபாளும் தாவீதுக்கு அவன் வாக்கை நினைப்பூட்டினார்கள்; தாவீதின் கட்டளைப்படி சாதோக் ஆசாரியன் கீகோனில் சாலொமோனை ராஜாவாக அபிஷேகம் பண்ணினான்; பயந்த அதோனியா பலிபீடத்தின் கொம்புகளைப் பிடித்துக்கொண்டான்.",
    "1 Kings 2": "தாவீது மரணத்துக்கு முன் சாலொமோனிடம், 'நீ திடன்கொண்டு புருஷனாயிரு; உன் தேவனாகிய கர்த்தருடைய கட்டளைகளைக் கைக்கொள்' என்று சொல்லி, நாற்பது வருஷம் அரசாண்டபின் மரித்தான். அதோனியா அபிஷாகை மனைவியாகக் கேட்டதால் கொல்லப்பட்டான்; அபியத்தார் ஆசாரிய ஊழியத்திலிருந்து நீக்கப்பட்டான், யோவாப் கொல்லப்பட்டான். கட்டளையை மீறி எருசலேமைவிட்டுப் போன சீமேயியும் கொல்லப்பட்டான்; ராஜ்யம் சாலொமோனின் கையில் உறுதிப்பட்டது.",
    "1 Kings 3": "சாலொமோன் கர்த்தரில் அன்புகூர்ந்தான்; கிபியோனில் கர்த்தர் சொப்பனத்தில் தோன்றி, 'நான் உனக்கு என்ன தரவேண்டும், கேள்' என்றார். ஜனங்களை நியாயம் விசாரிக்கவும் நன்மை தீமையை வகையறுக்கவும் ஞானமுள்ள இருதயத்தைச் சாலொமோன் கேட்டான்; கர்த்தர் அதில் பிரியப்பட்டு, ஞானத்தோடு ஐசுவரியத்தையும் கனத்தையும் கொடுத்தார். ஒரு குழந்தைக்காக வாதாடின இரண்டு ஸ்திரீகளின் வழக்கில், 'பிள்ளையை இரண்டாகப் பிளவுங்கள்' என்று சொல்லி, உண்மையான தாயைக் கண்டுபிடித்தான்; தேவஞானம் அவனுக்குள் இருப்பதை இஸ்ரவேலர் கண்டார்கள்.",
    "1 Kings 4": "சாலொமோனின் பிரதானிகளும், அவனுடைய அரமனைக்கு உணவு சேகரித்த பன்னிரண்டு மணியக்காரரும் பட்டியலிடப்பட்டுள்ளனர். யூதாவும் இஸ்ரவேலும் கடற்கரை மணலைப்போல் திரளாயிருந்து, புசித்துக் குடித்துச் சந்தோஷமாயிருந்தார்கள்; அவனவன் தன் திராட்சச்செடியின் கீழும் அத்திமரத்தின் கீழும் சுகமாய்க் குடியிருந்தான். தேவன் சாலொமோனுக்குக் கொடுத்த ஞானம் கிழக்கத்திப் புத்திரர் எல்லாருடைய ஞானத்திலும் மேலானது; அவன் மூவாயிரம் நீதிமொழிகளையும் ஆயிரத்தைந்து பாட்டுகளையும் சொன்னான்.",
    "1 Kings 5": "தீருவின் ராஜாவாகிய ஈராம் சாலொமோனிடம் தூதரை அனுப்பினான்; கர்த்தருடைய நாமத்துக்கு ஆலயம் கட்டும்படி லீபனோனின் கேதுரு மரங்களை வெட்டித்தரச் சாலொமோன் கேட்டான். ஈராம் கேதுரு மரங்களையும் தேவதாரு மரங்களையும் அனுப்பினான்; சாலொமோன் அதற்குப் பதிலாகக் கோதுமையையும் எண்ணெயையும் கொடுத்தான். முப்பதினாயிரம் ஊழியக்காரர் லீபனோனுக்கு அனுப்பப்பட்டார்கள்; கல்லுடைக்கிறவர்கள் ஆலய அஸ்திபாரத்துக்காக விலையேறப்பெற்ற பெரிய கற்களை வெட்டினார்கள்.",
    "1 Kings 6": "இஸ்ரவேலர் எகிப்திலிருந்து புறப்பட்ட நானூற்றெண்பதாம் வருஷத்தில், சாலொமோன் அரசாண்ட நான்காம் வருஷத்தில் கர்த்தருடைய ஆலயத்தைக் கட்டத் தொடங்கினான்; கட்டும்போது சுத்தியலின் சத்தமும் இரும்பு ஆயுதத்தின் சத்தமும் கேட்கப்படவில்லை. 'நீ என் கட்டளைகளின்படி நடந்தால் இஸ்ரவேல் புத்திரரின் நடுவே வாசம்பண்ணுவேன்' என்று கர்த்தர் சொன்னார். ஆலயத்தின் உட்புறம் முழுவதும் பொன்தகட்டால் மூடப்பட்டது; மகா பரிசுத்த ஸ்தலத்தில் இரண்டு கேருபீன்கள் வைக்கப்பட்டன; ஏழு வருஷத்தில் ஆலயம் கட்டி முடிக்கப்பட்டது.",
    "1 Kings 7": "சாலொமோன் தன் அரமனையையும் லீபனோன் வனமாளிகையையும் பதின்மூன்று வருஷமாகக் கட்டினான். வெண்கலக் கலைஞனாகிய ஈராம் யாகீன், போவாஸ் என்னும் இரண்டு வெண்கலத் தூண்களையும், வார்ப்பிக்கப்பட்ட கடல் தொட்டியையும், பத்து ஆதாரங்களையும் தொட்டிகளையும் செய்தான். ஆலயத்தின் பொற்பீடமும், பொன் மேஜையும், பொன் குத்துவிளக்குகளும், மற்றப் பணிமுட்டுகளும் செய்யப்பட்டன.",
    "1 Kings 8": "ஆசாரியர் உடன்படிக்கைப் பெட்டியை மகா பரிசுத்த ஸ்தலத்தில் கேருபீன்களின் செட்டைகளின் கீழ் கொண்டுவந்து வைத்தார்கள்; மேகம் ஆலயத்தை நிரப்பியது, கர்த்தருடைய மகிமையினால் ஆசாரியர் ஊழியம் செய்ய நிற்கக்கூடாதிருந்தது. 'வானங்களும் வானாதி வானங்களும் உம்மைக் கொள்ளாதே, நான் கட்டின இந்த ஆலயம் எப்படிக் கொள்ளும்?' என்று சாலொமோன் ஜெபித்து, இந்த ஸ்தலத்தை நோக்கி ஜெபிக்கிறவர்களின் விண்ணப்பத்தைக் கேட்டு மன்னிக்கும்படி வேண்டினான். அவன் ஜனங்களை ஆசீர்வதித்து, திரளான பலிகளைச் செலுத்தி, பதினான்கு நாள் பண்டிகை ஆசரித்தான்.",
    "1 Kings 9": "கர்த்தர் சாலொமோனுக்கு இரண்டாம்முறை தரிசனமாகி, நீ கட்டின இந்த ஆலயத்தைப் பரிசுத்தமாக்கினேன், என் கண்களும் என் இருதயமும் எந்நாளும் அங்கே இருக்கும் என்றார். தாவீதைப்போல் உத்தமமாய் நடந்தால் சிங்காசனம் நிலைநிற்கும்; விலகிப்போய் அந்நிய தேவர்களைச் சேவித்தால் இஸ்ரவேல் அறுப்புண்டு, இந்த ஆலயம் பாழாகும் என்று எச்சரித்தார். சாலொமோன் ஈராமுக்கு இருபது பட்டணங்களைக் கொடுத்தான்; அவன் கப்பல்கள் ஓப்பீரிலிருந்து பொன் கொண்டுவந்தன.",
    "1 Kings 10": "சேபாவின் ராஜஸ்திரீ சாலொமோனின் கீர்த்தியைக் கேள்விப்பட்டு, கடினமான கேள்விகளால் அவனைச் சோதிக்க வந்தாள்; அவன் ஞானத்தையும் மகிமையையும் கண்டு, 'பாதியும் எனக்குச் சொல்லப்படவில்லை' என்று சொல்லி கர்த்தரைத் துதித்தாள். சாலொமோன் ராஜா ஐசுவரியத்திலும் ஞானத்திலும் பூமியின் ராஜாக்களெல்லாரையும் பார்க்கப் பெரியவனாயிருந்தான். அவன் பொன் கேடகங்களையும் தந்தத்தால் செய்த பெரிய சிங்காசனத்தையும் உண்டாக்கினான்; எகிப்திலிருந்து குதிரைகளும் இரதங்களும் கொண்டுவரப்பட்டன.",
    "1 Kings 11": "சாலொமோன் அநேக அந்நிய ஸ்திரீகளை நேசித்தான்; அவனுக்கு எழுநூறு மனைவிகளும் முந்நூறு மறுமனையாட்டிகளும் இருந்தார்கள்; அவன் முதிர்வயதில் அவர்கள் அவன் இருதயத்தை அஸ்தரோத், மில்கோம் முதலிய அந்நிய தேவர்களிடம் சாயப்பண்ணினார்கள். ராஜ்யத்தை அவன் குமாரன் கையிலிருந்து பிடுங்குவேன், ஆனாலும் தாவீதினிமித்தம் ஒரு கோத்திரத்தை விட்டுவைப்பேன் என்று கர்த்தர் சொன்னார்; ஆதாத், ரேசோன் என்னும் விரோதிகள் எழும்பினார்கள். அகியா தீர்க்கதரிசி தன் புதுச் சால்வையைப் பன்னிரண்டு துண்டாகக் கிழித்து, பத்துத் துண்டுகளை யெரொபெயாமுக்குக் கொடுத்தான்; சாலொமோன் நாற்பது வருஷம் அரசாண்டு மரித்தான்.",
    "1 Kings 12": "ரெகொபெயாம் முதியோரின் ஆலோசனையைத் தள்ளி, வாலிபரின் ஆலோசனைப்படி, 'என் தகப்பன் உங்களைச் சவுக்குகளால் தண்டித்தார், நானோ உங்களைத் தேள்களால் தண்டிப்பேன்' என்றான். அப்பொழுது பத்துக் கோத்திரங்கள் தாவீதின் வீட்டைவிட்டுப் பிரிந்து யெரொபெயாமை ராஜாவாக்கின; யூதா கோத்திரமும் பென்யமீனும் மாத்திரம் ரெகொபெயாமோடு இருந்தன. ஜனங்கள் எருசலேமுக்குப் போகாதபடி யெரொபெயாம் இரண்டு பொன் கன்றுக்குட்டிகளைச் செய்து, ஒன்றைப் பெத்தேலிலும் ஒன்றைத் தாணிலும் வைத்து, 'இவைகளே உன் தேவர்கள்' என்றான்.",
    "1 Kings 13": "யூதாவிலிருந்து வந்த ஒரு தேவனுடைய மனுஷன், பெத்தேலின் பலிபீடத்துக்கு விரோதமாக, தாவீதின் வம்சத்தில் யோசியா என்னும் ஒரு குமாரன் பிறப்பான் என்று கூறினான்; பலிபீடம் வெடித்தது, அவனைப் பிடிக்க நீட்டின யெரொபெயாமின் கை மரத்துப்போனது. அங்கே அப்பம் புசிக்கவும் தண்ணீர் குடிக்கவும் வேண்டாம் என்ற கர்த்தருடைய கட்டளையை, கிழவனான ஒரு தீர்க்கதரிசியின் பொய்யை நம்பி மீறினான். வழியில் ஒரு சிங்கம் அவனைக் கொன்றது; ஆனாலும் யெரொபெயாம் தன் பொல்லாத வழியை விட்டுத் திரும்பவில்லை.",
    "1 Kings 14": "யெரொபெயாமின் குமாரன் வியாதிப்பட்டபோது, அவன் மனைவி வேஷம் மாறி அகியா தீர்க்கதரிசியிடம் போனாள்; யெரொபெயாமின் வீட்டுக்கு வரும் அழிவையும், பிள்ளை சாகும் என்பதையும் அகியா முன்னறிவித்தான். யூதாவில் ரெகொபெயாமின் நாட்களில் ஜனங்கள் மேடைகளையும் சிலைகளையும் கட்டி, கர்த்தருடைய பார்வைக்குப் பொல்லாப்பானதைச் செய்தார்கள். எகிப்தின் ராஜாவாகிய சீஷாக் எருசலேமுக்கு வந்து, ஆலயத்தின் பொக்கிஷங்களையும் சாலொமோன் செய்த பொன் கேடகங்களையும் எடுத்துக்கொண்டுபோனான்.",
    "1 Kings 15": "அபியாம் யூதாவை மூன்று வருஷம் அரசாண்டு, தன் தகப்பனுடைய பாவங்களில் நடந்தான். அவன் குமாரனாகிய ஆசா கர்த்தருடைய பார்வைக்குச் செம்மையானதைச் செய்து, விக்கிரகங்களை அகற்றி, விக்கிரகத்தை உண்டாக்கின தன் தாயை ராஜஸ்திரீயின் ஸ்தானத்திலிருந்து நீக்கினான்; இஸ்ரவேலின் ராஜாவாகிய பாஷாவுக்கு விரோதமாகச் சீரியாவின் ராஜாவாகிய பெனாதாதின் உதவியைத் தேடினான். இஸ்ரவேலில் யெரொபெயாமின் குமாரனாகிய நாதாபைக் கொன்று பாஷா ராஜாவானான்; அகியா சொன்னபடியே அவன் யெரொபெயாமின் வீட்டாரையெல்லாம் அழித்தான்.",
    "1 Kings 16": "யெகூ தீர்க்கதரிசி பாஷாவின் வீட்டுக்கு வரும் அழிவைக் கூறினான். பாஷாவின் குமாரனாகிய ஏலாவைச் சிம்ரி கொன்று ஏழு நாள் அரசாண்டான்; உம்ரி முற்றுகையிட்டபோது சிம்ரி அரமனையைத் தீக்கொளுத்தி அதில் செத்தான். உம்ரி சமாரியா பட்டணத்தைக் கட்டினான்; அவன் குமாரனாகிய ஆகாப் தனக்கு முன்னிருந்த எல்லாரைப் பார்க்கிலும் அதிகமாகப் பொல்லாப்புச் செய்து, சீதோனியரின் ராஜகுமாரத்தியாகிய யேசபேலை மணந்து, பாகாலைச் சேவித்தான்.",
    "1 Kings 17": "திஸ்பியனாகிய எலியா ஆகாபிடம், 'என் வார்த்தையின்படியல்லாமல் இந்த வருஷங்களில் பனியும் மழையும் பெய்யாது' என்று சொன்னான். கேரீத் ஆற்றண்டையில் காகங்கள் காலையிலும் மாலையிலும் அவனுக்கு அப்பமும் இறைச்சியும் கொண்டுவந்து போஷித்தன. சாறிபாத்தில் ஒரு விதவையின் பானையிலுள்ள மாவும் கலசத்திலுள்ள எண்ணெயும் பஞ்சகாலம் முழுவதும் குறையவில்லை; அவள் குமாரன் மரித்தபோது எலியா கர்த்தரிடம் ஜெபித்து அவனை உயிரோடெழுப்பினான்.",
    "1 Kings 18": "மூன்றாம் வருஷத்தில் எலியா ஆகாபைச் சந்திக்க வந்தான்; யேசபேல் கொன்ற நாட்களில் ஒபதியா நூறு தீர்க்கதரிசிகளைக் குகைகளில் ஒளித்து வைத்திருந்தான். கர்மேல் மலையில் எலியா, 'எதுவரைக்கும் இரண்டு நினைவுகளால் குந்திக் குந்தி நடப்பீர்கள்?' என்று கேட்டான்; பாகாலின் நானூற்றைம்பது தீர்க்கதரிசிகள் கூப்பிட்டும் பதில் இல்லை, எலியா ஜெபித்தபோதோ கர்த்தருடைய அக்கினி இறங்கி பலியையும் கற்களையும் தண்ணீரையும் பட்சித்தது; ஜனங்கள் 'கர்த்தரே தேவன்' என்று முகங்குப்புற விழுந்தார்கள். பாகாலின் தீர்க்கதரிசிகள் கொல்லப்பட்டார்கள்; எலியா ஏழுதரம் ஜெபித்தபோது கைப்போன்ற சிறிய மேகம் எழும்பி பெருமழை பெய்தது.",
    "1 Kings 19": "யேசபேல் கொல்லுவேன் என்று மிரட்டினதால் எலியா பயந்து ஓடி, ஒரு சூரைச்செடியின் கீழ் உட்கார்ந்து சாக விரும்பினான்; கர்த்தருடைய தூதன் அப்பமும் தண்ணீரும் கொடுத்தார், அந்தப் பலத்தினால் நாற்பது நாள் நடந்து ஓரேப் மலைக்கு வந்தான். பெருங்காற்றிலும் பூமியதிர்ச்சியிலும் அக்கினியிலும் கர்த்தர் இல்லை; அதன்பின் ஒரு மெல்லிய சத்தம் உண்டாயிற்று; பாகாலுக்கு முழங்கால் படியிடாத ஏழாயிரம் பேரை இஸ்ரவேலில் மீதியாக வைத்திருக்கிறேன் என்று கர்த்தர் சொன்னார். ஆசகேல், யெகூ, எலிசா ஆகியோரை அபிஷேகம் பண்ணச் சொன்னார்; எலியா உழுதுகொண்டிருந்த எலிசாவின்மேல் தன் சால்வையைப் போட்டான், எலிசா எழுந்து அவனைப் பின்பற்றினான்.",
    "1 Kings 20": "சீரியாவின் ராஜாவாகிய பெனாதாத் சமாரியாவை முற்றுகையிட்டான்; ஒரு தீர்க்கதரிசி மூலம் கர்த்தர் ஆகாபுக்கு ஜெயம் வாக்களித்து, சீரியரை முறியடிக்கப்பண்ணினார். அடுத்த வருஷம், 'இஸ்ரவேலின் தேவன் மலைகளின் தேவன்' என்று சீரியர் சொன்னதால், கர்த்தர் சமபூமியிலும் அவர்களை முறியடித்தார். ஆகாப் பெனாதாதோடு உடன்படிக்கை பண்ணி அவனை விட்டுவிட்டதால், 'அவன் உயிருக்குப் பதிலாக உன் உயிர் போகும்' என்று ஒரு தீர்க்கதரிசி அவனைக் கடிந்துகொண்டான்.",
    "1 Kings 21": "ஆகாப் யெஸ்ரயேலனாகிய நாபோத்தின் திராட்சத்தோட்டத்தை விரும்பினான்; நாபோத்தோ தன் பிதாக்களின் சுதந்தரத்தைக் கொடுக்க மறுத்தான். யேசபேல் ஆகாபின் பேரால் கடிதங்களை எழுதி, பொய்ச்சாட்சிகளைக் கொண்டு நாபோத்தைக் கல்லெறிந்து கொல்லுவித்தாள். 'நாய்கள் நாபோத்தின் இரத்தத்தை நக்கின இடத்திலே உன் இரத்தத்தையும் நக்கும்' என்று எலியா ஆகாபிடம் சொன்னான்; ஆகாப் தன்னைத் தாழ்த்தினதால், அந்தத் தீங்கை அவன் நாட்களில் அல்ல, அவன் குமாரனின் நாட்களில் வரப்பண்ணுவேன் என்று கர்த்தர் சொன்னார்.",
    "1 Kings 22": "ஆகாபும் யூதாவின் ராஜாவாகிய யோசபாத்தும் ராமோத் கீலேயாத்துக்கு விரோதமாக யுத்தத்துக்குப் போக நினைத்தார்கள்; நானூறு தீர்க்கதரிசிகள் ஜெயம் என்றார்கள், மிகாயா மாத்திரம் இஸ்ரவேலர் மேய்ப்பனில்லாத ஆடுகளைப்போல் மலைகளில் சிதறுவார்கள் என்றும், அந்தத் தீர்க்கதரிசிகளின் வாயில் பொய்யின் ஆவி இருக்கிறது என்றும் சொன்னான். ஆகாப் வேஷம் மாறி யுத்தத்துக்குப் போனான்; ஒருவன் குறிவைக்காமல் எய்த அம்பு அவனைக் குத்தியது, அவன் சாயங்காலத்தில் மரித்தான், நாய்கள் அவன் இரத்தத்தை நக்கின. யோசபாத் யூதாவில் கர்த்தருடைய பார்வைக்குச் செம்மையாய் நடந்தான்; ஆகாபின் குமாரனாகிய அகசியா இஸ்ரவேலில் பாகாலைச் சேவித்தான்.",

    "2 Kings 1": "ஆகாப் மரித்தபின் மோவாப் இஸ்ரவேலுக்கு விரோதமாகக் கலகம் பண்ணியது. ராஜாவாகிய அகசியா மேல்வீட்டிலிருந்து விழுந்து வியாதிப்பட்டு, எக்ரோனின் தேவனாகிய பாகால்சேபூபிடம் விசாரிக்க ஆட்களை அனுப்பினான்; 'இஸ்ரவேலில் தேவன் இல்லையென்றா?' என்று கேட்டு, அவன் சாவான் என்று எலியா சொன்னான். எலியாவைப் பிடிக்க ராஜா அனுப்பின இரண்டு ஐம்பதுபேர் தலைவர்களையும் அவர்கள் ஆட்களையும் வானத்திலிருந்து இறங்கின அக்கினி பட்சித்தது; மூன்றாம் தலைவன் மன்றாடினபோது எலியா அவனோடு போய் ராஜாவிடம் அதையே சொன்னான், அகசியா மரித்தான்.",
    "2 Kings 2": "எலியா பெத்தேலுக்கும் எரிகோவுக்கும் யோர்தானுக்கும் போனான்; 'நான் உம்மை விடுகிறதில்லை' என்று சொல்லி எலிசா அவனோடே போனான். எலியா தன் சால்வையால் யோர்தானை அடித்துப் பிரித்தான்; 'உம்முடைய ஆவியின் இரட்டிப்பான பங்கு எனக்கு வருவதாக' என்று எலிசா கேட்டான்; அப்பொழுது அக்கினி இரதமும் அக்கினிக் குதிரைகளும் வந்து, எலியா சுழல்காற்றிலே பரலோகத்துக்கு ஏறிப்போனான். எலிசா எலியாவின் சால்வையால் யோர்தானைப் பிரித்தான், எரிகோவின் கெட்ட தண்ணீரை ஆரோக்கியமாக்கினான்; பெத்தேலில் அவனைப் பரியாசம் பண்ணின பிள்ளைகளைக் கரடிகள் பீறிப்போட்டன.",
    "2 Kings 3": "மோவாபின் ராஜாவாகிய மேசா இஸ்ரவேலுக்குக் கப்பம் கொடுக்க மறுத்ததால், இஸ்ரவேல், யூதா, ஏதோம் ராஜாக்கள் அவனுக்கு விரோதமாகப் புறப்பட்டார்கள்; வனாந்தரத்தில் தண்ணீர் இல்லாதிருந்தது. யோசபாத்தினிமித்தம் எலிசா கர்த்தரிடம் விசாரித்து, பள்ளத்தாக்கில் வாய்க்கால்களை வெட்டச் சொன்னான்; மழையில்லாமலே அவை தண்ணீரால் நிறைந்தன. சூரிய ஒளியில் தண்ணீரை இரத்தமென்று நினைத்து வந்த மோவாபியர் முறியடிக்கப்பட்டார்கள்; மேசா தன் மூத்த குமாரனை அலங்கத்தின்மேல் தகனபலியாகச் செலுத்தினான்.",
    "2 Kings 4": "ஒரு தீர்க்கதரிசியின் விதவையின் கடனுக்காக, எலிசா அவள் வீட்டிலிருந்த கொஞ்சம் எண்ணெயைக் கொண்டு கடன் வாங்கின பாத்திரங்களெல்லாம் நிறையும்படி பெருகப்பண்ணினான். சூனேமிய ஸ்திரீ எலிசாவுக்கு ஒரு மேலறையைக் கட்டிக்கொடுத்தாள்; அவள் பெற்ற குமாரன் பின்பு வயலில் மரித்தபோது, எலிசா கர்த்தரிடம் ஜெபித்து அவனை உயிரோடெழுப்பினான். கில்காலில் விஷமுள்ள கூழை மாவு போட்டு குணமாக்கினான்; இருபது வாற்கோதுமை அப்பங்களால் நூறு பேர் திருப்தியடைந்து மீதியும் இருந்தது.",
    "2 Kings 5": "சீரியாவின் சேனாபதியாகிய நாகமான் குஷ்டரோகியாயிருந்தான்; அவன் வீட்டிலிருந்த இஸ்ரவேலின் சிறுபெண் சமாரியாவிலுள்ள தீர்க்கதரிசியைப் பற்றிச் சொன்னாள். யோர்தானில் ஏழுதரம் ஸ்நானம் பண்ணும்படி எலிசா சொன்னபோது நாகமான் கோபித்தான்; வேலைக்காரரின் வார்த்தைக்கு இணங்கி அப்படிச் செய்தபோது, அவன் மாம்சம் சிறுபிள்ளையின் மாம்சம்போலாகி சுத்தமானான்; 'இஸ்ரவேலிலே தேவன் இருக்கிறார்' என்று அறிக்கையிட்டான். எலிசா வெகுமதியை மறுத்தான்; அவன் வேலைக்காரன் கேயாசி பொய் சொல்லி வெகுமதியைப் பெற்றதால், நாகமானின் குஷ்டம் அவனைப் பிடித்தது.",
    "2 Kings 6": "இரவல் கோடரி தண்ணீரில் விழுந்தபோது, எலிசா ஒரு கொம்பை வெட்டிப்போட்டு இரும்பை மிதக்கப்பண்ணினான். சீரியா ராஜாவின் திட்டங்களை எலிசா இஸ்ரவேல் ராஜாவுக்கு அறிவித்தான்; தோத்தானில் சீரியர் அவனைச் சூழ்ந்தபோது, 'நம்மோடிருக்கிறவர்கள் அவர்களோடிருக்கிறவர்களைப் பார்க்கிலும் அதிகம்' என்று சொல்லி ஜெபித்தான், வேலைக்காரன் மலை அக்கினிமயமான குதிரைகளாலும் இரதங்களாலும் நிறைந்திருப்பதைக் கண்டான். சீரியரைக் குருட்டாட்டத்தால் அடித்து சமாரியாவுக்கு நடத்தி, விருந்து கொடுத்து அனுப்பினான்; பின்பு பெனாதாத் சமாரியாவை முற்றுகையிட்டதால் கொடிய பஞ்சம் உண்டானது, ராஜா எலிசாவைக் கொல்ல நினைத்தான்.",
    "2 Kings 7": "நாளை இந்நேரத்தில் சமாரியாவின் வாசலில் மாவு மலிவாய் விற்கப்படும் என்று எலிசா சொன்னான்; அதை நம்பாத அதிகாரியிடம், 'நீ அதைக் காண்பாய், ஆனாலும் புசிக்கமாட்டாய்' என்றான். கர்த்தர் சீரியரின் பாளயத்தில் பெரிய சேனையின் இரைச்சலைக் கேட்கப்பண்ணினதால், அவர்கள் எல்லாவற்றையும் விட்டு ஓடிப்போனார்கள்; அதைக் கண்ட நான்கு குஷ்டரோகிகள், 'இந்த நாள் நற்செய்தியின் நாள்' என்று பட்டணத்துக்கு அறிவித்தார்கள். எலிசா சொன்னபடியே மாவு மலிவாய் விற்றது; அந்த அதிகாரி வாசலில் ஜனங்களால் மிதியுண்டு செத்தான்.",
    "2 Kings 8": "எலிசாவின் ஆலோசனைப்படி ஏழு வருஷப் பஞ்சத்தின்போது பெலிஸ்தர் தேசத்தில் தங்கியிருந்த சூனேமிய ஸ்திரீ திரும்பி வந்தபோது, ராஜா அவள் வீட்டையும் நிலத்தையும் திரும்பக் கொடுத்தான். எலிசா தமஸ்குவில் ஆசகேலைப் பார்த்து அழுது, அவன் இஸ்ரவேலுக்குச் செய்யப்போகும் தீங்கை முன்னறிவித்தான்; ஆசகேல் பெனாதாதைக் கொன்று சீரியாவின் ராஜாவானான். யூதாவில் யோராமும் அகசியாவும் ஆகாபின் வீட்டாரின் வழியில் நடந்து பொல்லாப்புச் செய்தார்கள்; ஏதோம் யூதாவுக்கு விரோதமாகக் கலகம் பண்ணியது.",
    "2 Kings 9": "எலிசா தீர்க்கதரிசிகளின் புத்திரரில் ஒருவனை அனுப்பி, ஆகாபின் வீட்டை அழிக்கும்படி யெகூவை இஸ்ரவேலின்மேல் ராஜாவாக அபிஷேகம் பண்ணச் செய்தான். யெகூ வேகமாய் இரதத்தை ஓட்டி யெஸ்ரயேலுக்கு வந்து, யோராமை அம்பால் எய்து கொன்று, நாபோத்தின் நிலத்தில் போட்டான்; யூதாவின் ராஜாவாகிய அகசியாவும் கொல்லப்பட்டான். யேசபேல் ஜன்னல் வழியாகக் கீழே தள்ளப்பட்டாள்; எலியா சொன்ன கர்த்தருடைய வார்த்தையின்படியே நாய்கள் அவள் மாம்சத்தைத் தின்றன.",
    "2 Kings 10": "யெகூ சமாரியாவின் பெரியவர்களுக்குக் கடிதம் எழுதி, ஆகாபின் எழுபது குமாரரையும் கொல்லுவித்தான்; ஆகாபின் வீட்டாரில் ஒருவரும் மீதியாயிருக்கவில்லை. பாகாலின் தீர்க்கதரிசிகளையும் ஆராதனைக்காரரையும் பெரிய பலியிடுவதாகச் சொல்லிக் கூட்டி, பாகாலின் கோவிலில் அவர்களைக் கொன்று, கோவிலை இடித்துப்போட்டான். ஆனாலும் பெத்தேலிலும் தாணிலும் இருந்த பொன் கன்றுக்குட்டிகளை அவன் விட்டு விலகவில்லை; அந்நாட்களில் கர்த்தர் இஸ்ரவேலைக் குறைக்கத் தொடங்கினார், ஆசகேல் அவர்களை முறியடித்தான்.",
    "2 Kings 11": "அகசியாவின் தாயாகிய அத்தாலியாள் ராஜவம்சத்தாரையெல்லாம் அழித்துப்போட்டாள்; யோசேபாள் குழந்தையாகிய யோவாசை ஒளித்து, ஆறு வருஷம் கர்த்தருடைய ஆலயத்தில் வைத்திருந்தாள். ஏழாம் வருஷத்தில் யோய்தா ஆசாரியன் யோவாசுக்கு முடிசூட்டி அபிஷேகம் பண்ணினான்; ஜனங்கள் கைகொட்டி 'ராஜா வாழ்க' என்றார்கள், 'துரோகம், துரோகம்' என்று கூவின அத்தாலியாள் கொல்லப்பட்டாள். யோய்தா கர்த்தருக்கும் ராஜாவுக்கும் ஜனங்களுக்கும் நடுவே உடன்படிக்கை பண்ணினான்; ஜனங்கள் பாகாலின் கோவிலை இடித்துப்போட்டார்கள்.",
    "2 Kings 12": "யோவாஸ் ஏழு வயதில் ராஜாவாகி, யோய்தா ஆசாரியன் போதித்த நாளெல்லாம் கர்த்தருடைய பார்வைக்குச் செம்மையானதைச் செய்தான். ஆலயத்தைப் பழுதுபார்க்க ஆசாரியர் தாமதித்ததால், யோய்தா ஒரு பெட்டியின் மூடியில் துவாரம் போட்டு காணிக்கைகளைச் சேகரித்து, அதை வேலையாட்களின் கையில் கொடுத்தான். சீரியாவின் ராஜாவாகிய ஆசகேல் எருசலேமுக்கு விரோதமாக வந்தபோது, யோவாஸ் பரிசுத்தமாக்கப்பட்ட பொருட்களையெல்லாம் அவனுக்கு அனுப்பினான்; பின்பு யோவாஸ் தன் ஊழியக்காரரால் கொல்லப்பட்டான்.",
    "2 Kings 13": "இஸ்ரவேலில் யோவாகாஸ் பொல்லாப்புச் செய்ததால் கர்த்தர் அவர்களை ஆசகேலின் கையில் ஒப்புக்கொடுத்தார்; அவன் கர்த்தரிடம் வேண்டிக்கொண்டபோது, கர்த்தர் இஸ்ரவேலுக்கு ஒரு இரட்சகனைக் கொடுத்தார். இஸ்ரவேலின் ராஜாவாகிய யோவாஸ் வியாதிப்பட்டிருந்த எலிசாவிடம் வந்து அழுதான்; எலிசா அவனை அம்பு எய்யச் சொல்லி, பின்பு அம்புகளால் தரையில் அடிக்கச் சொன்னான்; அவன் மூன்றுதரம் மாத்திரம் அடித்ததால் சீரியரை மூன்றுதரம் மாத்திரம் முறியடிப்பாய் என்றான். எலிசா மரித்து அடக்கம் பண்ணப்பட்டான்; அவன் கல்லறையில் போடப்பட்ட ஒரு பிணம் அவன் எலும்புகளின்மேல் பட்டவுடனே உயிர்பெற்று எழுந்தது.",
    "2 Kings 14": "அமத்சியா யூதாவில் கர்த்தருடைய பார்வைக்குச் செம்மையானதைச் செய்தான், ஆனாலும் மேடைகளை அகற்றவில்லை; தன் தகப்பனைக் கொன்றவர்களைக் கொன்றான், நியாயப்பிரமாணத்தின்படி அவர்கள் பிள்ளைகளைக் கொல்லவில்லை. ஏதோமை முறியடித்தபின் பெருமைகொண்டு இஸ்ரவேலின் ராஜாவாகிய யோவாசோடு யுத்தம் பண்ணினான்; யூதா தோற்றுப்போனது, எருசலேமின் அலங்கம் இடிக்கப்பட்டது, ஆலயப் பொக்கிஷங்கள் கொள்ளையிடப்பட்டன. இஸ்ரவேலில் இரண்டாம் யெரொபெயாம், கர்த்தர் யோனா தீர்க்கதரிசி மூலம் சொன்னபடி, இஸ்ரவேலின் எல்லைகளைத் திரும்பக் கொண்டுவந்தான்.",
    "2 Kings 15": "யூதாவில் அசரியா கர்த்தருடைய பார்வைக்குச் செம்மையானதைச் செய்தான்; ஆனாலும் கர்த்தர் அவனை அடித்ததால் அவன் மரணநாள்மட்டும் குஷ்டரோகியாயிருந்தான்; பின்பு அவன் குமாரன் யோதாம் அரசாண்டான். இஸ்ரவேலில் சகரியா, சல்லூம், மெனாகேம், பெக்காகியா, பெக்கா ஆகியோர் ஒருவரையொருவர் கொன்று அரசாண்டார்கள்; யெகூவுக்குக் கர்த்தர் சொன்னபடி அவன் சந்ததி நாலாம் தலைமுறையோடு முடிந்தது. அசீரியாவின் ராஜாக்களாகிய பூலும் திகிலாத்பிலேசரும் வந்து, இஸ்ரவேல் ஜனங்களைச் சிறைபிடித்துக் கொண்டுபோனார்கள்.",
    "2 Kings 16": "ஆகாஸ் யூதாவின் ராஜாவாகி கர்த்தருடைய பார்வைக்குச் செம்மையானதைச் செய்யாமல், தன் குமாரனையும் அக்கினியிலே தகிக்கப்பண்ணினான். சீரியாவின் ராஜாவும் இஸ்ரவேலின் ராஜாவும் எருசலேமை முற்றுகையிட்டபோது, ஆலயத்தின் பொன் வெள்ளியை அசீரியாவின் ராஜாவாகிய திகிலாத்பிலேசருக்கு அனுப்பி உதவி கேட்டான். தமஸ்குவில் கண்ட பலிபீடத்தின் மாதிரியின்படி ஒரு பலிபீடத்தைக் கட்டுவித்து, கர்த்தருடைய வெண்கலப் பலிபீடத்தை அதின் இடத்திலிருந்து அகற்றினான்.",
    "2 Kings 17": "இஸ்ரவேலின் கடைசி ராஜாவாகிய ஓசெயா எகிப்தோடு சதி செய்ததால், அசீரியாவின் ராஜாவாகிய சல்மனாசார் சமாரியாவை மூன்று வருஷம் முற்றுகையிட்டுப் பிடித்து, இஸ்ரவேலரை அசீரியாவுக்குச் சிறைபிடித்துக் கொண்டுபோனான். அவர்கள் அந்நிய தேவர்களைச் சேவித்து, தீர்க்கதரிசிகள் மூலம் கர்த்தர் கொடுத்த எச்சரிப்புகளுக்குச் செவிகொடாமல், தங்கள் கழுத்தைக் கடினப்படுத்தினதினாலேயே இது நடந்தது. அசீரியர் அந்நிய ஜனங்களைச் சமாரியாவின் பட்டணங்களில் குடியேற்றினார்கள்; அவர்கள் கர்த்தருக்குப் பயந்தும் தங்கள் சொந்த தேவர்களையும் சேவித்தார்கள்.",
    "2 Kings 18": "எசேக்கியா யூதாவின் ராஜாவாகி, தன் தகப்பனாகிய தாவீதைப்போல் கர்த்தருடைய பார்வைக்குச் செம்மையானதைச் செய்தான்; மேடைகளை அகற்றி, ஜனங்கள் தூபங்காட்டி வந்த மோசேயின் வெண்கலச் சர்ப்பத்தை உடைத்துப்போட்டான்; அவனைப்போல் கர்த்தரை நம்பின ராஜா யூதாவில் இருந்ததில்லை. அசீரியாவின் ராஜாவாகிய சனகெரிப் யூதாவின் அரணான பட்டணங்களையெல்லாம் பிடித்தான். அவன் அனுப்பின ரப்சாக்கே எருசலேமின் அலங்கத்தண்டையில் நின்று, 'கர்த்தர் உங்களைத் தப்புவிப்பார் என்று எசேக்கியா உங்களை நம்பப்பண்ணாதிருக்கட்டும்' என்று எபிரெய பாஷையில் தூஷித்துப் பேசினான்.",
    "2 Kings 19": "எசேக்கியா தன் வஸ்திரங்களைக் கிழித்து, இரட்டுடுத்தி கர்த்தருடைய ஆலயத்துக்குப் போய், ஏசாயா தீர்க்கதரிசியிடம் ஆள் அனுப்பினான்; 'பயப்படாதே' என்று கர்த்தர் சொல்லுகிறார் என்று ஏசாயா பதில் அனுப்பினான். சனகெரிபின் கடிதத்தை எசேக்கியா கர்த்தருடைய சந்நிதியில் விரித்துவைத்து ஜெபித்தான்; கர்த்தர் ஏசாயா மூலம், அவன் இந்தப் பட்டணத்துக்குள் ஒரு அம்பும் எய்வதில்லை என்று பதில் கொடுத்தார். அன்று இரவு கர்த்தருடைய தூதன் அசீரியரின் பாளயத்தில் லட்சத்தெண்பத்தையாயிரம் பேரைச் சங்கரித்தார்; சனகெரிப் நினிவேக்குத் திரும்பிப்போய், தன் குமாரரால் கொல்லப்பட்டான்.",
    "2 Kings 20": "எசேக்கியா மரணத்துக்கு ஏதுவான வியாதிப்பட்டபோது, சுவரின் பக்கமாய்த் தன் முகத்தைத் திருப்பி அழுது ஜெபித்தான்; 'உன் விண்ணப்பத்தைக் கேட்டேன், உன் கண்ணீரைக் கண்டேன்' என்று சொல்லி, கர்த்தர் அவன் நாட்களோடே பதினைந்து வருஷம் கூட்டினார். அதற்கு அடையாளமாக, சூரிய கடிகாரத்தில் நிழல் பத்துப் பாகை பின்னிட்டுத் திரும்பியது. பாபிலோன் ராஜாவின் தூதருக்கு எசேக்கியா தன் பொக்கிஷங்களையெல்லாம் காண்பித்தான்; அவைகளெல்லாம் பாபிலோனுக்குக் கொண்டுபோகப்படும் என்று ஏசாயா முன்னறிவித்தான்.",
    "2 Kings 21": "மனாசே பன்னிரண்டு வயதில் ராஜாவாகி ஐம்பத்தைந்து வருஷம் அரசாண்டான்; அவன் மேடைகளைத் திரும்பக் கட்டி, பாகாலுக்குப் பலிபீடங்களை எடுப்பித்து, தன் குமாரனை அக்கினியில் தகிக்கப்பண்ணி, கர்த்தருடைய ஆலயத்திலேயே விக்கிரகத்தை வைத்தான்; குற்றமில்லாத இரத்தத்தையும் மிகுதியாய்ச் சிந்தினான். 'ஒருவன் தட்டைத் துடைத்துக் கவிழ்த்துவைப்பதுபோல எருசலேமைத் துடைப்பேன்' என்று கர்த்தர் தீர்க்கதரிசிகள் மூலம் சொன்னார். அவன் குமாரனாகிய ஆமோனும் அதே பொல்லாப்பைச் செய்து தன் ஊழியக்காரரால் கொல்லப்பட்டான்; அவன் குமாரனாகிய யோசியா ராஜாவானான்.",
    "2 Kings 22": "யோசியா எட்டு வயதில் ராஜாவாகி, வலதுபுறம் இடதுபுறம் விலகாமல் தாவீதின் வழியில் செம்மையாய் நடந்தான். கர்த்தருடைய ஆலயத்தைப் பழுதுபார்க்கும்போது, பிரதான ஆசாரியனாகிய இல்க்கியா நியாயப்பிரமாண புஸ்தகத்தைக் கண்டெடுத்தான்; சாப்பான் அதை ராஜாவுக்கு முன்பாக வாசித்தபோது, ராஜா தன் வஸ்திரங்களைக் கிழித்துக்கொண்டான். தீர்க்கதரிசியானவளாகிய உல்தாள், புஸ்தகத்தில் எழுதியிருக்கிற தீங்கு வரும் என்றும், ஆனாலும் யோசியா தன்னைத் தாழ்த்தினதால் அவன் நாட்களில் அது வராது என்றும் சொன்னாள்.",
    "2 Kings 23": "யோசியா ஜனங்களெல்லாருக்கும் முன்பாக உடன்படிக்கைப் புஸ்தகத்தை வாசித்து, கர்த்தரைப் பின்பற்றும்படி உடன்படிக்கை பண்ணினான். அவன் பாகால், அசேரா, சூரியன் ஆகியவற்றின் விக்கிரகங்களை ஆலயத்திலிருந்து அகற்றி, மேடைகளையும் தோப்பேத்தையும் அழித்து, தேவனுடைய மனுஷன் முன்னறிவித்தபடி பெத்தேலின் பலிபீடத்தை இடித்துப்போட்டான்; நியாயாதிபதிகளின் நாட்கள் முதல் ஆசரிக்கப்படாத பெரிய பஸ்காவை ஆசரித்தான். அவனைப்போல் முழு இருதயத்தோடு கர்த்தரிடம் திரும்பின ராஜா அவனுக்கு முன்னும் பின்னும் இல்லை; ஆனாலும் மனாசேயின் பாவங்களினிமித்தம் கர்த்தருடைய கோபம் தணியவில்லை; யோசியா மெகிதோவில் எகிப்தின் ராஜாவாகிய பார்வோன்நேகோவால் கொல்லப்பட்டான்.",
    "2 Kings 24": "பாபிலோனின் ராஜாவாகிய நேபுகாத்நேச்சார் வந்தபோது, யோயாக்கீம் மூன்று வருஷம் அவனுக்கு அடங்கி, பின்பு கலகம் பண்ணினான்; மனாசேயின் பாவங்களினிமித்தம் கர்த்தர் யூதாவுக்கு விரோதமாகச் சத்துருக்களை அனுப்பினார். யோயாக்கீன் மூன்று மாதம் அரசாண்டபோது நேபுகாத்நேச்சார் எருசலேமை முற்றுகையிட்டு, யோயாக்கீனையும் பிரபுக்களையும் பராக்கிரமசாலிகளையும் தொழிலாளிகளையும் பதினாயிரம் பேரைப் பாபிலோனுக்குச் சிறைபிடித்துக்கொண்டுபோனான்; ஆலயத்தின் பொக்கிஷங்களையும் எடுத்துக்கொண்டான். அவன் சிதேக்கியாவை ராஜாவாக்கினான்; சிதேக்கியாவும் பாபிலோன் ராஜாவுக்கு விரோதமாகக் கலகம் பண்ணினான்.",
    "2 Kings 25": "சிதேக்கியாவின் ஒன்பதாம் வருஷத்தில் நேபுகாத்நேச்சார் எருசலேமை முற்றுகையிட்டான்; பட்டணத்தில் கொடிய பஞ்சம் உண்டானது; சிதேக்கியா தப்பி ஓடிப் பிடிபட்டான், அவன் கண்களுக்கு முன்பாக அவன் குமாரர் கொல்லப்பட்டார்கள், அவன் கண்கள் குருடாக்கப்பட்டன. காவற்சேனாதிபதியாகிய நேபுசராதான் கர்த்தருடைய ஆலயத்தையும் ராஜாவின் அரமனையையும் எருசலேமின் வீடுகளையும் சுட்டெரித்து, அலங்கங்களை இடித்து, ஜனங்களைச் சிறைபிடித்துக்கொண்டுபோனான்; அதிபதியாக நியமிக்கப்பட்ட கெதலியா கொல்லப்பட்டதால், மீதியான ஜனங்கள் எகிப்துக்கு ஓடிப்போனார்கள். சிறையிருப்பின் முப்பத்தேழாம் வருஷத்தில், பாபிலோனின் ராஜாவாகிய ஏவில்மெரொதாக் யோயாக்கீனைச் சிறையிலிருந்து விடுவித்து, அவன் வாழ்நாளெல்லாம் தன் பந்தியில் புசிக்கப்பண்ணினான்.",

    "1 Chronicles 1": "ஆதாம் முதல் நோவா வரையிலான தலைமுறைகளும், நோவாவின் குமாரராகிய சேம், காம், யாப்பேத்தின் சந்ததியாரும் விவரிக்கப்பட்டுள்ளனர். சேமின் வம்சத்தில் ஆபிரகாம் வந்தான்; ஆபிரகாமின் குமாரராகிய இஸ்மவேல், ஈசாக்கு, கேத்தூராளின் குமாரர் ஆகியோரின் சந்ததியும் சொல்லப்பட்டுள்ளது. ஏசாவின் சந்ததியும், ஏதோமின் ராஜாக்களும் பிரபுக்களும் பட்டியலிடப்பட்டுள்ளனர்.",
    "1 Chronicles 2": "இஸ்ரவேலின் பன்னிரண்டு குமாரரின் பேர்கள் சொல்லப்பட்டுள்ளன. யூதாவின் சந்ததியில் பாரேஸ், எஸ்ரோன், ராம் வழியாக போவாஸ், ஓபேத், ஈசாய், தாவீது வரையிலான வம்ச வரிசை கொடுக்கப்பட்டுள்ளது. எஸ்ரோனின் குமாரராகிய யெராமியேல், காலேப் ஆகியோரின் சந்ததியாரும் விவரிக்கப்பட்டுள்ளனர்.",
    "1 Chronicles 3": "எபிரோனிலும் எருசலேமிலும் தாவீதுக்குப் பிறந்த குமாரரின் பேர்கள் கொடுக்கப்பட்டுள்ளன; அவர்களில் பத்சேபாள் பெற்ற சாலொமோனும் ஒருவன். சாலொமோன் முதல் யோசியா, சிதேக்கியா வரையிலான யூதாவின் ராஜாக்களின் வரிசை சொல்லப்பட்டுள்ளது. சிறையிருப்புக்குப் பின் யெகொனியாவிலிருந்து செருபாபேல் உட்பட வந்த சந்ததியாரும் பட்டியலிடப்பட்டுள்ளனர்.",
    "1 Chronicles 4": "யூதாவின் மற்ற வம்சங்கள் விவரிக்கப்பட்டுள்ளன. யாபேஸ், 'தேவனே, நீர் என்னை ஆசீர்வதித்து, என் எல்லையைப் பெரிதாக்கி, உமது கரம் என்னோடிருந்து, தீங்கு என்னைத் துக்கப்படுத்தாதபடி காத்தருளும்' என்று இஸ்ரவேலின் தேவனை நோக்கி வேண்டிக்கொண்டான்; அவன் கேட்டதைத் தேவன் அருளினார். சிமியோனின் சந்ததியும், அவர்கள் குடியிருந்த பட்டணங்களும், அவர்கள் அடைந்த வெற்றிகளும் சொல்லப்பட்டுள்ளன.",
    "1 Chronicles 5": "ரூபன் தன் தகப்பனுடைய மஞ்சத்தைத் தீட்டுப்படுத்தினதால், அவன் சேஷ்டபுத்திர உரிமை யோசேப்பின் குமாரருக்குக் கொடுக்கப்பட்டது; யூதா தன் சகோதரருக்குள் பலவானானான், அவனிலிருந்து அதிபதி தோன்றினார். ரூபன், காத், மனாசேயின் பாதிக் கோத்திரத்தார் ஆகாரியரோடு யுத்தம் பண்ணினபோது, தேவனை நோக்கிக் கூப்பிட்டு அவரை நம்பினதால் ஜெயம் பெற்றார்கள். பின்பு அவர்கள் தேசத்து ஜனங்களின் தேவர்களைப் பின்பற்றினதால், தேவன் அசீரியாவின் ராஜாவை எழுப்பி அவர்களைச் சிறைபிடித்துக் கொண்டுபோகப்பண்ணினார்.",
    "1 Chronicles 6": "லேவியின் சந்ததியும், ஆரோன் முதல் சிறையிருப்பின் காலத்திலிருந்த யோசதாக் வரையிலான பிரதான ஆசாரியர்களின் வரிசையும் கொடுக்கப்பட்டுள்ளன. பெட்டி இளைப்பாறின பின்பு, கர்த்தருடைய ஆலயத்தில் பாட்டுப்பாடும்படி தாவீது ஏமான், ஆசாப், ஏத்தான் ஆகியோரை நியமித்தான். ஆரோனின் குமாரருக்கும் மற்ற லேவியருக்கும் கொடுக்கப்பட்ட பட்டணங்களும் வெளிநிலங்களும் விவரிக்கப்பட்டுள்ளன.",
    "1 Chronicles 7": "இசக்கார், பென்யமீன், நப்தலி, மனாசே, எப்பிராயீம், ஆசேர் ஆகிய கோத்திரங்களின் சந்ததியார் விவரிக்கப்பட்டுள்ளனர். எப்பிராயீமின் குமாரர் கொல்லப்பட்டதால் அவன் நெடுநாள் துக்கித்தான்; அதன்பின் பிறந்த பெரீயாவின் வம்சத்தில் நூனின் குமாரனாகிய யோசுவா வந்தான். ஒவ்வொரு கோத்திரத்திலுமிருந்த பராக்கிரமசாலிகளின் எண்ணிக்கையும் சொல்லப்பட்டுள்ளது.",
    "1 Chronicles 8": "பென்யமீனின் சந்ததியார் விரிவாக விவரிக்கப்பட்டுள்ளனர். கீஸ், சவுல், யோனத்தான், மேரிபால் வழியாக வந்த சவுலின் வம்சம் கொடுக்கப்பட்டுள்ளது. உலாமின் குமாரர் பராக்கிரமசாலிகளான வில்வீரர்களாயிருந்தார்கள்.",
    "1 Chronicles 9": "இஸ்ரவேலர் எல்லாரும் வம்ச அட்டவணையில் எழுதப்பட்டார்கள்; யூதா தங்கள் துரோகத்தினிமித்தம் பாபிலோனுக்குச் சிறைபிடித்துக் கொண்டுபோகப்பட்டார்கள். சிறையிருப்புக்குப் பின் எருசலேமில் திரும்பக் குடியேறின ஆசாரியர், லேவியர், வாசல் காவலர், பாடகர் ஆகியோரும் அவர்களுடைய ஊழியப் பொறுப்புகளும் விவரிக்கப்பட்டுள்ளன. சவுலின் வம்ச அட்டவணை மறுபடியும் கொடுக்கப்பட்டுள்ளது.",
    "1 Chronicles 10": "கில்போவா மலையில் பெலிஸ்தர் இஸ்ரவேலரை முறியடித்தார்கள்; சவுலும் அவன் குமாரரும் மரித்தார்கள். யாபேஸ் கீலேயாத்தின் பராக்கிரமசாலிகள் அவர்கள் உடல்களை எடுத்து அடக்கம் பண்ணி ஏழு நாள் உபவாசித்தார்கள். சவுல் கர்த்தருடைய வார்த்தையைக் கைக்கொள்ளாமல் அஞ்சனக்காரியிடம் விசாரித்ததினால் மரித்தான்; கர்த்தர் ராஜ்யத்தை ஈசாயின் குமாரனாகிய தாவீதுக்குத் திருப்பினார்.",
    "1 Chronicles 11": "இஸ்ரவேலர் எல்லாரும் எபிரோனில் கூடி, கர்த்தர் சாமுவேல் மூலம் சொன்னபடி தாவீதை இஸ்ரவேலின்மேல் ராஜாவாக அபிஷேகம் பண்ணினார்கள். தாவீது எருசலேமிலுள்ள சீயோன் கோட்டையைப் பிடித்தான்; முதலாவது ஏறிப்போன யோவாப் சேனாபதியானான்; சேனைகளின் கர்த்தர் தாவீதோடிருந்ததால் அவன் மேன்மேலும் பெருகினான். தாவீதின் பராக்கிரமசாலிகளின் பட்டியலும், அவர்கள் பெத்லகேமின் கிணற்றுத் தண்ணீரைக் கொண்டுவந்த சம்பவமும் சொல்லப்பட்டுள்ளன.",
    "1 Chronicles 12": "சவுலுக்குப் பயந்து தாவீது சிக்லாகில் இருந்தபோது, பென்யமீனர், காத்தியர் முதலிய பராக்கிரமசாலிகள் அவனிடம் வந்து சேர்ந்தார்கள்; தேவ ஆவி அமாசாயின்மேல் இறங்கியபோது, 'தாவீதே, நாங்கள் உம்முடையவர்கள்' என்றான். தாவீதை ராஜாவாக்கும்படி எல்லாக் கோத்திரங்களிலிருந்தும் யுத்தவீரர் எபிரோனுக்கு வந்தார்கள்; இசக்காரின் புத்திரர் இஸ்ரவேல் செய்ய வேண்டியதை அறியக் காலங்களை அறிந்தவர்களாயிருந்தார்கள். அவர்கள் மூன்று நாள் தாவீதோடே புசித்துக் குடித்தார்கள்; இஸ்ரவேலில் மிகுந்த சந்தோஷம் உண்டானது.",
    "1 Chronicles 13": "தாவீது சபையோடு ஆலோசனைபண்ணி, கீரியாத்யாரீமிலிருந்து தேவனுடைய பெட்டியைக் கொண்டுவரப் புறப்பட்டான். மாடுகள் இடறினதால் ஊசா பெட்டியைப் பிடிக்கக் கையை நீட்டினான்; கர்த்தருடைய கோபம் மூண்டு அவனை அடித்தது, அந்த இடம் பேரேஸ்ஊசா எனப்பட்டது. தாவீது பயந்து பெட்டியை ஓபேத்ஏதோமின் வீட்டில் வைத்தான்; அது அங்கே மூன்று மாதம் இருந்தபோது கர்த்தர் அவன் வீட்டை ஆசீர்வதித்தார்.",
    "1 Chronicles 14": "தீருவின் ராஜாவாகிய ஈராம் தாவீதுக்கு வீடு கட்ட மரங்களையும் கலைஞர்களையும் அனுப்பினான்; கர்த்தர் தன்னை இஸ்ரவேலின்மேல் ராஜாவாக உறுதிப்படுத்தினார் என்று தாவீது அறிந்தான். எருசலேமில் தாவீதுக்குப் பிறந்த குமாரரின் பேர்கள் சொல்லப்பட்டுள்ளன. தேவனிடம் விசாரித்து, அவர் சொன்னபடி பெலிஸ்தரை இரண்டுதரம் முறியடித்தான்; தாவீதின் கீர்த்தி எல்லா தேசங்களிலும் பரவியது.",
    "1 Chronicles 15": "முதல்முறை லேவியர் பெட்டியைச் சுமக்காததாலேயே கர்த்தர் அடித்தார் என்று உணர்ந்து, தாவீது லேவியரைத் தங்களைப் பரிசுத்தப்படுத்திக்கொண்டு பெட்டியைத் தோள்களில் சுமக்கச் செய்தான். பாடகர்களும் வாத்தியக்காரர்களும் நியமிக்கப்பட்டார்கள்; ஆர்ப்பரிப்போடும் எக்காள சத்தத்தோடும் பெட்டி தாவீதின் நகரத்துக்குக் கொண்டுவரப்பட்டது. தாவீது குதித்து நடனமாடுவதை ஜன்னல் வழியாய்க் கண்ட மீகாள் அவனைத் தன் இருதயத்தில் அசட்டை பண்ணினாள்.",
    "1 Chronicles 16": "பெட்டி தாவீது அமைத்த கூடாரத்தில் வைக்கப்பட்டு பலிகள் செலுத்தப்பட்டன; தாவீது ஜனங்களுக்கு அப்பம் பங்கிட்டு, கர்த்தரைத் துதிக்க ஆசாப் முதலிய லேவியரை நியமித்தான். தாவீதின் ஸ்தோத்திரப் பாட்டு: 'கர்த்தரைத் துதியுங்கள், அவர் நல்லவர், அவர் கிருபை என்றுமுள்ளது'; 'பரிசுத்த அலங்காரத்தோடே கர்த்தரைத் தொழுதுகொள்ளுங்கள்'. கிபியோனிலிருந்த ஆசரிப்புக்கூடாரத்தில் சாதோக்கும் ஆசாரியரும் தினமும் தகனபலிகளைச் செலுத்தும்படி வைக்கப்பட்டார்கள்.",
    "1 Chronicles 17": "தாவீது கர்த்தருக்கு ஆலயம் கட்ட விரும்பினான்; நாத்தான் மூலம் கர்த்தர், நீ அல்ல உன் சந்ததியான குமாரனே ஆலயத்தைக் கட்டுவான், அவன் சிங்காசனத்தை என்றென்றைக்கும் நிலைப்படுத்துவேன் என்று சொன்னார். 'நான் அவனுக்குப் பிதாவாயிருப்பேன், அவன் எனக்குக் குமாரனாயிருப்பான்; என் கிருபையை அவனை விட்டு விலக்கமாட்டேன்' என்று வாக்களித்தார். தாவீது கர்த்தருக்கு முன்பாக உட்கார்ந்து, 'நான் யார்? என் வீடு எம்மாத்திரம்?' என்று நன்றியோடு ஜெபித்தான்.",
    "1 Chronicles 18": "தாவீது பெலிஸ்தரையும் மோவாபியரையும் சோபாவின் ராஜாவாகிய ஆதாரேசரையும் சீரியரையும் ஏதோமியரையும் முறியடித்தான்; தாவீது போன இடமெல்லாம் கர்த்தர் அவனுக்கு ஜெயம் கொடுத்தார். யுத்தத்தில் கொள்ளையிடப்பட்ட மிகுதியான வெண்கலத்தினால் சாலொமோன் பின்பு வெண்கலக் கடல் முதலியவற்றைச் செய்தான். தாவீது தன் ஜனங்கள் எல்லாருக்கும் நியாயமும் நீதியும் செய்தான்; அவனுடைய அதிகாரிகளின் பேர்களும் சொல்லப்பட்டுள்ளன.",
    "1 Chronicles 19": "அம்மோனியரின் ராஜாவாகிய ஆனூன் தாவீது அனுப்பின ஆறுதல் தூதர்களை அவமானப்படுத்தினான். அம்மோனியர் சீரியரைக் கூலிக்கு அமர்த்தி யுத்தத்துக்கு வந்தார்கள்; யோவாபும் அபிசாயும் அவர்களை முறியடித்தார்கள். சீரியர் மறுபடியும் கூடினபோது தாவீது தானே போய் அவர்களை முறியடித்தான்; அதன்பின் சீரியர் தாவீதோடு சமாதானம் பண்ணி அவனுக்குக் கீழ்ப்பட்டார்கள்.",
    "1 Chronicles 20": "யோவாப் அம்மோனியரின் ரப்பா பட்டணத்தை முறியடித்தான்; தாவீது அவர்கள் ராஜாவின் தலையிலிருந்த பொற்கிரீடத்தை எடுத்துத் தன் தலையில் வைத்துக்கொண்டான். பெலிஸ்தரோடு நடந்த யுத்தங்களில் இராட்சதரின் சந்ததியார் கொல்லப்பட்டார்கள்; கோலியாத்தின் சகோதரனாகிய லாக்மியும், கைகால்களில் ஆறாறு விரல்களுள்ள ஒரு பெரியவனும் அவர்களில் அடங்குவர். அவர்கள் தாவீதின் கையினாலும் அவன் ஊழியக்காரரின் கையினாலும் விழுந்தார்கள்.",
    "1 Chronicles 21": "சாத்தான் இஸ்ரவேலுக்கு விரோதமாய் எழும்பி, ஜனங்களை எண்ணும்படி தாவீதை ஏவினான்; யோவாப் தடுத்தும் ராஜாவின் வார்த்தையே மேற்கொண்டது. இந்தக் காரியம் தேவனுடைய பார்வைக்குப் பொல்லாப்பாயிருந்தது; தாவீது 'கர்த்தருடைய கையிலே விழுவேனாக' என்று சொன்னான், கொள்ளைநோயினால் எழுபதாயிரம் பேர் செத்தார்கள். தாவீது எபூசியனாகிய ஒர்னானின் களத்தை முழுவிலைக்கு வாங்கி அங்கே பலிபீடம் கட்டினான்; கர்த்தர் வானத்திலிருந்து அக்கினியால் உத்தரவு அருளினார், தூதன் தன் பட்டயத்தை உறையிலே போட்டான்.",
    "1 Chronicles 22": "'இதுவே தேவனாகிய கர்த்தருடைய ஆலயம்' என்று தாவீது சொல்லி, ஆலயம் கட்டுவதற்கு வெட்டின கற்களையும் இரும்பையும் வெண்கலத்தையும் கேதுரு மரங்களையும் மிகுதியாய் ஆயத்தம் பண்ணினான். நீ மிகுதியான இரத்தம் சிந்தினாய், உன் குமாரன் சமாதானமுள்ள மனுஷனாயிருந்து என் நாமத்துக்கு ஆலயத்தைக் கட்டுவான் என்று கர்த்தர் சொன்னதைச் சாலொமோனிடம் சொன்னான். 'பலங்கொண்டு திடமனதாயிரு; பயப்படாதே' என்று சொல்லி, சாலொமோனுக்கு உதவும்படி இஸ்ரவேலின் பிரபுக்களுக்குக் கட்டளையிட்டான்.",
    "1 Chronicles 23": "தாவீது வயதுசென்றவனானபோது தன் குமாரனாகிய சாலொமோனை இஸ்ரவேலின்மேல் ராஜாவாக்கினான். முப்பது வயதுக்கு மேற்பட்ட லேவியர் முப்பத்தெட்டாயிரம் பேர் எண்ணப்பட்டு, ஆலய வேலைக்கும், அதிபதிகளாகவும், வாசல் காவலராகவும், பாடகர்களாகவும் பிரிக்கப்பட்டார்கள். கெர்சோன், கோகாத், மெராரி வம்சங்கள் சொல்லப்பட்டு, காலையிலும் மாலையிலும் கர்த்தரைத் துதிக்கும் ஊழியம் லேவியருக்குக் கொடுக்கப்பட்டது.",
    "1 Chronicles 24": "ஆரோனின் சந்ததியாராகிய ஆசாரியர், எலெயாசார் மற்றும் இத்தாமாரின் வம்சங்களிலிருந்து, சீட்டுப்போட்டு இருபத்துநான்கு வகுப்புகளாகப் பிரிக்கப்பட்டார்கள். ஒவ்வொரு வகுப்பும் தன் முறைப்படி கர்த்தருடைய ஆலயத்தில் ஊழியம் செய்ய வேண்டும். மற்ற லேவியரும் தங்கள் சகோதரராகிய ஆசாரியரைப்போலவே சீட்டுப்போட்டுப் பிரிக்கப்பட்டார்கள்.",
    "1 Chronicles 25": "ஆசாப், ஏமான், எதுத்தூன் ஆகியோரின் குமாரர், சுரமண்டலங்களோடும் தம்புருகளோடும் கைத்தாளங்களோடும் தீர்க்கதரிசனம் சொல்லும் ஊழியத்துக்குப் பிரித்தெடுக்கப்பட்டார்கள். கர்த்தருக்குப் பாடக் கற்றுக்கொண்ட நிபுணர்கள் இருநூற்றெண்பத்தெட்டுப் பேர். சிறியவனும் பெரியவனும், ஆசிரியனும் சீஷனும் ஒரே முறைப்படி சீட்டுப்போட்டு இருபத்துநான்கு வகுப்புகளாக்கப்பட்டார்கள்.",
    "1 Chronicles 26": "வாசல் காவலரின் வகுப்புகள் சொல்லப்பட்டுள்ளன; தேவன் ஆசீர்வதித்த ஓபேத்ஏதோமின் வம்சத்தார் அவர்களில் அடங்குவர்; ஒவ்வொரு வாசலுக்கும் சீட்டுப்போடப்பட்டது. யுத்தக்கொள்ளையிலிருந்து கர்த்தருடைய ஆலயத்துக்குப் பரிசுத்தமாக்கப்பட்ட பொக்கிஷங்களை விசாரிக்கும்படி லேவியர் நியமிக்கப்பட்டார்கள். இஸ்ரவேலின் வெளிவேலைகளுக்கு அதிகாரிகளும் நியாயாதிபதிகளும் நியமிக்கப்பட்டார்கள்.",
    "1 Chronicles 27": "வருஷத்தின் ஒவ்வொரு மாதமும் ராஜாவுக்கு ஊழியம் செய்த, இருபத்துநாலாயிரம் பேர் கொண்ட பன்னிரண்டு வகுப்புகளும் அவைகளின் தலைவர்களும் சொல்லப்பட்டுள்ளனர். இஸ்ரவேல் கோத்திரங்களின் பிரபுக்களும் பட்டியலிடப்பட்டுள்ளனர்; இஸ்ரவேலை வானத்து நட்சத்திரங்களைப்போல் பெருகப்பண்ணுவேன் என்று கர்த்தர் சொன்னதால் தாவீது இருபது வயதுக்குக் கீழ்ப்பட்டவர்களை எண்ணவில்லை. ராஜாவின் பொக்கிஷங்கள், வயல்கள், திராட்சத்தோட்டங்கள், மந்தைகள் ஆகியவற்றின் விசாரிப்புக்காரரும் ஆலோசனைக்காரரும் சொல்லப்பட்டுள்ளனர்.",
    "1 Chronicles 28": "தாவீது இஸ்ரவேலின் பிரபுக்களையெல்லாம் எருசலேமில் கூட்டி, ஆலயம் கட்ட தனக்கு மனதிருந்தும், நீ யுத்தமனுஷன் என்று தேவன் சொல்லி சாலொமோனைத் தெரிந்துகொண்டார் என்று அறிவித்தான். 'என் குமாரனாகிய சாலொமோனே, நீ உன் பிதாவின் தேவனை அறிந்து, உத்தம இருதயத்தோடும் மனப்பூர்வமாயும் அவரைச் சேவி; நீ அவரைத் தேடினால் உனக்குத் தென்படுவார்' என்றான். கர்த்தருடைய கை தன்மேல் இருந்து எழுதிக்கொடுத்த ஆலயத்தின் மாதிரியைச் சாலொமோனிடம் ஒப்புவித்து, 'பலங்கொண்டு திடமனதாயிருந்து இதைச் செய்; தேவனாகிய கர்த்தர் உன்னோடே இருப்பார்' என்றான்.",
    "1 Chronicles 29": "தாவீது தன் சொந்தப் பொக்கிஷமாகிய பொன்னையும் வெள்ளியையும் ஆலயத்துக்குக் கொடுத்தான்; பிரபுக்களும் மனப்பூர்வமாய்க் காணிக்கை கொடுத்தார்கள், ஜனங்கள் அதினால் சந்தோஷப்பட்டார்கள். 'கர்த்தாவே, மாட்சிமையும் வல்லமையும் மகிமையும் உம்முடையவைகள்; எல்லாம் உம்மாலே உண்டானது; உம்முடைய கையிலிருந்து வாங்கி உமக்குக் கொடுத்தோம்' என்று தாவீது சபைக்கு முன்பாகக் கர்த்தரைத் துதித்து ஜெபித்தான். சாலொமோன் இரண்டாம்முறை ராஜாவாக அபிஷேகம் பண்ணப்பட்டான்; தாவீது நாற்பது வருஷம் அரசாண்டு, நல்ல முதிர்வயதில் நீடித்த நாளும் ஐசுவரியமும் கனமும் நிறைந்தவனாய் மரித்தான்.",

    "2 Chronicles 1": "தாவீதின் குமாரனாகிய சாலொமோன் தன் ராஜ்யத்தில் பலப்பட்டான்; அவன் கிபியோனிலிருந்த ஆசரிப்புக்கூடாரத்துக்கு முன்பான வெண்கலப் பலிபீடத்தின்மேல் ஆயிரம் தகனபலிகளைச் செலுத்தினான். அன்று இரவு தேவன் அவனுக்குத் தரிசனமாகி, 'நான் உனக்கு என்ன தரவேண்டும், கேள்' என்றார்; ஜனங்களை நியாயம் விசாரிக்க ஞானத்தையும் அறிவையும் சாலொமோன் கேட்டான். தேவன் அதோடுகூட ஐசுவரியத்தையும் சம்பத்தையும் கனத்தையும் கொடுத்தார்; எருசலேமில் பொன்னும் வெள்ளியும் கற்களைப்போல் மிகுதியாயிருந்தன.",
    "2 Chronicles 2": "சாலொமோன் கர்த்தருடைய நாமத்துக்கு ஆலயத்தையும் தனக்கு அரமனையையும் கட்டத் தீர்மானித்து, சுமைகாரரையும் கல்வெட்டிகளையும் நியமித்தான். 'வானங்களும் வானாதி வானங்களும் அவரைக் கொள்ளாதிருக்க, அவருக்கு ஆலயம் கட்ட நான் யார்?' என்று சொல்லி, தீருவின் ராஜாவாகிய ஈராமிடம் கேதுரு மரங்களையும் ஞானமுள்ள கலைஞனையும் கேட்டான். ஈராம் இஸ்ரவேலின் தேவனைத் துதித்து, ஈராம்அபி என்னும் கலைஞனை அனுப்பி, தேவையான மரங்களை அனுப்புவதாக ஒப்புக்கொண்டான்.",
    "2 Chronicles 3": "கர்த்தர் தாவீதுக்குத் தரிசனமான மோரியா மலையில், எபூசியனாகிய ஒர்னானின் களத்தில் சாலொமோன் ஆலயத்தைக் கட்டத் தொடங்கினான். மகா பரிசுத்த ஸ்தலம் பசும்பொன்னால் மூடப்பட்டு, அதில் இரண்டு பெரிய கேருபீன்கள் வைக்கப்பட்டன; இளநீலம், இரத்தாம்பரம், சிவப்பு நூல்களால் கேருபீன்கள் சித்திரிக்கப்பட்ட திரைச்சீலையும் செய்யப்பட்டது. ஆலயத்துக்கு முன்பாக யாகீன், போவாஸ் என்னும் இரண்டு தூண்கள் நிறுத்தப்பட்டன.",
    "2 Chronicles 4": "வெண்கலப் பலிபீடமும், பன்னிரண்டு காளைகளின்மேல் நிற்கும் வார்ப்பிக்கப்பட்ட கடலும், கழுவும்படி பத்துத் தொட்டிகளும் செய்யப்பட்டன. பத்துப் பொன் குத்துவிளக்குகளும், பத்து மேஜைகளும், ஆசாரியரின் பிராகாரமும் பெரிய பிராகாரமும் உண்டாக்கப்பட்டன. ஈராம் வெண்கலப் பணிமுட்டுகளைச் செய்து முடித்தான்; ஆலயத்தின் பொற்பீடமும், சமுகத்தப்பத்தின் மேஜைகளும், மற்றப் பொற்பணிமுட்டுகளும் செய்யப்பட்டன.",
    "2 Chronicles 5": "ஆலய வேலைகள் முடிந்தபின், தாவீது பரிசுத்தமாக்கியிருந்த பொருட்களைச் சாலொமோன் ஆலயத்தின் பொக்கிஷங்களில் வைத்தான். லேவியர் உடன்படிக்கைப் பெட்டியை மகா பரிசுத்த ஸ்தலத்துக்குக் கொண்டுவந்தார்கள்; அதில் மோசே ஓரேபில் வைத்த இரண்டு கற்பலகைகளே இருந்தன. பாடகர்களும் எக்காளம் ஊதுகிறவர்களும் ஒருமனமாய், 'அவர் நல்லவர், அவர் கிருபை என்றுமுள்ளது' என்று கர்த்தரைத் துதித்தபோது, மேகம் ஆலயத்தை நிரப்பியது; கர்த்தருடைய மகிமையினால் ஆசாரியர் ஊழியம் செய்ய நிற்கக்கூடாதிருந்தது.",
    "2 Chronicles 6": "சாலொமோன் சபையை ஆசீர்வதித்து, வெண்கல மேடையின்மேல் முழங்கால்படியிட்டு வானத்தை நோக்கிக் கைகளை விரித்து ஜெபித்தான். 'வானங்களும் வானாதி வானங்களும் உம்மைக் கொள்ளாதே' என்று சொல்லி, ஜனங்கள் பாவஞ்செய்து பஞ்சம், தோல்வி, சிறையிருப்பு வரும்போது இந்த ஸ்தலத்தை நோக்கி ஜெபித்தால் பரலோகத்திலிருந்து கேட்டு மன்னிக்கும்படி வேண்டினான். 'தேவனாகிய கர்த்தாவே, நீரும் உம்முடைய வல்லமையின் பெட்டியும் உம்முடைய இளைப்பாறுதலுக்கு எழுந்தருளும்' என்று ஜெபத்தை முடித்தான்.",
    "2 Chronicles 7": "சாலொமோன் ஜெபித்து முடித்தபோது, வானத்திலிருந்து அக்கினி இறங்கி பலிகளைப் பட்சித்தது, கர்த்தருடைய மகிமை ஆலயத்தை நிரப்பியது; ஜனங்கள் தரையில் முகங்குப்புற விழுந்து, 'அவர் நல்லவர், அவர் கிருபை என்றுமுள்ளது' என்று துதித்தார்கள். கர்த்தர் இரவில் சாலொமோனுக்குத் தரிசனமாகி, 'என் நாமம் தரிக்கப்பட்ட என் ஜனங்கள் தங்களைத் தாழ்த்தி, ஜெபம்பண்ணி, என் முகத்தைத் தேடி, தங்கள் பொல்லாத வழிகளைவிட்டுத் திரும்பினால், பரலோகத்திலிருந்து கேட்டு, அவர்கள் பாவத்தை மன்னித்து, அவர்கள் தேசத்துக்குச் சுகமளிப்பேன்' என்றார். அவர்கள் விலகிப்போனால் இந்த ஆலயத்தை என் சமுகத்தைவிட்டுத் தள்ளிவிடுவேன் என்றும் எச்சரித்தார்.",
    "2 Chronicles 8": "சாலொமோன் அநேக பட்டணங்களைக் கட்டி, தேசத்தில் மீந்திருந்த அந்நிய ஜனங்களை அடிமைவேலைக்காரராக்கினான்; இஸ்ரவேல் புத்திரரையோ அடிமைகளாக்கவில்லை. கர்த்தருடைய பெட்டி வந்த இடங்கள் பரிசுத்தமானவை என்பதால், பார்வோனின் குமாரத்திக்குத் தனியாக ஒரு அரமனையைக் கட்டினான். மோசேயின் கட்டளைப்படி பண்டிகைகளில் பலிகளைச் செலுத்தி, தாவீதின் ஒழுங்கின்படி ஆசாரிய லேவிய வகுப்புகளை நியமித்தான்; அவன் கப்பல்கள் ஓப்பீரிலிருந்து பொன் கொண்டுவந்தன.",
    "2 Chronicles 9": "சேபாவின் ராஜஸ்திரீ சாலொமோனைக் கடினமான கேள்விகளால் சோதிக்க வந்து, அவன் ஞானத்தையும் மகிமையையும் கண்டு, 'உமது ஞானத்தின் மகத்துவத்தில் பாதியும் எனக்குச் சொல்லப்படவில்லை' என்று சொல்லி அவனுடைய தேவனைத் துதித்தாள். சாலொமோன் ஐசுவரியத்திலும் ஞானத்திலும் பூமியின் ராஜாக்களெல்லாரிலும் பெரியவனாயிருந்தான்; பொன் கேடகங்களும் தந்தச் சிங்காசனமும் செய்தான். அவன் நாற்பது வருஷம் இஸ்ரவேலை அரசாண்டு மரித்தான்; அவன் குமாரன் ரெகொபெயாம் ராஜாவானான்.",
    "2 Chronicles 10": "ரெகொபெயாம் முதியோரின் ஆலோசனையைத் தள்ளி, வாலிபரின் ஆலோசனைப்படி ஜனங்களுக்குக் கடினமாய்ப் பதில் சொன்னான். 'தாவீதினிடத்தில் எங்களுக்குப் பங்கு ஏது? இஸ்ரவேலே, உங்கள் கூடாரங்களுக்குப் போங்கள்' என்று சொல்லி, இஸ்ரவேலர் தாவீதின் வீட்டைவிட்டுப் பிரிந்தார்கள். கர்த்தர் அகியா மூலம் யெரொபெயாமுக்குச் சொன்ன வார்த்தை நிறைவேறும்படி இந்தக் காரியம் தேவனால் உண்டானது.",
    "2 Chronicles 11": "ரெகொபெயாம் இஸ்ரவேலோடு யுத்தம் பண்ணப் புறப்பட்டபோது, 'உங்கள் சகோதரரோடு யுத்தம் பண்ணாதீர்கள்' என்று கர்த்தர் தீர்க்கதரிசியாகிய செமாயா மூலம் சொன்னார்; அவர்கள் கீழ்ப்படிந்து திரும்பினார்கள். ரெகொபெயாம் யூதாவில் அரணான பட்டணங்களைக் கட்டினான். யெரொபெயாம் லேவியரை ஆசாரிய ஊழியத்திலிருந்து தள்ளினதால், ஆசாரியரும் லேவியரும் இஸ்ரவேலின் தேவனைத் தேடுகிற ஜனங்களும் எருசலேமுக்கு வந்து யூதாவின் ராஜ்யத்தைப் பலப்படுத்தினார்கள்.",
    "2 Chronicles 12": "ரெகொபெயாம் பலப்பட்டபின் அவனும் இஸ்ரவேலர் எல்லாரும் கர்த்தருடைய நியாயப்பிரமாணத்தை விட்டுவிட்டார்கள்; ஆகையால் எகிப்தின் ராஜாவாகிய சீஷாக் எருசலேமுக்கு விரோதமாக வந்தான். 'நீங்கள் என்னை விட்டீர்கள், ஆகையால் நானும் உங்களைச் சீஷாக்கின் கையில் விட்டேன்' என்று செமாயா சொன்னபோது, ராஜாவும் பிரபுக்களும் தங்களைத் தாழ்த்தினார்கள்; அதனால் கர்த்தர் அவர்களை முழுதும் அழிக்கவில்லை. சீஷாக் ஆலயத்தின் பொக்கிஷங்களை எடுத்துக்கொண்டுபோனான்; ரெகொபெயாம் கர்த்தரைத் தேட தன் இருதயத்தை நிலைப்படுத்தாததால் பொல்லாப்புச் செய்தான்.",
    "2 Chronicles 13": "அபியா இஸ்ரவேலின் ராஜாவாகிய யெரொபெயாமோடு யுத்தம் பண்ணினான்; செமாரயீம் மலையில் நின்று, கர்த்தர் உப்பு உடன்படிக்கையினால் ராஜ்யத்தைத் தாவீதுக்குக் கொடுத்தார் என்றும், நாங்களோ கர்த்தரை விடவில்லை என்றும் இஸ்ரவேலரிடம் பேசினான். யெரொபெயாம் பதிவிருப்போரை வைத்து யூதாவைச் சூழ்ந்தபோது, யூதா மனுஷர் கர்த்தரை நோக்கிக் கூப்பிட்டு ஆர்ப்பரித்தார்கள்; தேவன் இஸ்ரவேலை முறியடித்தார். யூதா புத்திரர் தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரைச் சார்ந்திருந்ததால் மேற்கொண்டார்கள்.",
    "2 Chronicles 14": "ஆசா தன் தேவனாகிய கர்த்தருடைய பார்வைக்கு நன்மையும் செம்மையுமானதைச் செய்து, அந்நிய பலிபீடங்களையும் மேடைகளையும் அகற்றி, கர்த்தரைத் தேடும்படி யூதாவுக்குக் கட்டளையிட்டான்; அவன் நாட்களில் தேசம் அமைதலாயிருந்தது. எத்தியோப்பியனாகிய சேரா மிகப்பெரிய சேனையோடு யுத்தத்துக்கு வந்தான். 'கர்த்தாவே, பலமுள்ளவனுக்கும் பலமில்லாதவனுக்கும் உதவி செய்ய உமக்கு வித்தியாசமில்லை; எங்களுக்கு உதவிசெய்யும், உம்மையே சார்ந்திருக்கிறோம்' என்று ஆசா ஜெபித்தான்; கர்த்தர் எத்தியோப்பியரை முறியடித்தார்.",
    "2 Chronicles 15": "தேவனுடைய ஆவி அசரியாவின்மேல் வந்தது; அவன், 'நீங்கள் அவரைத் தேடினால் உங்களுக்குத் தென்படுவார்; அவரை விட்டால் அவர் உங்களை விடுவார்; நீங்கள் திடன்கொள்ளுங்கள், உங்கள் கிரியைக்குப் பலன் உண்டு' என்றான். ஆசா தைரியமடைந்து அருவருப்புகளை அகற்றினான்; ஜனங்கள் முழு இருதயத்தோடும் முழு ஆத்துமாவோடும் கர்த்தரைத் தேடும்படி உடன்படிக்கை பண்ணினார்கள். விக்கிரகத்தை உண்டாக்கின தன் தாயாகிய மாக்காளை ராஜஸ்திரீயின் ஸ்தானத்திலிருந்து நீக்கினான்; முப்பத்தைந்தாம் வருஷம்வரை யுத்தம் இல்லாதிருந்தது.",
    "2 Chronicles 16": "இஸ்ரவேலின் ராஜாவாகிய பாஷா யூதாவுக்கு விரோதமாக ராமாவைக் கட்டினபோது, ஆசா ஆலயத்தின் பொக்கிஷங்களைச் சீரியாவின் ராஜாவாகிய பெனாதாதுக்கு அனுப்பி உதவி கேட்டான். ஞானதிருஷ்டிக்காரனாகிய அனானி, 'நீ கர்த்தரைச் சாராமல் சீரியாவின் ராஜாவைச் சார்ந்தாய்; தம்மைப் பற்றி உத்தம இருதயமுள்ளவர்களுக்குத் தம்மை வல்லவராகக் காண்பிக்கும்படி கர்த்தருடைய கண்கள் பூமியெங்கும் உலாவிக்கொண்டிருக்கிறது' என்று கடிந்துகொண்டான். ஆசா கோபங்கொண்டு அவனைச் சிறையில் வைத்தான்; பின்பு கால்களில் கொடிய வியாதி வந்தபோதும் கர்த்தரைத் தேடாமல் பரிகாரிகளையே தேடினான், அப்படியே மரித்தான்.",
    "2 Chronicles 17": "யோசபாத் ராஜாவாகி பலப்பட்டான்; அவன் தன் தகப்பனாகிய தாவீதின் முந்தின வழிகளில் நடந்து பாகால்களைத் தேடாததால் கர்த்தர் அவனோடிருந்தார். அவன் தன் அரசாட்சியின் மூன்றாம் வருஷத்தில் பிரபுக்களையும் லேவியரையும் ஆசாரியரையும் அனுப்பி, கர்த்தருடைய நியாயப்பிரமாண புஸ்தகத்தைக் கொண்டு யூதாவின் பட்டணங்களெங்கும் ஜனங்களுக்குப் போதிக்கச் செய்தான். சுற்றியுள்ள ராஜ்யங்களின்மேல் கர்த்தருடைய பயங்கரம் உண்டானதால் அவர்கள் யுத்தம் பண்ணவில்லை; பெலிஸ்தரும் அரபியரும் காணிக்கை கொண்டுவந்தார்கள்.",
    "2 Chronicles 18": "யோசபாத் ஆகாபோடு சம்பந்தம் கலந்து, அவனோடு ராமோத் கீலேயாத்துக்கு யுத்தத்துக்குப் போக ஒப்புக்கொண்டான். நானூறு தீர்க்கதரிசிகள் ஜெயம் என்று சொன்னார்கள்; மிகாயா மாத்திரம், இஸ்ரவேலர் மேய்ப்பனில்லாத ஆடுகளைப்போல் மலைகளில் சிதறியிருப்பதைக் கண்டேன் என்றான். யுத்தத்தில் சூழப்பட்ட யோசபாத் கூப்பிட்டபோது கர்த்தர் அவனுக்கு உதவினார்; ஆகாபோ ஒருவன் குறிவைக்காமல் எய்த அம்பினால் குத்தப்பட்டு மரித்தான்.",
    "2 Chronicles 19": "ஞானதிருஷ்டிக்காரனாகிய யெகூ, 'துன்மார்க்கனுக்குத் துணைநின்று, கர்த்தரைப் பகைக்கிறவர்களைச் சிநேகிப்பது தகுமோ?' என்று யோசபாத்தைக் கடிந்துகொண்டான்; ஆனாலும் உன்னிடத்தில் நல்ல காரியங்களும் காணப்படுகின்றன என்றான். யோசபாத் தேசமெங்கும் நியாயாதிபதிகளை நியமித்து, 'நீங்கள் மனுஷனுக்காக அல்ல, கர்த்தருக்காகவே நியாயம் விசாரிக்கிறீர்கள்; நம்முடைய தேவனாகிய கர்த்தரிடத்தில் அநியாயமும் முகதாட்சணியமும் லஞ்சமும் இல்லை' என்றான். 'திடமனதாயிருந்து செய்யுங்கள்; கர்த்தர் நல்லவர்களோடே இருப்பார்' என்று சொன்னான்.",
    "2 Chronicles 20": "மோவாபியரும் அம்மோனியரும் சேயீர் மலைநாட்டாரும் திரளாய் யுத்தத்துக்கு வந்தபோது, யோசபாத் பயந்து கர்த்தரைத் தேடி யூதா எங்கும் உபவாசத்தைக் கூறினான்; 'எங்களுக்கு விரோதமாய் வரும் இந்தத் திரளான கூட்டத்துக்கு முன்பாக நிற்க எங்களுக்குப் பெலனில்லை; என்ன செய்யவேண்டும் என்று அறியோம்; எங்கள் கண்கள் உம்மையே நோக்கியிருக்கிறது' என்று ஜெபித்தான். யகாசியேலின்மேல் கர்த்தருடைய ஆவி வந்து, 'இந்த யுத்தம் உங்களுடையதல்ல, தேவனுடையது' என்றான். பாடகர்கள் சேனைக்கு முன்பாக நடந்து துதிக்கத் தொடங்கினபோது, கர்த்தர் பதிவிருப்போரை வைத்தார்; சத்துருக்கள் ஒருவரையொருவர் அழித்தார்கள், யூதா மூன்று நாள் கொள்ளையைச் சேர்த்து, பெராக்கா பள்ளத்தாக்கில் கர்த்தரை ஸ்தோத்திரித்தார்கள்.",
    "2 Chronicles 21": "யோசபாத் மரித்தபின் அவன் குமாரனாகிய யோராம் ராஜாவாகி, தன் சகோதரரையெல்லாம் கொன்று, ஆகாபின் குமாரத்தியை மணந்து கர்த்தருடைய பார்வைக்குப் பொல்லாப்பானதைச் செய்தான். ஏதோமும் லிப்னாவும் அவனுக்கு விரோதமாகக் கலகம் பண்ணின. எலியா தீர்க்கதரிசியிடமிருந்து வந்த கடிதம் அவனுக்கு வரும் கொடிய வியாதியை முன்னறிவித்தது; பெலிஸ்தரும் அரபியரும் அவன் வீட்டைக் கொள்ளையிட்டார்கள், அவன் குடல் வியாதியால் வேதனைப்பட்டு மரித்தான், அவனுக்காக ஒருவரும் வருந்தவில்லை.",
    "2 Chronicles 22": "அகசியா ராஜாவாகி, ஆகாபின் வீட்டாருடைய துர்ஆலோசனையின்படி நடந்து பொல்லாப்புச் செய்தான். இஸ்ரவேலின் ராஜாவாகிய யோராமோடு சேர்ந்ததால், தேவன் ஆகாபின் வீட்டை அழிக்க அபிஷேகம் பண்ணின யெகூவின் கையால் அவன் கொல்லப்பட்டான். அவன் தாயாகிய அத்தாலியாள் ராஜவம்சத்தையெல்லாம் அழித்தாள்; யோசேபெயாத் குழந்தையாகிய யோவாசை ஒளித்து, ஆறு வருஷம் தேவனுடைய ஆலயத்தில் வைத்திருந்தாள்.",
    "2 Chronicles 23": "ஏழாம் வருஷத்தில் யோய்தா ஆசாரியன் லேவியரையும் வம்சத் தலைவரையும் கூட்டி உடன்படிக்கை பண்ணி, ராஜகுமாரனாகிய யோவாசுக்கு முடிசூட்டினான்; ஜனங்கள் 'ராஜா வாழ்க' என்றார்கள். 'துரோகம், துரோகம்' என்று கூவின அத்தாலியாள் ஆலயத்துக்கு வெளியே கொண்டுபோகப்பட்டு கொல்லப்பட்டாள். ஜனங்கள் பாகாலின் கோவிலை இடித்துப்போட்டார்கள்; யோய்தா தாவீதின் ஒழுங்கின்படி லேவியரின் ஊழியத்தைத் திரும்ப ஏற்படுத்தினான், பட்டணம் அமைதலாயிருந்தது.",
    "2 Chronicles 24": "யோவாஸ் ஆசாரியனாகிய யோய்தாவின் நாளெல்லாம் கர்த்தருடைய பார்வைக்குச் செம்மையானதைச் செய்து, பெட்டியில் காணிக்கைகளைச் சேர்த்து ஆலயத்தைப் புதுப்பித்தான். யோய்தா மரித்தபின் யூதாவின் பிரபுக்களுடைய பேச்சைக் கேட்டு தோப்புகளையும் விக்கிரகங்களையும் சேவித்தான்; அவர்களைக் கடிந்துகொண்ட யோய்தாவின் குமாரனாகிய சகரியாவை ஆலயப் பிராகாரத்தில் கல்லெறிந்து கொல்லுவித்தான், அவன் சாகும்போது 'கர்த்தர் இதைப் பார்த்து விசாரிப்பார்' என்றான். சிறிய சீரியச் சேனை யூதாவின் பெரிய சேனையை முறியடித்தது; யோவாஸ் தன் ஊழியக்காரரால் கொல்லப்பட்டான்.",
    "2 Chronicles 25": "அமத்சியா கர்த்தருடைய பார்வைக்குச் செம்மையானதைச் செய்தான், ஆனாலும் உத்தம இருதயத்தோடே அல்ல. அவன் இஸ்ரவேலிலிருந்து கூலிச்சேனையை வாங்கினான்; ஒரு தேவனுடைய மனுஷன் எச்சரித்ததால், 'இதைப்பார்க்கிலும் அதிகமாய் உமக்குக் கொடுக்கக் கர்த்தரால் கூடும்' என்ற வார்த்தையை நம்பி அவர்களை அனுப்பிவிட்டான். ஏதோமை முறியடித்தபின் அவர்கள் தேவர்களைப் பணிந்துகொண்டு தீர்க்கதரிசியின் எச்சரிப்பைக் கேட்கவில்லை; இஸ்ரவேலின் ராஜாவாகிய யோவாசோடு யுத்தம் பண்ணித் தோற்றுப்போனான், பின்பு லாகீசில் கொல்லப்பட்டான்.",
    "2 Chronicles 26": "உசியா பதினாறு வயதில் ராஜாவானான்; தேவனுடைய தரிசனங்களில் அறிவுள்ள சகரியாவின் நாட்களில் அவன் தேவனைத் தேடினான், அவன் கர்த்தரைத் தேடின நாளெல்லாம் தேவன் அவனை வாய்க்கப்பண்ணினார். அவன் பெலிஸ்தரை முறியடித்து, பட்டணங்களையும் கோபுரங்களையும் யுத்த எந்திரங்களையும் உண்டாக்கினான்; அவன் கீர்த்தி தூரமட்டும் பரவியது. அவன் பலப்பட்டபோது மனமேட்டிமையாகி தூபங்காட்ட ஆலயத்துக்குள் பிரவேசித்தான்; ஆசாரியர் தடுத்தபோது கோபங்கொண்டான், உடனே அவன் நெற்றியில் குஷ்டம் எழும்பியது; மரணமட்டும் குஷ்டரோகியாய்த் தனிவீட்டில் இருந்தான்.",
    "2 Chronicles 27": "யோதாம் தன் தகப்பனாகிய உசியாவைப்போல் கர்த்தருடைய பார்வைக்குச் செம்மையானதைச் செய்தான்; ஆனால் கர்த்தருடைய ஆலயத்துக்குள் பிரவேசிக்கவில்லை; ஜனங்களோ இன்னும் கெட்டுப்போனார்கள். அவன் ஆலயத்தின் உயர்ந்த வாசலைக் கட்டி, அம்மோனியரை யுத்தத்தில் ஜெயித்தான். அவன் தன் தேவனாகிய கர்த்தருக்கு முன்பாகத் தன் வழிகளை நேராக்கினதால் பலப்பட்டான்.",
    "2 Chronicles 28": "ஆகாஸ் பாகால்களுக்கு வார்ப்பிக்கப்பட்ட விக்கிரகங்களைச் செய்து, தன் பிள்ளைகளை அக்கினியிலே தகிக்கப்பண்ணினான். சீரியரும் இஸ்ரவேலரும் யூதாவை முறியடித்தார்கள்; இஸ்ரவேலர் யூதாவிலிருந்து இரண்டு லட்சம் பேரைச் சிறைபிடித்தபோது, தீர்க்கதரிசியாகிய ஓதேத் கடிந்துகொண்டதால் சிறைகளைத் திருப்பி அனுப்பினார்கள். ஆகாஸ் அசீரியாவின் ராஜாவிடம் உதவி கேட்டான், அது அவனுக்கு நெருக்கமாயிற்று; தன் நெருக்கத்திலும் இன்னும் அதிகமாய்த் துரோகம் பண்ணி, தமஸ்குவின் தேவர்களுக்குப் பலியிட்டு, கர்த்தருடைய ஆலயத்தின் கதவுகளைப் பூட்டினான்.",
    "2 Chronicles 29": "எசேக்கியா தன் அரசாட்சியின் முதல் வருஷம் முதல் மாதத்திலேயே கர்த்தருடைய ஆலயத்தின் கதவுகளைத் திறந்து பழுதுபார்த்தான்; லேவியரைத் தங்களைப் பரிசுத்தப்படுத்திக்கொண்டு ஆலயத்தைச் சுத்திகரிக்கும்படி சொன்னான். இஸ்ரவேல் முழுவதற்குமாகப் பாவநிவாரணபலிகளும் தகனபலிகளும் செலுத்தப்பட்டன; தாவீதின் கட்டளைப்படி லேவியர் வாத்தியங்களோடு கர்த்தரைத் துதித்தார்கள். இந்தக் காரியம் சடிதியாய் நடந்ததால், தேவன் ஜனங்களுக்கு ஆயத்தம் பண்ணினதைக் குறித்து எசேக்கியாவும் ஜனங்களும் சந்தோஷப்பட்டார்கள்.",
    "2 Chronicles 30": "எசேக்கியா யூதாவுக்கும், எப்பிராயீம் மனாசே உட்பட இஸ்ரவேல் எங்கும் பஸ்காவுக்கு வரும்படி கடிதங்களை அனுப்பி, 'கர்த்தரிடம் திரும்புங்கள்; உங்கள் தேவனாகிய கர்த்தர் இரக்கமும் மனஉருக்கமுமுள்ளவர்' என்று அழைத்தான்; சிலர் பரியாசம் பண்ணினார்கள், சிலர் தங்களைத் தாழ்த்தி வந்தார்கள். இரண்டாம் மாதத்தில் பஸ்கா ஆசரிக்கப்பட்டது; சுத்திகரிக்கப்படாமல் புசித்தவர்களுக்காக எசேக்கியா ஜெபித்தான், கர்த்தர் கேட்டு ஜனங்களைக் குணமாக்கினார். அவர்கள் இன்னும் ஏழு நாள் பண்டிகை ஆசரித்தார்கள்; சாலொமோனின் நாட்கள்முதல் எருசலேமில் இப்படிப்பட்ட சந்தோஷம் உண்டாயிருக்கவில்லை.",
    "2 Chronicles 31": "பண்டிகை முடிந்தபின் இஸ்ரவேலர் விக்கிரகத் தூண்களையும் தோப்புகளையும் மேடைகளையும் உடைத்து அழித்தார்கள். எசேக்கியா ஆசாரிய லேவிய வகுப்புகளை ஒழுங்குபடுத்தினான்; ஜனங்கள் முதற்பலன்களையும் தசமபாகங்களையும் மிகுதியாய்க் கொண்டுவந்து குவியல் குவியலாக வைத்தார்கள். அவன் தன் தேவனைத் தேடும்படி தொடங்கின எல்லா வேலைகளையும் முழு இருதயத்தோடு செய்ததால் அவனுக்கு வாய்த்தது.",
    "2 Chronicles 32": "அசீரியாவின் ராஜாவாகிய சனகெரிப் படையெடுத்தபோது, எசேக்கியா நீரூற்றுகளை அடைத்து அலங்கத்தைப் பலப்படுத்தி, 'திடமனதாயிருங்கள்; அவனோடிருக்கிறது மாம்சபுயம், நம்மோடிருக்கிறவரோ நமக்குத் துணைநின்று யுத்தம் பண்ணும் நம்முடைய தேவனாகிய கர்த்தர்' என்று ஜனங்களைத் திடப்படுத்தினான். அசீரியர் தேவனைத் தூஷித்தபோது எசேக்கியாவும் ஏசாயாவும் ஜெபித்தார்கள்; கர்த்தர் ஒரு தூதனை அனுப்பி அசீரியரின் பராக்கிரமசாலிகளை அழித்தார். எசேக்கியா வியாதியிலிருந்து குணமாகி மனமேட்டிமையானான், பின்பு தன்னைத் தாழ்த்தினான்; பாபிலோனின் தூதர் விஷயத்தில் அவன் இருதயத்திலுள்ளதை அறியும்படி தேவன் அவனைச் சோதித்தார்.",
    "2 Chronicles 33": "மனாசே மேடைகளைத் திரும்பக் கட்டி, பாகால்களுக்குப் பலிபீடங்களை எடுப்பித்து, தன் பிள்ளைகளை அக்கினியில் தகித்து, அஞ்சனம் பார்த்து, தேவனுடைய ஆலயத்திலேயே விக்கிரகத்தை வைத்து மிகுதியான பொல்லாப்புச் செய்தான். கர்த்தர் அசீரியரின் சேனாபதிகளை வரப்பண்ணினார்; அவர்கள் மனாசேயைக் கொக்கிகளால் பிடித்து பாபிலோனுக்குக் கொண்டுபோனார்கள்; நெருக்கத்தில் அவன் தன்னை மிகவும் தாழ்த்தி ஜெபித்தான், கர்த்தர் கேட்டு அவனை எருசலேமுக்குத் திருப்பிக் கொண்டுவந்தார், அப்பொழுது கர்த்தரே தேவன் என்று மனாசே அறிந்தான். அவன் அந்நிய தேவர்களை அகற்றி கர்த்தரைச் சேவிக்கும்படி யூதாவுக்குக் கட்டளையிட்டான்; அவன் குமாரனாகிய ஆமோனோ தன்னைத் தாழ்த்தாமல் பொல்லாப்புச் செய்து கொல்லப்பட்டான்.",
    "2 Chronicles 34": "யோசியா எட்டு வயதில் ராஜாவாகி, தன் பதினாறாம் வயதில் தேவனைத் தேடத் தொடங்கி, இருபதாம் வயதில் யூதாவையும் எருசலேமையும் விக்கிரகங்களிலிருந்து சுத்திகரித்தான். ஆலயத்தைப் பழுதுபார்க்கும்போது இல்க்கியா ஆசாரியன் மோசேயின் மூலம் கொடுக்கப்பட்ட நியாயப்பிரமாண புஸ்தகத்தைக் கண்டெடுத்தான்; அதைக் கேட்ட ராஜா தன் வஸ்திரங்களைக் கிழித்துக்கொண்டான்; தீங்கு வரும், ஆனாலும் நீ உன்னைத் தாழ்த்தினதால் உன் நாட்களில் அல்ல என்று தீர்க்கதரிசியானவளாகிய உல்தாள் சொன்னாள். யோசியா ஜனங்களுக்கு முன்பாகப் புஸ்தகத்தை வாசித்து உடன்படிக்கை பண்ணினான்; அவன் நாளெல்லாம் ஜனங்கள் கர்த்தரைவிட்டு விலகவில்லை.",
    "2 Chronicles 35": "யோசியா எருசலேமில் கர்த்தருக்குப் பஸ்காவை ஆசரித்தான்; லேவியர் ஜனங்களுக்காக ஆயத்தம் பண்ணினார்கள், ராஜா தன் சொந்த மந்தையிலிருந்து ஜனங்களுக்குப் பலிமிருகங்களைக் கொடுத்தான். சாமுவேல் தீர்க்கதரிசியின் நாட்கள்முதல் இஸ்ரவேலில் இப்படிப்பட்ட பஸ்கா ஆசரிக்கப்படவில்லை. எகிப்தின் ராஜாவாகிய நேகோ மூலம் தேவன் சொன்ன எச்சரிப்பைக் கேளாமல் யோசியா மெகிதோவில் யுத்தம் பண்ணப்போனான்; வில்வீரர் எய்த அம்பால் காயப்பட்டு மரித்தான்; எரேமியா அவனுக்காகப் புலம்பினான்.",
    "2 Chronicles 36": "யோவாகாஸ், யோயாக்கீம், யோயாக்கீன், சிதேக்கியா ஆகியோர் கர்த்தருடைய பார்வைக்குப் பொல்லாப்பானதைச் செய்தார்கள்; சிதேக்கியா கர்த்தருடைய வாக்கைச் சொன்ன எரேமியாவுக்கு முன்பாகத் தன்னைத் தாழ்த்தவில்லை. கர்த்தர் தம்முடைய ஜனத்தின்மேல் இரங்கி அதிகாலமே தூதர்களை அனுப்பியும் அவர்கள் பரியாசம் பண்ணினதால், நேபுகாத்நேச்சார் ஆலயத்தைச் சுட்டெரித்து, எருசலேமின் அலங்கத்தை இடித்து, மீதியானவர்களைப் பாபிலோனுக்குச் சிறைபிடித்துக்கொண்டுபோனான்; எரேமியா சொன்னபடி எழுபது வருஷம் தேசம் தன் ஓய்வுநாட்களை அனுபவித்தது. பெர்சியாவின் ராஜாவாகிய கோரேஸ், எருசலேமில் தமக்கு ஆலயம் கட்டத் தேவன் தனக்குக் கட்டளையிட்டார் என்றும், அவருடைய ஜனங்கள் போகலாம் என்றும் விளம்பரம் பண்ணினான்.",

    "Ezra 1": "எரேமியாவின் வாயினால் கர்த்தர் சொன்ன வார்த்தை நிறைவேறும்படி, கர்த்தர் பெர்சியாவின் ராஜாவாகிய கோரேசின் ஆவியை ஏவினார்; எருசலேமில் கர்த்தருடைய ஆலயத்தைக் கட்டும்படி யூதர் போகலாம் என்று அவன் ராஜ்யமெங்கும் விளம்பரம் பண்ணினான். தேவன் ஏவின யூதா, பென்யமீன் வம்சத் தலைவரும் ஆசாரியரும் லேவியரும் புறப்பட்டார்கள்; சுற்றியிருந்தவர்கள் பொன், வெள்ளி, பொருட்கள், மிருகஜீவன்களைக் கொடுத்து உதவினார்கள். நேபுகாத்நேச்சார் எருசலேமிலிருந்து கொண்டுபோயிருந்த கர்த்தருடைய ஆலயப் பணிமுட்டுகளைக் கோரேஸ் யூதாவின் அதிபதியாகிய சேஸ்பாத்சாரிடம் ஒப்புவித்தான்.",
    "Ezra 2": "செருபாபேல், யெசுவா முதலியோரோடு பாபிலோனின் சிறையிருப்பிலிருந்து திரும்பி வந்தவர்களின் பட்டியல் வம்சவாரியாகக் கொடுக்கப்பட்டுள்ளது: ஜனங்கள், ஆசாரியர், லேவியர், பாடகர், வாசல்காவலர், நிதினீமியர். வம்ச அட்டவணையில் தங்கள் பேர்களைக் கண்டுபிடிக்க முடியாத ஆசாரியர் ஊரீமும் தும்மீமும் உள்ள ஆசாரியன் எழும்பும்வரை ஆசாரிய ஊழியத்திலிருந்து விலக்கப்பட்டார்கள். சபையார் மொத்தம் நாற்பத்தீராயிரத்து முந்நூற்றறுபது பேர்; வம்சத் தலைவர்களில் சிலர் ஆலயத்தைக் கட்டும்படி மனப்பூர்வமாய்க் காணிக்கை கொடுத்தார்கள்.",
    "Ezra 3": "ஏழாம் மாதத்தில் ஜனங்கள் ஒருமனப்பட்டு எருசலேமில் கூடினார்கள்; யெசுவாவும் செருபாபேலும் இஸ்ரவேலின் தேவனுடைய பலிபீடத்தைக் கட்டி, தகனபலிகளைச் செலுத்தி, கூடாரப்பண்டிகையை ஆசரித்தார்கள். இரண்டாம் வருஷத்தில் ஆலயத்தின் அஸ்திபாரம் போடப்பட்டது; ஆசாரியர் எக்காளங்களோடும் லேவியர் கைத்தாளங்களோடும், 'அவர் நல்லவர், அவர் கிருபை என்றுமுள்ளது' என்று கர்த்தரைத் துதித்துப் பாடினார்கள். முந்தின ஆலயத்தைக் கண்ட முதியோர் சத்தமிட்டு அழுதார்கள், அநேகர் சந்தோஷத்தால் ஆர்ப்பரித்தார்கள்; அழுகையின் சத்தத்தையும் ஆர்ப்பரிப்பின் சத்தத்தையும் பிரித்தறிய முடியாதிருந்தது.",
    "Ezra 4": "யூதாவின் சத்துருக்கள், 'உங்களோடேகூட நாங்களும் கட்டுவோம்' என்று வந்தார்கள்; செருபாபேலும் யெசுவாவும் அதற்கு இணங்கவில்லை. அவர்கள் யூதா ஜனங்களின் கைகளைத் தளரப்பண்ணி, ஆலோசனைக்காரரைக் கூலிக்கு அமர்த்தி, எருசலேம் கலகமும் பொல்லாப்புமுள்ள பட்டணம் என்று குற்றஞ்சாட்டி அர்தசஷ்டா ராஜாவுக்குக் கடிதம் எழுதினார்கள். ராஜா வேலையை நிறுத்தும்படி கட்டளையிட்டான்; பெர்சியாவின் ராஜாவாகிய தரியுவின் இரண்டாம் வருஷம்வரை தேவனுடைய ஆலயத்தின் வேலை நின்றுபோயிருந்தது.",
    "Ezra 5": "தீர்க்கதரிசிகளாகிய ஆகாயும் சகரியாவும் இஸ்ரவேலின் தேவனுடைய நாமத்தில் யூதருக்குத் தீர்க்கதரிசனம் சொன்னார்கள்; அப்பொழுது செருபாபேலும் யெசுவாவும் எழுந்து ஆலயத்தை மறுபடியும் கட்டத் தொடங்கினார்கள். அதிபதியாகிய தத்னாய், 'இந்த ஆலயத்தைக் கட்டும்படி உங்களுக்குக் கட்டளையிட்டது யார்?' என்று கேட்டு, தரியு ராஜாவுக்குக் கடிதம் எழுதினான். ஆனாலும் யூதருடைய மூப்பர்மேல் அவர்கள் தேவனுடைய கண் இருந்ததால் வேலை நிறுத்தப்படவில்லை; கோரேஸ் கொடுத்த கட்டளையைப் பொக்கிஷசாலையில் தேடிப்பார்க்கும்படி கடிதத்தில் கேட்கப்பட்டது.",
    "Ezra 6": "தரியு ராஜா தேடச் செய்தபோது, அக்மேதா அரமனையில் ஆலயத்தைக் கட்டும்படி கோரேஸ் கொடுத்த கட்டளைப் பத்திரம் கண்டுபிடிக்கப்பட்டது. தரியு, வேலைக்குத் தடைசெய்யாமல், ராஜாவின் வருமானத்திலிருந்து செலவைக் கொடுக்கவும், பலிகளுக்கு வேண்டியவைகளைத் தினந்தோறும் கொடுக்கவும் கட்டளையிட்டான். தரியுவின் ஆறாம் வருஷத்தில் ஆலயம் கட்டி முடிக்கப்பட்டு, ஜனங்கள் சந்தோஷத்தோடே அதைப் பிரதிஷ்டை பண்ணினார்கள்; பின்பு பஸ்காவையும் புளிப்பில்லா அப்பப் பண்டிகையையும் மகிழ்ச்சியோடு ஆசரித்தார்கள்.",
    "Ezra 7": "அர்தசஷ்டா ராஜாவின் நாட்களில் ஆரோனின் சந்ததியாகிய எஸ்றா பாபிலோனிலிருந்து எருசலேமுக்கு வந்தான்; அவன் மோசேயின் நியாயப்பிரமாணத்தில் தேறின வேதபாரகன், அவன் தேவனுடைய கரம் அவன்மேல் இருந்தது. எஸ்றா கர்த்தருடைய வேதத்தை ஆராயவும், அதின்படி செய்யவும், இஸ்ரவேலுக்குக் கற்றுக்கொடுக்கவும் தன் இருதயத்தைப் பக்குவப்படுத்தியிருந்தான். ராஜா ஆலயத்துக்காக அதிகாரமும் பொன் வெள்ளியும் கொடுத்து எஸ்றாவுக்குக் கடிதம் எழுதினான்; இதை ராஜாவின் இருதயத்தில் வைத்த கர்த்தருக்கு எஸ்றா ஸ்தோத்திரம் செலுத்தினான்.",
    "Ezra 8": "எஸ்றாவோடு பாபிலோனிலிருந்து வந்த வம்சத் தலைவர்களின் பட்டியல் கொடுக்கப்பட்டுள்ளது; லேவியர் ஒருவரும் இல்லாததைக் கண்டு அவர்களை அழைப்பித்தான். 'எங்கள் தேவனுடைய கரம் அவரைத் தேடுகிறவர்கள் எல்லார்மேலும் நன்மைக்காக இருக்கிறது' என்று ராஜாவிடம் சொல்லியிருந்ததால், வழியில் காவலுக்காகச் சேனையைக் கேட்க வெட்கப்பட்டு, அகாவா நதியண்டையில் உபவாசம் கூறி தேவனிடம் வேண்டிக்கொண்டான்; தேவன் அவர்கள் விண்ணப்பத்தைக் கேட்டார். பொன் வெள்ளி பணிமுட்டுகளை ஆசாரியரிடம் ஒப்புவித்து, சத்துருக்களுக்குத் தப்பி பத்திரமாக எருசலேமுக்கு வந்து, தகனபலிகளைச் செலுத்தினார்கள்.",
    "Ezra 9": "இஸ்ரவேல் ஜனங்களும் ஆசாரியரும் லேவியரும் தேசத்து ஜனங்களின் குமாரத்திகளை மணந்து, பரிசுத்த வித்து அந்நிய ஜனங்களோடு கலந்துபோனது என்று எஸ்றா கேள்விப்பட்டு, தன் வஸ்திரங்களைக் கிழித்து, தலைமயிரையும் தாடியையும் பிடுங்கி, திகைத்து உட்கார்ந்தான். மாலைப் பலியின் நேரத்தில் முழங்கால்படியிட்டு, 'என் தேவனே, என் முகத்தை உமக்கு முன்பாக ஏறெடுக்க வெட்கி நாணுகிறேன்; எங்கள் அக்கிரமங்கள் எங்கள் தலைக்கு மேலாகப் பெருகினது' என்று அறிக்கையிட்டு ஜெபித்தான். தேவன் சிறையிருப்பில் தங்களைக் கைவிடாமல் ஒரு மீதியை வைத்து இரக்கம் காட்டினார் என்று ஒப்புக்கொண்டான்.",
    "Ezra 10": "எஸ்றா அழுது ஜெபித்து அறிக்கையிடும்போது, திரளான ஜனங்கள் அவனிடம் கூடி மிகவும் அழுதார்கள்; செக்கனியா, 'இதைக் குறித்து இஸ்ரவேலுக்கு இன்னும் நம்பிக்கை உண்டு' என்று சொல்லி, அந்நிய மனைவிகளை அனுப்பிவிடும்படி உடன்படிக்கை பண்ணச் சொன்னான். மூன்று நாளுக்குள் ஜனங்கள் எல்லாரும் எருசலேமில் கூடி, அந்தக் காரியத்தினிமித்தமும் பெருமழையினிமித்தமும் நடுங்கிக்கொண்டிருந்தார்கள்; எஸ்றா அவர்கள் பாவத்தை அறிக்கையிட்டு அந்நிய ஸ்திரீகளைவிட்டுப் பிரிந்துபோகச் சொன்னான். காரியத்தை விசாரிக்கும்படி தலைவர்கள் நியமிக்கப்பட்டார்கள்; அந்நிய ஸ்திரீகளை மணந்தவர்களின் பேர்கள் பட்டியலிடப்பட்டுள்ளன.",

    // Matthew...
    "Matthew 1": "இயேசு கிறிஸ்துவின் வம்சவரலாறு: ஆபிரகாம் முதல் தாவீது வரை, தாவீது முதல் பாபிலோன் சிறையிருப்பு வரை, அங்கிருந்து கிறிஸ்து வரை தலைமுறைகள் விவரிக்கப்பட்டுள்ளன. கன்னி மரியாள் பரிசுத்த ஆவியினால் கர்ப்பவதியானார்; கர்த்தருடைய தூதன் யோசேப்பிற்கு சொப்பனத்தில் தோன்றி, அவருக்கு 'இயேசு' என்று பேரிடக் கட்டளையிட்டார்.",
    "Matthew 2": "கிழக்கிலிருந்து சாஸ்திரிகள் யூதருக்கு ராஜாவாகப் பிறந்தவரைத் தேடி எருசலேமுக்கு வந்தனர். ஏரோது ராஜா குழந்தையைக் கொல்ல வகைதேடியதால், யோசேப்பு குழந்தையையும் தாயையும் அழைத்துக் கொண்டு எகிப்திற்குத் தப்பியோடினார். ஏரோது மரித்தபின், அவர்கள் திரும்பி வந்து நாசரேத்திலே குடியேறினார்கள்.",
    "Matthew 3": "யோவான் ஸ்நானகன் யூதேயாவின் வனாந்தரத்தில் 'மனந்திரும்புங்கள், பரலோக ராஜ்யம் சமீபித்திருக்கிறது' என்று பிரசங்கித்தார். இயேசு யோவானிடத்தில் திருமுழுக்கு பெற்றபோது, வானம் திறக்கப்பட்டு, 'இவர் என்னுடைய நேச குமாரன், இவரில் பிரியமாயிருக்கிறேன்' என்று பிதாவின் சத்தம் வானத்திலிருந்து உண்டானது.",
    "Matthew 4": "இயேசு பரிசுத்த ஆவியினால் வனாந்தரத்திற்குக் கொண்டு செல்லப்பட்டு, நாற்பது நாள் உபவாசமிருந்தார்; அங்கு பிசாசினால் மூன்று முறை சோதிக்கப்பட்டு வெற்றி பெற்றார். பின்னர் அவர் கலிலேயாவில் பிரசங்கிக்கத் தொடங்கி, பேதுரு, அந்திரேயா, யாக்கோபு மற்றும் யோவானைத் தம்மைப் பின்பற்றும்படி அழைத்தார்.",
    "Matthew 5": "இயேசு மலையின் மேல் ஏறிப் பிரசங்கித்தார் (மலைப்பிரசங்கம்). இதில் ஆவிக்குரிய ஏழைகள் முதலானோருக்குரிய 'அஷ்டபாக்கியங்கள்' விவரிக்கப்பட்டுள்ளன. விசுவாசிகள் உலகத்திற்கு உப்பாயும் வெளிச்சமாயும் இருக்கிறார்கள் என்றும், நியாயப்பிரமாணத்தை நிறைவேற்றவே தாம் வந்ததாகவும் அவர் போதித்தார்.",
    "Matthew 6": "மனுஷர் காணும்படி தர்மம் செய்ய வேண்டாம் என்றும், அந்தரங்கத்தில் பார்க்கிற பிதாவுக்கு முன்பாக ஜெபிக்கும்படியும் இயேசு கற்பித்தார். 'பரலோகத்திலிருக்கிற எங்கள் பிதாவே' எனத் தொடங்கும் ஜெபத்தைக் கற்றுக்கொடுத்தார். 'முதலாவது தேவனுடைய ராஜ்யத்தையும் அவருடைய நீதியையும் தேடுங்கள்' என்று கவலைகளுக்குத் தீர்வுகூறினார்.",
    "Matthew 7": "மற்றவர்களைத் தீர்க்காதிருங்கள், அப்பொழுது நீங்களும் தீர்க்கப்படமாட்டீர்கள் என்று எச்சரித்தார். 'கேளுங்கள் கொடுக்கப்படும், தேடுங்கள் கண்டடைவீர்கள்' என்ற வாக்குத்தத்தத்தை அளித்தார். குறுகிய வாசல் வழியே நுழையவும், கன்மலையின் மேல் வீட்டைக்கட்டும் புத்தியுள்ள மனுஷனைப் போல வாழவும் அறிவுறுத்தினார்.",
    "Matthew 8": "இயேசு ஒரு குஷ்டரோகியைத் தொட்டுக் குணமாக்கினார் மற்றும் நூற்றுக்கு அதிபதியின் விசுவாசத்தைப் பாராட்டி அவன் வேலைக்காரனைச் சுகப்படுத்தினார். அவர் படகில் சென்றபோது எழுந்த பெரிய புயலை அதட்டி அமர்த்தினார். கதரேனர் தேசத்தில் பிசாசு பிடித்திருந்த இருவரை விடுவித்து, பிசாசுகளைப் பன்றிக்கூட்டத்திற்குள் அனுப்பினார்.",
    "Matthew 9": "திமிர்வாதக்காரனுக்குப் பாவமன்னிப்பு வழங்கி அவனைக் குணமாக்கினார். சுங்கச்சாவடியில் இருந்த மத்தேயுவை அழைத்து, பாவிகளோடும் சுங்கக்காரரோடும் போஜனம் பண்ணினார். இரத்தப்போக்குள்ள ஸ்திரீயைக் குணமாக்கியதோடு, மரித்துப்போன ஒரு அதிகாரியின் மகளை உயிரோடு எழுப்பினார்.",
    "Matthew 10": "இயேசு தமது பன்னிரண்டு சீடர்களுக்கும் அசுத்த ஆவிகளைத் துரத்தவும் வியாதியஸ்தர்களைக் குணமாக்கவும் அதிகாரம் கொடுத்து அனுப்பினார். 'ஆடுகளை ஓநாய்களுக்குள்ளே அனுப்புகிறது போல உங்களை அனுப்புகிறேன்' என்று கூறி, உபத்திரவங்கள் வரும்போது சோர்ந்து போகாமல் சாட்சிகளாக இருக்கும்படி திடப்படுத்தினார்.",
    "Matthew 11": "சிறையிலிருந்த யோவான் ஸ்நானகன் தன் சீடர்களை அனுப்பி 'வரப்போகிறவர் நீர்தானா?' என்று கேட்டார்; இயேசு தம் கிரியைகளைச் சான்றாகக் காட்டினார். 'வருத்தப்பட்டுப் பாரஞ்சுமக்கிறவர்களே, நீங்கள் எல்லாரும் என்னிடத்தில் வாருங்கள்; நான் உங்களுக்கு இளைப்பாறுதல் தருவேன்' என்று மனதுருகி அழைத்தார்.",
    "Matthew 12": "ஓய்வுநாளில் சீடர்கள் கதிர் கொய்தபோது, இயேசு தாமே 'ஓய்வுநாளுக்கு ஆண்டவர்' என்று அறிவித்தார். காய்ந்த கையையுடைய ஒருவனைக் குணமாக்கினார். 'ஒரு ராஜ்யம் தனக்குத்தானே விரோதமாகப் பிரிந்திருந்தால் அது நிலைநிற்காது' என்று கூறி, பிசாசின் வல்லமையால் தாம் கிரியை செய்யவில்லை என்பதை விளக்கினார்.",
    "Matthew 13": "இயேசு கடலோரத்தில் அமர்ந்து உவமைகளால் பேசினார்: விதைக்கிறவன் உவமை, கோதுமையும் களைகளும், கடுகு விதை, புளித்த மாவு, நிலத்தில் மறைந்திருந்த புதையல், நல்ல முத்து மற்றும் வலை உவமை. பரலோக ராஜ்யத்தின் இரகசியங்களை விவரித்து, சொந்த ஊரான நாசரேத்தில் மக்கள் அவரை விசுவாசிக்காததைக் கண்டார்.",
    "Matthew 14": "ஏரோது ராஜா யோவான் ஸ்நானகனைச் சிறையிலடைத்துச் சிரச்சேதம் செய்தான். இயேசு ஐந்து அப்பங்களையும் இரண்டு மீன்களையும் கொண்டு ஐயாயிரம் பேருக்கு (ஸ்திரீகள், பிள்ளைகள் தவிர) உணவளித்தார். சீடர்கள் படகில் தத்தளித்தபோது, இயேசு கடலின் மேல் நடந்து வந்து அவர்களைக் காப்பாற்றினார்.",
    "Matthew 15": "பரிசேயர்களின் பாரம்பரியங்களைக் கண்டித்த இயேசு, மனுஷனுடைய வாய்க்குள்ளே போகிறது அவனைத் தீட்டுப்படுத்தாது, இதயத்திலிருந்து புறப்படுகிறவையே தீட்டுப்படுத்தும் என்றார். கானானிய ஸ்திரீயின் விசுவாசத்தைப் பாராட்டி அவள் மகளைக் குணமாக்கினார் மற்றும் நாலாயிரம் பேருக்கு உணவளித்தார்.",
    "Matthew 16": "பரிசேயர் மற்றும் சதுசேயர்களின் புளித்த மாவைக் குறித்து எச்சரித்தார். பேதுரு இயேசுவை 'நீர் ஜீவனுள்ள தேவனுடைய குமாரனாகிய கிறிஸ்து' என்று அறிக்கை செய்தார். இயேசு சபையைக் கட்டுவதைப் பற்றியும், தான் எருசலேமில் பாடுபட்டு மரித்து உயிர்த்தெழுவதைப் பற்றியும் முதன்முதலாகப் பேசினார்.",
    "Matthew 17": "இயேசு பேதுரு, யாக்கோபு, யோவானை ஒரு உயர்ந்த மலைக்கு அழைத்துச் சென்றார்; அங்கு அவர் மறுரூபமானார், மோசேயும் எலியாவும் அவரோடு பேசினார்கள். மலையிலிருந்து இறங்கியபின், விசுவாசக் குறைவினால் சீடர்களால் குணமாக்க முடியாத பிசாசு பிடித்த சிறுவனை இயேசு குணமாக்கினார்.",
    "Matthew 18": "பரலோக ராஜ்யத்தில் பெரியவன் யார் என்ற கேள்விக்கு, குழந்தையைப் போல் மாற வேண்டும் என்று பதிலளித்தார். காணாமல் போன ஆட்டின் உவமையைக் கூறி ஒரு ஆத்துமாவின் மதிப்பை விளக்கினார். மேலும், பிறர் செய்யும் தப்பிதங்களை மனப்பூர்வமாக மன்னிக்க வேண்டும் என்பதை 'மன்னிக்காத ஊழியக்காரன்' உவமையால் போதித்தார்.",
    "Matthew 19": "திருமண பந்தத்தின் பரிசுத்தத்தையும் விவாகரத்து குறித்த தேவனுடைய திட்டத்தையும் விளக்கினார். ஒரு செல்வந்த வாலிபன் நித்திய ஜீவனைப் பெற என்ன செய்ய வேண்டும் என்று கேட்டபோது, 'உனக்குள்ளவைகளை விற்றுத் தரித்திரருக்குக் கொடு' என்றார். ஐசுவரியவான் பரலோக ராஜ்யத்தில் நுழைவது கடினம் என்று கற்பித்தார்.",
    "Matthew 20": "திராட்சைத் தோட்டத்து வேலையாட்களின் உவமை மூலம் தேவனுடைய கிருபை அனைவருக்கும் சமம் என்று விளக்கினார். செபதேயுவின் குமாரர்களுடைய தாய் தன் மகன்களுக்கு முதன்மையான இடத்தைக் கேட்டபோது, 'பெரியவனாக இருக்க விரும்புகிறவன் ஊழியக்காரனாக இருக்கக்கடவன்' என்று தாழ்மையைப் போதித்தார்.",
    "Matthew 21": "இயேசு ஒரு கழுதைக் குட்டியின் மேல் ஏறி எருசலேமுக்குள் நுழைந்தார்; மக்கள் 'ஓசன்னா' என்று ஆர்ப்பரித்தனர். ஆலயத்தில் விற்கிறவர்களையும் வாங்குகிறவர்களையும் துரத்திவிட்டு, அதை 'ஜெபவீடு' என்று நிலைநாட்டினார். சபிக்கப்பட்ட அத்திமரம் காய்ந்து போனது மற்றும் இரண்டு குமாரர்களின் உவமையைக் கூறினார்.",
    "Matthew 22": "கல்யாண விருந்து உவமையின் மூலம் அழைக்கப்படுபவர்கள் பலர், தெரிந்துகொள்ளப்படுபவர்கள் சிலரே என்றார். 'ராயனுடையதை ராயனுக்கும், தேவனுடையதை தேவனுக்கும் செலுத்துங்கள்' என்று தந்திரமான கேள்விக்குப் பதிலளித்தார். 'உன் தேவனாகிய கர்த்தரிடத்தில் அன்புகூருவாயாக' என்பதே பிரதான கற்பனை என்றார்.",
    "Matthew 23": "பரிசேயர்கள் மற்றும் வேதபாரகர்களின் மாய்மாலமான செயல்களை இயேசு மிகக் கடுமையாகக் கண்டித்தார். அவர்கள் புறம்பே வெள்ளையடிக்கப்பட்ட கல்லறைகளைப் போல இருக்கிறார்கள் என்று கூறி, ஏழு முறை 'ஐயோ' என்று சாபமிட்டு எச்சரித்தார். எருசலேமுக்காக அவர் கண்ணீர் விட்டுப் புலம்பினார்.",
    "Matthew 24": "எருசலேம் ஆலயத்தின் அழிவையும், உலகத்தின் முடிவையும் குறித்துச் சீடர்கள் கேட்டனர். யுத்தங்கள், பஞ்சங்கள், பூகம்பங்கள் மற்றும் கள்ளத் தீர்க்கதரிசிகள் தோன்றுவார்கள் என்று இயேசு முன்னறிவித்தார். அந்த நாள் எப்போது வரும் என்று பிதா ஒருவருக்கு மட்டுமே தெரியும் என்பதால் விழித்திருக்கும்படி எச்சரித்தார்.",
    "Matthew 25": "ஆயத்தமாக இருப்பதைக் குறிக்க 'பத்து கன்னிகைகள்' உவமையையும், பொறுப்புணர்வைக் குறிக்க 'தாலந்துகள்' உவமையையும் கூறினார். இறுதியில் மனுஷகுமாரன் வரும்போது, ஜனங்களைச் செம்மறியாடுகள் மற்றும் வெள்ளாடுகளாகப் பிரித்து, அவர்கள் செய்த கிரியைகளின்படி நியாயந்தீர்ப்பார் என்று விளக்கினார்.",
    "Matthew 26": "இயேசுவின் மேல் தைலம் பூசப்பட்டது; யூதாஸ் முப்பது வெள்ளிக்காசுக்காக அவரைக் காட்டிக்கொடுக்க உடன்பட்டான். கடைசி விருந்தின்போது இராப்போஜனத்தை ஏற்படுத்தினார். கெத்செமனே தோட்டத்தில் அவர் பாரத்தோடு ஜெபித்தார்; பின்னர் யூதாஸால் முத்தமிட்டுக் காட்டிக்கொடுக்கப்பட்டு, பிரதான ஆசாரியனிடம் கொண்டு செல்லப்பட்டார்.",
    "Matthew 27": "பிலாத்துவின் முன்னிலையில் இயேசு விசாரிக்கப்பட்டார்; ஜனங்கள் பரபாஸை விடுவித்து இயேசுவைச் சிலுவையில் அறையக் கோரினர். இயேசு கேலி செய்யப்பட்டு, கொல்கொதாவிற்குச் சுமந்து செல்லப்பட்டுச் சிலுவையில் அறையப்பட்டு மரித்தார். அரிமத்தியா ஊர் யோசேப்பு அவருடைய சரீரத்தைக் கல்லறையில் வைத்தார்.",
    "Matthew 28": "வாரத்தின் முதல் நாள் விடியற்காலையில் மகதலேனா மரியாளும் மற்ற மரியாளும் கல்லறைக்கு வந்தபோது, இயேசு உயிர்த்தெழுந்ததை ஒரு தூதன் அறிவித்தார். உயிர்த்தெழுந்த இயேசு அவர்களுக்குக் காட்சியளித்தார். பின்னர் சீடர்களைச் சந்தித்து, 'சகல ஜாதிகளையும் சீடராக்கி, பிதா குமாரன் பரிசுத்த ஆவியின் நாமத்திலே திருமுழுக்குக் கொடுங்கள்' என்று மகா கட்டளையிட்டார்.",

    "Mark 1": "இயேசுவின் ஊழியத்தின் ஆரம்பம்: யோவான் ஸ்நானகன் வனாந்தரத்தில் திருமுழுக்குக் கொடுத்தார். இயேசு திருமுழுக்கு பெற்று, வனாந்தரத்தில் சோதிக்கப்பட்ட பின், கலிலேயாவில் பிரசங்கிக்கத் தொடங்கினார். அவர் சீமோன், அந்திரேயா, யாக்கோபு, யோவானை அழைத்து, அசுத்த ஆவிகளைத் துரத்தி, பலரைக் குணமாக்கினார்.",
    "Mark 2": "இயேசு திமிர்வாதக்காரனைக் குணமாக்கி, அவனுடைய பாவங்களை மன்னித்தார்; இது பரிசேயரிடையே விவாதத்தை உண்டாக்கியது. அவர் சுங்கக்காரனாகிய லேவியை அழைத்து, பாவிகளுடன் போஜனம் பண்ணினார். 'ஓய்வுநாள் மனுஷனுக்காக உண்டாக்கப்பட்டது' என்று அவர் போதித்தார்.",
    "Mark 3": "ஓய்வுநாளில் கைசூம்பின மனுஷனைக் குணமாக்கியதால் பரிசேயர் அவருக்கு விரோதமாக ஆலோசனை செய்தனர். இயேசு பன்னிரண்டு அப்போஸ்தலர்களைத் தெரிந்து கொண்டு அவர்களுக்கு அதிகாரம் அளித்தார். தம்மை எதிர்க்கிறவர்களுக்கு விரோதமாக 'பரிசுத்த ஆவிக்கு விரோதமான தூஷணம்' குறித்து எச்சரித்தார்.",
    "Mark 4": "இயேசு கடலோரத்தில் படகிலிருந்து உவமைகளைப் போதித்தார்: விதைக்கிறவன் உவமை, தானியத்தின் வளர்ச்சி மற்றும் கடுகு விதை உவமை. அன்று மாலை படகில் செல்லும்போது எழுந்த பெரிய காற்றையும் கடலையும் நோக்கி: 'இரையாதே, அடங்கு' என்று அதட்டி அமைதிப்படுத்தினார்.",
    "Mark 5": "கெதரேனர் தேசத்தில் 'லெகியோன்' என்னும் பிசாசு பிடித்தவனை விடுவித்தார். வழியில் பன்னிரண்டு வருஷமாய் இரத்தப்போக்குள்ள ஸ்திரீயைக் குணமாக்கினார். பின்னர், மரித்துப்போன யவீருவின் மகளை நோக்கி 'தலீத்தாகும்' (சிறுபெண்ணே எழுந்திரு) என்று கூறி உயிரோடு எழுப்பினார்.",
    "Mark 6": "சொந்த ஊரான நாசரேத்தில் மக்கள் அவரை விசுவாசிக்கவில்லை. ஏரோது ராஜா யோவான் ஸ்நானகனைச் சிரச்சேதம் செய்தான். இயேசு ஐந்து அப்பங்களைக் கொண்டு ஐயாயிரம் பேருக்கு உணவளித்தார் மற்றும் கடல் மேல் நடந்து வந்து சீடர்களைத் திடப்படுத்தினார்.",
    "Mark 7": "பாரம்பரியங்களைக் கடைப்பிடிக்கும் பரிசேயர்களை மாயக்காரர் என்று இயேசு கடிந்துகொண்டார். மனுஷனுக்கு உள்ளே போகிறது அவனைத் தீட்டுப்படுத்தாது, இதயத்திலிருந்து புறப்படுகிறவைகளே தீட்டுப்படுத்தும் என்றார். செரோபெனிக்கியா தேசத்து ஸ்திரீயின் மகளையும், ஒரு செவிடனையும் குணமாக்கினார்.",
    "Mark 8": "இயேசு நாலாயிரம் பேருக்கு அற்புதமாக உணவளித்தார். பரிசேயரின் புளித்த மாவைக் குறித்து எச்சரித்தார். பெத்சாயிதாவில் ஒரு குருடனுக்குப் பார்வை அளித்தார். பேதுரு அவரை 'கிறிஸ்து' என்று அறிக்கை செய்தபோது, இயேசு முதன்முறையாகத் தமது மரணத்தைப் பற்றி முன்னறிவித்தார்.",
    "Mark 9": "மறுரூப மலையில் இயேசுவின் மகிமை வெளிப்பட்டது; மோசே, எலியா அவரோடு பேசினர். மலையிலிருந்து இறங்கியதும் பிசாசு பிடித்த ஒரு சிறுவனைக் குணமாக்கினார். 'எல்லாருக்கும் ஊழியக்காரனாய் இருக்கிறவனே பெரியவன்' என்று சீடர்களுக்குத் தாழ்மையைப் போதித்தார்.",
    "Mark 10": "விவாகரத்து மற்றும் சிறுபிள்ளைகளிடத்தில் அன்பு காட்டுவது குறித்துப் போதித்தார். ஐசுவரியவான் ஒருவன் நித்திய ஜீவனைப் பற்றி கேட்டபோது, தன் சொத்துக்களை விற்க இயலாமல் வருத்தத்தோடு போனான். எரிகோவிற்குப் போகும் வழியில் குருடனான பர்திமேயுவுக்குப் பார்வை அளித்தார்.",
    "Mark 11": "இயேசு கழுதைக்குட்டியின் மேல் ஏறி எருசலேமுக்குள் வெற்றியோடு நுழைந்தார்; மக்கள் துணிகளைப் பரப்பி வரவேற்றனர். அவர் தேவாலயத்தைச் சுத்திகரித்து, வியாபாரிகளைத் துரத்தினார். விசுவாசத்தோடு ஜெபிப்பதன் வல்லமையைக் குறித்துச் சீடர்களுக்கு விளக்கினார்.",
    "Mark 12": "கொடிய திராட்சைத் தோட்டக்காரர்களின் உவமையைக் கூறினார். 'ராயனுடையதை ராயனுக்கும் தேவனுடையதை தேவனுக்கும் செலுத்துங்கள்' என்றார். ஒரு ஏழை விதவை போட்ட இரண்டு காசுகளே மற்ற எல்லாரையும் விட அதிகமானது என்று அவளுடைய காணிக்கையைப் பாராட்டினார்.",
    "Mark 13": "எருசலேம் ஆலயத்தின் அழிவு மற்றும் கடைசி காலத்தின் அடையாளங்களைப் பற்றி இயேசு விளக்கினார். வஞ்சிக்கப்படாமல் விழித்திருக்கும்படி எச்சரித்தார். 'வானமும் பூமியும் ஒழிந்துபோம், என் வார்த்தைகளோ ஒழிந்துபோவதில்லை' என்று உறுதிபடக் கூறினார்.",
    "Mark 14": "மரியாள் இயேசுவின் மேல் நளத தைலத்தைப் பூசினாள்; யூதாஸ் அவரைக் காட்டிக்கொடுக்க உடன்பட்டான். கடைசி விருந்தின்போது இராப்போஜனத்தை ஏற்படுத்தினார். கெத்செமனே தோட்டத்தில் இயேசு ஜெபித்தபின் பிடிபட்டார்; பேதுரு அவரை மூன்று முறை மறுதலித்தார்.",
    "Mark 15": "பிலாத்துவின் விசாரணக்குப் பின், போர்ச்சேவகர்கள் இயேசுவை வதைத்து பரியாசம் செய்தனர். அவர் கொல்கொதாவிற்குக் கொண்டு செல்லப்பட்டுச் சிலுவையில் அறையப்பட்டார். மதிய வேளையில் எங்கும் இருள் உண்டானது; இயேசு மகா சத்தமிட்டு உயிர்விட்டார். பின்னர் அவர் கல்லறையில் வைக்கப்பட்டார்.",
    "Mark 16": "வாரத்தின் முதல் நாள் காலையில் ஸ்திரீகள் கல்லறைக்கு வந்தபோது, இயேசு உயிர்த்தெழுந்ததை ஒரு தூதன் அறிவித்தார். உயிர்த்தெழுந்த கர்த்தர் சீடர்களுக்குக் காட்சி தந்து: 'உலகமெங்கும் போய், சர்வ சிருஷ்டிக்கும் நற்செய்தியைப் பிரசங்கியுங்கள்' என்று கட்டளையிட்டுப் பரலோகத்திற்கு எடுத்துக்கொள்ளப்பட்டார்.",

    "Luke 1": "இயேசுவின் பிறப்பு முன்னறிவிப்பு: சகரியாவுக்கு யோவான் ஸ்நானகனின் பிறப்பும், மரியாளுக்கு இயேசுவின் பிறப்பும் தேவதூதனால் அறிவிக்கப்பட்டது. எலிசபெத்தைச் சந்தித்த மரியாள் கர்த்தரை மகிமைப்படுத்திப் பாடினார். யோவான் பிறந்தார்.",
    "Luke 2": "இயேசுவின் பிறப்பு: பெத்லகேமில் ஒரு முன்னணையில் இயேசு பிறந்தார்; தேவதூதர்கள் மேய்ப்பர்களுக்கு நற்செய்தி அறிவித்தனர். எருசலேம் தேவாலயத்தில் சிமியோனும் அன்னாளும் குழந்தையாகிய இயேசுவைக் கண்டு தீர்க்கதரிசனம் கூறினர்.",
    "Luke 3": "யோவான் ஸ்நானகனின் ஊழியம்: யோவான் மனந்திரும்புதலுக்கு ஏதுவான ஞானஸ்நானத்தைப் பிரசங்கித்தார். இயேசு யோவானிடம் திருமுழுக்கு பெற்றபோது, பரிசுத்த ஆவி புறாவைப் போல் அவர்மேல் இறங்கினார். இயேசுவின் வம்சவரலாறு இங்கு விவரிக்கப்பட்டுள்ளது.",
    "Luke 4": "சோதனையும் ஊழியமும்: இயேசு வனாந்தரத்தில் பிசாசினால் சோதிக்கப்பட்டு வெற்றி பெற்றார். நாசரேத் ஜெப ஆலயத்தில் ஏசாயா தீர்க்கதரிசனத்தை வாசித்துத் தம் ஊழியத்தை அறிவித்தார். கப்பர்நகூமில் அசுத்த ஆவிகளைத் துரத்திக் குணமாக்கினார்.",
    "Luke 5": "சீடர்களின் அழைப்பு: பேதுருவின் படகில் இருந்து போதித்தபின், அற்புதமாக மீன்பிடிக்கச் செய்து அவர்களை அழைத்தார். குஷ்டரோகியையும் திமிர்வாதக்காரனையும் குணமாக்கினார். லேவி (மத்தேயு) என்னும் சுங்கக்காரனைத் தம்மைப் பின்பற்றும்படி அழைத்தார்.",
    "Luke 6": "ஓய்வுநாளும் உபதேசமும்: ஓய்வுநாளின் ஆண்டவர் தாமே என்று விளக்கினார். ஒரு மலையில் ஏறி ஜெபித்தபின் பன்னிரண்டு அப்போஸ்தலர்களைத் தெரிந்து கொண்டார். சமவெளியில் நின்று ஆசீர்வாதங்களையும் எச்சரிக்கைகளையும் (சமவெளிப் பிரசங்கம்) போதித்தார்.",
    "Luke 7": "நூற்றுக்கு அதிபதியின் விசுவாசம்: இயேசு நூற்றுக்கு அதிபதியின் வேலைக்காரனைக் குணமாக்கினார். நாயீன் ஊர் விதவையின் மகனை உயிர் எழுப்பினார். ஒரு பாவியான ஸ்திரீ இயேசுவின் பாதங்களில் கண்ணீர் விட்டு தைலம் பூசி மன்னிப்புப் பெற்றாள்.",
    "Luke 8": "உவமைகளும் அற்புதங்களும்: விதைக்கிறவன் உவமையை விளக்கினார். இயேசு கடலின் புயலை அமர்த்தினார்; லெகியோன் பிசாசுகளைத் துரத்தினார். யவீருவின் மகளை உயிரோடு எழுப்பினார் மற்றும் இரத்தப்போக்குள்ள ஸ்திரீயைக் குணமாக்கினார்.",
    "Luke 9": "அதிகாரமும் மறுரூபமும்: பன்னிரண்டு சீடர்களை ஊழியம் செய்ய அனுப்பினார். ஐயாயிரம் பேருக்கு உணவளித்தார். மறுரூப மலையில் மோசே மற்றும் எலியாவோடு உரையாடினார். தம்மைப் பின்பற்ற விரும்புகிறவன் தன் சிலுவையைச் சுமக்க வேண்டும் என்றார்.",
    "Luke 10": "எழுபது பேர் அனுப்புதல்: எழுபது சீடர்களை ஊழியம் செய்ய அனுப்பினார். 'நல்ல சமாரியன்' உவமையின் மூலம் அயலானிடத்தில் அன்புகூரப் போதித்தார். மார்த்தாள் மற்றும் மரியாள் வீட்டிற்குச் சென்றார்; மரியாள் 'நல்ல பங்கைத்' தெரிந்துகொண்டாள் என்றார்.",
    "Luke 11": "ஜெபமும் எச்சரிக்கையும்: சீடர்களுக்குப் 'பரலோக பிதாவே' ஜெபத்தைக் கற்றுக்கொடுத்தார். பிசாசுகளைத் துரத்துவதைக் குறித்துப் பேசினார். பரிசேயர்களின் மாய்மாலத்தைக் கண்டித்து அவர்களுக்கு 'ஐயோ' என்று எச்சரித்தார்.",
    "Luke 12": "மாய்மாலத்திற்கு எச்சரிக்கை: பரிசேயரின் புளித்த மாவாகிய மாய்மாலத்தைக் குறித்து எச்சரித்தார். 'அறிவில்லாத ஐசுவரியவான்' உவமையைக் கூறி, உலகப் பொருட்களுக்காகக் கவலைப்படாமல் தேவனுடைய ராஜ்யத்தைத் தேடும்படி அறிவுறுத்தினார்.",
    "Luke 13": "மனந்திரும்புதலும் ராஜ்யமும்: மனந்திரும்புங்கள், இல்லாவிட்டால் அழிவீர்கள் என்று எச்சரித்தார். கனி தராத அத்திமர உவமையைக் கூறினார். ஓய்வுநாளில் கூனியாயிருந்த ஸ்திரீயைக் குணமாக்கினார். குறுகிய வாசல் வழியே நுழையப் போதித்தார்.",
    "Luke 14": "தாழ்மையும் விருந்தும்: விருந்துகளில் முதன்மையான இடங்களைத் தேடாதீர்கள் என்று தாழ்மையைப் போதித்தார். 'பெரிய விருந்து' உவமையைக் கூறினார். இயேசுவைப் பின்பற்றுவதற்கு ஆகும் செலவைக் கணக்கிட்டு, எல்லாவற்றையும் வெறுக்கத் தயாராக இருக்கச் சொன்னார்.",
    "Luke 15": "காணாமல் போனவைகள்: வரி வசூலிப்பவர்களோடும் பாவிகளோடும் இயேசு உணவு உண்டபோது, காணாமல் போன ஆடு, காணாமல் போன காசு மற்றும் 'கெட்ட குமாரன்' (மகன்) உவமைகள் மூலம் தேவனுடைய மன்னிப்பை விளக்கினார்.",
    "Luke 16": "பொருளாசைக்கு எச்சரிக்கை: 'நீதியற்ற உக்கிராணக்காரன்' உவமையைக் கூறி, உலக ஐசுவரியத்தைக் கையாளும் விதம் பற்றிப் போதித்தார். ஐசுவரியவான் மற்றும் லாசருவின் கதையின் மூலம் மரணத்திற்குப் பின் நடக்கும் நியாயத்தீர்ப்பை விவரித்தார்.",
    "Luke 17": "விசுவாசமும் நன்றியும்: மற்றவர்களுக்கு இடறல் உண்டாக்காதீர்கள் என்றும், விசுவாசத்தில் வளரவும் போதித்தார். பத்து குஷ்டரோகிகளைக் குணமாக்கினார்; அவர்களில் ஒரு சமாரியன் மட்டுமே திரும்பி வந்து நன்றி செலுத்தினான். மனுஷகுமாரன் வரும் நாளைப் பற்றிப் பேசினார்.",
    "Luke 18": "ஜெபமும் விசுவாசமும்: சோர்ந்து போகாமல் ஜெபிப்பதைக் குறித்து 'அநீதியுள்ள நியாயாதிபதி' உவமையைக் கூறினார். பரிசேயன் மற்றும் சுங்கக்காரன் ஜெபத்தின் மூலம் தாழ்மையை விளக்கினார். சிறுபிள்ளைகளை ஆசீர்வதித்தார்; ஒரு குருடனுக்குப் பார்வை அளித்தார்.",
    "Luke 19": "சகேயுவும் எருசலேம் வருகையும்: குள்ளமான சகேயுவின் வீட்டிற்குச் சென்று அவனுக்கு இரட்சிப்பை அளித்தார். 'பத்து ராத்தல்' உவமையைக் கூறினார். கழுதைக் குட்டியின் மேல் ஏறி எருசலேமுக்குள் நுழைந்தார்; எருசலேம் அழியப்போவதை எண்ணி அழுதார்.",
    "Luke 20": "அதிகாரமும் தந்திரமும்: இயேசுவின் அதிகாரத்தைப் பற்றி ஆசாரியர்கள் கேள்வி எழுப்பினர். ராயனுக்கு வரி செலுத்துவது குறித்து ஞானமாகப் பதிலளித்தார். மரித்தோர் உயிர்த்தெழுவதைக் குறித்துச் சதுசேயர்களுடன் விவாதித்தார்.",
    "Luke 21": "எதிர்கால அடையாளங்கள்: ஏழை விதவையின் சிறு காணிக்கையைப் பாராட்டினார். எருசலேம் ஆலயத்தின் அழிவு, உபத்திரவங்கள் மற்றும் மனுஷகுமாரனின் இரண்டாம் வருகையின் அடையாளங்களை முன்னறிவித்தார். விழித்திருந்து ஜெபிக்கக் கட்டளையிட்டார்.",
    "Luke 22": "காட்டிக்கொடுத்தலும் பாடுகளும்: யூதாஸ் இயேசுவைக் காட்டிக்கொடுக்க உடன்பட்டான். இயேசு கடைசி விருந்தை உண்டு இராப்போஜனத்தை ஏற்படுத்தினார். கெத்செமனே தோட்டத்தில் இரத்த வியர்வை சிந்த ஜெபித்தார். பேதுரு அவரை மூன்று முறை மறுதலித்தார்.",
    "Luke 23": "விசாரணையும் சிலுவையும்: இயேசு பிலாத்து மற்றும் ஏரோதினால் விசாரிக்கப்பட்டார். ஜனங்களின் வற்புறுத்தலால் சிலுவையில் அறையப்பட்டார். சிலுவையில் இருந்த ஒரு திருடனை மன்னித்து 'இன்று நீ என்னுடனேகூடப் பரதீசிலிருப்பாய்' என்றார். மரித்தபின் யோசேப்பின் கல்லறையில் வைக்கப்பட்டார்.",
    "Luke 24": "உயிர்த்தெழுதலும் பரமேறுதலும்: இயேசு உயிர்த்தெழுந்தார்; எம்மாவு ஊருக்குச் சென்ற இரு சீடர்களுக்கும், பின்னர் அப்போஸ்தலர்களுக்கும் காட்சியளித்தார். வேதாகமத்தை அவர்களுக்கு விளக்கினார். பின்னர் பெத்தானியாவிலிருந்து பரலோகத்திற்கு எடுத்துக்கொள்ளப்பட்டார்.",

    "John 1": "ஆதியிலே வார்த்தை இருந்தது, அந்த வார்த்தை தேவனிடத்திலிருந்தது, அந்த வார்த்தை தேவனாயிருந்தது. யோவான் ஸ்நானகன் இயேசுவை 'உலகத்தின் பாவத்தைச் சுமந்துதீர்க்கிற தேவ ஆட்டுக்குட்டி' என்று சாட்சி பகர்ந்தார். அந்திரேயா, பேதுரு, பிலிப்பு மற்றும் நாத்தான்வேல் சீடர்களானார்கள்.",
    "John 2": "கானா ஊர் கல்யாணத்தில் இயேசு தண்ணீரைத் திராட்சரசமாக மாற்றித் தமது முதல் அற்புதத்தைச் செய்தார். பின்னர் எருசலேம் தேவாலயத்திற்குச் சென்று, அங்கிருந்த வியாபாரிகளைத் துரத்தி ஆலயத்தைச் சுத்திகரித்தார். 'இந்த ஆலயத்தை இடித்துப்போடுங்கள், மூன்று நாளைக்குள்ளே இதை எழுப்புவேன்' என்றார்.",
    "John 3": "நிக்கொதேமு என்னும் யூத அதிகாரி இரவில் இயேசுவிடம் வந்தபோது, 'ஒருவன் மறுபடியும் பிறவாவிட்டால் தேவனுடைய ராஜ்யத்தைக் காணமாட்டான்' என்று இயேசு போதித்தார். 'தேவன், தம்முடைய ஒரேபேறான குமாரனை விசுவாசிக்கிறவன் எவனோ அவன் கெட்டுப்போகாமல் நித்தியஜீவனை அடையும்படிக்கு, இவ்வளவாய் உலகத்தில் அன்புகூர்ந்தார்' (யோவான் 3:16).",
    "John 4": "சமாரிய ஸ்திரீயுடன் யாக்கோபின் கிணற்றருகே இயேசு பேசினார். தம்மால் கொடுக்கப்படும் 'ஜீவத்தண்ணீர்' ஒருக்காலும் தாகம் உண்டாக்காது என்றார். சமாரியர்கள் பலரும் அவரை விசுவாசித்தனர். பின்னர் அவர் கலிலேயாவில் ஒரு அதிகாரியின் மகனைத் தமது வார்த்தையினால் குணமாக்கினார்.",
    "John 5": "எருசலேமிலுள்ள பெதஸ்தா குளத்தருகே முப்பத்தெட்டு வருஷமாய் வியாதிப்பட்டிருந்த ஒருவனை ஓய்வுநாளில் இயேசு குணமாக்கினார். இதனால் யூதர்கள் அவரைத் துன்புறுத்தத் தொடங்கினர். இயேசு தமக்கும் பிதாவுக்கும் உள்ள நெருங்கிய உறவை அவர்களுக்கு விளக்கினார்.",
    "John 6": "ஐந்து வாற்கோதுமை அப்பங்களையும் இரண்டு மீன்களையும் கொண்டு ஐயாயிரம் பேருக்கு உணவளித்தார். மக்கள் அவரை ராஜாவாக்க முயன்றபோது அவர் விலகிச் சென்றார். பின்னர் கடலின் மேல் நடந்து சீடர்களிடம் வந்தார். 'நானே ஜீவ அப்பம்' என்று போதித்தார்.",
    "John 7": "கூடாரப் பண்டிகைக்காக இயேசு ரகசியமாக எருசலேமுக்குச் சென்று ஆலயத்தில் போதித்தார். மக்கள் அவர் கிறிஸ்துவா என்று தங்களுக்குள் விவாதித்தனர். பண்டிகையின் கடைசி நாளில், 'தாகமாயிருக்கிறவன் என்னிடத்தில் வந்து பானம்பண்ணக்கடவன்' என்று உரக்கக் கூறினார்.",
    "John 8": "விபசாரத்தில் பிடிபட்ட ஒரு ஸ்திரீயைக் கல்லெறியக் கொண்டுவந்தபோது, 'உங்களில் பாவமில்லாதவன் முதலாவது இவள்மேல் கல்லெறியக்கடவன்' என்று கூறி அவளை விடுவித்தார். 'நானே உலகத்திற்கு ஒளியாயிருக்கிறேன்' என்றும், 'சத்தியத்தையும் அறிவீர்கள், சத்தியம் உங்களை விடுதலையாக்கும்' என்றும் போதித்தார்.",
    "John 9": "பிறவிக்குருடன் ஒருவனுக்கு இயேசு பார்வையளித்தார். சீடர்கள் அவனது பாவம் குறித்துக் கேட்டபோது, தேவனுடைய கிரியைகள் அவனிடத்தில் வெளிப்படும்பொருட்டு இப்படி ஆனான் என்றார். அவன் சீலோவாம் குளத்தில் போய்க் கழுவிப் பார்வை பெற்றான்; இது பரிசேயரிடையே பெரிய சர்ச்சையை உண்டாக்கியது.",
    "John 10": "இயேசு தம்மை 'நல்ல மேய்ப்பன்' என்றும், 'ஆடுகளுக்காகத் தன் ஜீவனைக் கொடுக்கிறவன்' என்றும் அறிவித்தார். 'நானும் பிதாவும் ஒன்றாயிருக்கிறோம்' என்று அவர் கூறியபோது, யூதர்கள் அவரைக் கல்லெறியத் துணிந்தனர்.",
    "John 11": "மரித்துப் போன லாசருவை நான்கு நாட்களுக்குப் பிறகு இயேசு கல்லறையிலிருந்து உயிரோடு எழுப்பினார். 'நானே உயிர்த்தெழுதலும் ஜீவனுமாயிருக்கிறேன்' என்று மார்த்தாளிடம் கூறினார். இந்த அற்புதம் ஆசாரியர்களை இயேசுவைக் கொலை செய்யத் தூண்டியது.",
    "John 12": "பெத்தானியாவில் மரியாள் விலையேறப்பெற்ற தைலத்தை இயேசுவின் பாதங்களில் பூசினாள். இயேசு ஒரு கழுதைக் குட்டியின் மேல் ஏறி எருசலேமுக்குள் நுழைந்தார். 'கோதுமை மணியானது நிலத்தில் விழுந்து சாகாவிட்டால் தனித்திருக்கும், செத்ததேயாகில் மிகுந்த பலனைத் தரும்' என்று தமது மரணத்தைக் குறித்துப் பேசினார்.",
    "John 13": "கடைசி விருந்தின்போது இயேசு ஒரு ஊழியக்காரனைப் போலத் தமது சீடர்களின் பாதங்களைக் கழுவித் தாழ்மையை வெளிப்படுத்தினார். யூதாஸ் காட்டிக்கொடுக்கப் புறப்பட்டான். 'நீங்கள் ஒருவரிலொருவர் அன்பாயிருங்கள்' என்ற புதிய கற்பனையைத் தந்தார்.",
    "John 14": "சீடர்களின் கலக்கத்தை நீக்க, 'பிதாவின் வீட்டில் அநேக வாசஸ்தலங்கள் உண்டு' என்று தேற்றினார். 'நானே வழியும் சத்தியமும் ஜீவனுமாயிருக்கிறேன்' என்றார். தமக்குப்பின் 'தேற்றரவாளனாகிய' பரிசுத்த ஆவியானவரை அனுப்புவதாக வாக்குத்தத்தம் செய்தார்.",
    "John 15": "இயேசு தம்மை 'மெய்யான திராட்சைச்செடி' என்றும், சீடர்களை 'கொம்புகள்' என்றும் விவரித்தார். என்னைப் பிரிந்து உங்களால் ஒன்றும் செய்ய முடியாது என்றார். உலகம் தம்மைப் பகைத்தது போலச் சீடர்களையும் பகைக்கும் என்று எச்சரித்தார்.",
    "John 16": "பரிசுத்த ஆவியானவர் வரும்போது அவர் உலகத்தைச் சுட்டிக்காட்டி, பாவத்தைக் குறித்தும் நீதியைக் குறித்தும் நியாயத்தீர்ப்பைக் குறித்தும் கண்டிப்பார் என்றார். உங்கள் துக்கம் சந்தோஷமாக மாறும் என்று கூறி சீடர்களைத் திடப்படுத்தினார்.",
    "John 17": "இயேசு சிலுவைக்குச் செல்லும் முன் பிதாவிடம் மனதுருகி வேண்டிக்கொண்டார் (பிரதான ஆசாரிய ஜெபம்). தமக்காகவும், தம்முடைய சீடர்களுக்காகவும், இனி விசுவாசிக்கப்போகிறவர்களுக்காகவும் அவர்கள் அனைவரும் ஒன்றாயிருக்க வேண்டும் என்று ஜெபித்தார்.",
    "John 18": "கெத்செமனே தோட்டத்தில் யூதாஸ் கூட்டத்தோடு வந்து இயேசுவைக் காட்டிக்கொடுத்தான். இயேசு முதலில் அன்னாவிடமும், பின்னர் காய்பாவிடமும் விசாரணைக்குக் கொண்டு செல்லப்பட்டார். பேதுரு அவரை மூன்று முறை மறுதலித்தார். இறுதியில் பிலாத்துவிடம் ஒப்படைக்கப்பட்டார்.",
    "John 19": "பிலாத்து இயேசுவைச் சாட்டையினால் அடிப்பித்தான்; போர்ச்சேவகர்கள் அவருக்கு முள்முடி சூட்டிப் பரியாசம் செய்தனர். 'இதோ, மனுஷன்' என்று பிலாத்து அவரைக் காண்பித்தான். பின்னர் இயேசு சிலுவையில் அறையப்பட்டு, 'முடிந்தது' என்று கூறி உயிர்நீத்தார். யோசேப்பும் நிக்கொதேமுவும் அவரை அடக்கம் செய்தனர்.",
    "John 20": "வாரத்தின் முதல் நாள் காலையில் இயேசு உயிர்த்தெழுந்தார். மகதலேனா மரியாளுக்கு முதலில் காட்சியளித்தார். பின்னர் சீடர்களுக்குக் காட்சியளித்துத் தமது சமாதானத்தைக் கூறினார். சந்தேகப்பட்ட தோமா அவருடைய காயங்களைத் தொட்டுப் பார்த்து, 'என் ஆண்டவரே, என் தேவனே' என்று அறிக்கை செய்தார்.",
    "John 21": "திபேரியா கடலருகே மீன்பிடித்துக் கொண்டிருந்த சீடர்களுக்கு இயேசு காட்சியளித்தார். அற்புதமாக மீன்பிடிக்கச் செய்தபின் அவர்களோடு போஜனம் பண்ணினார். பேதுருவிடம் 'நீ என்னிடத்தில் அன்பாயிருக்கிறாயா?' என்று மூன்று முறை கேட்டு, 'என் ஆடுகளை மேய்ப்பாயாக' என்று அவரிடம் பொறுப்பை ஒப்படைத்தார்.",

    "Acts 1": "இயேசு பரலோகத்திற்கு எடுத்துக்கொள்ளப்படுதல்: இயேசு நாற்பது நாள் வரை தரிசனமாகி, சீடர்களுக்குப் பரிசுத்த ஆவியின் வாக்குத்தத்தத்தைக் கொடுத்துப் பரமேறினார். சீடர்கள் எருசலேமுக்குத் திரும்பி, மத்தையாவை யூதாஸுக்குப் பதிலாக அப்போஸ்தலனாகத் தெரிந்து கொண்டனர்.",
    "Acts 2": "பெந்தெகொஸ்தே நாள்: பரிசுத்த ஆவியானவர் பலத்த காற்றைப் போலவும் அக்கினி நாவுகளைப் போலவும் சீடர்கள் மேல் இறங்கினார். பேதுரு வல்லமையுடன் பிரசங்கித்தார்; அன்று சுமார் மூவாயிரம் பேர் ஞானஸ்நானம் பெற்று சபையில் சேர்க்கப்பட்டனர்.",
    "Acts 3": "அற்புதமும் பிரசங்கமும்: பேதுருவும் யோவானும் தேவாலயத்தின் 'அலங்கார வாசல்' அருகே அமர்ந்திருந்த சப்பாணியை இயேசுவின் நாமத்தினால் குணமாக்கினர். திரண்டிருந்த ஜனங்களுக்குப் பேதுரு மனந்திரும்புதலைப் பிரசங்கித்தார்.",
    "Acts 4": "எதிர்ப்பும் உறுதியும்: ஆசாரியர்கள் பேதுருவையும் யோவானையும் கைது செய்தனர். 'இயேசுவின் நாமத்தினால் பேசக்கூடாது' என்று எச்சரிக்கப்பட்டபோது, 'நாங்கள் கண்டவைகளையும் கேட்டவைகளையும் பேசாமலிருக்க முடியாது' என்று அவர்கள் தைரியமாகக் கூறினர்.",
    "Acts 5": "அனனியா மற்றும் சப்பீராள்: நிலத்தை விற்றுப் பொய் சொன்ன அனனியாவும் சப்பீராளும் கர்த்தரால் தண்டிக்கப்பட்டு மரித்தனர். அப்போஸ்தலர்கள் பல அற்புதங்களைச் செய்தனர்; அவர்கள் சிறையில் அடைக்கப்பட்டபோது, தேவதூதன் கதவுகளைத் திறந்து விடுவித்தார்.",
    "Acts 6": "ஏழு உதவிக்காரர்கள்: சபையின் தேவைகளைக் கவனிக்க ஸ்தேவான், பிலிப்பு உள்ளிட்ட ஏழு உதவிக்காரர்கள் (Deacons) தெரிந்து கொள்ளப்பட்டனர். விசுவாசமும் வல்லமையும் நிறைந்த ஸ்தேவான் அதிகாரிகளுக்கு முன்பாகக் கொண்டுவரப்பட்டார்.",
    "Acts 7": "ஸ்தேவானின் சாட்சியும் மரணமும்: ஸ்தேவான் இஸ்ரவேல் வரலாற்றை விளக்கி, அவர்கள் தீர்க்கதரிசிகளை எதிர்த்ததைக் கடிந்து பேசினார். இதனால் கோபமடைந்த ஜனங்கள் அவரை எருசலேமுக்கு வெளியே கொண்டுபோய்க் கல்லெறிந்து கொன்றனர். சவுல் இதற்குச் சம்மதித்திருந்தார்.",
    "Acts 8": "சபைக்கு நேரிட்ட உபத்திரவம்: எருசலேமில் பெரும் துன்புறுத்தல் உண்டானதால் சீடர்கள் சிதறிப்போய் சுவிசேஷத்தைப் பிரசங்கித்தனர். பிலிப்பு சமாரியாவிலும், பின்னர் ஒரு எத்தியோப்பிய மந்திரிக்கும் இயேசுவைப் பற்றி அறிவித்து ஞானஸ்நானம் கொடுத்தார்.",
    "Acts 9": "சவுலின் மனமாற்றம்: சீடர்களைத் துன்புறுத்தத் தமஸ்குவிற்குச் சென்ற சவுல், வழியில் இயேசுவின் ஒளியைக் கண்டு மனமாறினார். அனனியா அவருக்குக் கைகளை வைத்தபோது அவர் பார்வை பெற்றார். பேதுரு யப்பா ஊரில் தொற்காள் என்பவளை உயிரோடு எழுப்பினார்.",
    "Acts 10": "கொர்நேலியுவின் மனமாற்றம்: புறஜாதியினனாகிய கொர்நேலியு என்ற நூற்றுக்கு அதிபதிக்கு தேவதூதன் காட்சியளித்தார். பேதுரு தரிசனத்தின் மூலம் புறஜாதியினரும் தேவனுக்கு ஏற்கத்தக்கவர்கள் என்பதை உணர்ந்து, கொர்நேலியுவின் வீட்டிற்குச் சென்று சுவிசேஷத்தைப் பிரசங்கித்தார்.",
    "Acts 11": "புறஜாதியினருக்குக் கதவு திறக்கப்படுதல்: பேதுரு எருசலேம் சபையினருக்குத் தனது தரிசனத்தை விளக்கி, புறஜாதியினரும் பரிசுத்த ஆவியைப் பெற்றதைச் சாட்சி பகர்ந்தார். அந்தியோகியா சபையில் சீடர்கள் முதல்முறையாக 'கிறிஸ்தவர்கள்' என்று அழைக்கப்பட்டனர்.",
    "Acts 12": "யாக்கோபின் மரணமும் பேதுருவின் விடுதலையும்: ஏரோது ராஜா அப்போஸ்தலனாகிய யாக்கோபைக் கொலை செய்தான். பேதுரு சிறையில் அடைக்கப்பட்டார், ஆனால் சபை ஊக்கமாய் ஜெபித்தபோது தூதன் அவரை விடுவித்தார். ஏரோது ராஜா கர்த்தரால் தண்டிக்கப்பட்டு மரித்தான்.",
    "Acts 13": "பவுலின் முதல் ஊழியப் பயணம்: அந்தியோகியா சபை பவுலையும் பர்னபாவையும் ஊழியத்திற்குப் பிரித்து அனுப்பியது. அவர்கள் சீப்புரு தீவுக்கும் பிசிதியா நாட்டிற்கும் சென்று ஜெப ஆலயங்களில் இயேசுவைப் பிரசங்கித்தனர்.",
    "Acts 14": "இக்கோனியா மற்றும் லீஸ்திரா: பவுலும் பர்னபாவும் லீஸ்திராவில் ஒரு சப்பாணியைக் குணமாக்கினர்; மக்கள் அவர்களைத் தேவர்கள் என்று எண்ணிப் பலியிட முயன்றனர். பின்னர் பவுல் கல்லெறியப்பட்டும் உயிர் தப்பி, சபைகளைத் திடப்படுத்தி அந்தியோகியா திரும்பினார்.",
    "Acts 15": "எருசலேம் சங்கம்: புறஜாதியினர் விருத்தசேதனம் செய்ய வேண்டுமா என்ற விவாதம் எழுந்தது. அப்போஸ்தலர்கள் கூடி ஆலோசித்து, விசுவாசத்தினால் மட்டுமே இரட்சிப்பு உண்டு என்றும், சில முக்கியமான விலக்கல்களை மட்டும் கடைப்பிடிக்கவும் கடிதம் எழுதினர்.",
    "Acts 16": "பவுலின் இரண்டாம் பயணம்: பவுல் தீமோத்தேயுவைச் சேர்த்துக்கொண்டார். மக்கெதோனியாவுக்குப் போகும்படி தரிசனம் கண்டு பிலிப்பிக்குச் சென்றார். அங்கு லீதியாள் மனமாறினாள். பவுலும் சீலாவும் சிறையிலடைக்கப்பட்டபோது, நிலஅதிர்ச்சி உண்டாகி சிறைச்சாலை அதிகாரி இரட்சிக்கப்பட்டான்.",
    "Acts 17": "தெசலோனிக்கேயா மற்றும் ஏதென்ஸ்: பவுல் தெசலோனிக்கேயாவிலும் பெரோயாவிலும் போதித்தார். பின்னர் ஏதென்ஸ் நகரில் 'அறியப்படாத தேவன்' என்று எழுதப்பட்டிருந்த பீடத்தைக் குறிப்பிட்டு, மெய்யான தேவனைப் பற்றி அரியோபாகில் பிரசங்கித்தார்.",
    "Acts 18": "கொரிந்துவில் ஊழியம்: பவுல் கொரிந்துவில் அக்கில்லா, பிரிஸ்கில்லாவுடன் தங்கி ஊழியம் செய்தார். பின்னர் எபேசுவிற்குச் சென்றார். அப்பொல்லோ என்னும் திறமையுள்ள பிரசங்கி எபேசுவில் இயேசுவைப் பற்றித் தைரியமாகப் போதித்தார்.",
    "Acts 19": "எபேசுவில் எழுப்புதல்: பவுல் எபேசுவில் இரண்டு வருடம் தங்கிப் போதித்தார்; பல அற்புதங்கள் நடந்தன. தியன்னா தேவியின் சிலைகளைச் செய்த தட்டார்கள் கலகம் செய்தனர், ஏனெனில் பவுலின் போதனையால் அவர்கள் தொழில் பாதிக்கப்பட்டது.",
    "Acts 20": "மக்கெதோனியா மற்றும் துரோவா: பவுல் சீடர்களைத் திடப்படுத்திப் பயணம் செய்தார். துரோவாவில் ஐதீகூ என்னும் வாலிபன் ஜன்னலிலிருந்து விழுந்து மரித்தபோது, பவுல் அவனை உயிரோடு எழுப்பினார். மிலேத்துவில் எபேசு சபை மூப்பர்களுக்கு உருக்கமான விடைபெறும் உரையாற்றினார்.",
    "Acts 21": "எருசலேம் வருகை: பவுல் எருசலேமுக்குச் சென்றால் கட்டப்படுவார் என்று தீர்க்கதரிசிகள் எச்சரித்தும் அவர் சென்றார். தேவாலயத்தில் யூதர்கள் அவரைக் கண்டு கலகம் செய்து, அவரைக் கொலை செய்ய முயன்றனர்; ரோமச் சிப்பாய்கள் அவரைக் கைது செய்தனர்.",
    "Acts 22": "பவுலின் தற்காப்பு உரை: பவுல் யூத ஜனங்களுக்கு முன்பாகத் தனது மனமாற்றத்தைப் பற்றிச் சாட்சி கூறினார். தான் ஒரு ரோமப் பிரஜை என்று அவர் கூறியதால், ரோம அதிகாரிகள் அவரை அடிக்காமல் விசாரிக்க முடிவு செய்தனர்.",
    "Acts 23": "ஆலோசனைச் சங்கம்: பவுல் யூத ஆலோசனைச் சங்கத்தின் முன் நின்று, தான் உயிர்த்தெழுதலைப் பற்றிப் பேசுவதால் விசாரிக்கப்படுவதாகக் கூறினார். அவரைக் கொலை செய்யச் சதி நடந்ததால், ரோம அதிகாரி அவரைப் பாதுகாப்புடன் செசரியா பட்டணத்திற்கு அனுப்பினார்.",
    "Acts 24": "பெலிக்ஸ் முன்னிலையில் விசாரணை: பிரதான ஆசாரியன் பவுலுக்கு விரோதமாகப் பெலிக்ஸ் என்னும் தேசாதிபதியிடம் குற்றம் சாட்டினான். பவுல் தனது நீதியையும் விசுவாசத்தையும் விளக்கினார். பெலிக்ஸ் அவரை இரண்டு வருடம் சிறையிலேயே வைத்திருந்தான்.",
    "Acts 25": "பெஸ்து மற்றும் அகிரிப்பா: பெஸ்து புதிய அதிகாரியாக வந்தபோது, பவுல் 'இராயனிடம் (Emperor) முறையிடுகிறேன்' என்றார். பவுலின் வழக்கை ஆலோசிக்க அகிரிப்பா ராஜா செசரியாவுக்கு வந்தார்.",
    "Acts 26": "அகிரிப்பா ராஜாவுக்கு முன்பாக: பவுல் ராஜாவுக்கு முன்பாகத் தனது இளமைப் பருவம், மனமாற்றம் மற்றும் கிறிஸ்துவின் உயிர்த்தெழுதலைப் பற்றிப் பிரசங்கித்தார். 'நீ என்னை ஒரு கிறிஸ்தவனாக்கச் சம்மதிக்கப்பண்ணுகிறாய்' என்று அகிரிப்பா கூறினார்.",
    "Acts 27": "ரோமாபுரிக்குப் பயணம்: பவுல் கைதியாகக் கப்பலில் ரோமாபுரிக்குக் கொண்டு செல்லப்பட்டார். கடலில் கடும் புயல் வீசி கப்பல் சேதமடைந்தது. ஆனால் பவுல் விசுவாசத்தோடு யாவரையும் தேற்றினார்; அனைவரும் மெலித்தா தீவில் தப்பினர்.",
    "Acts 28": "ரோமாபுரியில் பவுல்: மெலித்தாவில் பவுல் பாம்பினால் கடிக்கப்பட்டும் சாகாமல் பிழைத்தார். பின்னர் ரோமாபுரிக்குச் சென்றார். அங்கு ஒரு வாடகை வீட்டில் தங்கி, இரண்டு வருடம் தடையின்றித் தேவனுடைய ராஜ்யத்தைப் பிரசங்கித்தார்.",

    "Romans 1": "சுவிசேஷத்தின் வல்லமை: பவுல் ரோமாபுரியிலுள்ள விசுவாசிகளைச் சந்திக்க விரும்புவதாகக் கூறினார். 'நீதிமான் விசுவாசத்தினாலே பிழைப்பான்' என்ற சுவிசேஷத்தின் மையக்கருத்தை விளக்கினார். மனுஷர் சத்தியத்தைத் தடுத்து, விக்கிரகாராதனை மற்றும் அசுத்தமான கிரியைகளில் விழுந்ததைக் குறித்துக் கண்டித்தார்.",
    "Romans 2": "தேவனுடைய நீதியுள்ள தீர்ப்பு: மற்றவர்களைத் தீர்க்கிறவன் தன்னையே ஆக்கினைக்குள்ளாக்குகிறான் என்றார். தேவன் பட்சபாதம் இல்லாதவர்; அவர் யூதர்களுக்கும் கிரேக்கர்களுக்கும் அவரவர் கிரியைகளின்படி பலன் அளிப்பார். புறம்பான விருத்தசேதனத்தை விட இருதயத்தின் விருத்தசேதனமே மேலானது என்று விளக்கினார்.",
    "Romans 3": "விசுவாசத்தினால் நீதிமான்: 'நீதிமான் ஒருவனாகிலும் இல்லை' என்று வேதம் கூறுகிறது. நியாயப்பிரமாணத்தின் கிரியைகளினால் ஒருவனும் நீதிமானாக்கப்படுவதில்லை. கிறிஸ்து இயேசுவின் மேல் வைக்கும் விசுவாசத்தினாலே தேவன் தம்முடைய கிருபையினால் இலவசமாக நீதிமான்களாக்குகிறார்.",
    "Romans 4": "ஆபிரகாமின் உதாரணம்: ஆபிரகாம் கிரியைகளினால் அல்ல, விசுவாசத்தினாலேயே நீதிமானாக எண்ணப்பட்டார் என்பதைச் சுட்டிக்காட்டினார். விருத்தசேதனம் பெறுவதற்கு முன்பே அவர் விசுவாசித்ததால், அவர் விசுவாசிகளுக்கெல்லாம் தகப்பனானார்.",
    "Romans 5": "தேவனுடன் சமாதானம்: விசுவாசத்தினாலே நீதிமான்களாக்கப்பட்ட நமக்குத் தேவனுடன் சமாதானம் உண்டு. ஆதாமுக்குள் மரணம் வந்தது போல, கிறிஸ்து ஒருவருக்குள் ஜீவன் பெருகிற்று. நாம் பாவிகளாயிருக்கையில் கிறிஸ்து நமக்காக மரித்ததினால் தேவன் நம்மேல் வைத்த அன்பை வெளிப்படுத்தினார்.",
    "Romans 6": "பாவத்திற்கு மரித்தல்: கிருபை பெருகும்படி நாம் பாவத்திலே நிலைத்திருக்கலாமா? கூடாதே! திருமுழுக்கின் மூலம் நாம் கிறிஸ்துவுடன் மரித்து, புதிய ஜீவனுள்ளவர்களாக எழுந்திருக்கிறோம். பாவம் இனி உங்களை ஆளக்கூடாது, ஏனெனில் நீங்கள் கிருபைக்குக் கீழ்ப்பட்டிருக்கிறீர்கள்.",
    "Romans 7": "நியாயப்பிரமாணமும் பாவமும்: நியாயப்பிரமாணம் பரிசுத்தமானது, ஆனால் அது நம்மிடமுள்ள பாவத்தை வெளிப்படுத்துகிறது. 'நான் செய்ய விரும்புகிற நன்மையைச் செய்யாமல், விரும்பாத தீமையையே செய்கிறேன்' என்ற மனித போராட்டத்தை விவரித்து, கிறிஸ்துவே இதிலிருந்து விடுதலையளிக்கிறார் என்றார்.",
    "Romans 8": "ஆவிக்குரிய ஜீவன்: கிறிஸ்துவுக்குள் இருக்கிறவர்களுக்கு ஆக்கினைத்தீர்ப்பு இல்லை. மாம்சத்தின்படி நடக்காமல் ஆவியின்படி நடக்கிறவர்கள் தேவனுடைய புத்திரர். 'தேவன் நம்முடைய பட்சத்திலிருந்தால், நமக்கு விரோதமாயிருப்பவன் யார்?' என்று கூறி, தேவனுடைய அன்பிலிருந்து நம்மை எதுவும் பிரிக்க முடியாது என்று உறுதிபடக் கூறினார்.",
    "Romans 9": "தேவனுடைய தெரிந்துகொள்ளுதல்: இஸ்ரவேல் ஜனங்களுக்காகப் பவுல் மனவேதனைப்பட்டார். தேவனுடைய இறையாண்மை மற்றும் தெரிந்துகொள்ளுதலைப் பற்றி விளக்கினார். குயவன் மண்ணைக் கையாளுவது போலத் தேவன் சுதந்திரமுள்ளவர் என்றும், புறஜாதிகள் விசுவாசத்தினால் நீதியை அடைந்தார்கள் என்றும் கூறினார்.",
    "Romans 10": "இரட்சிப்பின் வழி: கிறிஸ்துவே நியாயப்பிரமாணத்தின் முடிவாயிருக்கிறார். 'இயேசுவைக் கர்த்தரென்று உன் வாயினாலே அறிக்கை பண்ணி, தேவன் அவரை மரித்தோரிலிருந்து எழுப்பினார் என்று உன் இருதயத்திலே விசுவாசித்தால் இரட்சிக்கப்படுவாய்.' விசுவாசம் கேள்வியினால் வரும், கேள்வி தேவனுடைய வசனத்தினால் வரும்.",
    "Romans 11": "இஸ்ரவேலின் மீட்பு: தேவன் தம்முடைய ஜனங்களைக் கைவிடவில்லை; ஒரு மீதியான பங்கை வைத்துள்ளார். புறஜாதிகள் காட்டு ஒலிவ மரக்கிளைகளைப் போல ஒட்டவைக்கப்பட்டார்கள். இறுதியில் இஸ்ரவேலர் அனைவரும் இரட்சிக்கப்படுவார்கள் என்ற தேவனுடைய ஞானத்தின் ஆழத்தைப் புகழ்ந்து பாடினார்.",
    "Romans 12": "பரிசுத்தமான பலி: உங்கள் சரீரங்களைப் பரிசுத்தமும் தேவனுக்குப் பிரியமுமான ஜீவபலியாக ஒப்புக்கொடுங்கள் என்றார். சபையில் உள்ள வெவ்வேறு வரங்களைப் பற்றி விவரித்து, 'தீமையை நன்மையினாலே வெல்லுங்கள்' என்று சகோதர அன்பைப் போதித்தார்.",
    "Romans 13": "அதிகாரிகளுக்குக் கீழ்ப்படிதல்: மேலான அதிகாரங்களுக்குக் கீழ்ப்படிய வேண்டும், ஏனெனில் அதிகாரங்கள் தேவனால் நியமிக்கப்பட்டவை. அன்பு செலுத்துவதே நியாயப்பிரமாணத்தின் நிறைவேறுதல். காலம் சமீபமாயிருப்பதால், அந்தகாரத்தின் கிரியைகளைக் களைந்துவிட்டு ஒளியின் ஆயுதங்களைத் தரித்துக்கொள்ளச் சொன்னார்.",
    "Romans 14": "இடறல் உண்டாக்காதிருங்கள்: விசுவாசத்தில் பலவீனமானவர்களை ஏற்றுக்கொள்ளுங்கள். உண்ணுதல் மற்றும் நாட்களைக் கடைப்பிடித்தல் போன்ற விஷயங்களில் ஒருவரை ஒருவர் தீர்க்கக்கூடாது. தேவனுடைய ராஜ்யம் புசிப்பும் குடிப்பும் அல்ல, அது நீதியும் சமாதானமும் பரிசுத்த ஆவியினால் உண்டாகும் சந்தோஷமுமே.",
    "Romans 15": "கிறிஸ்துவின் மாதிரி: பலமுள்ளவர்கள் பலவீனருடைய பலவீனங்களைத் தாங்க வேண்டும். கிறிஸ்து புறஜாதிகளுக்காகவும் இரக்கம் காட்டினார். பவுல் தனது ஊழியப் பயணங்களைக் குறித்துப் பேசி, ரோமாபுரி வழியாக எஸ்பானியாவுக்கு (Spain) வர விரும்புவதாகக் குறிப்பிட்டார்.",
    "Romans 16": "வாழ்த்துக்களும் எச்சரிக்கைகளும்: பெபேயாள் முதலான விசுவாசிகளுக்கு வாழ்த்துக்களைத் தெரிவித்தார். பிரிவினைகளை உண்டாக்குகிறவர்களைக் குறித்து எச்சரித்தார். சுவிசேஷத்தின் மூலமாக விசுவாசத்திற்குக் கீழ்ப்படியச் செய்கிற தேவனுக்குப் புகழ்ச்சி பாடி நிருபத்தை முடித்தார்.",

    "I Corinthians 1": "சபையில் பிரிவினைகள்: பவுல் கொரிந்து சபையிலுள்ள பிரிவினைகளைக் கண்டித்தார். மனுஷ ஞானத்தைப் பார்க்கிலும் தேவனுடைய சிலுவையைப்பற்றிய உபதேசமே இரட்சிக்கப்படுகிறவர்களுக்குத் தேவபலனாயிருக்கிறது. தேவன் உலகத்தில் ஞானிகளை வெட்கப்படுத்தப் பைத்தியமானவைகளைத் தெரிந்துகொண்டார்.",
    "I Corinthians 2": "தேவனுடைய ஞானம்: பவுல் தர்க்க ஞானத்தினாலே பேசாமல், ஆவியின் பலத்தினாலே பிரசங்கித்தார். மனுஷனுடைய ஆவியைத் தவிர மனுஷனிலுள்ளவைகளை ஒருவனும் அறியான்; அதுபோலத் தேவனுடைய ஆவியைத் தவிர ஒருவனும் தேவனுடையவைகளை அறியான்.",
    "I Corinthians 3": "தேவனுடைய உடன்வேலையாட்கள்: சபையார் இன்னும் மாம்சத்திற்குரியவர்களாக இருக்கிறார்கள் என்று பவுல் கடிந்துகொண்டார். 'நான் நட்டேன், அப்பொல்லோ நீர் பாய்ச்சினான், தேவனே விளையச்செய்தார்.' நாம் அனைவரும் தேவனுடைய ஆலயமாயிருக்கிறோம்.",
    "I Corinthians 4": "அப்போஸ்தலர்களின் ஊழியப் பொறுப்பு: கிறிஸ்துவின் ஊழியக்காரர் தேவனுடைய இரகசியங்களை மேய்க்கிற உக்கிராணக்காரராய் இருக்க வேண்டும். அப்போஸ்தலர்கள் உலகத்திற்கு வேடிக்கைப் பொருளாகவும், கிறிஸ்துவின் நிமித்தம் பைத்தியக்காரராகவும் எண்ணப்பட்டதை விவரித்தார்.",
    "I Corinthians 5": "சபையில் பரிசுத்தம்: சபைக்குள் இருந்த விபசாரக் குற்றத்தைக் குறித்துப் பவுல் எச்சரித்தார். 'கொஞ்சம் புளித்த மாவு பிசைந்த மாவையெல்லாம் புளிப்பாக்கும்' என்று கூறி, தீயவர்களைச் சபையிலிருந்து நீக்கிப் பரிசுத்தத்தைக் காக்கக் கட்டளையிட்டார்.",
    "I Corinthians 6": "வழக்குகளும் சரீரப் பரிசுத்தமும்: விசுவாசிகள் ஒருவருக்கொருவர் உலக நீதிமன்றங்களுக்குச் செல்வதைக் கண்டித்தார். உங்கள் சரீரம் பரிசுத்த ஆவியானவர் தங்கும் ஆலயமாயிருக்கிறது; அதைத் தேவனுடைய மகிமைக்கென்று பயன்படுத்துங்கள் என்றார்.",
    "I Corinthians 7": "திருமணம் குறித்த போதனை: கணவன் மனைவியின் கடமைகள் மற்றும் விவாகரத்து குறித்துப் பவுல் விளக்கினார். கர்த்தருடைய ஊழியத்தில் முழுமையாக ஈடுபட விரும்புவோருக்குத் தனித்திருப்பது நல்லது என்றும், ஆனால் பாவம் செய்யாதபடித் திருமணம் செய்துகொள்வது சிறந்தது என்றும் கூறினார்.",
    "I Corinthians 8": "விக்கிரகங்களுக்குப் படைக்கப்பட்டவை: அறிவு அகந்தையை உண்டாக்கும், அன்போ பக்திவிருத்தியை உண்டாக்கும். விக்கிரகங்களுக்குப் படைக்கப்பட்டவைகளை உண்பது பாவம் அல்ல என்றாலும், பலவீனமான சகோதரனுக்கு அது இடறலாய் இருந்தால் அதைத் தவிர்க்க வேண்டும்.",
    "I Corinthians 9": "அப்போஸ்தலனின் உரிமைகள்: சுவிசேஷத்தைப் பிரசங்கிக்கிறவர்கள் சுவிசேஷத்தினால் பிழைக்க வேண்டும் என்ற உரிமை இருந்தாலும், பவுல் அதை உபயோகிக்கவில்லை. எல்லாரையும் ஆதாயப்படுத்திக்கொள்ளும்படி எல்லாருக்கும் எல்லாமானார்.",
    "I Corinthians 10": "இஸ்ரவேலரின் எச்சரிக்கை: வனாந்தரத்தில் இஸ்ரவேலர் செய்த பாவங்களை ஒரு எச்சரிக்கையாகக் கொள்ள வேண்டும். 'சோதிக்கப்படுகிற எவனும் தாங்கத்தக்கதாய் தேவன் தப்பித்துக்கொள்ளும் வழியைச் செய்வார்.' விக்கிரகாராதனைக்கு விலகி ஓடுங்கள் என்றார்.",
    "I Corinthians 11": "சபை ஒழுக்கமும் திருவிருந்தும்: ஜெபம் செய்யும்போது ஆண்கள் மற்றும் பெண்களின் ஒழுங்குமுறைகளைப் பற்றிப் பேசினார். கர்த்தருடைய பந்தியில் (திருவிருந்து) தகுதியற்ற முறையில் பங்குபெறக்கூடாது என்றும், தங்களைத் தாங்களே நிதானித்து அறிந்து அதில் பங்குபெற வேண்டும் என்றும் எச்சரித்தார்.",
    "I Corinthians 12": "ஆவிக்குரிய வரங்கள்: பரிசுத்த ஆவியானவர் ஒவ்வொருவருக்கும் வெவ்வேறு வரங்களைக் கொடுக்கிறார். சரீரத்தில் அநேக அவயவங்கள் இருந்தாலும் சரீரம் ஒன்றே என்பது போல, சபையாரும் கிறிஸ்துவின் சரீரமாய் இருக்கிறார்கள்.",
    "I Corinthians 13": "அன்பின் மேன்மை: 'நான் மனுஷர் பாஷைகளையும் தூதர்கள் பாஷைகளையும் பேசினாலும் அன்பு எனக்கிராவிட்டால் சத்தமிடுகிற வெண்கலம்போலிருப்பேன்.' விசுவாசம், நம்பிக்கை, அன்பு இம்மூன்றிலும் அன்பே பெரியது என்று அன்பின் இலக்கணத்தை விவரித்தார்.",
    "I Corinthians 14": "அந்நிய பாஷையும் தீர்க்கதரிசனமும்: சபையில் அந்நிய பாஷையில் பேசுவதை விடத் தீர்க்கதரிசனம் சொல்வதே சபைக்குப் பக்திவிருத்தி உண்டாக்கும். எல்லாக் காரியங்களும் ஒழுக்கமாயும் கிரமமாயும் செய்யப்பட வேண்டும் என்று கட்டளையிட்டார்.",
    "I Corinthians 15": "உயிர்த்தெழுதலின் நிச்சயம்: கிறிஸ்துவின் உயிர்த்தெழுதலே நம் விசுவாசத்தின் அடிப்படை. 'மரணமே உன் கூர் எங்கே? பாதாளமே உன் ஜெயம் எங்கே?' என்று மரணத்தின் மேல் நமக்குக் கிடைத்துள்ள வெற்றியைப் பற்றிப் பறைசாற்றினார்.",
    "I Corinthians 16": "காணிக்கையும் வாழ்த்துக்களும்: எருசலேம் விசுவாசிகளுக்காகக் காணிக்கை சேர்ப்பது குறித்துப் போதித்தார். 'விழித்திருங்கள், விசுவாசத்திலே நிலைத்திருங்கள், புருஷராயிருங்கள், திடன்கொள்ளுங்கள்' என்று ஊக்கப்படுத்தி வாழ்த்துக்களுடன் நிருபத்தை முடித்தார்.",

    "II Corinthians 1": "ஆறுதலின் தேவன்: உபத்திரவங்கள் பெருகினாலும், கிறிஸ்துவின் மூலமாக ஆறுதலும் பெருகுகிறது என்று பவுல் சாட்சி பகர்ந்தார். தேவன் நம்மை மரணத்திலிருந்து விடுவித்தார்; அவர் வாக்குத்தத்தங்கள் எல்லாம் கிறிஸ்துவுக்குள் 'ஆமென்' என்றும் 'உண்டு' என்றும் இருக்கின்றன.",
    "II Corinthians 2": "மன்னிப்பும் வெற்றியும்: தவறு செய்தவர்களைத் தண்டனையோடு நிறுத்திவிடாமல், அவர்கள் அதிக துக்கத்தில் மூழ்காதபடி அன்பினால் தேற்றி மன்னிக்க வேண்டும் என்றார். சுவிசேஷத்தைப் பிரசங்கிக்கிறவர்கள் தேவனுக்கு முன்பாகக் கிறிஸ்துவின் நறுமணமாக இருக்கிறார்கள்.",
    "II Corinthians 3": "புதிய உடன்படிக்கை: விசுவாசிகளே பவுலின் ஊழியத்திற்கு 'கிறிஸ்துவின் நிருபங்களாக' இருக்கிறார்கள். எழுத்து கொல்லுகிறது, ஆவியோ உயிர்ப்பிக்கிறது. கர்த்தருடைய ஆவி எங்கேயோ அங்கே விடுதலையுண்டு என்று புதிய உடன்படிக்கையின் மகிமையை விளக்கினார்.",
    "II Corinthians 4": "மண் பாண்டங்களில் பொக்கிஷம்: இந்த உலகத்தின் தெய்வம் அவிசுவாசிகளின் மனதைக் குருடாக்கியிருக்கிறது. 'மண் பாண்டங்களில் இந்தப் பொக்கிஷத்தைச் சுமக்கிறோம்' என்று கூறி, உபத்திரவங்கள் இருந்தாலும் சோர்ந்து போகாமல் நித்திய மகிமையை நோக்கிக் காத்திருக்கச் சொன்னார்.",
    "II Corinthians 5": "புதிய சிருஷ்டி: ஒருவன் கிறிஸ்துவுக்குள் இருந்தால் அவன் புதிய சிருஷ்டியாய் இருக்கிறான். பழையவைகள் ஒழிந்துபோயின, எல்லாம் புதியவாயின. நாம் தேவனுடன் ஒப்புரவாகும்படி கிறிஸ்து நமக்காகப் பாவமானார்; நாம் அவருக்கு 'கிறிஸ்துவின் ராயபாரிகளாய்' (Ambassadors) இருக்கிறோம்.",
    "II Corinthians 6": "தேவனுடைய ஊழியக்காரர்: கிருபையை வீணாகப் பெறாதபடி எச்சரித்தார். ஊழியத்தில் உபத்திரவங்களையும் நிந்தைகளையும் சகிப்பதைப் பற்றிப் பேசினார். 'அவிசுவாசிகளுடன் பிணைக்கப்படாதிருங்கள்' என்றும், நாம் ஜீவனுள்ள தேவனுடைய ஆலயமாயிருக்கிறோம் என்றும் போதித்தார்.",
    "II Corinthians 7": "பரிசுத்தமும் துக்கமும்: மாம்சத்திலும் ஆவியிலும் உண்டான அசுசி நீங்கத் நம்மைச் சுத்திகரிக்க வேண்டும். தேவனுக்கு ஏற்ற துக்கம் இரட்சிப்புக்கு ஏதுவான மனந்திரும்புதலை உண்டாக்குகிறது; அது ஒருபோதும் வருத்தத்தை உண்டாக்காது என்று விளக்கினார்.",
    "II Corinthians 8": "கொடுப்பதில் தாராளம்: மக்கெதோனியா சபையினர் வறுமையிலும் தாராளமாகக் கொடுத்ததைச் சான்றாகக் காட்டினார். 'நம்முடைய கர்த்தராகிய இயேசு கிறிஸ்து ஐசுவரியமுள்ளவராயிருந்தும், நீங்கள் அவருடைய தரித்திரத்தினாலே ஐசுவரியவான்களாகும்படி உங்களுக்காகத் தரித்திரரானார்.'",
    "II Corinthians 9": "உற்சாகமாய்க் கொடுப்பவன்: 'உற்சாகமாய்க் கொடுக்கிறவனிடத்தில் தேவன் பிரியமாயிருக்கிறார்.' விதைக்கிறவனுக்கு விதையையும் புசிக்கிறதற்கு ஆகாரத்தையும் கொடுக்கிறவர், உங்கள் நீதியின் விளைச்சலை அதிகமாக்குவார் என்று தர்மம் செய்வதின் பலனை விவரித்தார்.",
    "II Corinthians 10": "ஆவிக்குரிய போர்: 'எங்கள் போராயுதங்கள் மாம்சத்திற்குரியவைகளாயிராமல், அரண்களை நிர்மூலமாக்கத் தேவபலன் உள்ளவைகளாயிருக்கின்றன.' வீண் பெருமை பாராட்டாமல், கர்த்தருக்குள்ளேயே மேன்மைபாராட்ட வேண்டும் என்று பவுல் தனது அதிகாரத்தை விளக்கினார்.",
    "II Corinthians 11": "பவுலின் பாடுகளும் ஊழியமும்: கள்ளத் அப்போஸ்தலர்களைக் குறித்து எச்சரித்தார். தாம் கிறிஸ்துவுக்காகப் பட்ட கசையடிகள், கல்லெறிதல், கப்பல் சேதம் மற்றும் பல இன்னல்களைப் பட்டியலிட்டு, பலவீனத்திலேயே மேன்மைபாராட்டுவதாகக் கூறினார்.",
    "II Corinthians 12": "பலவீனத்தில் வல்லமை: பவுல் மூன்றாம் வானம் வரை எடுக்கப்பட்ட தரிசனங்களைப் பற்றிப் பேசினார். தமக்குக் கொடுக்கப்பட்ட 'மாம்சத்திலுள்ள முள்ளை' நீக்க வேண்டினபோது, கர்த்தர்: 'என் கிருபை உனக்குப்போதும், உன் பலவீனத்திலே என் பலம் பூரணமாய் விளங்கும்' என்றார்.",
    "II Corinthians 13": "கடைசி எச்சரிக்கை: 'நீங்கள் விசுவாசத்தில் இருக்கிறீர்களா என்று உங்களை நீங்களே சோதித்து அறியுங்கள்.' கிறிஸ்து உங்களிலே இருக்கிறாரா என்று பாருங்கள். சமாதானத்தோடு இருங்கள், அப்பொழுது அன்பும் சமாதானமுமுள்ள தேவன் உங்களோடிருப்பார் என்று வாழ்த்திக் கடிதத்தை முடித்தார்.",

    "Galatians 1": "சுவிசேஷத்தின் உண்மை: பவுல் அறிவித்த சுவிசேஷம் மனுஷனால் உண்டானதல்ல, அது இயேசு கிறிஸ்துவினால் வெளிப்படுத்தப்பட்டது. வேறொரு சுவிசேஷத்தைப் பிரசங்கிக்கிறவன் சபிக்கப்பட்டவன் என்று பவுல் எச்சரித்தார்.",
    "Galatians 2": "விசுவாசத்தினால் நீதி: மனுஷன் நியாயப்பிரமாணத்தின் கிரியைகளினால் அல்ல, இயேசு கிறிஸ்துவை விசுவாசிப்பதினாலேயே நீதிமானாக்கப்படுகிறான். 'கிறிஸ்துவுடனேகூடச் சிலுவையில் அறையப்பட்டேன்; இனி நான் பிழைத்திருக்கவில்லை, கிறிஸ்துவே என்னில் பிழைத்திருக்கிறார்' என்று பவுல் சாட்சி பகர்ந்தார்.",
    "Galatians 3": "ஆபிரகாமின் ஆசீர்வாதம்: ஆபிரகாம் விசுவாசத்தினாலே நீதிமானானார். நியாயப்பிரமாணம் நம்மைக் கிறிஸ்துவினிடத்தில் வழிநடத்தும் உபாத்தியாயராக இருந்தது. கிறிஸ்துவை விசுவாசிக்கிறவர்கள் அனைவரும் ஆபிரகாமின் சந்ததியாயும் வாக்குத்தத்தத்தின்படி சுதந்தரவாளிகளாயும் இருக்கிறார்கள்.",
    "Galatians 4": "தேவனுடைய புத்திரர்: நாம் அடிமைகளாக இராமல், கிறிஸ்துவினால் சுதந்திரவாக்கப்பட்டுத் தேவனுடைய புத்திரரானோம். பவுல் கலாத்திய விசுவாசிகள் மீண்டும் நியாயப்பிரமாணத்தின் அடிமைத்தனத்திற்குத் திரும்புவதைக் குறித்து வருத்தப்பட்டுப் பேசினார்.",
    "Galatians 5": "ஆவியின் கனிகள்: கிறிஸ்து நமக்குக் கொடுத்த விடுதலையில் நிலைத்திருங்கள். மாம்சத்தின் கிரியைகளுக்கும் ஆவியின் கனிகளுக்கும் உள்ள வித்தியாசத்தை விளக்கினார். 'அன்பு, சந்தோஷம், சமாதானம், நீடியபொறுமை, தயவு, நற்குணம், விசுவாசம், சாந்தம், இச்சையடக்கம்' ஆகிய ஆவியின் கனிகளைத் தாங்குங்கள் என்றார்.",
    "Galatians 6": "நன்மை செய்வதில் சோர்ந்து போகாதிருங்கள்: ஒருவன் பாரத்தை ஒருவன் சுமந்து கிறிஸ்துவின் பிரமாணத்தை நிறைவேற்றுங்கள். 'மனுஷன் எதை விதைக்கிறானோ அதையே அறுப்பான்.' சிலுவையைப் பற்றி மட்டுமே மேன்மைபாராட்டி, எல்லாருக்கும் நன்மை செய்யும்படி அறிவுறுத்தினார்.",

    "Ephesians 1": "கிறிஸ்துவுக்குள் ஆசீர்வாதம்: உலகம் தோன்றுவதற்கு முன்பே தேவன் நம்மைத் கிறிஸ்துவுக்குள் தெரிந்துகொண்டார். அவருடைய இரத்தத்தினாலே நமக்கு பாவமன்னிப்பு உண்டாயிருக்கிறது. விசுவாசிகளுக்குச் சுதந்தரத்தின் அச்சாராமாகப் பரிசுத்த ஆவியானவர் முத்திரையாகக் கொடுக்கப்பட்டார்.",
    "Ephesians 2": "கிருபையினால் இரட்சிப்பு: அக்கிரமங்களினாலும் பாவங்களினாலும் மரித்தவர்களாயிருந்த நம்மைத் தேவன் கிறிஸ்துவுடனேகூட உயிர்ப்பித்தார். 'கிருபையினாலே விசுவாசத்தைக்கொண்டு இரட்சிக்கப்பட்டீர்கள்; இது உங்களால் உண்டானதல்ல, இது தேவனுடைய ஈவு.'",
    "Ephesians 3": "மறைபொருளின் ஊழியம்: புறஜாதிகளும் கிறிஸ்துவுக்குள் உடன் சுதந்தரவாளிகள் என்கிற இரகசியத்தைப் பவுல் விளக்கினார். கிறிஸ்துவினுடைய அன்பின் அகலம், நீளம், ஆழம், உயரம் என்னவென்று விசுவாசிகள் உணர்ந்துகொள்ள வேண்டும் என்று ஜெபித்தார்.",
    "Ephesians 4": "சபையின் ஒருமைப்பாடு: அழைக்கப்பட்ட அழைப்பிற்குப் பாத்திரவான்களாக நடங்கள். சபை பக்திவிருத்தி அடையத் தேவன் அப்போஸ்தலர்களையும், தீர்க்கதரிசிகளையும், சுவிசேஷகர்களையும் கொடுத்தார். பழைய மனுஷனைக் களைந்துவிட்டுப் புதிய மனுஷனைத் தரித்துக்கொள்ளச் சொன்னார்.",
    "Ephesians 5": "ஒளியின் பிள்ளைகள்: தேவனைப் பின்பற்றுகிறவர்களாக நடந்து, அன்பிலே நிலைத்திருங்கள். கணவன் மற்றும் மனைவியின் உறவைக் கிறிஸ்துவுக்கும் சபைக்கும் உள்ள உறவுக்கு ஒப்பிட்டு விளக்கினார். அந்தகாரத்தின் கிரியைகளில் பங்குபெறாமல் ஒளியின் பிள்ளைகளாக நடங்கள் என்றார்.",
    "Ephesians 6": "தேவனுடைய சர்வாயுதவர்க்கம்: பிசாசின் தந்திரங்களை எதிர்க்கத் தேவனுடைய சர்வாயுதவர்க்கத்தைத் தரித்துக்கொள்ளுங்கள். சத்தியம், நீதி, சமாதானம், விசுவாசம், இரட்சிப்பு மற்றும் தேவவசனமாகிய ஆவியின் பட்டயத்தைக் கொண்டு போரிடவும், இடைவிடாமல் ஜெபிக்கவும் கட்டளையிட்டார்.",

    "Philippians 1": "கிறிஸ்துவே ஜீவன்: பவுல் சிறையிலிருந்தபோதும் சுவிசேஷம் பரவுவதற்காகச் சந்தோஷப்பட்டார். 'எனக்குப் பிழைப்பது கிறிஸ்து, சாவது லாபம்' என்று கூறி, கிறிஸ்துவின் நிமித்தம் பாடுபடுவதும் ஒரு சிலாக்கியம் என்று விளக்கினார்.",
    "Philippians 2": "கிறிஸ்துவின் தாழ்மை: கிறிஸ்து தம்மைத்தாமே வெறும்மையாக்கி, அடிமையின் ரூபமெடுத்து, சிலுவையின் மரணபரியந்தமும் கீழ்ப்படிந்திருந்தார். 'உங்களில் இருக்க வேண்டிய சிந்தை கிறிஸ்து இயேசுவிலும் இருந்தது' என்று தாழ்மையைப் போதித்தார்.",
    "Philippians 3": "கிறிஸ்துவை அறியும் அறிவு: பவுல் தனது பாரம்பரியப் பெருமைகளை குப்பையாக எண்ணி, கிறிஸ்துவை ஆதாயப்படுத்திக்கொள்ள விரும்பினார். 'பின்னானவைகளை மறந்து, முன்னானவைகளை நாடி' பரம அழைப்பின் பந்தயப்பொருளுக்காக இலக்கை நோக்கித் தொடர்ந்தார்.",
    "Philippians 4": "கர்த்தருக்குள் சந்தோஷம்: 'கர்த்தருக்குள் எப்பொழுதும் சந்தோஷமாயிருங்கள்.' எதைக் குறித்தும் கவலைப்படாமல், ஜெபத்தினால் உங்கள் விண்ணப்பங்களைத் தேவனுக்குத் தெரியப்படுத்துங்கள். 'என்னைப் பெலப்படுத்துகிற கிறிஸ்துவினாலே எல்லாவற்றையும் செய்ய எனக்குப் பெலனுண்டு.'",

    "Colossians 1": "கிறிஸ்துவின் முதன்மை: கிறிஸ்துவே அதரிசனமான தேவனுடைய தற்சுரூபம்; அவர் எல்லாவற்றிற்கும் முந்தினவர், எல்லாவற்றையும் படைத்தவர். சிலுவையின் இரத்தத்தினாலே தேவன் நம்மைத் தம்மோடு ஒப்புரவாக்கினார் என்ற இரகசியத்தை விவரித்தார்.",
    "Colossians 2": "கிறிஸ்துவுக்குள் பூரணம்: மனுஷருடைய தந்திரமான வார்த்தைகளினாலும் பாரம்பரியங்களினாலும் வஞ்சிக்கப்படாமல் எச்சரிக்கையாயிருங்கள். கிறிஸ்துவுக்குள் தேவத்துவத்தின் பரிபூரணமெல்லாம் வாசமாயிருக்கிறது; நாம் அவருக்குள் பூரணமானவர்கள்.",
    "Colossians 3": "மேலானவைகளைத் தேடுங்கள்: நீங்கள் கிறிஸ்துவுடனேகூட உயிர்த்தெழுந்ததுண்டானால், பூமியிலுள்ளவைகளையல்ல, மேலானவைகளையே நாடுங்கள். கோபம், மூர்க்கம், பொய் போன்ற பழைய மனுஷனைக் களைந்துவிட்டு, உருக்கமான இரக்கத்தையும் அன்பையும் தரித்துக்கொள்ளுங்கள்.",
    "Colossians 4": "ஜெபமும் விவேகமும்: விழித்திருந்து ஜெபத்தில் நிலைத்திருங்கள். புறம்பே இருக்கிறவர்களிடத்தில் ஞானமாய் நடந்து, உங்கள் பேச்சு எப்பொழுதும் கிருபை பொருந்தினதாயும் உப்பால் சாரமேற்றப்பட்டதாயும் இருக்கட்டும் என்று அறிவுறுத்தினார்.",

    "I Thessalonians 1": "மாதிரியான விசுவாசம்: தெசலோனிக்கேய விசுவாசிகள் விக்கிரகங்களை விட்டு தேவனிடத்திற்குத் திரும்பியதையும், அவர்களுடைய விசுவாசத்தின் கிரியையையும் பவுல் பாராட்டி, அவர்கள் எல்லாருக்கும் மாதிரியானார்கள் என்றார்.",
    "I Thessalonians 2": "பவுலின் ஊழியம்: பவுல் ஒரு தாயைப் போலவும் தகப்பனைப் போலவும் அவர்களுக்குப் போதித்ததை நினைவூட்டினார். மனுஷருக்குப் பிரியமாயிராமல், இருதயங்களைச் சோதித்தறிகிற தேவனுக்கே பிரியமாய் நடக்கப் பிரயாசப்பட்டதாகக் கூறினார்.",
    "I Thessalonians 3": "விசுவாசத்தில் உறுதி: உபத்திரவங்கள் மத்தியிலும் அவர்களுடைய விசுவாசம் எப்படியிருக்கிறதென்று அறியத் தீமோத்தேயுவை அனுப்பினார். அவர்கள் விசுவாசத்தில் உறுதியாய் இருக்கிறார்கள் என்ற செய்தியைக் கேட்டுப் பவுல் மிகுந்த ஆறுதலடைந்தார்.",
    "I Thessalonians 4": "பரிசுத்தமும் கர்த்தரின் வருகையும்: தேவனுக்குப் பிரியமாய் நடப்பதிலும் பரிசுத்தத்திலும் வளருங்கள். கர்த்தருடைய வருகையின்போது, கிறிஸ்துவுக்குள் மரித்தவர்கள் முதலாவது உயிர்த்தெழுவார்கள், பின்பு உயிருடனிருப்பவர்கள் அவர்களோடே மேகங்கள்மேல் எடுத்துக்கொள்ளப்படுவார்கள்.",
    "I Thessalonians 5": "விழித்திருங்கள்: கர்த்தருடைய நாள் இரவிலே திருடன் வருகிறவிதமாய் வரும். எனவே தூங்காமல் விழித்திருந்து, விசுவாசம் மற்றும் அன்பென்னும் மார்பக்கவசத்தைத் தரித்துக்கொள்ளுங்கள். 'எப்பொழுதும் சந்தோஷமாயிருங்கள், இடைவிடாமல் ஜெபம் பண்ணுங்கள்.'",

    "II Thessalonians 1": "நீதியுள்ள தீர்ப்பு: விசுவாசிகள் அனுபவிக்கும் உபத்திரவங்களுக்குப் பதிலாக, கர்த்தராகிய இயேசு தமது வல்லமையுள்ள தூதர்களோடு வானத்திலிருந்து வெளிப்படும்போது அவர்களுக்கு இளைப்பாறுதல் கிடைக்கும் என்று தேற்றினார்.",
    "II Thessalonians 2": "கேட்டின் மகன்: கர்த்தருடைய நாள் வருவதற்கு முன்னதாக விசுவாச துரோகம் உண்டாகும் என்றும், 'கேட்டின் மகனாகிய' அந்திக்கிறிஸ்து வெளிப்படுவான் என்றும் விளக்கினார். சத்தியத்தை விசுவாசித்து இரட்சிப்பு அடைய உறுதியாய் நிற்கச் சொன்னார்.",
    "II Thessalonians 3": "ஒழுங்கான நடக்கை: வேலை செய்யாதவன் சாப்பிடவும் கூடாது என்று கட்டளையிட்டார். சோம்பேறிகளாய் இராமல், அமைதலோடு வேலை செய்து தங்கள் சொந்த ஆகாரத்தைப் புசிக்க வேண்டும் என்றும், நன்மை செய்வதில் சோர்ந்து போக வேண்டாம் என்றும் அறிவுறுத்தினார்.",

    "I Timothy 1": "உபதேசத்தின் சுத்தம்: கள்ள உபதேசங்களுக்கு விலகியிருக்கத் தீமோத்தேயுவை எச்சரித்தார். பவுல் தான் 'பாவிகளில் பிரதானி' என்றும், கிறிஸ்து தம்மை ஊழியத்திற்கு ஏற்படுத்திய கிருபையையும் விவரித்தார்.",
    "I Timothy 2": "ஜெபமும் ஒழுக்கமும்: எல்லா மனுஷருக்காகவும், அதிகாரிகளுக்காகவும் விண்ணப்பம் செய்ய வேண்டும். புருஷர்களும் ஸ்திரீகளும் தேவபக்தியுள்ளவர்களாய் சபை ஒழுக்கத்தைக் கடைப்பிடிக்கப் போதித்தார்.",
    "I Timothy 3": "கண்காணி மற்றும் உதவிக்காரர்: சபையின் கண்காணி (Overseer) மற்றும் உதவிக்காரர் (Deacon) ஆகியோருக்கு இருக்க வேண்டிய தகுதிகளை விளக்கினார். 'தேவபக்தியின் இரகசியம்' மகத்தானது என்று போற்றினார்.",
    "I Timothy 4": "நல்ல ஊழியக்காரன்: பிற்காலங்களில் விசுவாச துரோகம் உண்டாகும் என்று எச்சரித்தார். வசனத்திலும், நடக்கையிலும், அன்பிலும் விசுவாசிகளுக்கு மாதிரியாய் இருக்கத் தீமோத்தேயுவைப் பலப்படுத்தினார்.",
    "I Timothy 5": "விதவைகளும் மூப்பர்களும்: சபையிலுள்ள பெரியோர்களையும் சிறியோர்களையும் மரியாதையுடன் நடத்தவும், திக்கற்ற விதவைகளுக்குத் தக்க உதவி செய்யவும் அறிவுறுத்தினார். மூப்பர்களைக் கனம் பண்ணப் போதித்தார்.",
    "I Timothy 6": "திருப்தியுள்ள தேவபக்தி: பண ஆசை எல்லாத் தீமைக்கும் வேராய் இருக்கிறது. நித்திய ஜீவனைப் பற்றிக்கொண்டு, விசுவாசத்தின் நல்ல போராட்டத்தைப் போராடவும், நற்கிரியைகளில் ஐசுவரியவான்களாய் இருக்கவும் கட்டளையிட்டார்.",

    "II Timothy 1": "விசுவாசத்தின் சுவாலை: தீமோத்தேயுவுக்குள் இருக்கும் விசுவாசத்தை எழுப்பி விடப் பவுல் அறிவுறுத்தினார். 'தேவன் நமக்கு பயமுள்ள ஆவியைக் கொடாமல், பலமும் அன்பும் தெளிந்த புத்தியுமுள்ள ஆவியையே கொடுத்தார்' என்று திடப்படுத்தினார்.",
    "II Timothy 2": "கிறிஸ்துவின் நல்ல போர்ச்சேவகன்: கிறிஸ்துவின் நல்ல போர்ச்சேவகனைப் போலப் பாடுகளைச் சகிக்கவும், சத்திய வசனத்தை நிதானமாய்ப் பிரிக்கிற வேலையாளாய் இருக்கவும் பவுல் அறிவுறுத்தினார்.",
    "II Timothy 3": "கடைசிகால உபத்திரவம்: கடைசி நாட்களில் கொடிய காலங்கள் வரும் என்று எச்சரித்தார். 'வேதவாக்கியங்களெல்லாம் தேவ ஆவியினால் அருளப்பட்டிருக்கிறது', அது மனுஷனைத் தேறினவனாக்க வல்லது என்று வேதாகமத்தின் மேன்மையை விளக்கினார்.",
    "II Timothy 4": "ஓட்டத்தை முடித்தல்: 'நல்ல போராட்டத்தைப் போராடினேன், ஓட்டத்தை முடித்தேன், விசுவாசத்தைக் காத்துக்கொண்டேன்.' சீக்கிரத்தில் தீமோத்தேயுவைத் தம்மிடம் வரும்படி அழைத்து, இறுதி வாழ்த்துக்களைக் கூறினார்.",

    "I Peter 1": "நிச்சயமான நம்பிக்கை: இயேசு கிறிஸ்துவின் உயிர்த்தெழுதலினால் நமக்கு உண்டாயிருக்கிற ஜீவனுள்ள நம்பிக்கையைப் பற்றிப் பேதுரு விளக்கினார். நாம் அழியாத வித்துவாகிய தேவ வசனத்தினால் மறுபடியும் பிறந்திருக்கிறோம்; ஆதலால் 'நான் பரிசுத்தர், ஆகையால் நீங்களும் பரிசுத்தராயிருங்கள்' என்று போதித்தார்.",
    "I Peter 2": "ஜீவனுள்ள கற்கள்: விசுவாசிகள் ஆவிக்குரிய மாளிகையாகக் கட்டப்பட்டு வருகிற ஜீவனுள்ள கற்களாய் இருக்கிறார்கள். நீங்கள் அந்தகாரத்தினின்று ஆச்சரியமான ஒளியினிடத்திற்கு வரவழைக்கப்பட்ட 'தெரிந்துகொள்ளப்பட்ட சந்ததியாய்' இருக்கிறீர்கள் என்று விவரித்தார்.",
    "I Peter 3": "குடும்பமும் நல்மனச்சாட்சியும்: மனைவிகளும் கணவன்மார்களும் ஒருவருக்கொருவர் எப்படி நடக்க வேண்டும் என்று அறிவுறுத்தினார். நீதியின் நிமித்தம் பாடுபடுவது பாக்கியம் என்றும், உங்கள் விசுவாசத்தைக் குறித்துக் கேட்பவர்களுக்கு நல்மனச்சாட்சியோடு பதில் சொல்ல ஆயத்தமாயிருக்கவும் சொன்னார்.",
    "I Peter 4": "தேவனுடைய உக்கிராணக்காரர்: மாம்சத்தில் பாடுபடுகிறவன் பாவத்தை விட்டிருக்கிறான். ஒருவருக்கொருவர் அன்பு பாராட்டி, தேவன் அருளும் வரங்களின்படி ஒருவருக்கொருவர் உதவி செய்யுங்கள். கிறிஸ்துவின் பாடுகளில் பங்கடைவதினால் சந்தோஷப்படுங்கள் என்று ஊக்கப்படுத்தினார்.",
    "I Peter 5": "மந்தையை மேய்த்தல்: மூப்பர்கள் தேவனுடைய மந்தையை உற்சாகத்தோடும் மனப்பூர்வமாகவும் மேய்க்க வேண்டும். பிசாசானவன் கெர்ச்சிக்கிற சிங்கம்போல யாரை விழுங்கலாமோ என்று சுற்றித் திரிகிறான், அவனுக்கு விசுவாசத்தில் உறுதியாய் நின்று எதிர்த்து நில்லுங்கள்.",

    "II Peter 1": "தெய்வீக சுபாவம்: விசுவாசத்தோடு நற்குணம், அறிவு, இச்சையடக்கம், பொறுமை, தேவபக்தி, சகோதர சிநேகம், அன்பு ஆகியவைகளைக் கூட்டிக்கொள்ளுங்கள். தீர்க்கதரிசனங்கள் மனுஷனுடைய சித்தத்தினால் உண்டாகாமல், பரிசுத்த ஆவியினால் ஏவப்பட்டுப் பேசப்பட்டது.",
    "II Peter 2": "கள்ளப் போதகர்கள்: சபைக்குள் நுழையும் கள்ளப் போதகர்களைக் குறித்துப் பேதுரு எச்சரித்தார். அவர்கள் அழிவுக்கு ஏதுவான தந்திரமான போதனைகளைக் கொண்டுவருவார்கள். நோவா மற்றும் லோத்துவை விடுவித்த தேவன், அநீதிமான்களை ஆக்கினைக்குள்ளாக வைப்பார்.",
    "II Peter 3": "கர்த்தருடைய நாள்: கர்த்தருடைய நாள் திருடன் வருகிறவிதமாய் வரும்; அன்று வானங்கள் மகா முழக்கத்தோடு ஒழிந்துபோகும். கர்த்தர் தாமதிக்கிறார் என்று எண்ணாமல், எல்லாரும் மனந்திரும்ப வேண்டும் என்று அவர் நீடியபொறுமை உள்ளவராயிருக்கிறார் என்று விளக்கினார்.",

    "I John 1": "ஜீவவார்த்தை: ஆதிமுதல் இருந்த ஜீவவார்த்தையைப் பற்றிச் சாட்சி பகர்ந்தார். தேவன் ஒளியாயிருக்கிறார்; நாம் நம்முடைய பாவங்களை அறிக்கையிட்டால், அவர் நம்முடைய பாவங்களை மன்னித்து நம்மைச் சுத்திகரிக்க உண்மையுள்ளவராயிருக்கிறார்.",
    "I John 2": "கிறிஸ்துவே நம் பரிந்துபேசுபவர்: நாம் பாவம் செய்தால் பிதாவினிடத்தில் இயேசு கிறிஸ்து நமக்காகப் பரிந்துபேசுகிறார். 'உலகத்திலும் உலகத்திலுள்ளவைகளிலும் அன்புகூராதிருங்கள்.' அந்திக்கிறிஸ்துவின் ஆவியைக் குறித்து எச்சரித்து, சத்தியத்தில் நிலைத்திருக்கச் சொன்னார்.",
    "I John 3": "தேவனுடைய பிள்ளைகள்: தேவன் நம்மேல் வைத்த அன்பு எவ்வளவு பெரியது, நாம் தேவனுடைய பிள்ளைகள் என்று அழைக்கப்படுகிறோம். 'சகோதரனிடத்தில் அன்புகூராதவன் மரணத்திலே நிலைத்திருக்கிறான்' என்று கூறி, கிரியையினாலும் உண்மையினாலும் அன்புகூரப் போதித்தார்.",
    "I John 4": "தேவன் அன்பாயிருக்கிறார்: ஆவிகளைச் சோதித்துப் பாருங்கள்; தேவன் அன்பாயிருக்கிறார், அன்பில்லாதவன் தேவனை அறியான். தேவன் தம்முடைய குமாரனை அனுப்பியதினால் அன்பு இன்னதென்று அறிந்திருக்கிறோம்; நாமும் ஒருவரிலொருவர் அன்புகூரக் கடனாளிகளாய் இருக்கிறோம்.",
    "I John 5": "விசுவாசத்தின் ஜெயம்: தேவனுடைய குமாரனை விசுவாசிக்கிறவன் உலகத்தை ஜெயிக்கிறான். நித்திய ஜீவன் குமாரனுக்குள் இருக்கிறது. நாம் எதை வேண்டிக்கொண்டாலும் அவர் நமக்குச் செவிகொடுக்கிறார் என்ற தைரியம் நமக்கு உண்டு.",

    "II John 1": "சத்தியத்திலும் அன்பிலும் நடத்தல்: தெரிந்துகொள்ளப்பட்ட அம்மாளுக்கும் அவளுடைய பிள்ளைகளுக்கும் யோவான் எழுதினார். நாம் ஒருவரிலொருவர் அன்புகூர வேண்டும் என்பதே கட்டளை. கிறிஸ்துவின் உபதேசத்தில் நிலைத்திராதவர்களை ஏற்றுக்கொண்டு அவர்களுக்கு வாழ்த்துச் சொல்ல வேண்டாம் என்று எச்சரித்தார்.",

    "III John 1": "காயுவுக்கு வாழ்த்து: சத்தியத்தின்படி நடக்கிற காயுவைப் பார்த்து யோவான் சந்தோஷப்பட்டார். சபையில் முதன்மையாயிருக்க விரும்பிய தியோத்திரேப்பு என்பவனின் பொல்லாத செயல்களைக் கண்டித்தார். நன்மையானதைப் பின்பற்றுங்கள் என்று அறிவுறுத்தினார்.",

    "Jude 1": "விசுவாசத்திற்காகப் போராடுதல்: விசுவாசத்தைக் கெடுக்கிற கள்ளப் போதகர்களுக்கு எதிராகப் போராடுங்கள். ஏனோக்கின் தீர்க்கதரிசனத்தைக் குறிப்பிட்டு, அநீதிமான்களுக்கு வரும் நியாயத்தீர்ப்பை எச்சரித்தார். கர்த்தருடைய அன்பிலே உங்களைக் காத்துக்கொள்ளுங்கள்.",

    "Revelation 1": "இயேசுவின் வெளிப்படுத்தல்: யோவான் பத்மு தீவில் இருந்தபோது கண்ட தரிசனங்களை எழுதினார். ஏழு பொன் குத்துவிளக்குகளின் மத்தியில் மனுஷகுமாரனைப் போன்றவரைக் கண்டார். 'இருக்கிறவரும் இருந்தவரும் வருகிறவருமாகிய சர்வவல்லமையுள்ள கர்த்தர்' என அவரைப் போற்றினார்.",
    "Revelation 2": "ஏழு சபைகளுக்கு நிருபங்கள் (பகுதி 1): எபேசு, சிமிர்னா, பெர்கமு, தியத்தீரா சபைகளுக்குக் கடிதம் எழுதினார். அன்பில் குறைந்துபோனவர்களையும், விக்கிரக ஆராதனை செய்பவர்களையும் கண்டித்து, ஜெயங்கொள்ளுகிறவர்களுக்கு வாக்குத்தத்தங்களை அளித்தார்.",
    "Revelation 3": "ஏழு சபைகளுக்கு நிருபங்கள் (பகுதி 2): சர்தை, பிலடெல்பியா, லவோதிக்கேயா சபைகளுக்கு எழுதினார். 'இதோ, வாசற்படியிலே நின்று தட்டுகிறேன்' என்று கூறி, வெதுவெதுப்பான நிலையில் இருந்த லவோதிக்கேயா சபையை மனந்திரும்ப அழைத்தார்.",
    "Revelation 4": "பரலோகத் தரிசனம்: பரலோகத்தில் ஒரு சிங்காசனம் வைக்கப்பட்டிருந்தது; அதைச் சுற்றிலும் இருபத்து நான்கு மூப்பர்களும் நான்கு ஜீவன்களும் 'பரிசுத்தர், பரிசுத்தர், பரிசுத்தர்' என்று இரவும் பகலும் ஓயாமல் தேவனைப் போற்றிக் கொண்டிருந்தனர்.",
    "Revelation 5": "ஆட்டுக்குட்டியானவர்: ஏழு முத்திரையிடப்பட்ட புஸ்தகத்தைத் திறக்க எவருக்கும் தகுதியில்லை. ஆனால் அடிக்கப்பட்ட ஆட்டுக்குட்டியானவரே அந்த முத்திரைகளை உடைக்கப் பாத்திரவானாயிருக்கிறார் என்று யோவான் கண்டு மகிழ்ந்தார்.",
    "Revelation 6": "ஆறு முத்திரைகள்: ஆட்டுக்குட்டியானவர் முத்திரைகளை உடைக்கத் தொடங்கினார். வெவ்வேறு நிறமுள்ள குதிரைகளும் அவற்றின்மேல் ஏறியவர்களும் பூமியில் யுத்தம், பஞ்சம் மற்றும் மரணத்தைக் கொண்டுவந்தனர். ஆறாம் முத்திரையில் பூமி அதிர்ச்சியும் பேரழிவும் உண்டானது.",
    "Revelation 7": "முத்திரை போடப்பட்டவர்கள்: இஸ்ரவேல் கோத்திரங்களில் ஒரு இலட்சத்து நாற்பத்து நாலாயிரம் பேர் முத்திரை போடப்பட்டனர். பின்னர் சகல ஜாதிகளிலுமிருந்து வந்த திரளான ஜனங்கள் வெள்ளை அங்கிகளைத் தரித்து தேவனை வணங்குவதைக் கண்டார்.",
    "Revelation 8": "ஏழாம் முத்திரை: ஏழாம் முத்திரை உடைக்கப்பட்டபோது பரலோகத்தில் அரைமணி நேரம் அமைதி நிலவியது. பின்னர் ஏழு தூதர்கள் எக்காளங்களை ஊதத் தொடங்கினர். முதல் நான்கு எக்காளங்களால் நிலம், கடல், ஆறுகள் மற்றும் ஆகாயம் சேதமடைந்தன.",
    "Revelation 9": "ஐந்து மற்றும் ஆறாம் எக்காளங்கள்: ஐந்தாம் எக்காளத்தில் பாதாளத்தின் புகை எழும்பி வெட்டுக்கிளிகள் மனுஷரை வதைத்தன. ஆறாம் எக்காளத்தில் ஐப்பிராத்து நதியருகே இருந்த தூதர்கள் விடுவிக்கப்பட்டு, பெரும்படையினால் திரளான ஜனங்கள் மடிந்தனர்.",
    "Revelation 10": "சிறிய புஸ்தகம்: ஒரு பலமுள்ள தூதன் வானத்திலிருந்து இறங்கி வந்து, யோவானிடம் ஒரு சிறிய புஸ்தகத்தைக் கொடுத்தார். யோவான் அதை வாங்கிப் புசித்தார்; அது வாய்க்குத் தேனைப் போல இனிப்பும், வயிற்றுக்குக் கசப்புமாயிருந்தது.",
    "Revelation 11": "இரண்டு சாட்சிகள்: தேவன் தமக்காக இரண்டு சாட்சிகளை எழுப்பினார்; அவர்கள் தீர்க்கதரிசனம் சொல்லிப் பின்னர் மரித்து உயிர்த்தெழுந்தனர். ஏழாம் எக்காளம் ஊதப்பட்டபோது, 'உலகத்தின் ராஜ்யங்கள் நம்முடைய கர்த்தருக்கும் அவருடைய கிறிஸ்துவுக்கும் உரியவைகளாயின' என்று அறிவிக்கப்பட்டது.",
    "Revelation 12": "ஸ்திரீயும் வலுசர்ப்பமும்: சூரியனைத் தரித்த ஒரு ஸ்திரீயும், அவளுடைய குழந்தையை விழுங்கக் காத்திருந்த சிவப்பு வலுசர்ப்பமும் தரிசனமாயின. பரலோகத்தில் போர் உண்டாகி, வலுசர்ப்பமாகிய பிசாசு பூமிக்குத் தள்ளப்பட்டான்.",
    "Revelation 13": "இரண்டு மிருகங்கள்: சமுத்திரத்திலிருந்து ஒரு மிருகமும் பூமியிலிருந்து ஒரு மிருகமும் எழும்பின. மக்கள் அந்த மிருகத்தின் முத்திரையை (666) தரிக்கக் கட்டாயப்படுத்தப்பட்டனர். அந்த மிருகம் பரிசுத்தவான்களோடு போர் செய்தது.",
    "Revelation 14": "ஆட்டுக்குட்டியின் வெற்றி: ஆட்டுக்குட்டியானவர் சீயோன் மலையில் நிற்பதைக் கண்டார். மூன்று தூதர்கள் உலகிற்கு எச்சரிக்கை விடுத்தனர். பூமியின் அறுவடை காலம் வந்ததென்றும், அநீதிமான்கள் தேவனுடைய கோபாக்கினையாகிய ஆலையிலே தள்ளப்படுவார்கள் என்றும் அறிவிக்கப்பட்டது.",
    "Revelation 15": "கடைசி ஏழு வாதைகள்: தேவனுடைய கோபாக்கினையினால் நிறைந்த ஏழு பொற்கலசங்களை ஏந்திய ஏழு தூதர்கள் வெளிப்பட்டனர். கண்ணாடிக் கடலருகே நின்றவர்கள் மோசேயின் பாட்டையும் ஆட்டுக்குட்டியின் பாட்டையும் பாடினர்.",
    "Revelation 16": "கோபாக்கினைக் கலசங்கள்: தூதர்கள் கலசங்களைப் பூமியின் மேல் ஊற்றினர்; இதனால் கொடிய புண்கள், இரத்தமான கடல் மற்றும் ஆறுகள், கடும் வெப்பம், அந்தகாரம் மற்றும் பூமி அதிர்ச்சி உண்டானது. அர்மகெதோன் என்னும் இடத்தில் யுத்தத்திற்கு ஜனங்கள் கூடினர்.",
    "Revelation 17": "பெரிய விபசாரி: ஏழு கலசங்களை உடைய தூதர்களில் ஒருவன், அநேக தண்ணீர்களின் மேல் வீற்றிருக்கிற பெரிய விபசாரியின் ஆக்கினைத்தீர்ப்பை யோவானுக்குக் காண்பித்தான். அவள் பூமியின் ராஜாக்களுடன் வேசித்தனம்பண்ணி, பரிசுத்தவான்களின் இரத்தத்தைக் குடித்திருந்தாள்.",
    "Revelation 18": "பாபிலோனின் வீழ்ச்சி: 'பாபிலோன் மகா நகரம் விழுந்தது' என்று வானதூதன் முழக்கமிட்டான். அந்த நகரின் செல்வமும் ஆடம்பரமும் ஒரே நாழிகையில் அழிந்துபோனது. பரலோகமும் பரிசுத்தவான்களும் அதன் நியாயத்தீர்ப்பைக் குறித்துச் சந்தோஷப்பட்டனர்.",
    "Revelation 19": "ஆட்டுக்குட்டியின் கல்யாண விருந்து: பரலோகத்தில் 'அல்லேலூயா' என்ற சத்தம் ஒலித்தது. வெள்ளைக் குதிரையின் மேல் ஏறியிருந்த 'தேவனுடைய வார்த்தை' என்ற நாமமுள்ளவர் சேனைகளுடன் வந்து, மிருகத்தையும் கள்ளத் தீர்க்கதரிசியையும் பிடித்தார்.",
    "Revelation 20": "ஆயிரம் வருஷ அரசாட்சி: சாத்தான் ஆயிரம் வருஷம் கட்டி வைக்கப்பட்டுப் பாதாளத்தில் தள்ளப்பட்டான். ஆயிரம் வருஷங்களுக்குப் பின் அவன் விடுவிக்கப்பட்டு மீண்டும் கலகம் செய்தான். பின்னர் வெள்ளைச் சிங்காசனத்தின் முன் மரித்தோர் அனைவரும் நியாயந்தீர்க்கப்பட்டனர்.",
    "Revelation 21": "புதிய வானமும் புதிய பூமியும்: முந்தின வானமும் பூமியும் ஒழிந்துபோயின. புதிய எருசலேம் நகரம் தேவனிடத்திலிருந்து இறங்கி வந்தது. 'இதோ, மனுஷர்களிடத்திலே தேவனுடைய வாசஸ்தலமிருக்கிறது.' அங்கே இனி மரணமும் துக்கமும் இல்லை.",
    "Revelation 22": "ஜீவநதி மற்றும் முடிவு: நகரத்தின் நடுவே பளிங்கைப் போன்ற ஜீவத்தண்ணீருள்ள நதியும் ஜீவவிருட்சமும் இருந்தன. 'இதோ, சீக்கிரமாய் வருகிறேன்' என்று இயேசு வாக்குக் கொடுத்தார். 'கர்த்தராகிய இயேசுவே, வாரும்' என்று யோவான் நிருபத்தை முடித்தார்.",

    // ஓசியா (Hosea) - 14 Chapters
    "Hosea 1": "ஓசியாவின் குடும்பம்: இஸ்ரவேலின் விபசார குணத்தைக் காண்பிக்க, தேவன் ஓசியாவை ஒரு சோரமார்க்கமுள்ள ஸ்திரீயை விவாகம் பண்ணச் சொன்னார். அவர்களுக்குப் பிறந்த பிள்ளைகளின் பெயர்கள் தீர்ப்பை உணர்த்தின.",
    "Hosea 2": "மன்னிப்பும் சமாதானமும்: இஸ்ரவேல் அந்நிய தெய்வங்களைப் பின்பற்றியதை விபசாரத்திற்கு ஒப்பிட்ட தேவன், அவளை வனாந்தரத்திற்கு அழைத்துச் சென்று, மீண்டும் அன்புடன் ஏற்றுக்கொள்வதாக வாக்கு அளித்தார்.",
    "Hosea 3": "திரும்பப் பெறுதல்: ஓசியா தன் மனைவியை விலை கொடுத்துத் திரும்ப வாங்கினார்; இது இஸ்ரவேல் பல நாட்கள் ராஜா இல்லாமல் இருந்து, பின்னாளில் கர்த்தரைத் தேடித் திரும்புவார்கள் என்பதைக் குறித்தது.",
    "Hosea 4": "அறிவில்லாத ஜனங்கள்: தேசத்தில் உண்மை இல்லை, அன்பு இல்லை. 'என் ஜனங்கள் அறிவில்லாமையினால் சங்காரமாகிறார்கள்' என்று தேவன் ஆசாரியர்களையும் ஜனங்களையும் கண்டித்தார்.",
    "Hosea 5": "தண்டனை: 'இஸ்ரவேல் ராஜா இல்லாமல், யூதா தலைவர்களில்லாமல் தண்டிக்கப்படுவார்கள்' என்று தேவன் கூறினார். 'நீங்கள் என்னைத் துன்புறுத்துகிறீர்கள், நான் உங்களைத் துன்புறுத்துவேன்' என்று கூறி, அவர்களைத் தண்டிப்பார் என்று அறிவித்தார்.",
    "Hosea 6": "மனந்திரும்புதலுக்கு அழைப்பு: 'வாருங்கள், கர்த்தரிடத்தில் திரும்புவோம்' என்று தீர்க்கதரிசி அழைத்தார். தேவன் பலியை அல்ல, இரக்கத்தையும், தகனபலிகளைப் பார்க்கிலும் தேவனை அறிகிற அறிவையுமே விரும்புகிறார்.",
    "Hosea 7": "பாவங்களின் விளைவுகள்: 'இஸ்ரவேல் பாவங்களால் சிதறடிக்கப்பட்டு, அவன் பாவங்களை மறைக்க முயற்சிக்கிறான்' என்று தேவன் கூறினார். 'நீங்கள் என்னைத் துன்புறுத்துகிறீர்கள், நான் உங்களைத் துன்புறுத்துவேன்' என்று கூறி, அவர்களைத் தண்டிப்பார் என்று அறிவித்தார்.",
    "Hosea 8": "பாவங்களுக்குத் தீர்ப்பு: 'இஸ்ரவேல் பாவங்களால் சிதறடிக்கப்பட்டு, அவன் பாவங்களை மறைக்க முயற்சிக்கிறான்' என்று தேவன் கூறினார். 'நீங்கள் என்னைத் துன்புறுத்துகிறீர்கள், நான் உங்களைத் துன்புறுத்துவேன்' என்று கூறி, அவர்களைத் தண்டிப்பார் என்று அறிவித்தார்.",
    "Hosea 9": "வெளிநாட்டில் தண்டனை: 'இஸ்ரவேல் பாவங்களால் சிதறடிக்கப்பட்டு, அவன் பாவங்களை மறைக்க முயற்சிக்கிறான்' என்று தேவன் கூறினார். 'நீங்கள் என்னைத் துன்புறுத்துகிறீர்கள், நான் உங்களைத் துன்புறுத்துவேன்' என்று கூறி, அவர்களைத் தண்டிப்பார் என்று அறிவித்தார்.",
    "Hosea 10": "பாவங்களுக்குத் தீர்ப்பு: 'இஸ்ரவேல் பாவங்களால் சிதறடிக்கப்பட்டு, அவன் பாவங்களை மறைக்க முயற்சிக்கிறான்' என்று தேவன் கூறினார். 'நீங்கள் என்னைத் துன்புறுத்துகிறீர்கள், நான் உங்களைத் துன்புறுத்துவேன்' என்று கூறி, அவர்களைத் தண்டிப்பார் என்று அறிவித்தார்.",
    "Hosea 11": "பிதாவின் அன்பு: 'இஸ்ரவேல் சிறுபிள்ளையாயிருந்தபோது அவனை நேசித்தேன்' என்று தேவன் உருக்கமாகப் பேசினார். கோபம் இருந்தாலும், தம் ஜனங்களைக் கைவிடத் தமது இருதயம் இடங்கொடாது என்றார்.",
    "Hosea 12": "யாக்கோபு மற்றும் எஸாவின் கதைகள்: தேவன் யாக்கோபு மற்றும் எஸாவின் கதைகளை எடுத்துக்காட்டாகக் கூறினார். 'நீங்கள் என்னைத் துன்புறுத்துகிறீர்கள், நான் உங்களைத் துன்புறுத்துவேன்' என்று கூறி, அவர்களைத் தண்டிப்பார் என்று அறிவித்தார்.",
    "Hosea 13": "பாவங்களுக்குத் தீர்ப்பு: 'இஸ்ரவேல் பாவங்களால் சிதறடிக்கப்பட்டு, அவன் பாவங்களை மறைக்க முயற்சிக்கிறான்' என்று தேவன் கூறினார். 'நீங்கள் என்னைத் துன்புறுத்துகிறீர்கள், நான் உங்களைத் துன்புறுத்துவேன்' என்று கூறி, அவர்களைத் தண்டிப்பார் என்று அறிவித்தார்.",
    "Hosea 14": "குணமடைதல்: 'இஸ்ரவேலே, உன் தேவனாகிய கர்த்தரிடத்தில் திரும்பு' என்று கூறி, அவர்கள் மனந்திரும்பினால் லீலி புஷ்பத்தைப் போலச் செழிப்பார்கள் என்று ஆசீர்வாதத்துடன் முடித்தார்.",

    // யோவேல் (Joel) - 3 Chapters
    "Joel 1": "வெட்டுக்கிளி வாதை: தேசத்தில் உண்டான பயங்கரமான வெட்டுக்கிளி வாதையையும் பஞ்சத்தையும் விவரித்தார். இது 'கர்த்தருடைய நாள்' சமீபமாயிருக்கிறது என்பதற்கான எச்சரிக்கையாக இருந்தது.",
    "Joel 2": "ஆவி ஊற்றப்படுதல்: 'உங்கள் இருதயங்களைக் கிழித்துக்கொண்டு கர்த்தரிடத்தில் திரும்புங்கள்' என்றார். கடைசி நாட்களில் மாம்சமான யாவர்மேலும் தமது ஆவியை ஊற்றுவதாகத் தேவன் வாக்குத்தத்தம் செய்தார்.",
    "Joel 3": "ஜாதிகளுக்குத் தீர்ப்பு: யோசபாத்தின் பள்ளத்தாக்கில் ஜாதிகள் நியாயந்தீர்க்கப்படுவார்கள். கர்த்தர் சீயோனிலிருந்து கெர்ச்சிப்பார்; யூதா என்றென்றைக்கும் நிலைத்திருக்கும்.",

    // ஆமோஸ் (Amos) - 9 Chapters
    "Amos 1": "சுற்றியுள்ள ஜாதிகளுக்குத் தீர்ப்பு: தமஸ்கு, காசா, தீரு, ஏதோம் மற்றும் அம்மோன் புத்திரருடைய அக்கிரமங்களினிமித்தம் தேவன் அவர்களைத் தண்டிப்பார் என்று ஆமோஸ் அறிவித்தார்.",
    "Amos 2": "இஸ்ரவேலுக்கு தீர்ப்பு: 'இஸ்ரவேல் மக்களே, நீங்களும் தண்டிக்கப்படுவீர்கள்' என்று ஆமோஸ் கூறினார். 'நீங்கள் ஏதோமின் மக்களிடத்தில் தங்கியிருக்கிறீர்கள்; நீங்கள் எகிப்தின் நிலத்தில் தங்கியிருக்கிறீர்கள்' என்று கூறி, அவர்களின் பாவங்களை வெளிப்படுத்தினார்.",
    "Amos 3": "தேவனுடைய வார்த்தை: 'கர்த்தருடைய வார்த்தை ஒரு நரம்பு போலவே என் உள்ளத்தில் உள்ளது' என்று ஆமோஸ் கூறினார். 'நீங்கள் என்னை அழைக்கிறீர்கள், நான் உங்களுக்கு பதிலளிக்கவில்லை என்று நினைக்கிறீர்களா?' என்று கேள்வி எழுப்பினார்.",
    "Amos 4": "பாவங்களுக்குத் தீர்ப்பு: 'நீங்கள் என்னை அழைக்கிறீர்கள், நான் உங்களுக்கு பதிலளிக்கவில்லை என்று நினைக்கிறீர்களா?' என்று ஆமோஸ் கேள்வி எழுப்பினார். 'நீங்கள் என்னைத் துன்புறுத்துகிறீர்கள், நான் உங்களைத் துன்புறுத்துவேன்' என்று கூறி, அவர்களைத் தண்டிப்பார் என்று அறிவித்தார்.",
    "Amos 5": "நீதியின் ஊற்று: 'தீமையை வெறுத்து, நன்மையை நேசியுங்கள்' என்றார். 'நீதி தண்ணீரைப்போலவும், நியாயம் வற்றாத நதியைப்போலவும் புரண்டுவரக்கடவது' என்று சமூக நீதியை வலியுறுத்தினார்.",
    "Amos 6": "அறிவில்லாத மக்களுக்குத் தீர்ப்பு: 'நீங்கள் தங்களுடைய செல்வத்திலும் ஆடம்பரத்திலும் நம்பிக்கை வைக்கிறீர்கள்' என்று ஆமோஸ் கூறினார். 'நீங்கள் தங்களுடைய வீடுகளில் படுக்கையில் படுத்து, தங்களுடைய கல்லறைகளில் உறங்குகிறீர்கள்' என்று கூறி, அவர்களைத் தண்டிப்பார் என்று அறிவித்தார்.",
    "Amos 7": "ஆமோஸின் சொப்பனங்கள்: ஆமோஸ் கர்த்தரிடத்தில் இருந்து இரண்டு சொப்பனங்களைப் பெற்றார்; ஒன்று பஞ்சம் மற்றும் வெட்டுக்கிளி வாதையைப் பற்றியது, மற்றொன்று ஜலப்பிரளயத்தைப் பற்றியது. இரண்டையும் தேவன் நிறுத்தினார்.",
    "Amos 8": "பஞ்சம் மற்றும் வெட்டுக்கிளி வாதை: 'பஞ்சம் வந்துவிட்டது' என்று ஆமோஸ் கூறினார். 'நீங்கள் தானியத்தை அளவில்லாமல் விற்று, வறுமையானவர்களை விற்று, பஞ்சம் வந்துவிட்டது' என்று கூறி, அவர்களைத் தண்டிப்பார் என்று அறிவித்தார்.",
    "Amos 9": "மறுசீரமைப்பு: இஸ்ரவேல் ஜல்லடையால் சலிக்கப்படுவது போலச் சிதறடிக்கப்படும். ஆனால் முடிவில், விழுந்துபோன தாவீதின் கூடாரத்தை மீண்டும் எடுப்பிப்பதாகத் தேவன் வாக்குக் கொடுத்தார்.",

    // ஒபதியா (Obadiah) - 1 Chapter
    "Obadiah 1": "ஏதோமின் அழிவு: தன் சகோதரன் யாக்கோபுக்கு விரோதமாகக் கொடுமை செய்த ஏதோம் தேசம் முற்றிலும் பாழாக்கப்படும். கர்த்தருடைய ராஜ்யமே எங்கும் மேலோங்கும்.",

    // யோனா (Jonah) - 4 Chapters
    "Jonah 1": "கீழ்ப்படியாமை: நினவேக்குப் போக மறுத்துத் தார்சிஷுக்கு ஓடிய யோனாவை ஒரு பெரிய மீன் விழுங்கியது.",
    "Jonah 2": "மீனின் வயிற்றில் ஜெபம்: யோனா மீனின் வயிற்றிலிருந்து கர்த்தரை நோக்கிக் கூப்பிட்டார்; கர்த்தர் மீனை நோக்கிச் சொல்ல, அது அவரைத் தரையில் கக்கியது.",
    "Jonah 3": "நினவேயின் மனமாற்றம்: யோனா நினவேயில் பிரசங்கித்தார்; ராஜா முதல் மிருகங்கள் வரை அனைவரும் சாக்கைத் தரித்து உபவாசித்து மனந்திரும்பியதால் தேவன் அவர்களைத் தப்பவித்தார்.",
    "Jonah 4": "தேவனுடைய இரக்கம்: நினவே தப்பித்ததைக் கண்டு யோனா கோபமடைந்தார். ஒரு ஆமணக்குச் செடியின் மூலம் தேவன் அவருக்குத் தமது இரக்கத்தின் ஆழத்தைப் போதித்தார்.",

    // மீகா (Micah) - 7 Chapters
    "Micah 1": "இஸ்ரவேலின் பாவம்: 'எருசலேமின் பாவம் வெளிப்படையாக உள்ளது; அதில் தீமை செய்யும் யூதா நகரம் இருக்கிறது' என்று மீகா தீர்க்கதரிசனமாகக் கூறினார்.",
    "Micah 2": "பாவிகளுக்குத் தீர்ப்பு: 'பாவிகள் தங்கள் வீட்டை அழிக்க விரும்புகிறார்கள்; அவர்கள் தங்கள் நிலங்களைப் பறிக்க விரும்புகிறார்கள்' என்று கூறி, அவர்களுடைய பாவங்களை வெளிப்படுத்தினார்.",
    "Micah 3": "தீர்க்கதரிசிகளுக்குத் தீர்ப்பு: 'நீங்கள் தீமையை விரும்புகிறீர்கள், நியாயத்தை விரும்பவில்லை; நீங்கள் பொய்க்குரைகளைப் பேசுகிறீர்கள், ظلمத்தை விரும்புகிறீர்கள், நீதியை விரும்பவில்லை' என்று தீர்க்கதரிசிகளையும் அரசர்களையும் கண்டித்தார்.",
    "Micah 4": "சமாதான காலம்: 'கடவுளுடைய மலை எருசலேமில் நிலைத்திருக்கும்; அது அனைத்து தேசங்களையும் மேலோங்கும்' என்று தீர்க்கதரிசனமாகக் கூறினார். 'அவர்கள் தங்கள் வாள்களை உதிரி கருவிகளாக மாற்றுவார்கள்; அவர்கள் போருக்கு கற்றைகளை உருவாக்குவார்கள்' என்று கூறி, சமாதானத்தை முன்னறிவித்தார்.",
    "Micah 5": "மேசியாவின் பிறப்பு: 'எப்பிராத்தா என்னப்பட்ட பெத்லகேமே, உன்னிடத்திலிருந்து இஸ்ரவேலை ஆளப்போகிறவர் புறப்படுவார்' என்று இயேசுவின் பிறப்பிடத்தைத் தீர்க்கதரிசனமாகக் கூறினார்.",
    "Micah 6": "தேவன் விரும்புவது: 'மனுஷனே, நன்மை இன்னதென்று அவர் உனக்குக் காட்டியிருக்கிறார்; நியாயம் செய்து, இரக்கத்தைச் சிநேகித்து, உன் தேவனுக்கு முன்பாக மனத்தாழ்மையாய் நடப்பதேயன்றி வேறென்ன?'",
    "Micah 7": "நீதி மற்றும் இரக்கம்: 'நான் கர்த்தருக்கு காத்திருக்கிறேன்; என் ஆன்மா அவருக்குக் காத்திருக்கிறது' என்று மீகா தன்னம்பிக்கையுடன் கூறினார். 'கர்த்தர் உன்னுடைய பாவங்களை மண்ணில் எரித்து விடுவார்; உன் பாவங்களை கடலுக்கு ஆழமாகக் கொண்டு போகும்' என்று கூறி, தேவனுடைய இரக்கத்தை வெளிப்படுத்தினார்.",

    // நாகூம் (Nahum) - 3 Chapters
    "Nahum 1": "கர்த்தருடைய கோபம்: 'கர்த்தர் கோபத்துடன் இருக்கிறார்; அவர் துன்புறுத்துபவர்களைத் துன்புறுத்துவார்' என்று நாகூம் கூறினார். 'கர்த்தர் நீண்ட பொறுமையுள்ளவர், ஆனால் அவர் கோபமடைந்தால் சக்திவாய்ந்தவர்' என்று கூறி, தேவனுடைய நீதியை வெளிப்படுத்தினார்.",
    "Nahum 2": "நினவேயின் வீழ்ச்சி: நினவேயின் பாதுகாப்பான கோட்டைகள் அழிக்கப்பட்டு, அதன் வீரர்கள் சிதறடிக்கப்பட்டனர். 'நினவேயின் பாவங்கள் வெளிப்படுத்தப்பட்டன; அவர் தன் துன்புறுத்துபவர்களைத் துன்புறுத்துவார்' என்று கூறி, தேவனுடைய நீதியை வெளிப்படுத்தினார்.",
    "Nahum 3": "நினவேயின் வீழ்ச்சி: இரத்தம் சிந்துகிற நகரமாகிய நினவேயின் பாவங்கள் வெளிப்படுத்தப்பட்டு, அது தேற்றவாருமில்லாமல் பாழாய்ப்போகும் என்று அறிவிக்கப்பட்டது.",

    // ஆபகூக் (Habakkuk) - 3 Chapters
    "Habakkuk 1": "துன்புறுத்துபவர்களுக்குத் தீர்ப்பு: ஹபக்கூக் தேவனிடம், 'என் காலத்தில் நீ ஏன் துன்புறுத்துபவர்களை அனுமதிக்கிறாய்?' என்று கேட்கிறார். தேவன் பாபிலோனியர்களை துன்புறுத்துபவர்களாக அனுப்புவதாக பதிலளிக்கிறார்.",
    "Habakkuk 2": "விசுவாசத்தால் பிழைத்தல்: 'நீதிமான் தன் விசுவாசத்தினாலே பிழைப்பான்.' விக்கிரகங்களை வணங்குகிறவர்களுக்கு ஐயோ என்று எச்சரிக்கை விடுக்கப்பட்டது.",
    "Habakkuk 3": "துதிப் பாடல்: ஆபகூக் தேசத்தின் அழிவைக் கண்டு நடுங்கினாலும், 'நான் கர்த்தருக்குள் மகிழ்ச்சியாயிருப்பேன், என் இரட்சிப்பின் தேவனுக்குள் களிகூருவேன்' என்று பாடினார்.",

    // செப்பனியா (Zephaniah) - 3 Chapters
    "Zephaniah 1": "பாவிகளுக்குத் தீர்ப்பு: 'கர்த்தர் தன் கோபத்துடன் வருகிறார்; அவர் துன்புறுத்துபவர்களைத் துன்புறுத்துவார்' என்று செப்பனியா கூறினார். 'கர்த்தர் தன் கோபத்துடன் வருகிறார்; அவர் துன்புறுத்துபவர்களைத் துன்புறுத்துவார்' என்று கூறி, தேவனுடைய நீதியை வெளிப்படுத்தினார்.",
    "Zephaniah 2": "நினவேயின் அழிவு: நினவேயின் பாவங்கள் வெளிப்படுத்தப்பட்டு, அது தேற்றவாருமில்லாமல் பாழாய்ப்போகும் என்று அறிவிக்கப்பட்டது. 'நினவேயின் பாவங்கள் வெளிப்படுத்தப்பட்டன; அவர் தன் துன்புறுத்துபவர்களைத் துன்புறுத்துவார்' என்று கூறி, தேவனுடைய நீதியை வெளிப்படுத்தினார்.",
    "Zephaniah 3": "மீதியான ஜனங்கள்: தேவன் எருசலேமின் பாவத்தைச் சுத்திகரிப்பார். 'உன் தேவனாகிய கர்த்தர் உன் நடுவில் இருக்கிறார்; அவர் உன்மேல் மகிழ்ச்சியாய் மகிழ்ந்து, தமது அன்பினிமித்தம் அமர்ந்திருப்பார்.'",

    // ஆகாய் (Haggai) - 2 Chapters
    "Haggai 1": "ஆலயம் கட்டும் அழைப்பு: 'இந்த காலத்தில் நீங்கள் வீட்டை கட்டுவதற்கு நேரம் இல்லை என்று நினைக்கிறீர்களா?' என்று ஆகாய் கூறி, கர்த்தருடைய ஆலயத்தை மீண்டும் கட்டுமாறு இஸ்ரவேலுக்கு அழைத்தார்.",
    "Haggai 2": "ஆலயத்தின் மகிமை: 'இந்த முந்தின ஆலயத்தின் மகிமையைப் பார்க்கிலும், பிந்தின ஆலயத்தின் மகிமை பெரியதாயிருக்கும்' என்று தேவன் ஜனங்களைத் திடப்படுத்தினார்.",

    // சகரியா (Zechariah) - 14 Chapters
    "Zechariah 1": "கர்த்தருடைய இரக்கம்: 'கர்த்தர் தன் கோபத்துடன் வருகிறார்; அவர் துன்புறுத்துபவர்களைத் துன்புறுத்துவார்' என்று சகரியா கூறினார். 'கர்த்தர் தன் கோபத்துடன் வருகிறார்; அவர் துன்புறுத்துபவர்களைத் துன்புறுத்துவார்' என்று கூறி, தேவனுடைய நீதியை வெளிப்படுத்தினார்.",
    "Zechariah 2": "கர்த்தருடைய பாதுகாப்பு: 'கர்த்தர் உன்னுடன் இருக்கிறார்; அவர் உன்னை விலக்கி விடுவார்' என்று சகரியா கூறினார். 'கர்த்தர் உன்னுடன் இருக்கிறார்; அவர் உன்னை விலக்கி விடுவார்' என்று கூறி, தேவனுடைய பாதுகாப்பை வெளிப்படுத்தினார்.",
    "Zechariah 3": "யோசுவா மற்றும் கர்த்தர்: யோசுவா, இஸ்ரவேலின் மகா ஆசாரியர், கர்த்தருடைய தூதனாக இருந்தார். தேவன் யோசுவாவை சுத்திகரித்து, அவருக்கு புதிய ஆடைகளை வழங்கினார்.",
    "Zechariah 4": "ஆவியின் சக்தி: சகரியா ஒரு எண்ணெய் ஊற்றும் விளக்கை கண்டார்; அது ஆவியின் சக்தியால் எரியும் என்று கூறப்பட்டது. 'மனுஷனின் கைகளால் அல்ல, என் ஆவியினாலே' என்று தேவன் கூறினார்.",
    "Zechariah 5": "கடவுளுடைய நீதியின் வண்டி: சகரியா ஒரு வண்டியை கண்டார்; அது கடவுளுடைய நீதியை உலகம் முழுவதும் பரப்பும் என்று கூறப்பட்டது. 'கடவுளுடைய நீதியின் வண்டி உலகம் முழுவதும் பரப்பப்படும்' என்று தேவன் கூறினார்.",
    "Zechariah 6": "மெல்கிசேதேக்: 'நீங்கள் இந்த மனிதனைக் கண்டு அதனை ஆசீர்வதியுங்கள்; அது என் தூதன்' என்று தேவன் சகரியாவை வழிநடத்தினார். மெல்கிசேதேக் ராஜா மற்றும் ஆசாரியராகவும், தேவனுடைய தூதனாகவும் இருந்தார்.",
    "Zechariah 7": "உண்மையான விருதுகள்: 'நீங்கள் விருதுகளைத் தந்தாலும், நான் அவற்றை ஏற்க மாட்டேன்' என்று தேவன் கூறினார். 'நீங்கள் விருதுகளைத் தந்தாலும், நான் அவற்றை ஏற்க மாட்டேன்; உங்கள் கைகளில் இரக்கம் இருக்க வேண்டும்' என்று கூறி, உண்மையான விருதுகளைக் குறித்தார்.",
    "Zechariah 8": "கர்த்தருடைய மகிழ்ச்சி: 'கர்த்தர் உன்னுடன் இருக்கிறார்; அவர் உன்னுடன் மகிழ்ச்சியாய் மகிழ்ந்து, தமது அன்பினிமித்தம் அமர்ந்திருப்பார்' என்று சகரியா கூறினார். 'கர்த்தர் உன்னுடன் இருக்கிறார்; அவர் உன்னுடன் மகிழ்ச்சியாய் மகிழ்ந்து, தமது அன்பினிமித்தம் அமர்ந்திருப்பார்' என்று கூறி, தேவனுடைய மகிழ்ச்சியை வெளிப்படுத்தினார்.",
    "Zechariah 9": "சாந்தகுணமுள்ள ராஜா: 'சீயோன் குமாரத்தியே, இதோ உன் ராஜா உன்னிடத்தில் வருகிறார்; அவர் நீதியுள்ளவரும் இரட்சிக்கிறவரும் தாழ்மையுள்ளவருமாய், கழுதைக் குட்டியின்மேல் ஏறி வருகிறார்.'",
    "Zechariah 10": "கர்த்தருடைய ஆவியின் சக்தி: 'கர்த்தர் உன்னுடன் இருக்கிறார்; அவர் உன்னுடன் மகிழ்ச்சியாய் மகிழ்ந்து, தமது அன்பினிமித்தம் அமர்ந்திருப்பார்' என்று சகரியா கூறினார். 'கர்த்தர் உன்னுடன் இருக்கிறார்; அவர் உன்னுடன் மகிழ்ச்சியாய் மகிழ்ந்து, தமது அன்பினிமித்தம் அமர்ந்திருப்பார்' என்று கூறி, தேவனுடைய ஆவியின் சக்தியை வெளிப்படுத்தினார்.",
    "zechariah 11": "கர்த்தருடைய மேய்ப்பாளர்: சகரியா ஒரு மேய்ப்பாளராக இருந்தார்; அவர் இரண்டு ஆடுகளை மேய்த்தார். தேவன் அவரை மேய்ப்பாளராக அனுப்பி, இஸ்ரவேலை மேய்க்கச் சொன்னார். ஆனால் மக்கள் அவரை மதிக்கவில்லை; அவர் தன் கைகளில் இரக்கம் வைத்திருந்தாலும், அவர்கள் அவனை விலக்கி விட்டனர்.",
    "Zechariah 12": "கர்த்தருடைய பாதுகாப்பு: 'கர்த்தர் உன்னுடன் இருக்கிறார்; அவர் உன்னுடன் மகிழ்ச்சியாய் மகிழ்ந்து, தமது அன்பினிமித்தம் அமர்ந்திருப்பார்' என்று சகரியா கூறினார். 'கர்த்தர் உன்னுடன் இருக்கிறார்; அவர் உன்னுடன் மகிழ்ச்சியாய் மகிழ்ந்து, தமது அன்பினிமித்தம் அமர்ந்திருப்பார்' என்று கூறி, தேவனுடைய பாதுகாப்பை வெளிப்படுத்தினார்.",
    "Zechariah 13": "பாவிகளுக்குத் தீர்ப்பு: 'கர்த்தர் தன் கோபத்துடன் வருகிறார்; அவர் துன்புறுத்துபவர்களைத் துன்புறுத்துவார்' என்று சகரியா கூறினார். 'கர்த்தர் தன் கோபத்துடன் வருகிறார்; அவர் துன்புறுத்துபவர்களைத் துன்புறுத்துவார்' என்று கூறி, தேவனுடைய நீதியை வெளிப்படுத்தினார்.",
    "Zechariah 14": "கர்த்தர் ஒருவரே ராஜா: கர்த்தர் பூமியின் மீதெல்லாம் ராஜாவாயிருப்பார்; அன்று கர்த்தர் ஒருவரே, அவருடைய நாமமும் ஒன்றே என்று இருக்கும்.",

    // மல்கியா (Malachi) - 4 Chapters
    "Malachi 1": "கடவுளின் அன்பு: 'என் பெயருக்கு விரோதமாகக் கொடுமை செய்த இஸ்ரவேலே, நான் உன்னை நேசித்தேன்' என்று தேவன் கூறினார். 'எனக்கு விரோதமாகக் கொடுமை செய்த லேவியர், நான் உன்னை நேசித்தேன்' என்று கூறி, அவர்களுடைய பாவங்களை வெளிப்படுத்தினார்.",
    "Malachi 2": "கடவுளின் சபை: 'நீங்கள் என்னுடைய சபையை அவமதிக்கிறீர்கள்' என்று தேவன் லேவியர்களை கண்டித்தார். 'நீங்கள் என் சபையை அவமதிக்கிறீர்கள், நீங்கள் என்னுடைய பண்டகசாலையை அவமதிக்கிறீர்கள்' என்று கூறி, அவர்களுடைய பாவங்களை வெளிப்படுத்தினார்.",
    "Malachi 3": "தசமபாகம்: 'என் ஆலயத்தில் ஆகாரமிருக்கும்படித் தசமபாகங்களை எல்லாம் பண்டகசாலையிலே கொண்டுவாருங்கள்.' வானத்தின் பலகணிகளைத் திறந்து உங்களை ஆசீர்வதிப்பேன் என்றார்.",
    "Malachi 4": "நீதியின் சூரியன்: 'என் நாமத்திற்குப் பயந்திருக்கிற உங்கள்மேல் நீதியின் சூரியன் உதிக்கும்; அதின் செட்டைகளின்கீழ் ஆரோக்கியம் இருக்கும்' என்று மேசியாவின் வருகையை முன்னறிவித்தார்.",

    "Daniel 1": "தானியேலும் அவர் நண்பர்களும்: பாபிலோன் ராஜா நேபுகாத்நேச்சார் எருசலேமைப் பிடித்தபோது, தானியேல், அனனியா, மீஷாவேல், அசரியா ஆகியோரை அரண்மனைப் பணிக்காகத் தேர்ந்தெடுத்தார். அவர்கள் ராஜாவின் அசுத்தமான உணவைத் தவிர்த்து, தேவன் தந்த ஞானத்தினால் மற்ற எல்லாரையும் விடப் பத்து மடங்கு சிறந்தவர்களாக விளங்கினர்.",
    "Daniel 2": "நேபுகாத்நேச்சாரின் சொப்பனம்: ராஜா ஒரு பெரிய சிலையைக் கண்டார்; அதன் தலை பொன்னாகவும், மார்பு வெள்ளியாகவும், இடுப்பு வெண்கலமாகவும், கால்கள் இரும்பும் களிமண்ணுமாக இருந்தன. ஒரு கல் சிலையயைத் தகர்த்துப் பெரிய மலையானது. இது உலகப் பேரரசுகளின் வீழ்ச்சியையும், தேவனுடைய நித்திய ராஜ்யத்தின் வருகையையும் குறித்தது.",
    "Daniel 3": "எரியும் அக்கினிச் சூளை: நேபுகாத்நேச்சார் செய்த பொற்சிலையை வணங்க மறுத்த சாத்ராக், மேஷாக், ஆபேத்நேகோ ஆகியோர் எரியும் அக்கினிச் சூளையில் போடப்பட்டனர். தேவன் அவர்களுடன் நாலாவது மனுஷனாக (தேவபுத்திரன்) உலாவினார்; அவர்கள் ஒரு தீங்கும் இன்றி விடுதலையானார்கள்.",
    "Daniel 4": "நேபுகாத்நேச்சாரின் தாழ்மை: ராஜா ஒரு பெரிய விருட்சத்தைக் குறித்த சொப்பனம் கண்டார். அவர் தன் அகந்தையினிமித்தம் புத்தியிழந்தவராக ஏழு காலம் மிருகங்களைப் போல வனாந்தரத்தில் திரிந்தார். பின்பு அவர் தேவனை மகிமைப்படுத்தி, மீண்டும் தன் ராஜ்யத்தைப் பெற்றார்.",
    "Daniel 5": "பெல்ஷாத்சாரின் விருந்து: பெல்ஷாத்சார் ராஜா எருசலேம் ஆலயத்துப் பாத்திரங்களில் மது அருந்திக் கலகம் செய்தபோது, சுவரில் ஒரு கை தோன்றி 'மெனே மெனே தெக்கேல் உப்பார்சின்' என்று எழுதியது. அன்று இரவே பாபிலோன் மேதிய-பெர்சியர்களிடம் வீழ்ந்தது, ராஜா கொல்லப்பட்டார்.",
    "Daniel 6": "சிங்கக் கெபி: தானியேல் இடைவிடாமல் ஜெபித்ததினிமித்தம் சிங்கக் கெபியில் போடப்பட்டார். தேவன் தமது தூதனை அனுப்பி சிங்கங்களின் வாயைக் கட்டிப்போட்டார். அதிகாலையில் ராஜா வந்து தானியேலை உயிரோடு கண்டு சந்தோஷப்பட்டு, அவரை விடுவித்துத் தேவனைப் போற்றினார்.",
    "Daniel 7": "நான்கு மிருகங்களின் தரிசனம்: தானியேல் கடலிலிருந்து எழும்பிய நான்கு பெரிய மிருகங்களைக் கண்டார் (சிங்கம், கரடி, சிறுத்தை, மற்றும் பலத்த மிருகம்). இவை உலக அரசுகளைக் குறித்தன. முடிவில் 'நீண்ட ஆயுசுள்ளவர்' (தேவன்) நியாயந்தீர்த்து, மனுஷகுமாரனிடம் நித்திய ஆளுகையை ஒப்படைப்பதைக் கண்டார்.",
    "Daniel 8": "ஆட்டுக்கடாவும் வெள்ளாட்டுக்கடாவும்: மேதிய-பெர்சியாவைக் குறிக்கும் ஆட்டுக்கடாவையும், கிரேக்கரைக் குறிக்கும் வெள்ளாட்டுக்கடாவையும் தானியேல் கண்டார். இது அலெக்சாண்டர் மற்றும் அவருக்குப்பின் எழும்பும் அந்திக்கிறிஸ்துவின் முன்னோடியான அந்தியோகஸ் எபிபானஸை முன்னறிவித்தது.",
    "Daniel 9": "எழுபது வாரங்கள்: எருசலேமின் பாழ்க்கடிப்பு குறித்துத் தானியேல் மனமுருகி ஜெபித்தார். தூதன் காபிரியேல் தோன்றி, மேசியா வரப்போகும் காலத்தையும், எருசலேமின் எதிர்காலத்தையும் குறித்த 'எழுபது வாரங்கள்' என்ற தீர்க்கதரிசனத்தை வெளிப்படுத்தினார்.",
    "Daniel 10": "பெர்சியாவின் அதிபதி: தானியேல் மூன்று வாரம் துக்கங்கொண்டாடி ஜெபித்தபோது, ஒரு தேவதூதன் தோன்றிப் பரலோகத்தில் நடக்கும் ஆவிக்குரிய போராட்டங்களை விவரித்தார். பெர்சியாவின் அதிபதி என்ற பொல்லாத ஆவியுடன் தூதன் போரிட்டதாகக் கூறினார்.",
    "Daniel 11": "வடதிசை மற்றும் தென்திசை ராஜாக்கள்: பெர்சியா முதல் கிரேக்கம் வரையிலும், பின்னர் வடதிசை மற்றும் தென்திசை ராஜாக்களுக்கு இடையே நடக்கும் நீண்ட காலப் போர்களைக் குறித்த துல்லியமான தீர்க்கதரிசனங்கள் இதில் விவரிக்கப்பட்டுள்ளன.",
    "Daniel 12": "முடிவு காலம்: ஆபத்துக்காலம் வரும் என்றும், ஞானவான்கள் ஆகாயமண்டலத்தின் ஒளியைப் போலப் பிரகாசிப்பார்கள் என்றும் அறிவிக்கப்பட்டது. 'புஸ்தகத்தை முத்திரைபோடு' என்று கூறப்பட்டு, மரித்தோர் உயிர்த்தெழுதலைப் பற்றிய வாக்குத்தத்தத்துடன் தீர்க்கதரிசனம் முடிந்தது.",

    "Joshua 1": "யோசுவாவின் அழைப்பு: மோசேயின் மரணத்திற்குப் பின், கர்த்தர் யோசுவாவை நோக்கி: 'நீ திடன்கொண்டு பலப்படு; இந்த நியாயப்பிரமாண புஸ்தகம் உன் வாயைவிட்டுப் பிரியாதிருக்கக்கடவது' என்று கட்டளையிட்டு, அவனைத் தலைவனாக உறுதிப்படுத்தினார்.",
    "Joshua 2": "ராகாபும் வேவுகாரர்களும்: யோசுவா எரிகோவை வேவுபார்க்க இரண்டு பேரை அனுப்பினார். விபசாரியான ராகாப் அவர்களைத் தன் வீட்டில் மறைத்து வைத்துக் காப்பாற்றினாள்; அதற்கு அடையாளமாக அவள் தன் ஜன்னலில் சிவப்பு நூலைக் கட்டினாள்.",
    "Joshua 3": "யோர்தானைக் கடத்தல்: ஆசாரியர்கள் உடன்படிக்கைப் பெட்டியைச் சுமந்து யோர்தான் நதியில் கால் வைத்தபோது, தண்ணீர் மேடாக நின்றது. இஸ்ரவேல் ஜனங்கள் அனைவரும் வெட்டாந்தரை வழியாக யோர்தானைக் கடந்தனர்.",
    "Joshua 4": "நினைவுக்கற்கள்: யோர்தானைக் கடந்ததின் அடையாளமாக, நதியின் நடுவிலிருந்து பன்னிரண்டு கற்களை எடுத்து வந்து கில்காலில் நட்டனர். இது வரும் சந்ததியினருக்குத் தேவன் செய்த அற்புதத்தைச் சொல்லும் அடையாளமாக இருந்தது.",
    "Joshua 5": "விருத்தசேதனம் மற்றும் மன்னா: கில்காலில் புதிய தலைமுறைக்கு விருத்தசேதனம் செய்யப்பட்டது. அவர்கள் கானானின் விளைச்சலைப் புசித்தபோது மன்னா நின்றது. யோசுவா கர்த்தருடைய சேனையின் அதிபதியைக் கண்டு பணிந்து கொண்டார்.",
    "Joshua 6": "எரிகோ வீழ்ச்சி: கர்த்தருடைய கட்டளைப்படி, ஜனங்கள் ஏழு நாட்கள் எரிகோவைச் சுற்றி வந்தனர். ஏழாம் நாளில் எக்காளம் ஊதி ஆரவாரித்தபோது, எரிகோவின் மதில்கள் விழுந்தன; ராகாபின் குடும்பம் மாத்திரம் தப்பியது.",
    "Joshua 7": "ஆகாளின் பாவம்: எரிகோவில் விலக்கப்பட்டப் பொருட்களை ஆகான் திருடி மறைத்து வைத்ததால், இஸ்ரவேலர் ஆயி பட்டணத்தாரோடு தோற்றுப்போனார்கள். பாவம் வெளிப்பட்டு, ஆகான் தண்டிக்கப்பட்ட பின் கர்த்தருடைய கோபம் தணிந்தது.",
    "Joshua 8": "ஆயி பட்டணம் பிடிபடுதல்: யோசுவா தந்திரமாகப் போர் புரிந்து ஆயி பட்டணத்தை அழித்தார். பின்னர் ஏபால் மலையில் பலிபீடம் கட்டி, நியாயப்பிரமாணத்தை ஜனங்களுக்கு வாசித்துக் காட்டினார்.",
    "Joshua 9": "கிபியோனியரின் தந்திரம்: கிபியோனியர் பழைய வஸ்திரங்களைத் தரித்து தூர தேசத்திலிருந்து வந்தவர்கள் போலத் நடித்து, இஸ்ரவேலருடன் உடன்படிக்கை செய்து கொண்டனர். உண்மை தெரிந்தபின் அவர்கள் சபைக்கு விறகு வெட்டுகிறவர்களாகவும் தண்ணீர் இறைக்கிறவர்களாகவும் மாற்றப்பட்டனர்.",
    "Joshua 10": "சூரியன் நின்ற அற்புதம்: ஐந்து ராஜாக்கள் கிபியோனை எதிர்த்தபோது யோசுவா உதவினார். யுத்தத்தின் போது சூரியனும் சந்திரனும் ஒரு பகல் முழுவதும் அசையாமல் நின்றன. கர்த்தர் வானத்திலிருந்து கல்மழையைப் பெய்து எதிரிகளை அழித்தார்.",
    "Joshua 11": "வடதேச வெற்றி: வடதேசத்து ராஜாக்கள் பெரிய சேனையோடு வந்தனர். கர்த்தர் அவர்களை யோசுவாவின் கையில் ஒப்புக்கொடுத்தார்; தேசம் யுத்தமில்லாமல் அமைதியடைந்தது.",
    "Joshua 12": "தோற்கடிக்கப்பட்ட ராஜாக்கள்: யோர்தானுக்குக் கிழக்கே மோசே தோற்கடித்த இரண்டு ராஜாக்களையும், மேற்கே யோசுவா தோற்கடித்த முப்பத்தொரு ராஜாக்களையும் இந்தப் பட்டியல் விவரிக்கிறது.",
    "Joshua 13": "பங்கிடப்படாத நிலம்: யோசுவா முதிர்வயதானபோது, இன்னும் பிடிக்க வேண்டிய நிலங்களைக் கர்த்தர் காண்பித்தார். லேவியர்களுக்கு நிலம் சுதந்தரமாகக் கொடுக்கப்படவில்லை, கர்த்தரே அவர்களுக்குச் சுதந்தரம்.",
    "Joshua 14": "காலேபின் சுதந்தரம்: எண்பத்தைந்து வயதான காலேப், தான் வேவு பார்த்தபோது காட்டிய விசுவாசத்திற்காக எபிரோன் மலையைத் தனக்குச் சுதந்தரமாகக் கேட்டுப் பெற்றார்.",
    "Joshua 15": "யூதா கோத்திரத்தின் பங்கு: யூதா கோத்திரத்திற்கு ஒதுக்கப்பட்ட நிலத்தின் எல்லைகள் மற்றும் அவர்கள் பிடித்த பட்டணங்கள் விவரிக்கப்பட்டுள்ளன. காலேபின் குமாரத்தி அக்சாள் நீர்நிலைகளைத் தன் தந்தையிடம் கேட்டுப் பெற்றாள்.",
    "Joshua 16": "எப்பிராயீமின் பங்கு: யோசேப்பின் புமாரனாகிய எப்பிராயீமின் புத்திரருக்குக் கிடைத்த நிலப்பகுதிகள் மற்றும் அதன் எல்லைகள் விவரிக்கப்பட்டுள்ளன.",
    "Joshua 17": "மனாசேயின் பங்கு: யோசேப்பின் மூத்த குமாரனாகிய மனாசேயின் பாதி கோத்திரத்தாருக்குக் கிடைத்த இடங்கள் விவரிக்கப்பட்டுள்ளன. யோசேப்பின் புத்திரர் தங்களுக்குக் கூடுதல் நிலம் கேட்டபோது யோசுவா அவர்களைக் காடுகளை வெட்டித் திருத்தச் சொன்னார்.",
    "Joshua 18": "ஏனைய கோத்திரங்கள்: சீலோவிலே ஆசரிப்புக் கூடாரம் நிறுவப்பட்டது. நிலத்தை இன்னும் பங்கிடாத ஏழு கோத்திரத்தாருக்காகத் தேசம் அளக்கப்பட்டு, சீலோவிலே சீட்டுப் போட்டுப் பங்கிடப்பட்டது.",
    "Joshua 19": "மீதமுள்ள கோத்திரங்கள்: சிமியோன், செபுலோன், இசக்கார், ஆசேர், நப்தலி மற்றும் தாண் கோத்திரத்தாருக்குரிய இடங்கள் ஒதுக்கப்பட்டன. யோசுவாவுக்குத் திம்னாத் சேராக் பட்டணம் சுதந்தரமாகக் கொடுக்கப்பட்டது.",
    "Joshua 20": "அடைக்கலப் பட்டணங்கள்: தெரியாமல் கொலை செய்தவன் பழிவாங்குபவனுக்குத் தப்பித்துக் கொள்ளும்படி, ஏற்கனவே மோசே சொன்னபடி ஆறு அடைக்கலப் பட்டணங்கள் நியமிக்கப்பட்டன.",
    "Joshua 21": "லேவியர் பட்டணங்கள்: லேவியர்களுக்குப் பன்னிரண்டு கோத்திரங்களிலிருந்தும் மொத்தம் நாற்பத்தெட்டு பட்டணங்கள் ஒதுக்கப்பட்டன. தேவன் பிதாக்களுக்கு ஆணையிட்டபடியே தேசத்தை இஸ்ரவேலருக்குக் கொடுத்தார்.",
    "Joshua 22": "கிழக்குக் கோத்திரங்கள் திரும்புதல்: ரூபன், காத் மற்றும் மனாசேயின் பாதி கோத்திரத்தார் தங்கள் நிலங்களுக்குத் திரும்பினர். அவர்கள் யோர்தான் நதியருகே ஒரு பெரிய பலிபீடத்தைக் கட்டியது முதலில் சந்தேகத்தை உண்டாக்கினாலும், அது ஒரு நினைவுச் சின்னம் என்று விளக்கப்பட்டது.",
    "Joshua 23": "யோசுவாவின் இறுதி எச்சரிக்கை: யோசுவா மூப்பர்களை அழைத்து, அந்நிய தெய்வங்களை வழிபடக்கூடாது என்றும், கர்த்தரிடத்தில் அன்புகூர வேண்டும் என்றும், மீறினால் தேசத்திலிருந்து அழிந்து போவீர்கள் என்றும் எச்சரித்தார்.",
    "Joshua 24": "சீகேமில் உடன்படிக்கை: யோசுவா சரித்திரத்தை நினைவூட்டி, 'நீங்களும் உங்கள் வீட்டாரும் யாரைச் சேவிப்பீர்கள்? நானும் என் வீட்டாருமோவென்றால் கர்த்தரையே சேவிப்போம்' என்றார். நூற்றுப்பத்து வயதில் யோசுவா மரித்து அடக்கம் செய்யப்பட்டார்.",

    "Judges 1": "முழுமையற்ற வெற்றி: யோசுவாவின் மரணத்திற்குப் பின் யூதா கோத்திரத்தார் போரைத் தொடங்கினர். அதோனிபெசேக் பிடிபட்டான். ஆனால் பல கோத்திரங்கள் கானானியரை முழுமையாகத் துரத்தாமல், அவர்களைத் தங்களுக்குக் கப்பம் கட்டுகிறவர்களாக்கிக் கொண்டனர்.",
    "Judges 2": "போகீமில் எச்சரிக்கை: கர்த்தருடைய தூதன் தோன்றி, ஜாதிகளுடன் உடன்படிக்கை செய்ததற்காக ஜனங்களைக் கடிந்துகொண்டார். அந்நிய தெய்வங்களை வணங்கியதால் இஸ்ரவேலர் ஒடுக்கப்பட்டனர்; கர்த்தர் அவர்களை இரட்சிக்க நியாயாதிபதிகளை எழும்பப்பண்ணினார்.",
    "Judges 3": "ஒத்னியேல், ஏகூத், சம்கார்: முதல் நியாயாதிபதியாகிய ஒத்னியேல் மெசொப்பொத்தாமியரிடமிருந்து விடுவித்தார். இடதுகை பழக்கமுள்ள ஏகூத், மோவாப் ராஜா எக்லோனைக் கொன்று இஸ்ரவேலை மீட்டார். சம்கார் ஒரு தாற்றுக்கோலால் 600 பெலிஸ்தியரைக் கொன்றார்.",
    "Judges 4": "தெபொராளும் பாராக்கும்: பெண் தீர்க்கதரிசியாகிய தெபொராள் பாராக்கை அழைத்து யாபீன் ராஜாவின் சேனையை எதிர்க்கச் சொன்னார். சிசெரா ஓடிப்போய் யாகேல் என்னும் ஸ்திரீயினுடைய கூடாரத்தில் ஒளிந்தபோது, அவள் அவனை ஆணியால் அடித்துக் கொன்றாள்.",
    "Judges 5": "தெபொராளின் பாட்டு: கர்த்தர் தங்களுக்குத் தந்த வெற்றியைப் புகழ்ந்து தெபொராளும் பாராக்கும் பாடினர். கர்த்தருக்காக முன்வந்த பிரபுக்களையும், எதிரியை வீழ்த்திய யாகேலையும் இப்பாடல் போற்றியது.",
    "Judges 6": "கிதியோனின் அழைப்பு: மீதியானியர் இஸ்ரவேலை ஒடுக்கியபோது, கிதியோன் கோதுமை போரடிக்கையில் கர்த்தருடைய தூதன் அவனுக்குத் தரிசனமானார். கிதியோன் தன் தகப்பனின் பாகால் பீடத்தைத் தகர்த்து, கர்த்தருக்குப் பலிபீடம் கட்டினான்.",
    "Judges 7": "முந்நூறு பேர் வெற்றி: கர்த்தர் கிதியோனின் சேனையை 32,000-லிருந்து 300 பேராகக் குறைத்தார். அவர்கள் எக்காளங்களையும், மண்பாண்டங்களையும், தீவட்டிகளையும் கொண்டு மீதியானியரைத் திகைக்க வைத்து வெற்றி பெற்றனர்.",
    "Judges 8": "கிதியோனின் முடிவு: கிதியோன் மீதியானிய ராஜாக்களைப் பிடித்துக் கொன்றார். ஜனங்கள் அவரை ராஜாவாக விரும்பியபோது அவர் மறுத்தார்; ஆனால் அவர் செய்த ஒரு 'ஏபோத்து' (ஆபரணம்) பின்னாளில் ஜனங்களுக்கு ஒரு கண்ணியாக மாறியது.",
    "Judges 9": "அபிமெலேக்கின் கொடுங்கோன்மை: கிதியோனின் குமாரன் அபிமெலேக் தன் 70 சகோதரர்களைக் கொன்று ராஜாவாக முயன்றான். யோதாம் ஒரு உவமையின் மூலம் அவனை எச்சரித்தான். இறுதியில் ஒரு ஸ்திரீ எறிந்த ஏந்திரக்கல்லினால் அபிமெலேக் மரித்தான்.",
    "Judges 10": "தோலா மற்றும் யாயீர்: தோலா 23 வருஷமும், யாயீர் 22 வருஷமும் நியாயாதிபதிகளாக இருந்தனர். ஜனங்கள் மீண்டும் விக்கிரகாராதனை செய்ததால் அம்மோனியரிடம் சிக்கினர்; அவர்கள் மனந்திரும்பித் தேவனை நோக்கிக் கூப்பிட்டனர்.",
    "Judges 11": "யெப்தாவும் அவன் பொருத்தனையும்: தள்ளப்பட்ட குமாரனாகிய யெப்தா அம்மோனியரை எதிர்க்கத் தலைவனானான். அவன் செய்த ஒரு தவறான பொருத்தனையின்படி, வெற்றியைத் தொடர்ந்து தன் ஒரே மகளைக் கர்த்தருக்கு அர்ப்பணிக்க வேண்டியதாயிற்று.",
    "Judges 12": "எப்பிராயீமுடன் சண்டை: எப்பிராயீமியர் யெப்தாவோடு போரிட்டனர். 'ஷிபோலெத்' என்ற வார்த்தையைச் சரியாகச் சொல்லத் தெரியாத 42,000 எப்பிராயீமியர் கொல்லப்பட்டனர். இப்சான், ஏலோன், அப்தோன் ஆகியோர் பின்னாளில் நியாயாதிபதிகளாக இருந்தனர்.",
    "Judges 13": "சிம்சோனின் பிறப்பு: பெலிஸ்தியர் இஸ்ரவேலை ஒடுக்கியபோது, மனோவாவின் மனைவிக்குத் தூதன் தோன்றி ஒரு குமாரன் பிறப்பான் என்று கூறினார். அவன் பிறப்பிலிருந்தே தேவனுக்கு நசரேயனாக இருக்க வேண்டும் என்று கட்டளையிடப்பட்டது.",
    "Judges 14": "சிம்சோனின் திருமணம்: சிம்சோன் திம்னாத்திலுள்ள ஒரு பெலிஸ்தியப் பெண்ணைத் திருமணம் செய்ய விரும்பினான். வழியில் ஒரு சிங்கத்தைக் கிழித்துப் போட்டார். பின்னர் திருமண விருந்தில் ஒரு விடுகதையைச் சொல்லி பெலிஸ்தியரைச் சோதித்தார்.",
    "Judges 15": "நரியும் தாடை எலும்பும்: சிம்சோன் 300 நரிகளின் வாலைப் பிணைத்துத் தீ மூட்டி பெலிஸ்தியரின் வயல்களை அழித்தார். பின்னர் ஒரு கழுதையின் தாடை எலும்பைக் கொண்டு 1000 பெலிஸ்தியரைக் கொன்றார்.",
    "Judges 16": "சிம்சோனும் தெலீலாளும்: தெலீலாளின் சூழ்ச்சியினால் சிம்சோன் தன் பலத்தின் இரகசியத்தைக் கூறினார்; அவர் தலைமயிர் சவரம் செய்யப்பட்டு பெலிஸ்தியரால் சிறைபிடிக்கப்பட்டார். இறுதியில் ஆலயத்தின் தூண்களைச் சாய்த்துத் தம்மோடு அநேக பெலிஸ்தியரைக் கொன்று மரித்தார்.",
    "Judges 17": "மீகாவின் விக்கிரகம்: எப்பிராயீம் மலைத்தேசத்து மீகா ஒரு விக்கிரகத்தைச் செய்து, ஒரு லேவியனைத் தனக்கு ஆசாரியனாக நியமித்துக் கொண்டான். இது இஸ்ரவேலில் நிலவிய ஆவிக்குரிய குழப்பத்தைக் காண்பித்தது.",
    "Judges 18": "தாண் கோத்திரத்தாரும் விக்கிரகமும்: தாண் கோத்திரத்தார் தங்களுக்கு நிலம் தேடிச் சென்றபோது, மீகாவின் விக்கிரகத்தையும் ஆசாரியனையும் கவர்ந்து சென்றனர். அவர்கள் லாயிசு பட்டணத்தைப் பிடித்து அதற்குத் 'தாண்' என்று பெயரிட்டனர்.",
    "Judges 19": "லேவியனும் அவன் மறுமனையாட்டியும்: கிபியாவிலுள்ள பென்யமீன் கோத்திரத்தார் ஒரு லேவியனின் மறுமனையாட்டியைத் துன்புறுத்திக் கொன்றனர். இந்தக் கொடிய செயல் இஸ்ரவேல் கோத்திரங்கள் அனைத்தையும் அதிர்ச்சியடைய வைத்தது.",
    "Judges 20": "பென்யமீன் கோத்திரத்தாருடன் போர்: மற்ற கோத்திரங்கள் ஒன்று கூடி கிபியாவின் தீமைக்காகப் பென்யமீன் கோத்திரத்தாரைத் தண்டித்தனர். நடந்த கடும் போரில் பென்யமீன் கோத்திரம் ஏறக்குறைய அழியும் நிலைக்கு வந்தது.",
    "Judges 21": "மறுசீரமைப்பு: பென்யமீன் கோத்திரம் அழிந்துவிடக் கூடாது என்பதற்காக மற்றவர்கள் அவர்களுக்குப் பெண்களை ஏற்பாடு செய்தனர். 'அந்நாட்களில் இஸ்ரவேலில் ராஜா இல்லை; அவனவன் தன் தன் பார்வைக்குச் சரிப்போனபடி செய்தான்' என்று நூல் முடிகிறது.",

    "Ruth 1": "நகோமியும் ரூத்தும்: பெத்லகேமில் பஞ்சம் உண்டானதால் எலிமெலேக்கும் நகோமியும் மோவாப் தேசத்திற்குச் சென்றனர். அங்கே கணவனையும் இரண்டு குமாரர்களையும் இழந்த நகோமி, தன் மருமகள் ரூத்துடன் பெத்லகேமிற்குத் திரும்பினாள். ரூத்: 'உம்முடைய ஜனம் என்னுடைய ஜனம், உம்முடைய தேவன் என்னுடைய தேவன்' என்று உறுதிகூறினாள்.",
    "Ruth 2": "போவாசின் வயலில் ரூத்: வறுமையிலிருந்த ரூத், கதிர் பொறுக்குவதற்காகப் போவாஸ் என்னும் உறவினரின் வயலுக்குச் சென்றாள். ரூத்தின் உத்தமத்தைக் கேள்விப்பட்ட போவாஸ், அவளுக்குத் தயவு காட்டி, அவளுக்குப் பாதுகாப்பு அளித்து உணவூட்டினான்.",
    "Ruth 3": "போவாசின் பாதத்தில் ரூத்: நகோமியின் ஆலோசனையின்படி, ரூத் போவாஸின் களத்திற்குச் சென்று அவன் பாதத்தருகே படுத்துக்கொண்டாள். போவாஸ் அவளைச் சுதந்தரித்துக்கொள்ளச் சம்மதித்து, தன்னைவிடச் சமீபமான உறவினன் ஒருவன் இருப்பதைச் சுட்டிக்காட்டினான்.",
    "Ruth 4": "மீட்பும் ஆசீர்வாதமும்: சமீபமான உறவினன் நிலத்தை மீட்க மறுத்ததால், போவாஸ் ரூத்தைத் திருமணம் செய்து நிலத்தையும் மீட்டுக்கொண்டார். அவர்களுக்கு ஓபேத் பிறந்தார்; அவர் ஈசாயின் தகப்பனும், தாவீதின் பாட்டனுமானார்.",

    "Nehemiah 1": "நெகேமியாவின் பாரம்: எருசலேமின் மதில்கள் இடிக்கப்பட்டுக் கிடப்பதைக் கேட்டு நெகேமியா அழுது, உபவாசித்து ஜெபித்தார். 'உமது அடியானின் ஜெபத்தைக் கேட்டருளும்' என்று மன்றாடினார்.",
    "Nehemiah 2": "ராஜாவின் அனுமதி: நெகேமியா துக்க முகமாய் இருந்ததைக் கண்டு அர்தசஷ்டா ராஜா காரணம் கேட்டான். நெகேமியா எருசலேமின் மதில்களைக் கட்ட அனுமதி கேட்டார். ராஜா அனுமதித்ததுடன் தேவையான மரங்களையும் வழங்கினார். சன்பல்லாத் போன்றோர் இதை எதிர்த்தனர்.",
    "Nehemiah 3": "மதிலைக் கட்டுபவர்கள்: ஆசாரியர்கள், லேவியர்கள் மற்றும் பல்வேறு குடும்பத்தினர் மதிலின் ஒவ்வொரு பகுதியையும் வாசல்வாரியாகப் பங்கிட்டு எப்படிக் கட்டினார்கள் என்ற விரிவான பட்டியல்.",
    "Nehemiah 4": "பகைவர்களின் சூழ்ச்சி: சன்பல்லாத்தும் தொபியாவும் யூதர்களைப் பரியாசம் செய்து தாக்க முயன்றனர். நெகேமியா ஜனங்களை ஆயுதம் தரிக்கச் செய்து, ஒரு கையால் வேலை செய்து மறு கையால் ஆயுதம் ஏந்தி மதிலைக் கட்டச் சொன்னார்.",
    "Nehemiah 5": "ஏழைகளுக்கு உதவி: யூத பிரபுக்கள் ஏழை சகோதரர்களிடம் வட்டி வாங்கி அவர்களை ஒடுக்கினர். நெகேமியா இதைக் கண்டித்து, வாங்கிய ஈடுகளைத் திருப்பிக் கொடுக்கச் செய்தார். அவர் ஆளுநராக இருந்தும் ஜனங்களிடம் வரி வாங்காமல் தாராளம் காட்டினார்.",
    "Nehemiah 6": "மதில் கட்டி முடித்தல்: எதிரிகள் நெகேமியாவைக் கொல்லச் சதி செய்தனர்; பயமுறுத்தினர். ஆனால் 52 நாட்களில் மதில் கட்டி முடிக்கப்பட்டது. இதைக் கண்ட பகைவர்கள் இது 'தேவனால் உண்டானது' என்று அறிந்து பயந்தனர்.",
    "Nehemiah 7": "பாதுகாப்பும் ஜனத்தொகையும்: மதில் முடிந்தபின் நெகேமியா வாசல்களை அமைத்துக் காவல் வைத்தார். முதலில் சிறையிருப்பிலிருந்து வந்தவர்களின் பட்டியலைச் சரிபார்த்து, அவர்கள் பட்டணங்களில் குடியேறச் செய்தார்.",
    "Nehemiah 8": "வேத வாசிப்பு: எஸ்றா ஒரு மர மேடையின் மேல் நின்று ஜனங்களுக்கு நியாயப்பிரமாணத்தை வாசித்துக் காட்டினார். லேவியர்கள் அதற்குப் பொருள் சொன்னார்கள். ஜனங்கள் அழுதுகொண்டிருந்தபோது, 'கர்த்தருக்குள் மகிழ்ச்சியாயிருப்பதே உங்கள் பெலன்' என்று நெகேமியா தேற்றினார்.",
    "Nehemiah 9": "பாவ அறிக்கை: ஜனங்கள் சாக்கைத் தரித்துத் தங்கள் பாவங்களை அறிக்கையிட்டனர். ஆபிரகாம் முதல் சிறையிருப்பு வரை தேவன் செய்த நன்மைகளையும், ஜனங்கள் செய்த துரோகத்தையும் ஒரு நீண்ட ஜெபமாக லேவியர் ஏறெடுத்தனர்.",
    "Nehemiah 10": "உடன்படிக்கையில் கையொப்பம்: ஜனங்கள் கர்த்தருடைய கட்டளைகளின்படி நடப்போம் என்று உறுதி பூண்டனர். குறிப்பாக, அந்நியரோடு சம்பந்தம் கலப்பதில்லை என்றும், ஓய்வுநாளைக் கைக்கொள்வோம் என்றும், தசமபாகம் கொடுப்போம் என்றும் கையொப்பமிட்டனர்.",
    "Nehemiah 11": "எருசலேமில் குடியேறுதல்: எருசலேம் மக்கள் குறைவாக இருந்ததால், பத்தில் ஒரு பங்கு ஜனங்கள் எருசலேமில் குடியிருக்கச் சீட்டுப் போடப்பட்டது. மற்றவர்கள் தங்களுக்குரிய ஊர்களில் குடியேறினர்.",
    "Nehemiah 12": "மதில் பிரதிஷ்டை: ஆசாரியர்களும் லேவியர்களும் சுத்திகரிக்கப்பட்டனர். பாடகர்கள் இரண்டு பெரிய கூட்டங்களாகப் பிரிந்து மதிலின் மேல் துதித்துக் கொண்டு வந்தனர். எருசலேமின் மகிழ்ச்சியின் சத்தம் தூரத்திலே கேட்கப்பட்டது.",
    "Nehemiah 13": "நெகேமியாவின் சீர்திருத்தம்: நெகேமியா தற்காலிகமாகப் பெர்சியா சென்று திரும்பியபோது, ஆலயத்தில் தொபியாவுக்கு இடம் கொடுக்கப்பட்டிருப்பதையும், ஓய்வுநாள் மீறப்படுவதையும் கண்டார். அவர் எல்லாவற்றையும் கண்டித்துச் சீர்ப்படுத்தினார்.",

    "Esther 1": "வஸ்தி தள்ளப்படுதல்: பெர்சிய ராஜாவாகிய அகாஸ்வேரு ஒரு பெரிய விருந்து செய்தான். ராஜாவின் கட்டளைக்குக் கீழ்ப்படியாத ராணி வஸ்தி தன் பதவியிலிருந்து நீக்கப்பட்டாள். அவளுக்குப் பதில் புதிய ராணியைத் தேட கட்டளை பிறந்தது.",
    "Esther 2": "எஸ்தர் ராணியாதல்: மொர்தெகாயின் வளர்ப்பு மகளான எஸ்தர் அழகாயிருந்ததால் ராஜாவுக்கு முன்பாக தயவு பெற்றாள்; அவள் எஸ்தர் ராணியாக முடிசூட்டப்பட்டாள். மொர்தெகாய் ராஜாவைக் கொல்லச் செய்த சதியைக் கண்டுபிடித்துக் காப்பாற்றினார்.",
    "Esther 3": "ஆமானின் சூழ்ச்சி: ஆகாகியனாகிய ஆமான் உயர்த்தப்பட்டான். மொர்தெகாய் அவனுக்கு வணங்காததால், கோபமடைந்த ஆமான் யூதர்களை முழுவதும் அழிக்க ராஜாவிடம் அனுமதி பெற்று சீட்டு (பூர்) போட்டான்.",
    "Esther 4": "எஸ்தரின் தீர்மானம்: ஆமானின் திட்டத்தைக் கேட்டு மொர்தெகாய் துக்கப்பட்டு எஸ்தருக்குத் தெரியப்படுத்தினார். 'இப்படிப்பட்ட காலத்துக்கு நீ ராணியானது யாரால் தெரியும்?' என்று அவர் கேட்டார். எஸ்தர் 'செத்தாலும் சாகிறேன்' என்று உபவாசித்து ராஜாவிடம் செல்லத் தீர்மானித்தாள்.",
    "Esther 5": "எஸ்தர் ராஜாவிடம் செல்லுதல்: எஸ்தர் தன் உயிரைப் பணயம் வைத்து ராஜா முன் நின்றாள். ராஜா தயவுடன் செங்கோலை நீட்டினார். எஸ்தர் ராஜாவையும் ஆமானையும் ஒரு விருந்துக்கு அழைத்தாள். ஆமான் மொர்தெகாயைத் தூக்கிலிட ஒரு தூக்குமரத்தைச் செய்தான்.",
    "Esther 6": "மொர்தெகாய் கனப்படுத்தப்படுதல்: அன்று இரவு ராஜாவுக்குத் தூக்கம் வராததால் நாளாகம வாசிப்பைக் கேட்டார். மொர்தெகாய் செய்த உதவிக்கு இன்னும் பிரதிபலன் கிடைக்கவில்லை என்று அறிந்து, ஆமானைக் கொண்டே மொர்தெகாயை வீதிவழியே கனப்படுத்தச் செய்தார்.",
    "Esther 7": "ஆமானின் வீழ்ச்சி: இரண்டாம் விருந்தில் எஸ்தர் தன் இனத்தைக் குறித்து ராஜாவிடம் முறையிட்டாள். ஆமானே இந்தச் சதிக்குக் காரணம் என்று தெரிந்ததும், ராஜா கோபமடைந்து, ஆமான் செய்த தூக்குமரத்திலேயே அவனைத் தூக்கிலிடக் கட்டளையிட்டார்.",
    "Esther 8": "யூதர்களுக்கு விடுதலை: மொர்தெகாயிடம் ராஜாவின் முத்திரை மோதிரம் கொடுக்கப்பட்டது. யூதர்கள் தங்களைப் பாதுகாத்துக் கொள்ளவும், எதிரிகளை எதிர்க்கவும் புதிய ஆணை பிறப்பிக்கப்பட்டது. யூதர்கள் மத்தியில் மகிழ்ச்சியும் ஒளியும் உண்டானது.",
    "Esther 9": "பூர் பண்டிகை: குறித்த நாளில் யூதர்கள் தங்கள் பகைவர்களை வென்றனர். இந்த வெற்றியைக் கொண்டாட 'பூர்' (Purim) என்ற பண்டிகை ஏற்படுத்தப்பட்டது. எஸ்தரும் மொர்தெகாயும் இந்தப் பண்டிகையை உறுதிப்படுத்தினர்.",
    "Esther 10": "மொர்தெகாயின் மேன்மை: அகாஸ்வேரு ராஜா மொர்தெகாயை உயர்த்தினார். மொர்தெகாய் ராஜாவுக்கு அடுத்தபடியாகப் பெரியவனாகவும், தன் ஜனங்களின் நன்மையைத் தேடுகிறவனாகவும் விளங்கினார்.",

    "Job 1": "யோபுவின் சோதனை: உத்தமனும் சன்மார்க்கனுமான யோபுவின் ஆஸ்திகளையும் பிள்ளைகளையும் சாத்தான் ஒரே நாளில் அழித்தான். யோபு: 'கர்த்தர் கொடுத்தார், கர்த்தர் எடுத்தார்; கர்த்தருடைய நாமத்திற்கு ஸ்தோத்திரம்' என்றார்.",
    "Job 2": "சரீர உபாதை: சாத்தான் யோபுவின் சரீரத்தில் கொடிய பருக்களை வரவழைத்தான். யோபுவின் மனைவி 'தேவனைத் தூஷித்து ஜீவனை விடு' என்றாள். யோபு: 'நன்மையைப் பெற்ற நாம் தீமையையும் பெறவேண்டாமா?' என்றார்.",
    "Job 3": "யோபுவின் புலம்பல்: மிகுந்த வேதனையினால் யோபு தன் பிறந்த நாளைச் சபித்தார். தான் ஏன் பிறக்கும்போதே இறக்கவில்லை என்று வருந்தி, மரணத்தை ஒரு இளைப்பாறுதலாகக் கருதினார்.",
    "Job 4": "எலிப்பாசின் முதல் பேச்சு: யோபுவின் நண்பன் எலிப்பாஸ், 'குற்றமற்றவன் யாராவது அழிந்ததுண்டா?' என்று கேட்டு, யோபு ஏதோ பாவம் செய்திருக்க வேண்டும் என்று மறைமுகமாகக் குற்றம் சாட்டினான்.",
    "Job 5": "தேவனுடைய சிட்சை: எலிப்பாஸ் தொடர்ந்து பேசுகையில், 'தேவன் சிட்சிக்கிற மனுஷன் பாக்கியவான்' என்றும், கர்த்தர் அடிக்கிறவர் ஆனால் அவரே காயத்தைக் கட்டுகிறவர் என்றும் யோபுவைத் தேற்ற முயன்றான்.",
    "Job 6": "யோபுவின் பதில்: தன் துக்கம் கடலைவிடப் பெரியது என்றும், நண்பர்கள் தமக்குத் தயவு காட்டாமல் வறண்ட நதியைப் போல மாறிவிட்டார்கள் என்றும் யோபு வருத்தத்துடன் கூறினார்.",
    "Job 7": "மனுஷனின் போராட்டம்: மனித வாழ்வு ஒரு கூலி ஆளின் வேலையைப் போன்றது என்று புலம்பினார். 'நான் பாவம் செய்திருந்தாலும் உமக்கு அதனால் என்ன?' என்று கர்த்தரிடம் தன் வேதனையைக் கொட்டினார்.",
    "Job 8": "பில்தாதின் பேச்சு: பில்தாத் பேசுகையில், யோபுவின் பிள்ளைகள் பாவம் செய்திருக்கலாம் என்றும், யோபு உண்மையில் நீதிமானாக இருந்தால் தேவன் அவரை உடனே ஆசீர்வதிப்பார் என்றும் வாதிட்டான்.",
    "Job 9": "தேவனின் வல்லமை: தேவன் மனுஷனைவிடப் பெரியவர், அவர் முன் ஒருவனும் நீதிமானாக நிற்க முடியாது என்று யோபு ஒப்புக்கொண்டார். 'அவர் என்னைக் கொன்றுபோட்டாலும் அவரிடத்தில் நம்பிக்கையாயிருப்பேன்' என்றார்.",
    "Job 10": "நியாயம் கேட்டல்: தேவன் ஏன் தம்மைக் குற்றவாளியாகத் தீர்க்கிறார் என்று யோபு வினவினார். 'உம்முடைய கைகள் என்னை உருவாக்கினது, இப்போது என்னை அழிக்கிறீரோ?' என்று உருக்கமாகக் கேட்டார்.",
    "Job 11": "சோப்பாரின் பேச்சு: யோபு தன் நீதியைப் பேசுகிறதைக் கண்டித்த சோப்பார், தேவன் யோபுவுக்குத் தகுந்த தண்டனையைவிடக் குறைவாகவே கொடுத்திருக்கிறார் என்று மிகவும் கடுமையாகப் பேசினான்.",
    "Job 12": "யோபுவின் அறிவு: தன் நண்பர்களுக்குப் பதில் சொன்ன யோபு, 'உங்களுக்குத் தெரிந்த ஞானம் எனக்கும் தெரியும்' என்றார். மிருகங்களும் பறவைகளும் கூடத் தேவனே எல்லாவற்றையும் படைத்தார் என்று சொல்லும் என்றார்.",
    "Job 13": "உத்தமத்தின் உறுதி: 'என் வழிகளை அவருக்கு முன்பாக நிரூபிப்பேன்' என்று தைரியமாகக் கூறினார். நண்பர்கள் தேவன் சார்பாகப் பொய் பேசுகிறார்கள் என்று அவர்களைக் கடிந்து கொண்டார்.",
    "Job 14": "வாழ்வின் நிலையாமை: 'ஸ்திரீயினிடத்தில் பிறந்த மனுஷன் ஆயுசு குறைந்தவனும், கிலேசங்கள் நிறைந்தவனுமாயிருக்கிறான்' என்று மனித வாழ்வின் பலவீனத்தையும் மரணத்தின் நிச்சயத்தையும் விவரித்தார்.",
    "Job 15": "எலிப்பாசின் இரண்டாம் பேச்சு: யோபுவின் வார்த்தைகள் வீணானது என்று எலிப்பாஸ் சாடினான். துன்மார்க்கன் வாழ்நாள் முழுதும் வேதனைப்படுவான் என்று கூறி யோபுவை மீண்டும் பயமுறுத்தினான்.",
    "Job 16": "சலிப்புண்டாக்கும் தேற்றரவாளர்கள்: 'நீங்கள் எல்லாரும் சலிப்புண்டாக்கும் தேற்றரவாளர்கள்' என்று யோபு நண்பர்களைச் சாடினார். பரலோகத்தில் தமக்காக ஒரு சாட்சி (Witness) இருப்பதாக விசுவாசித்தார்.",
    "Job 17": "மரணத்தின் வாசல்: 'என் நாட்கள் முடிந்தது, என் நோக்கம் சிதைந்தது' என்று புலம்பினார். கல்லறை மாத்திரமே தமக்கு வீடாகத் தெரிகிறது என்று தன் நம்பிக்கையற்ற நிலையைக் கூறினார்.",
    "Job 18": "பில்தாதின் இரண்டாம் பேச்சு: பில்தாத் கோபத்துடன், துன்மார்க்கனின் வெளிச்சம் அணைந்து போகும் என்றும், அவனுடைய நினைவு பூமியில் இல்லாமற்போகும் என்றும் யோபுவைச் சுட்டிக்காட்டிப் பேசினான்.",
    "Job 19": "மீட்பர் உயிரோடிருக்கிறார்: நண்பர்களின் நிந்தனையால் நொந்த யோபு, ஒரு தீர்க்கதரிசன அறிக்கையைச் செய்தார்: 'என் மீட்பர் உயிரோடிருக்கிறார், கடைசி நாளில் அவர் பூமியின்மேல் நிற்பார்.'",
    "Job 20": "சோப்பாரின் இரண்டாம் பேச்சு: துன்மார்க்கனின் மகிழ்ச்சி ஒரு நிமிஷம் மாத்திரமே இருக்கும் என்றும், அவன் சம்பாதித்த ஆஸ்திகளை மீண்டும் கக்க வேண்டியிருக்கும் என்றும் சோப்பார் வாதிட்டான்.",
    "Job 21": "துன்மார்க்கரின் வாழ்வு: நண்பர்களின் வாதத்திற்குப் பதில் சொன்ன யோபு, 'துன்மார்க்கர் ஏன் சுகமாய் வாழ்கிறார்கள்? அவர்கள் ஏன் முதிர்வயது வரை செழிப்பாய் இருக்கிறார்கள்?' என்று கேட்டு அவர்கள் தியரியை மறுத்தார்.",
    "Job 22": "எலிப்பாசின் பொய்க் குற்றச்சாட்டு: எலிப்பாஸ் மூன்றாம் முறையாகப் பேசுகையில், யோபு ஏழைகளை ஒடுக்கினான் என்றும், விதவைகளை வெறும் கையாய் அனுப்பினான் என்றும் இல்லாத பொல்லாத பாவங்களைச் சுமத்தினான்.",
    "Job 23": "தேவனைத் தேடுதல்: 'அவர் எங்கே அகப்படுவார் என்று அறிந்தால் நலமாயிருக்கும்' என்று யோபு ஏங்கினார். 'அவர் என்னைச் சோதித்தபின் நான் பொன்னாக விளங்குவேன்' என்று நம்பிக்கையோடு கூறினார்.",
    "Job 24": "அநீதி நிலவுதல்: உலகில் ஏழைகள் ஒடுக்கப்படுவதையும், கொலைஞர்களும் விபசாரிகளும் இருட்டில் திரிவதையும் தேவன் ஏன் உடனே தண்டிப்பதில்லை என்று யோபு கேள்வி எழுப்பினார்.",
    "Job 25": "பில்தாதின் கடைசிப் பேச்சு: மனுஷன் தேவன் முன்னிலையில் எப்படி நீதிமானாக முடியும்? புழுவாகிய மனுஷன் அவருக்கு முன்பாக எம்மாத்திரம் என்று மிகச் சுருக்கமாகப் பேசி முடித்தான்.",
    "Job 26": "தேவனின் மகத்துவம்: 'உதவியற்றவனுக்கு நீ எப்படி உதவினாய்?' என்று பில்தாதை எள்ளி நகையாடிய யோபு, பாதாளம் முதல் ஆகாயம் வரை தேவன் செய்யும் அதியசயங்களை விவரித்தார்.",
    "Job 27": "உத்தமத்தின் உறுதிமொழி: 'என் ஆவி என்னில் இருக்குமட்டும் என் உத்தமத்தை என்னை விட்டு விலக்கேன்' என்று யோபு ஆணையிட்டுக் கூறினார். பொய்யர்களாகிய தன் நண்பர்களைக் கண்டித்தார்.",
    "Job 28": "ஞானம் எங்கே அகப்படும்?: மனுஷன் பூமியைத் தோண்டிப் பொன்னையும் வெள்ளியையும் எடுக்கிறான். ஆனால் ஞானம் எங்கே? 'கர்த்தருக்குப் பயப்படுவதே ஞானம்; தீமையை விட்டு விலகுவதே புத்தி' என்று விளக்கினார்.",
    "Job 29": "பழைய நாட்களின் நினைவு: தான் முன்னொரு காலத்தில் பெற்றிருந்த கனத்தையும், ஏழைகளுக்குத் தான் செய்த உதவிகளையும், ஜனங்கள் தனக்குக் கொடுத்த மரியாதையையும் நினைத்து யோபு ஏங்கினார்.",
    "Job 30": "தற்போதைய அவமானம்: முன்பு தன்னை மதித்தவர்களின் பிள்ளைகளே இப்போது தன்னைப் பரியாசம் செய்கிறார்கள் என்றும், தன் சரீரம் கருத்துக் போய் உருக்குலைந்து விட்டது என்றும் புலம்பினார்.",
    "Job 31": "யோபுவின் கடைசித் தற்காப்பு: தான் ஒருபோதும் இச்சையுள்ள கண்ணால் பார்க்கவில்லை என்றும், அநீதி செய்யவில்லை என்றும் கூறி, 'சர்வவல்லவர் எனக்குப் பதில் சொல்லட்டும்' என்று சவால் விட்டார்.",
    "Job 32": "எலிகூவின் கோபம்: இதுவரை அமைதியாயிருந்த வாலிபனாகிய எலிகூ பேசத் தொடங்கினான். யோபு தன்னை நீதிமான் என்று சொன்னதாலும், நண்பர்கள் யோபுவை வாயடைக்கச் செய்ய முடியாததாலும் அவன் கோபமடைந்தான்.",
    "Job 33": "தேவன் பேசும் விதம்: தேவன் கனவுகள் மூலமும், வியாதியின் மூலமும் மனுஷனைத் திருத்தி, அவனை அழிவிற்குத் தப்புவிக்கிறார் என்று எலிகூ யோபுவுக்கு விளக்கினான்.",
    "Job 34": "தேவ நீதி: தேவன் ஒருபோதும் அநீதி செய்யமாட்டார் என்றும், மனுஷன் தன் செயல்களுக்குத் தக்க பலனை அடைவான் என்றும் எலிகூ வாதிட்டு யோபுவைக் கடிந்து கொண்டான்.",
    "Job 35": "பக்தியின் பயன்: 'நான் பாவம் செய்யாதிருந்தால் எனக்கு என்ன லாபம்?' என்று யோபு கேட்டதாக எலிகூ அவனைக் குற்றஞ்சாட்டினான். தேவன் வானாதி வானங்களுக்கு மேலானவர் என்று விளக்கினான்.",
    "Job 36": "தேவனின் மேன்மை: துன்பங்கள் மனுஷனுடைய காதைத் திறந்து அவனுக்குப் போதிக்கின்றன. தேவன் வல்லமையுள்ளவர், அவர் யாரையும் புறக்கணிப்பதில்லை என்று எலிகூ கூறினான்.",
    "Job 37": "இயற்கையின் அதிசயம்: இடி, மின்னல், பனி மற்றும் மேகங்களை ஆளுகிற தேவனுடைய செயல்களைச் சிந்தித்துப் பார் என்று எலிகூ கூறி, தேவன் ஆராய்ந்து முடியாதவர் என்று முடித்தான்.",
    "Job 38": "பெருங்காற்றிலிருந்து தேவன்: கர்த்தர் யோபுவுக்குப் பதில் அளித்தார். 'பூமியை அஸ்திபாரமிட்டபோது நீ எங்கேயிருந்தாய்? விடிவெள்ளி நட்சத்திரங்கள் ஏகமாய்ப் பாடினபோது நீ அறிவாயோ?' என்று கேட்டார்.",
    "Job 39": "சிருஷ்டிப்பின் விந்தை: காட்டு ஆடுகள், காட்டுக் கழுதைகள், காண்டாமிருகம் மற்றும் தீக்கோழி போன்ற மிருகங்களைப் பராமரிப்பது யார்? குதிரைக்குப் பலத்தைத் தந்தது யார் என்று தேவன் வினவினார்.",
    "Job 40": "பெகிமோத் (Behemoth): யோபு வாயை மூடித் தன்னைத் தாழ்த்தினார். தேவன் மகா பலத்த மிருகமாகிய பெகிமோத்தைக் குறித்து விவரித்து, அதன் வல்லமையை எவன் எதிர்க்க முடியும் என்றார்.",
    "Job 41": "லிவியாதான் (Leviathan): கடலில் வாழும் கொடிய லிவியாதானைத் தூண்டிலால் பிடிக்க முடியுமா? அது பெருமையுள்ள எல்லாவற்றிற்கும் ராஜாவாயிருக்கிறது என்று தேவன் தன் அதிகாரத்தைக் காண்பித்தார்.",
    "Job 42": "யோபுவின் மீட்பு: 'நீர் சகலத்தையும் செய்யவல்லவர்' என்று யோபு மனந்திரும்பினார். கர்த்தர் யோபுவின் நண்பர்களைக் கடிந்து கொண்டு, யோபுவின் சிறையிருப்பை மாற்றி, அவனுக்கு இரண்டத்தனையாய் ஆசீர்வாதங்களைத் தந்தார்.",

    "Psalms 1": "இரு வழிகள்: துன்மார்க்கருடைய ஆலோசனையில் நடவாமல், கர்த்தருடைய வேதத்தில் இரவும் பகலும் தியானமாயிருக்கிற மனுஷன் பாக்கியவான். அவன் நீர்க்கால்களின் ஓரமாய் நடப்பட்ட மரத்தைப் போலிருப்பான்.",
    "Psalms 2": "ராஜரீக சங்கீதம்: ஜாதிகள் ஏன் கொந்தளித்து, ராஜாக்கள் கர்த்தருக்கு விரோதமாய் எழும்புகிறார்கள்? தேவன் தம்முடைய குமாரனைச் சீயோன் பர்வதத்தின்மேல் ராஜாவாக அபிஷேகம் பண்ணியிருக்கிறார்.",
    "Psalms 3": "ஆபத்தில் நம்பிக்கை: தாவீது தன் குமாரன் அப்சலோமுக்குத் தப்பி ஓடும்போது பாடியது. 'கர்த்தாவே, என் சத்துருக்கள் எவ்வளவோ பெருகியிருக்கிறார்கள்; ஆனாலும் நீர் என்னைச் சுற்றியுள்ள கேடயமாயிருக்கிறீர்.'",
    "Psalms 4": "இரவு ஜெபம்: 'நீதியின் தேவனே, நான் கூப்பிடும்போது எனக்குப் பதிலளியும்.' மனுஷர் வீணானதைத் தேடினாலும், கர்த்தர் எனக்குத் தருகிற சந்தோஷம் தானியமும் திராட்சரசமும் பெருகும் சந்தோஷத்தைவிடப் பெரியது.",
    "Psalms 5": "காலை ஜெபம்: 'கர்த்தாவே, காலையிலே என் சத்தத்தைக் கேட்டருளுவீர்.' துன்மார்க்கன் தேவனுக்கு முன்பாக நிற்கமாட்டான்; ஆனால் கர்த்தரை நம்புகிறவர்கள் என்றென்றைக்கும் மகிழ்வார்கள்.",
    "Psalms 6": "இரக்கத்திற்காக வேண்டுதல்: தாவீது தன் வியாதியிலும் வேதனையிலும் கண்ணீர் விட்டு ஜெபித்தார். 'என் ஆத்துமா மிகவும் கலங்கியிருக்கிறது; கர்த்தாவே, எதுவரைக்கும் இரங்காதிருப்பீர்?'",
    "Psalms 7": "நீதியான நியாயத்தீர்ப்பு: தாவீது தன் உத்தமத்தை நிரூபிக்கக் கர்த்தரை வேண்டுகிறார். 'என் கேடயம் தேவனிடத்திலிருக்கிறது; அவர் செம்மையான இருதயமுள்ளவர்களை இரட்சிக்கிறவர்.'",
    "Psalms 8": "தேவ மகிமையும் மனுஷனும்: 'எங்கள் ஆண்டவராகிய கர்த்தாவே, உம்முடைய நாமம் பூமியெங்கும் எவ்வளவு மேன்மையுள்ளதாயிருக்கிறது!' வானத்தையும் சந்திரனையும் பார்க்கும்போது, மனுஷன் எம்மாத்திரம்?",
    "Psalms 9": "வெற்றித் துதி: கர்த்தர் ஒடுக்கப்பட்டவர்களுக்கு உயர்ந்த அடைக்கலமானவர். ஜாதிகள் தாங்கள் வெட்டின குழியில் தாங்களே விழுவார்கள்; கர்த்தர் நீதியாய் நியாயந்தீர்ப்பார்.",
    "Psalms 10": "ஏழைகளின் முறையீடு: 'கர்த்தாவே, ஏன் தூரத்தில் நிற்கிறீர்?' துன்மார்க்கன் தேவனைத் தேடாமல் ஏழைகளைத் துன்புறுத்துகிறான். ஆனால் தேவன் திக்கற்றவர்களுக்குச் சகாயர்.",
    "Psalms 11": "கர்த்தரில் அடைக்கலம்: 'பறவையைப் போல உன் மலைக்குப் பறந்துபோ என்று என் ஆத்துமாவோடு ஏன் சொல்லுகிறீர்கள்?' கர்த்தர் தம்முடைய பரிசுத்த ஆலயத்தில் இருக்கிறார்; அவர் நீதியை நேசிக்கிறார்.",
    "Psalms 12": "உண்மையுள்ளவர்கள் குறைதல்: மனுஷர் மத்தியிலிருந்து பக்தியுள்ளவர்கள் அற்றுப்போகிறார்கள். ஆனால் கர்த்தருடைய சொற்கள் ஏழு தரம் உருக்கப்பட்ட வெள்ளியைப் போலப் பரிசுத்தமானவை.",
    "Psalms 13": "எதுவரைக்கும்?: 'கர்த்தாவே, எதுவரைக்கும் என்னை மறந்திருப்பீர்?' தாவீது தன் துக்கத்தைப் புலம்பிவிட்டு, இறுதியில் 'உம்முடைய இரட்சிப்பினால் என் இருதயம் மகிழும்' என்று முடிக்கிறார்.",
    "Psalms 14": "மூடனின் எண்ணம்: 'தேவன் இல்லை என்று மூடன் தன் இருதயத்தில் சொல்லிக்கொள்ளுகிறான்.' மனுபுத்திரர் எல்லாரும் வழிவிலகிப் போனார்கள்; ஒருவனாகிலும் நன்மை செய்கிறவன் இல்லை.",
    "Psalms 15": "பரிசுத்த பர்வதத்தில் தங்குபவன்: கர்த்தருடைய கூடாரத்தில் தங்குபவன் யார்? உத்தமனாய் நடந்து, நீதியைச் செய்து, தன் இருதயத்தில் சத்தியத்தைப் பேசுகிறவனே அவன்.",
    "Psalms 16": "மேன்மையான சுதந்தரம்: 'கர்த்தர் என் சுதந்தரமும் என் பாத்திரத்தின் பங்குமானவர்.' கர்த்தரை எப்போதும் எனக்கு முன்பாக வைத்திருக்கிறேன்; அவர் என் வலதுபாரிசத்தில் இருப்பதால் அசைக்கப்படுவதில்லை.",
    "Psalms 17": "பாதுகாப்பிற்காக ஜெபம்: 'கர்த்தாவே, உம்முடைய கண்ணின் பாவையைப்போல என்னைக் காத்தருளும்.' துன்மார்க்கரிடமிருந்து என்னைத் தப்புவியும்; நான் விழிக்கும்போது உமது சாயலால் திருப்தியாவேன்.",
    "Psalms 18": "மீட்பின் பாடல்: தாவீது தன் சத்துருக்களுக்கும் சவுலுக்கும் தப்புவிக்கப்பட்ட நாளில் பாடியது. 'என் பெலனாகிய கர்த்தாவே, உம்மில் அன்புகூருவேன். அவர் என் கன்மலை, என் கோட்டை.'",
    "Psalms 19": "இயற்கையும் வேதமும்: 'வானங்கள் தேவனுடைய மகிமையை வெளிப்படுத்துகிறது.' கர்த்தருடைய வேதம் குறைவற்றதும், ஆத்துமாவை உயிர்ப்பிக்கிறதுமாயிருக்கிறது.",
    "Psalms 20": "வெற்றிக்கான ஜெபம்: 'ஆபத்துக்காலத்திலே கர்த்தர் உமக்குச் செவிகொடுப்பாராக.' சிலர் இரதங்களைக் குறித்தும், சிலர் குதிரைகளைக் குறித்தும் மேன்மைபாராட்டுகிறார்கள்; நாங்களோ எங்கள் தேவனை முன்னிட்டு மேன்மைபாராட்டுவோம்.",
    "Psalms 21": "ராஜாவின் மகிழ்ச்சி: கர்த்தாவே, உமது பலத்தினால் ராஜா மகிழ்வார். அவர் கேட்ட இருதயத்தின் விருப்பத்தை அவருக்குத் தந்து, அவர் தலையில் பொற்கிரீடம் சூட்டினீர்.",
    "Psalms 22": "சிலுவை முன்னறிவிப்பு: 'என் தேவனே, என் தேவனே, ஏன் என்னைக் கைவிட்டீர்?' என்று தொடங்குகிறது. கிறிஸ்துவின் பாடுகளை விவரிக்கும் விதமாக, அவர்கள் என் ஆடைக்குச் சீட்டுப் போட்டார்கள் என்று கூறுகிறது.",
    "Psalms 23": "நல்ல மேய்ப்பன்: 'கர்த்தர் என் மேய்ப்பராயிருக்கிறார்; நான் தாழ்ச்சியடையேன்.' அவர் என்னைப் புல்லுள்ள இடங்களில் மேய்த்து, அமர்ந்த தண்ணீர்கள் அண்டையில் என்னைக் கொண்டுபோய் விடுகிறார்.",
    "Psalms 24": "மகிமையின் ராஜா: 'பூமியும் அதின் நிறைவும் கர்த்தருடையது.' பரிசுத்த பர்வதத்தில் ஏறுபவன் யார்? கைகளில் சுத்தமுள்ளவனும் இருதயத்தில் மாசில்லாதவனுமே அவன். வாசல்களே, மகிமையின் ராஜா நுழைய உயருங்கள்!",
    "Psalms 25": "வழிகாட்டுதலுக்காக ஜெபம்: 'கர்த்தாவே, உம்முடைய வழிகளை எனக்குத் தெரிவியும்.' இளவயதின் பாவங்களை நினையாமல், உமது இரக்கத்தின்படி என்னை நினைத்தருளும்.",
    "Psalms 26": "உத்தமத்தின் சோதனை: 'கர்த்தாவே, என்னை ஆராய்ந்து சோதித்துப் பாரும்.' நான் துன்மார்க்கரின் கூட்டத்தில் உட்காராமல், உமது பலிபீடத்தைச் சுற்றி வந்து துதிப்பேன்.",
    "Psalms 27": "பயமில்லாத நம்பிக்கை: 'கர்த்தர் என் வெளிச்சமும் என் இரட்சிப்புமானவர், யாருக்குப் பயப்படுவேன்?' ஒரு காரியத்தைக் கர்த்தரிடத்தில் கேட்டேன்: 'நான் உயிரோடிருக்கும் நாளெல்லாம் அவர் ஆலயத்தில் தங்கியிருப்பதே.'",
    "Psalms 28": "கேட்கப்பட்ட ஜெபம்: 'என் கன்மலையாகிய கர்த்தாவே, உம்மை நோக்கிக் கூப்பிடுகிறேன்.' கர்த்தர் என் பெலனும் என் கேடயமுமானவர்; என் இருதயம் அவரை நம்பியிருந்தது.",
    "Psalms 29": "கர்த்தருடைய சத்தம்: 'கர்த்தருடைய சத்தம் தண்ணீர்களின்மேல் தொனிக்கிறது.' பலமுள்ள இடிமுழக்கத்தைப் போன்ற அவருடைய சத்தம் கேதுரு மரங்களை முறிக்கிறது.",
    "Psalms 30": "துக்கம் சந்தோஷமாகும்: 'அவருடைய கோபம் ஒரு நிமிஷம், அவருடைய தயவோ ஆயுள்காலம்.' சாயங்காலத்தில் அழுகை தங்கும், விடியற்காலத்திலே களிப்புண்டாகும்.",
    "Psalms 31": "ஆபத்தில் அடைக்கலம்: 'கர்த்தாவே, உம்மை நம்பியிருக்கிறேன்; நான் ஒருபோதும் வெட்கப்பட்டுப் போகாதபடி செய்யும்.' என் காலங்கள் உமது கரத்தில் இருக்கிறது.",
    "Psalms 32": "மன்னிப்பின் பாக்கியம்: எவனுடைய மீறுதல் மன்னிக்கப்பட்டதோ, அவன் பாக்கியவான். நான் என் பாவத்தை மறைக்காமல் அறிக்கையிட்டபோது, நீர் என் அக்கிரமத்தை மன்னித்தீர்.",
    "Psalms 33": "புதிய பாட்டு: 'நீதிமான்களே, கர்த்தருக்குள் களிகூருங்கள்.' கர்த்தருடைய வார்த்தையினால் வானங்கள் உண்டாயின. அவர் சொல்ல ஆகும், அவர் கட்டளையிட நிற்கும்.",
    "Psalms 34": "ருசித்துப்பார்: 'கர்த்தரை எக்காலத்திலும் ஸ்தோத்தரிப்பேன்.' கர்த்தர் நல்லவர் என்பதை ருசித்துப் பாருங்கள்; அவரை நம்புகிற மனுஷன் பாக்கியவான்.",
    "Psalms 35": "பகைவரிடமிருந்து விடுதலை: 'கர்த்தாவே, என்னோடு வழக்காடுகிறவர்களோடு நீர் வழக்காடும்.' நான் அவர்களுக்கு நன்மை செய்தும், அவர்கள் எனக்குத் தீமை செய்கிறார்கள்; கர்த்தாவே, நீதியைச் செய்யும்.",
    "Psalms 36": "தேவ தயவின் மேன்மை: 'கர்த்தாவே, உமது கிருபை வானங்களில் எட்டுகிறது.' உமது செட்டைகளின் நிழலிலே மனுபுத்திரர் அடைக்கலம் புகுகிறார்கள்; உம்மிடத்தில் ஜீவ ஊற்று இருக்கிறது.",
    "Psalms 37": "பொறுமையாயிரு: 'பொல்லாதவர்களைக் குறித்து எரிச்சலடையாதே.' கர்த்தரிடத்தில் மனமகிழ்ச்சியாயிரு, அவர் உன் இருதயத்தின் வேண்டுதல்களை உனக்கு அருளுவார். நீதிமான் கைவிடப்படுவதில்லை.",
    "Psalms 38": "பாவத்தின் வேதனை: 'கர்த்தாவே, உமது கோபத்தில் என்னைக் கண்டியாதேயும்.' என் அக்கிரமங்கள் என் தலைக்கு மேலாகப் பெருகிற்று; என் பாவம் எப்போதும் எனக்கு முன்பாக இருக்கிறது.",
    "Psalms 39": "வாழ்வின் சுருக்கம்: 'கர்த்தாவே, என் முடிவு என்னவென்று எனக்குத் தெரிவியும்.' ஒவ்வொரு மனுஷனும் ஒரு நிழலைப் போலவே திரிகிறான்; என் நம்பிக்கை உம்மேல் இருக்கிறது.",
    "Psalms 40": "சேற்றிலிருந்து எடுத்தார்: 'கர்த்தருக்காகப் பொறுமையுடன் காத்திருந்தேன்; அவர் அலறுதலைக் கேட்டு, பயங்கரமான குழியிலும் பிசுபிசுப்பான சேற்றிலுமிருந்து என்னைத் தூக்கி எடுத்தார்.'",
    "Psalms 41": "ஏழைகளை நினைப்பவன்: சிறுமைப்பட்டவன்மேல் சிந்தைவைக்கிறவன் பாக்கியவான். என் நண்பனே எனக்கு விரோதமாய்க் குதிங்காலைத் தூக்கினான் (யூதாஸின் காட்டிக்கொடுப்பைக் குறிக்கும் முன்னறிவிப்பு).",
    "Psalms 42": "தாகமுள்ள ஆத்துமா: 'மான் நீரோடைகளை வாஞ்சித்து கதறுவதுபோல, என் ஆத்துமாவே உம்மை வாஞ்சித்துக் கதறுகிறது.' என் ஆத்துமாவே, நீ ஏன் கலங்குகிறாய்? தேவனை நம்பு.",
    "Psalms 43": "ஒளியும் சத்தியமும்: 'உமது ஒளியையும் சத்தியத்தையும் அனுப்பும், அவைகள் என்னை உம்முடைய பரிசுத்த பர்வதத்திற்கு வழிநடத்திச் செல்லட்டும்.' தேவனே, என் மகிழ்ச்சியான சந்தோஷமே!",
    "Psalms 44": "சோதனையில் முறையீடு: 'கர்த்தாவே, விழித்துக்கொள்ளும்; ஏன் தூங்குகிறீர்?' நாங்கள் உம்மை மறக்கவில்லை, ஆனாலும் நாங்கள் கொல்லப்படும் ஆடுகளைப் போல எண்ணப்படுகிறோம்.",
    "Psalms 45": "ராஜாவின் கல்யாணப் பாட்டு: இது மேசியாவாகிய ராஜாவைக் குறித்த பாடல். 'தேவனே, உமது சிங்காசனம் என்றென்றைக்குமுள்ளது; உமது ராஜ்யத்தின் செங்கோல் நீதியுள்ள செங்கோல்.'",
    "Psalms 46": "அஞ்சாத கோட்டை: 'தேவன் நமக்கு அடைக்கலமும் பெலனும், ஆபத்துக்காலத்தில் அநு கூலமான துணையுமானவர்.' பூமி நிலைமாறினாலும் நாங்கள் பயப்படோம். அமர்ந்திருந்து நானே தேவனென்று அறியுங்கள்.",
    "Psalms 47": "சர்வலோக ராஜா: 'ஜனங்களே, கைகொட்டி ஆர்ப்பரியுங்கள்.' தேவன் ஜாதிகளின்மேல் அரசாளுகிறார்; அவர் உயர்ந்த எக்காள சத்தத்தோடே எழுந்தருளுகிறார்.",
    "Psalms 48": "சீயோன் மகிமை: 'எங்கள் தேவனுடைய நகரமாகிய சீயோன் எவ்வளவு அழகானது!' அது வடதிசையிலுள்ள மகாராஜாவின் நகரம். தேவன் என்றென்றைக்கும் நம்மை வழிநடத்துவார்.",
    "Psalms 49": "செல்வத்தின் நிலையாமை: மனுஷன் எவ்வளவு ஐசுவரியவானாய் இருந்தாலும், அவன் சாகும்போது ஒன்றையும் கொண்டுபோவதில்லை. ஆத்தும மீட்பு விலையேறப்பெற்றது; அதை மனுஷனால் செய்ய முடியாது.",
    "Psalms 50": "உண்மையான ஆராதனை: தேவன் பலிகளைவிட ஸ்தோத்திரப் பலியையே விரும்புகிறார். 'ஆபத்துக்காலத்தில் என்னை நோக்கிக் கூப்பிடு, நான் உன்னை விடுவிப்பேன், நீ என்னை மகிமைப்படுத்துவாய்.'",
    "Psalms 51": "மன்னிப்பின் மன்றாட்டு: தாவீது பத்சேபாளுடன் பாவம் செய்தபின் பாடியது. 'தேவனே, உமது கிருபையின்படி எனக்கு இரங்கும். என் அக்கிரமங்கள் நீங்க என்னை முழுதும் கழுவும். சுத்த இருதயத்தை என்னிலே சிருஷ்டியும்.'",
    "Psalms 52": "நாக்கின் தீமை: 'பராக்கிரமசாலியே, நீ தீமையில் ஏன் பெருமைபாராட்டுகிறாய்?' கர்த்தருடைய கிருபையை நம்புகிறவன் தேவனுடைய ஆலயத்தில் பச்சையான ஒலிவமரத்தைப் போலிருப்பான்.",
    "Psalms 53": "மூடனின் எண்ணம்: (சங்கீதம் 14-ன் மறுபதிப்பு). தேவன் இல்லை என்று மூடன் சொல்கிறான். ஜனங்கள் எல்லாரும் கெட்டுப்போனார்கள்; நன்மை செய்கிறவன் ஒருவனுமில்லை.",
    "Psalms 54": "விடுதலைக்காக ஜெபம்: 'தேவனே, உமது நாமத்தினால் என்னை இரட்சியும்.' அந்நியர் எனக்கு விரோதமாய் எழும்புகிறார்கள்; ஆனால் தேவன் எனக்குச் சகாயர்.",
    "Psalms 55": "நண்பனின் துரோகம்: 'புறாவைப் போல எனக்குச் சிறகுகள் இருந்தால் நான் பறந்துபோய் இளைப்பாறுவேன்.' என்னோடு உடன்படிக்கை செய்த நண்பனே எனக்கு விரோதமானான்; ஆனாலும் நான் கர்த்தர்மேல் என் பாரத்தை வைப்பேன்.",
    "Psalms 56": "கண்ணீரின் துருத்தி: 'நான் பயப்படுகிற நாளில் உம்மை நம்புவேன். என் கண்ணீரை உம்முடைய துருத்தியில் வைத்திருக்கிறீர்; அவைகள் உம்முடைய கணக்கில் இல்லையோ?'",
    "Psalms 57": "செட்டைகளின் நிழல்: 'உமது செட்டைகளின் நிழலிலே அடைக்கலம் புகுகிறேன்.' என் இருதயம் ஆயத்தமாயிருக்கிறது; விடியற்காலத்திலே விழித்துத் தேவனைத் துதிப்பேன்.",
    "Psalms 58": "அநீதியான நியாயாதிபதிகள்: பூமியில் நீதியைத் தீர்க்கிறீர்களா? துன்மார்க்கர் பிறந்ததுமுதல் வழிவிலகிப் போகிறார்கள். கர்த்தர் அவர்களுக்கு நீதியான தண்டனை வழங்குவார்.",
    "Psalms 59": "பாதுகாப்பின் பாடல்: சவுல் தாவீதைக் கொல்ல ஆள் அனுப்பியபோது பாடியது. 'என் பெலனே, உம்மை நோக்கிப் பாடுவேன்; தேவன் எனக்கு உயர்ந்த அடைக்கலமானவர்.'",
    "Psalms 60": "தோல்வியின் மத்தியிலும் ஜெபம்: 'தேவனே, எங்களைக் கைவிட்டீரோ?' மனுஷனுடைய சகாயம் வீண்; தேவனாலே பராக்கிரமம் செய்வோம், அவரே எங்கள் சத்துருக்களை மிதிப்பார்.",
    "Psalms 61": "உயர்ந்த கன்மலை: 'என் இருதயம் தியங்கும்போது பூமியின் கடைசியிலிருந்து உம்மை நோக்கிக் கூப்பிடுவேன்; எனக்கு எட்டாத உயரமான கன்மலையில் என்னைக் கொண்டுபோய்விடும்.'",
    "Psalms 62": "அமைதியான நம்பிக்கை: 'என் ஆத்துமா தேவனை நோக்கியே அமர்ந்திருக்கிறது; அவராலே என் இரட்சிப்பு வரும்.' மனுஷர் ஒரு மாயை, தராசிலே வைத்தால் அவர்கள் காற்றுக்குச் சமம்.",
    "Psalms 63": "வனாந்தரத் தாகம்: 'தேவனே, நீர் என் தேவன்; அதிகாலமே உம்மைத் தேடுகிறேன்.' வறண்ட நிலத்தில் தண்ணீர் மேல் தாகமாயிருப்பது போல என் ஆத்துமா உம்மை வாஞ்சிக்கிறது.",
    "Psalms 64": "பகைவரின் அம்புகள்: பொல்லாதவர்கள் தங்கள் நாக்கைப் பட்டயத்தைப் போலக் கூர்மையாக்குகிறார்கள். ஆனால் தேவன் அவர்கள்மேல் அம்புகளை எய்வார்; அவர்கள் திடீரெனக் காயப்படுவார்கள்.",
    "Psalms 65": "அறுவடைத் துதி: தேவனே, சீயோனில் உமக்குத் துதி காத்திருக்கிறது. நீர் பூமியைச் சந்தித்து அதற்கு நீர்ப்பாய்ச்சி, வருஷத்தை நன்மையால் முடிசூட்டுகிறீர்.",
    "Psalms 66": "அதிசயமான செயல்கள்: 'பூமியே, தேவனுக்குச் சந்தோஷமாய் ஆர்ப்பரியுங்கள்.' அவர் செய்த கிரியைகளை வந்து பாருங்கள்; அவர் மனுபுத்திரரிடத்தில் பயங்கரமான கிரியை செய்கிறார்.",
    "Psalms 67": "தேசங்களின் ஆசீர்வாதம்: 'தேவன் நமக்கு இரங்கி, நம்மை ஆசீர்வதிப்பாராக.' பூமியில் உம்முடைய வழியும், சகல ஜாதிகளுக்குள்ளும் உம்முடைய இரட்சிப்பும் அறியப்படும்படியாகவே இதை வேண்டுகிறோம்.",
    "Psalms 68": "ஜெயமுயர்த்தும் தேவன்: 'தேவன் எழுந்தருளுவார், அவருடைய சத்துருக்கள் சிதறுண்டு போவார்கள்.' அவர் திக்கற்ற பிள்ளைகளுக்குத் தகப்பனும், விதவைகளுக்கு நியாயாதிபதியுமாயிருக்கிறார்.",
    "Psalms 69": "ஆழமான வெள்ளம்: 'தேவனே, என்னை இரட்சியும், தண்ணீர் என் ஆத்துமா வரைக்கும் எட்டுகிறது.' கிறிஸ்துவின் பாடுகளைப் போல, 'என் தாகத்திற்கு வினிகொடுத்தார்கள்' என்று இதில் கூறப்பட்டுள்ளது.",
    "Psalms 70": "விரைவான உதவி: 'தேவனே, என்னை விடுவிக்கத் தகுதி செய்யும்; கர்த்தாவே, எனக்குச் சகாயம் செய்யத் தீவிரியும்.' நான் தேவையுள்ளவன், நீர் என் உதவியாளர்.",
    "Psalms 71": "முதிர்வயதின் ஜெபம்: 'என் முதிர்வயதில் என்னைக் கைவிடாதேயும்; என் பெலன் ஒடுங்கும்போது என்னை விட்டு விலகாதேயும்.' நான் இடைவிடாமல் உம்மைத் துதிப்பேன்.",
    "Psalms 72": "ராஜ்யத்தின் நீதி: சாலொமோனுக்காகப் பாடப்பட்டது. 'அவருடைய நாமம் என்றென்றைக்கும் இருக்கும்; சூரியன் உள்ளவரைக்கும் அவருடைய நாமம் நிலைக்கும்.' இதோடு தாவீதின் விண்ணப்பங்கள் முடிகிறது.",
    "Psalms 73": "துன்மார்க்கரின் செழிப்பு: ஆசாபின் சங்கீதம். துன்மார்க்கர் சுகமாய் வாழ்வதைக் கண்டு நான் இடறினேன். ஆனால் தேவனுடைய பரிசுத்த ஸ்தலத்திற்குள் நுழைந்தபோதுதான் அவர்கள் முடிவை உணர்ந்தேன்.",
    "Psalms 74": "ஆலய அழிவிற்காகப் புலம்பல்: 'சத்துரு பரிசுத்த ஸ்தலத்தில் எல்லாவற்றையும் அழித்தான்.' கர்த்தாவே, உமது உடன்படிக்கையை நினைத்தருளும்; தேசம் கொடுமையுள்ள இடங்களால் நிறைந்திருக்கிறது.",
    "Psalms 75": "தேவனே நியாயாதிபதி: 'நியாயத்தீர்ப்பு கிழக்கிலிருந்தும் மேற்கிலிருந்தும் வருவதில்லை; தேவனே நியாயாதிபதி, அவர் ஒருவனைத் தாழ்த்தி ஒருவனை உயர்த்துகிறார்.'",
    "Psalms 76": "பயங்கரமான தேவன்: யூதாவிலே தேவன் அறியப்பட்டவர். மனுஷனுடைய கோபம் உம்மைத் துதிக்கும்; கோபத்தின் மீதியை நீர் அடக்குவீர்.",
    "Psalms 77": "கடந்த கால நினைவுகள்: 'என் கவலைகளில் நான் இராக்காலத்தில் என் கையை விரித்துத் தேடினேன்.' கர்த்தருடைய பழைய அற்புதங்களை நான் தியானிப்பேன்; உமது வழி கடலிலே இருக்கிறது.",
    "Psalms 78": "சரித்திரப் பாடம்: இஸ்ரவேலின் வரலாற்றை அடுத்த சந்ததிக்குச் சொல்லும் நீண்ட பாடல். தேவன் செய்த அற்புதங்களை மறந்ததால் அவர்கள் வனாந்தரத்தில் சோதிக்கப்பட்டனர்.",
    "Psalms 79": "எருசலேமின் அழிவு: 'புறஜாதிகள் உமது சுதந்தரத்தில் வந்து, எருசலேமை மண்மேடாக்கினார்கள்.' எருசலேமைச் சுற்றியுள்ள இரத்தம் தண்ணீரைப் போலச் சிந்தப்பட்டது; கர்த்தாவே இரங்கும்.",
    "Psalms 80": "இஸ்ரவேலின் மேய்ப்பர்: 'இஸ்ரவேலின் மேய்ப்பரே, செவிகொடும்.' நீர் எகிப்திலிருந்து ஒரு திராட்சச் செடியைக் கொண்டுவந்தீர்; அதைத் திரும்பவும் செழிக்கச் செய்யும்.",
    "Psalms 81": "எக்காளம் ஊதுங்கள்: பண்டிகை நாளில் எக்காளம் ஊதி தேவனைத் துதியுங்கள். 'என் ஜனமே, கேள்; எனக்குச் செவிகொடுத்தால், நான் உன்னை உன்னதமான கோதுமையினால் போஷிப்பேன்.'",
    "Psalms 82": "தேவன் நியாயாதிபதி: தேவன் தேவர்களின் சபையிலே நிற்கிறார். 'எதுவரைக்கும் அநியாயமாய் நியாயந்தீர்ப்பீர்கள்? திக்கற்றவனுக்கும் எளியவனுக்கும் நியாயஞ்செய்யுங்கள்.'",
    "Psalms 83": "பகைவரின் சதி: இஸ்ரவேலை அழிக்கப் பல ஜாதிகள் ஆலோசனை செய்கிறார்கள். கர்த்தாவே, நீர் ஒருவரே பூமியனைத்தின் மேலும் உன்னதமானவர் என்று அவர்கள் அறியும்படிச் செய்யும்.",
    "Psalms 84": "ஆலய வாஞ்சை: 'சேனைகளின் கர்த்தாவே, உமது வாசஸ்தலங்கள் எவ்வளவு இன்பமானவைகள்!' உமது பிரகாரங்களில் தங்கியிருக்கும் ஒரு நாள், வேறெங்கும் ஆயிரம் நாளைவிட மேலானது.",
    "Psalms 85": "இரக்கமும் சத்தியமும்: 'கிருபையும் சத்தியமும் ஒன்றையொன்று சந்திக்கும்; நீதியும் சமாதானமும் ஒன்றையொன்று முத்தமிடும்.' தேவன் தம்முடைய ஜனங்களுக்குச் சமாதானம் கூறுவார்.",
    "Psalms 86": "தாவீதின் ஜெபம்: 'கர்த்தாவே, உமது வழியை எனக்குப் போதியும்; நான் உமது சத்தியத்திலே நடப்பேன்.' நீர் ஒருவரே தேவன், நீர் உருக்கமும் இரக்கமுமுள்ளவர்.",
    "Psalms 87": "சீயோனின் பெருமை: கர்த்தர் சீயோனின் வாசல்களை நேசிக்கிறார். 'இவன் அங்கே பிறந்தான்' என்று ஜாதிகளுக்குள்ளே சீயோனைக் குறித்துக் கூறப்படும்.",
    "Psalms 88": "இருண்ட நேரத்தின் கதறல்: இது மிகவும் துக்ககரமான சங்கீதம். 'என் பிராணனைப் பாதாளம் நெருங்குகிறது.' நண்பர்களும் உறவினர்களும் என்னை விட்டுத் தூரமானார்கள்.",
    "Psalms 89": "உடன்படிக்கையின் உறுதி: தாவீதுக்குக் கொடுத்த வாக்குத்தத்தத்தைப் புகழும் பாடல். 'உமது கிருபையை என்றென்றைக்கும் பாடுவேன்.' தேவன் தம்முடைய உடன்படிக்கையை ஒருபோதும் மீறமாட்டார்.",
    "Psalms 90": "மோசேயின் ஜெபம்: இது மிகப்பழைய சங்கீதம். 'ஆண்டவரே, தலைமுறை தலைமுறையாக நீர் எங்களுக்கு அடைக்கலமானவர்.' எங்கள் நாட்களை எண்ணும் அறிவை எங்களுக்குப் போதியும்.",
    "Psalms 91": "உன்னதமானவரின் மறைவு: 'உன்னதமானவரின் மறைவில் இருக்கிறவன் சர்வவல்லவருடைய நிழலில் தங்குவான்.' அவர் உன்னைத் தமது செட்டைகளாலே மூடுவார்; ஒரு பொல்லாப்பும் உனக்கு நேரிடாது.",
    "Psalms 92": "ஓய்வுநாளின் துதி: கர்த்தரைத் துதிப்பது நல்லது. நீதிமான் பனைமரத்தைப் போலச் செழித்து, லீபனோனிலுள்ள கேதுருவைப் போல வளருவான். அவர் முதிர்வயதிலும் கனி தந்து பசுமையாய் இருப்பார்.",
    "Psalms 93": "கர்த்தர் அரசாளுகிறார்: கர்த்தர் ராஜரீகம் பண்ணுகிறார், அவர் மகத்துவத்தை ஆடையாக உடுத்தியிருக்கிறார். பெருவெள்ளங்களின் சத்தத்தைவிடக் கர்த்தர் வல்லமையுள்ளவர்.",
    "Psalms 94": "நீதிபதி எழும்புவார்: 'மனுஷனுடைய எண்ணங்கள் வீணென்று கர்த்தர் அறிந்திருக்கிறார்.' கர்த்தர் தம்முடைய ஜனத்தைக் கைவிடமாட்டார்; அவர் அநீதியான சிங்காசனத்திற்குத் துணைநிற்கமாட்டார்.",
    "Psalms 95": "ஆராதனைக்கு அழைப்பு: 'வாருங்கள், கர்த்தரைப் பாடி, நம்முடைய இரட்சிப்பின் கன்மலையைச் சங்கீர்த்தனம் பண்ணக்கடவோம்.' இன்று அவருடைய சத்தத்தைக் கேட்பீர்களாகில், உங்கள் இருதயத்தைக் கடினப்படுத்தாதேயுங்கள்.",
    "Psalms 96": "புதிய பாட்டு: 'பூமியின் குடிகளே, கர்த்தருக்குப் புதிய பாட்டைப் பாடுங்கள்.' அவர் நீதியோடு ஜாதிகளை நியாயந்தீர்க்க வருகிறார்; வானங்கள் மகிழ்ந்து பூமி பூரிப்பதாக.",
    "Psalms 97": "தேவ மகிமையின் பிரகாசம்: கர்த்தர் அரசாளுகிறார், பூமி மகிழக்கடவது. பர்வதங்கள் கர்த்தருடைய சமுகத்தில் மெழுகுபோல உருகும். நீதிமான்களுக்கு வெளிச்சம் விதைக்கப்பட்டிருக்கிறது.",
    "Psalms 98": "இரட்சிப்பின் கீதம்: கர்த்தர் தமது இரட்சிப்பைத் தெரியப்படுத்தினார். ஆறுகள் கைகொட்டி, பர்வதங்கள் ஏகமாய் கம்பீரிக்கக்கடவது; அவர் உலகத்தை நீதியாய் நியாயந்தீர்ப்பார்.",
    "Psalms 99": "பரிசுத்தமானவர்: கர்த்தர் பெரியவர், அவர் பரிசுத்தமுள்ளவர். மோசே, ஆரோன், சாமுவேல் ஆகியோர் அவரை நோக்கிக் கூப்பிட்டார்கள்; அவர் அவர்களுக்குப் பதில் அளித்தார்.",
    "Psalms 100": "நன்றி செலுத்துதல்: 'பூமியின் குடிகளே, எல்லாரும் கர்த்தருக்குச் சந்தோஷமாய் ஆர்ப்பரியுங்கள்.' மகிழ்ச்சியோடு ஆராதனை செய்யுங்கள்; அவர் நல்லவர், அவர் கிருபை என்றென்றைக்குமுள்ளது.",
    "Psalms 101": "உத்தம மார்க்கம்: தாவீதின் தீர்மானம். 'நான் என் வீட்டிற்குள்ளே உத்தம இருதயத்தோடே நடப்பேன்.' தீய காரியங்களை என் கண்ணுக்கு முன் வைக்கமாட்டேன்; துன்மார்க்கரை அகற்றுவேன்.",
    "Psalms 102": "சிறுமைப்பட்டவனின் விண்ணப்பம்: 'என் நாட்கள் புகையைப்போலப் பறந்துபோயிற்று.' கர்த்தரோ என்றென்றைக்கும் இருப்பவர். அவர் சீயோனைக் கட்டி, தம்முடைய மகிமையில் வெளிப்படுவார்.",
    "Psalms 103": "நன்மைகளை மறவாதே: 'என் ஆத்துமாவே, கர்த்தரை ஸ்தோத்தரி; அவர் செய்த சகல உபகாரங்களையும் மறவாதே.' தகப்பன் தன் பிள்ளைகளுக்கு இரங்குகிறதுபோல, கர்த்தர் தமக்குப்பயந்தவர்களுக்கு இரங்குகிறார்.",
    "Psalms 104": "சிருஷ்டிப்பின் கீதம்: தேவன் ஒளியை ஆடையாக உடுத்தியிருக்கிறார். அவர் பூமிக்கும், கடலுக்கும், மிருகங்களுக்கும் தேவையானதைத் தந்து பராமரிக்கிறார். கர்த்தருடைய மகிமை என்றென்றைக்குமுள்ளது.",
    "Psalms 105": "வரலாற்றுத் துதி: ஆபிரகாம் முதல் கானான் தேசம் வரை இஸ்ரவேலரைத் தேவன் வழிநடத்திய விதம். அவர் எகிப்தில் செய்த அற்புதங்களையும், வனாந்தரத்தில் தந்த மன்னாவையும் நினைவுகூருகிறது.",
    "Psalms 106": "ஜனங்களின் துரோகம்: தேவன் செய்த நன்மைகளை மறந்த இஸ்ரவேலரின் பாவம். அவர்கள் விக்கிரகங்களை வணங்கினாலும், கர்த்தர் தம்முடைய உடன்படிக்கையை நினைத்து அவர்களைத் தப்புவித்தார்.",
    "Psalms 107": "மீட்கப்பட்டவர்களின் பாடல்: வனாந்தரத்தில் அலைந்தவர்கள், சிறையில் இருந்தவர்கள், கடலில் தத்தளித்தவர்கள் கர்த்தரை நோக்கிக் கூப்பிட்டபோது அவர் அவர்களை விடுவித்தார். 'அவர் கிருபை என்றும் உள்ளது.'",
    "Psalms 108": "ஜெயத்தின் நிச்சயம்: 'என் இருதயம் ஆயத்தமாயிருக்கிறது; நான் பாடிக் கீர்த்தனம் பண்ணுவேன்.' மனுஷனுடைய சகாயம் வீண், தேவனாலே பராக்கிரமம் செய்வோம்.",
    "Psalms 109": "பகைவருக்கு எதிரான ஜெபம்: தாவீது தன்னை நிந்தித்தவர்களுக்கு எதிராக நியாயம் கேட்கிறார். 'அவர்கள் சபிக்கட்டும், நீர் ஆசீர்வதியும்.' கர்த்தர் எளியவனுடைய வலதுபாரிசத்தில் நிற்கிறார்.",
    "Psalms 110": "மேசியாவின் அதிகாரம்: 'கர்த்தர் என் ஆண்டவரை நோக்கி: நான் உம்முடைய சத்துருக்களை உமக்குத் பாதப்படியாக்கிப்போடும் வரைக்கும், நீர் என்னுடைய வலதுபாரிசத்தில் உட்காரும் என்றார்.'",
    "Psalms 111": "கர்த்தரின் கிரியைகள்: கர்த்தரைத் துதியுங்கள். அவருடைய கிரியைகள் ஆராய்ந்து முடியாவதைகள். 'கர்த்தருக்குப் பயப்படுதலே ஞானத்தின் ஆரம்பம்.'",
    "Psalms 112": "நீதிமானின் பாக்கியம்: கர்த்தருக்குப் பயந்து அவர் கட்டளைகளில் பிரியமாயிருக்கிற மனுஷன் பாக்கியவான். அவனுடைய சந்ததி பூமியில் பலத்திருக்கும்; அவனுக்கு அந்தகாரத்தில் வெளிச்சம் உதிக்கும்.",
    "Psalms 113": "உன்னதமான தேவன்: சூரியன் உதிக்கும் திசைமுதல் அஸ்தமிக்கும் திசைவரை கர்த்தருடைய நாமம் துதிக்கப்படக்கடவது. அவர் எளியவனைப் புழுதியிலிருந்து தூக்கிவிடுகிறார்.",
    "Psalms 114": "எகிப்திலிருந்து விடுதலை: இஸ்ரவேல் எகிப்திலிருந்து புறப்பட்டபோது, கடல் கண்டு ஓடியது, யோர்தான் பின்னிட்டுத் திரும்பியது. கன்மலையைத் தண்ணீர்த்தடாகமாக மாற்றின தேவனுக்குப் பயப்படுங்கள்.",
    "Psalms 115": "உயிருள்ள தேவன்: 'எங்களுக்கு அல்ல கர்த்தாவே, உமது நாமத்திற்கே மகிமை உண்டாவதாக.' புறஜாதிகளின் விக்கிரகங்கள் வாய் இருந்தும் பேசாது; ஆனால் இஸ்ரவேலே, கர்த்தரை நம்பு.",
    "Psalms 116": "அன்பின் அறிக்கை: 'கர்த்தர் என் சத்தத்தைக் கேட்டதினால், அவரில் அன்புகூருகிறேன்.' எனக்குச் செய்த எல்லா உபகாரங்களுக்காகவும் நான் அவருக்கு என்னத்தைச் செலுத்துவேன்?",
    "Psalms 117": "மிகச்சிறிய சங்கீதம்: 'ஜாதிகளே, எல்லாரும் கர்த்தரைத் துதியுங்கள்; ஜனங்களே, எல்லாரும் அவரைப் போற்றுங்கள்.' அவர் கிருபை நமமேல் உறுதியாயிருக்கிறது.",
    "Psalms 118": "கர்த்தரின் தயவு: 'கர்த்தரைத் துதியுங்கள், அவர் நல்லவர்.' மனுஷனை நம்புவதைவிட கர்த்தர்மேல் பற்றுதலாயிருப்பதே நலம். வீடுகட்டுகிறவர்கள் தள்ளின கல்லே மூலைக்குத் தலைக்கல்லாயிற்று.",
    "Psalms 119": "வேதத்தின் மேன்மை: இது வேதாகமத்தின் மிக நீளமான அதிகாரம் (176 வசனங்கள்). தேவனுடைய வார்த்தையின் வல்லமையையும், அதன் அழகையும் ஏபிசிடி (Acrostic) வரிசையில் விவரிக்கிறது.",
    "Psalms 120": "நெருக்கத்தில் கூப்பிடுதல்: (யாத்திரைப் பாடல் - 1). 'என் நெருக்கத்தில் கர்த்தரை நோக்கிக் கூப்பிட்டேன், அவர் எனக்குச் செவிகொடுத்தார்.' பொய் பேசுகிற உதடுகளுக்கு என்னைத் தப்புவியும்.",
    "Psalms 121": "ஒத்தாசை வரும் பர்வதம்: 'எனக்கு ஒத்தாசை வரும் பர்வதங்களுக்கு நேராக என் கண்களை ஏறெடுக்கிறேன்; கர்த்தரிடத்திலிருந்து எனக்கு ஒத்தாசை வரும்.' அவர் உன்னைத் தூங்காமல் காப்பார்.",
    "Psalms 122": "எருசலேமின் அமைதி: 'கர்த்தருடைய ஆலயத்திற்குப் போவோம் வாருங்கள் என்று எனக்குச் சொன்னபோது மகிழ்ச்சியாயிருந்தேன்.' எருசலேமின் சமாதானத்திற்காக வேண்டிக்கொள்ளுங்கள்.",
    "Psalms 123": "உயரத்திலிருப்பவர்: 'பரலோகத்தில் வாசமாயிருக்கிறவரே, உம்மிடத்திற்கு என் கண்களை ஏறெடுக்கிறேன்.' வேலைக்காரன் தன் எஜமானின் கையை நோக்கியிருப்பது போல நாங்கள் உம்மை நோக்குகிறோம்.",
    "Psalms 124": "தப்புவித்தவர் கர்த்தர்: 'கர்த்தர் நம்முடைய பட்சத்தில் இல்லாவிட்டால், மனுஷர் நம்மை உயிரோடு விழுங்கியிருப்பார்கள்.' தப்பியோடிய பறவையைப் போல நாம் தப்பினோம்.",
    "Psalms 125": "சீயோன் பர்வதம்: 'கர்த்தரை நம்புகிறவர்கள் என்றென்றைக்கும் அசையாமல் நிலைத்திருக்கும் சீயோன் பர்வதத்தைப் போலிருப்பார்கள்.' மலைகள் எருசலேமைச் சுற்றியிருப்பது போல கர்த்தர் நம்மைச் சுற்றியிருக்கிறார்.",
    "Psalms 126": "கண்ணீரோடு விதைப்பவன்: 'கர்த்தர் சீயோனின் சிறையிருப்பைத் திருப்பினபோது சொப்பனம் காண்கிறவர்களைப் போலிருந்தோம்.' கண்ணீரோடு விதைக்கிறவன் கம்பீரத்தோடே அறுப்பான்.",
    "Psalms 127": "கர்த்தரே கட்டுபவர்: 'கர்த்தர் வீட்டைக் கட்டாராகில் அதைக்கட்டுகிறவர்களின் பிரயாசம் வீண்.' பிள்ளைகள் கர்த்தர் அருளும் சுதந்தரம்; அவர்கள் அம்புகளைப் போன்றவர்கள்.",
    "Psalms 128": "குடும்ப ஆசீர்வாதம்: கர்த்தருக்குப் பயந்து அவர் வழிகளில் நடக்கிறவன் பாக்கியவான். உன் மனைவி கனிதரும் திராட்சக்கொடியைப் போலவும், உன் பிள்ளைகள் ஒலிவமரக் கன்றுகளைப் போலவும் இருப்பார்கள்.",
    "Psalms 129": "சத்துருக்களின் வீழ்ச்சி: 'என் சிறுவயதுமுதல் அவர்கள் என்னை மிகவும் நெருக்கினார்கள்; ஆனாலும் அவர்கள் என்னை மேற்கொள்ளவில்லை.' கர்த்தர் நீதியுள்ளவர், அவர் துன்மார்க்கரின் கயிறுகளை அறுத்தார்.",
    "Psalms 130": "ஆழங்களிலிருந்து: 'ஆழங்களிலிருந்து உம்மை நோக்கிக் கூப்பிடுகிறேன்.' கர்த்தாவே, நீர் அக்கிரமங்களைக் கவனிப்பீரானால் யார் நிலைநிற்பார்? ஆனால் உம்மிடத்தில் மன்னிப்பு உண்டு.",
    "Psalms 131": "குழந்தையைப் போன்ற அமைதி: 'என் இருதயம் மேட்டிமையுள்ளதல்ல.' தாயின் மார்பில் பால் மறந்த குழந்தையைப் போல என் ஆத்துமாவை அமைதிப்படுத்தினேன்.",
    "Psalms 132": "தாவீதுக்குச் செய்த உடன்படிக்கை: தாவீது கர்த்தருடைய ஆலயத்திற்காகக் காட்டிய வைராக்கியம். 'கர்த்தர் சீயோனைத் தெரிந்துகொண்டார்; அது அவர் தங்கும் நித்திய வாசஸ்தலம்.'",
    "Psalms 133": "சகோதர ஒற்றுமை: 'சகோதரர் ஒருமித்து வாசம்பண்ணுகிறது எவ்வளவு நன்மையும் எவ்வளவு இன்பமுமானது!' அது ஆரோனின் தாடியில் இறங்கும் தைலத்திற்கும், எர்மோன் பனிக்கும் ஒப்பானது.",
    "Psalms 134": "இரவுத் துதி: 'இரவுநேரத்தில் கர்த்தருடைய ஆலயத்தில் நிற்கும் கர்த்தரின் ஊழியக்காரரே, கர்த்தரை ஸ்தோத்தரியுங்கள்.' சீயோனிலிருந்து கர்த்தர் உன்னை ஆசீர்வதிப்பாராக.",
    "Psalms 135": "பெரியவர் கர்த்தர்: எகிப்தில் அடையாளங்களைச் செய்து, பல ஜாதிகளை அழித்த கர்த்தரைத் துதியுங்கள். புறஜாதிகளின் விக்கிரகங்கள் வாய் இருந்தும் பேசாது, ஆனால் கர்த்தர் வல்லமையுள்ளவர்.",
    "Psalms 136": "என்றென்றும் உள்ள கிருபை: (இராகப் பாடல்). ஒவ்வொரு வசனமும் 'அவர் கிருபை என்றுமுள்ளது' (His mercy endureth forever) என்று முடிகிறது. சிருஷ்டிப்பு முதல் விடுதலை வரை அவர் கிருபையைப் போற்றுகிறது.",
    "Psalms 137": "பாபிலோன் நதிக்கரையில்: 'பாபிலோன் ஆறுகளண்டையிலே நாங்கள் உட்கார்ந்து சீயோனை நினைத்து அழுதோம்.' அந்நிய தேசத்தில் கர்த்தருடைய பாட்டை எப்படிப் பாடுவோம்?",
    "Psalms 138": "முழு இருதயத்தோடு துதி: 'தேவர்களெல்லாருக்கு முன்பாகவும் உம்மைப் புகழ்வேன்.' கர்த்தர் உன்னதமானவராயிருந்தும், தாழ்மையுள்ளவனை நோக்கிப் பார்க்கிறார்.",
    "Psalms 139": "எல்லாவற்றையும் அறிந்தவர்: 'கர்த்தாவே, நீர் என்னை ஆராய்ந்து அறிந்திருக்கிறீர்.' நான் எங்கே போனாலும் உம்முடைய ஆவிக்குத் தப்ப முடியாது. அதிசயமாகவும் பயங்கரமாகவும் உண்டாக்கப்பட்டேன்.",
    "Psalms 140": "தீயவரிடமிருந்து பாதுகாப்பு: 'பொல்லாத மனுஷனுக்கு என்னைத் தப்புவியும்.' அவர்கள் தங்கள் நாக்கைப் பாம்பைப் போலக் கூர்மையாக்குகிறார்கள்; கர்த்தாவே, என்னை மூடிருளும்.",
    "Psalms 141": "காப்பாற்றும் ஜெபம்: 'என் ஜெபம் உமக்கு முன்பாகத் தூபமாகவும், என் கைகளை ஏறெடுப்பது சாயங்காலப் பலியாகவும் இருப்பதாக.' என் வாய்க்கு ஒரு காவலை வையும்.",
    "Psalms 142": "கெபியிலிருந்து கூப்பிடுதல்: தாவீது கெபியில் இருந்தபோது பாடியது. 'நீர் என் அடைக்கலம்; உயிரோடிருப்பவர்களின் தேசத்தில் நீர் என் பங்கு.'",
    "Psalms 143": "உயிர்ப்பிக்கும் ஜெபம்: 'என் ஆவி என்னில் தியங்குகிறது; என் இருதயம் எனக்குள் திகைக்கிறது.' உமது நல்ல ஆவி என்னைச் செம்மையான வழியில் நடத்தட்டும்.",
    "Psalms 144": "யுத்தத்திற்குப் பெலன்: 'என் கைகளை யுத்தத்திற்கும், என் விரல்களைப் போருக்கும் பழக்குவிக்கிற என் கன்மலையாகிய கர்த்தருக்கு ஸ்தோத்திரம்.' கர்த்தரைத் தெய்வமாகக் கொண்ட ஜனம் பாக்கியமுள்ளது.",
    "Psalms 145": "ராஜாவாகிய தேவன்: 'என் ராஜாவாகிய தேவனே, உம்மை உயர்த்துவேன்.' கர்த்தர் எல்லாருக்கும் நல்லவர், அவருடைய இரக்கங்கள் அவருடைய எல்லாச் செயல்களின்மேலும் உள்ளது.",
    "Psalms 146": "மனுஷனை நம்பாதே: 'பிரபுக்களையும் மனுபுத்திரனையும் நம்பாதேயுங்கள்.' யாக்கோபின் தேவனைத் தன் துணையாகக் கொண்டவன் பாக்கியவான்; அவர் குருடரின் கண்களைத் திறக்கிறார்.",
    "Psalms 147": "சகலத்தையும் பராமரிப்பவர்: 'எருசலேமே, கர்த்தரைத் துதி.' அவர் நட்சத்திரங்களின் எண்ணிக்கையை அறிந்திருக்கிறார்; அவர் பனிக்கும் மழைக்கும் தேவன்; அவர் யாக்கோபுக்குத் தமது வார்த்தைகளை அறிவிக்கிறார்.",
    "Psalms 148": "சர்வ சிருஷ்டியின் துதி: வானத்திலுள்ளவைகளே, தூதர்களே, சூரிய சந்திரர்களே, நட்சத்திரங்களே, கடல்களே, மிருகங்களே, ராஜாக்களே, வாலிபர்களே—யாவரும் கர்த்தரைத் துதிக்கக்கடவீர்கள்.",
    "Psalms 149": "புதிய பாடல்: 'பரிசுத்தவான்களின் சபையிலே அவருக்குத் துதி உண்டாவதாக.' இஸ்ரவேல் தன் சிருஷ்டிகரில் மகிழக்கடவது; அவர்கள் நடனத்தோடும் தம்புருவோடும் அவரைத் துதிக்கக்கடவர்கள்.",
    "Psalms 150": "முடிவுரை: 'சுவாசம் உள்ள யாவும் கர்த்தரைத் துதிப்பதாக. அல்லேலூயா!' எக்காள சத்தத்தோடும், வீணையோடும், சுரமண்டலத்தோடும், தாளங்களோடும் கர்த்தரைத் துதியுங்கள்.",

    "Proverbs 1": "ஞானத்தின் நோக்கம்: வாலிபருக்கு அறிவையும் விவேகத்தையும் தருவதே இந்நுாலின் நோக்கம். 'கர்த்தருக்குப் பயப்படுதலே ஞானத்தின் ஆரம்பம்.' ஞானம் வீதிகளிலே நின்று கூப்பிடுகிறது; மூடரோ அதை அலட்சியம் செய்கிறார்கள்.",
    "Proverbs 2": "ஞானத்தினால் வரும் நன்மைகள்: நீ ஞானத்தைத் தேடினால், அது உன்னைத் துன்மார்க்கரின் வழிக்கும், அந்நிய ஸ்திரீயின் வலைக்கும் தப்புவித்து, நீதிமான்களின் பாதையில் நடத்தும்.",
    "Proverbs 3": "கர்த்தரை நம்புதல்: 'உன் சுயபுத்தியின்மேல் சாயாமல், உன் முழு இருதயத்தோடும் கர்த்தரில் நம்பிக்கையாயிரு.' உன் வருமானத்தில் முதற்பலனை அவருக்குக் கொடு; அவர் உன் பாதைகளைச் செவ்வைப்படுத்துவார்.",
    "Proverbs 4": "தகப்பனின் போதனை: ஞானமே முக்கியம், ஞானத்தைச் சம்பாதி. உன் இருதயத்தை எல்லாக் காவலோடும் காத்துக்கொள்; அதினின்றே ஜீவஊற்று புறப்படும். தீய வழியை விட்டு விலகு.",
    "Proverbs 5": "விபசாரத்திற்கு எச்சரிக்கை: அந்நிய ஸ்திரீயின் உதடுகள் தேன்கூடுபோலத் துளிக்கும், ஆனால் அவள் முடிவு எட்டியளவு கசப்பானது. உன் இளவயதின் மனைவியோடு மகிழ்ச்சியாயிரு; அந்நிய இச்சையில் சிக்காதே.",
    "Proverbs 6": "சோம்பலும் பிணையும்: சோம்பேறியே, எறும்பினிடத்தில் போய் அதின் வழிகளைப் பார்த்து ஞானத்தைக் கற்றுக்கொள். தேவன் வெறுக்கும் ஏழு காரியங்கள்: மேட்டிமையான கண், பொய்நாக்கு, குற்றமற்ற இரத்தம் சிந்துதல் போன்றவை.",
    "Proverbs 7": "மதியீனனின் முடிவு: ஒரு மதியீனன் வேசியின் பின்னே போவதை, ஒரு மாடு அடிக்கப்படும் இடத்திற்குப் போவதற்கும், ஒரு பறவை கண்ணியில் விழுவதற்கும் ஒப்பிடப்படுகிறது. அவளுடைய வீடு பாதாளத்திற்குப் போகும் வழி.",
    "Proverbs 8": "ஞானத்தின் நித்தியம்: ஞானம் ஒரு நபராய் நின்று பேசுகிறது. உலகம் சிருஷ்டிக்கப்படும் முன்னே நான் இருந்தேன்; என்னைக் கண்டடைகிறவன் ஜீவனைக் கண்டடைகிறான். கர்த்தருக்குப் பயப்படுதலே தீமையை வெறுப்பதாகும்.",
    "Proverbs 9": "இரண்டு விருந்துகள்: ஞானம் ஒரு விருந்துக்கு அழைக்கிறது; அறியாமையும் (Folly) ஒரு விருந்துக்கு அழைக்கிறது. ஞானவானைக் கடிந்துகொண்டால் அவன் இன்னும் ஞானமடைவான்; பரியாசக்காரனோ உன்னைப் பகைப்பான்.",
    "Proverbs 10": "நீதிமானும் துன்மார்க்கனும்: சாலொமோனின் நீதிமொழிகள் தொடங்குகின்றன. சோம்பேறிக் கை தரித்திரத்தை உண்டாக்கும்; ஜாக்கிரதையுள்ளவன் கையோ செல்வத்தை உண்டாக்கும். ஆசீர்வாதம் நீதிமானுடைய தலையின்மேல் இருக்கும்.",
    "Proverbs 11": "நேர்மையும் பலனும்: கள்ளத்தராசு கர்த்தருக்கு அருவருப்பானது. கிருபையுள்ள ஸ்திரீ கனத்தைப் பெறுகிறாள். தாராளமாய்க் கொடுக்கிறவன் செழிப்பான்; தண்ணீர்பாய்ச்சுகிறவனுக்குத் தண்ணீர்பாய்ச்சப்படும்.",
    "Proverbs 12": "நல்லொழுக்கம்: தன் நிலத்தைப் பயிரிடுகிறவன் ஆகாரத்தினால் திருப்தியாவான். புத்தியுள்ளவன் நிந்தையை மூடுகிறான். உண்மையுள்ள உதடுகள் என்றென்றைக்கும் நிலைத்திருக்கும்; பொய்நாக்கோ ஒரு நிமிஷம்தான்.",
    "Proverbs 13": "பேச்சும் செயலும்: தன் வாயைக் காக்கிறவன் தன் ஆத்துமாவைக் காக்கிறான். ஞானிகளோடே நடக்கிறவன் ஞானமடைவான்; மூடருக்குத் தோழனோ அழிவான். பிரம்பைக் கையாளாதவன் தன் மகனைப் பகைக்கிறான்.",
    "Proverbs 14": "ஞானமுள்ள ஸ்திரீ: ஞானமுள்ள ஸ்திரீ தன் வீட்டைக் கட்டுகிறாள்; மூடியுள்ளவளோ தன் கைகளினால் அதை இடித்துப்போடுகிறாள். நீதியானது ஒரு ஜனத்தை உயர்த்தும்; பாவமோ எந்த ஜனத்திற்கும் இகழ்ச்சி.",
    "Proverbs 15": "மிருதுவான பதில்: 'மிருதுவான உத்தரம் குரோதத்தை மாற்றும்; கடுஞ்சொற்களோ கோபத்தை எழுப்பும்.' கர்த்தருடைய கண்கள் எவ்விடத்திலுமிருந்து நல்லோரையும் தீயோரையும் பார்க்கிறது.",
    "Proverbs 16": "தேவ திட்டமும் பெருமையும்: 'மனுஷன் தன் இருதயத்தில் திட்டம் தீட்டுகிறான், ஆனால் நாவின் பதில் கர்த்தரால் வரும்.' அழிவுக்கு முன்னானது அகந்தை; விழுதலுக்கு முன்னானது மனமேட்டிமை.",
    "Proverbs 17": "சமாதானமும் நட்பு: 'சண்டையோடு கூடிய விருந்தைவிட, அமைதியோடு கூடிய ஒரு துண்டு காய்ந்த ரொட்டி மேல்.' சிநேகிதன் எக்காலத்திலும் நேசிப்பான்; இக்காலத்திற்காகவே சகோதரன் பிறந்திருக்கிறான்.",
    "Proverbs 18": "நாவின் அதிகாரம்: 'மரணமும் ஜீவனும் நாவின் அதிகாரத்திலிருக்கிறது.' தன் குற்றத்தை முதலில் சொல்பவன் நீதிமானாகத் தெரிவான், ஆனால் அடுத்தவன் வந்து அவனைச் சோதிக்கும் வரைதான்.",
    "Proverbs 19": "புத்தியுள்ளவன்: மனைவி கர்த்தர் அருளும் ஈவு. கோபக்காரன் தண்டனை அடையட்டும்; அவனை ஒருமுறை தப்புவித்தால் மீண்டும் தப்புவிக்க வேண்டியிருக்கும். ஏழைக்கு இரங்குகிறவன் கர்த்தருக்குக் கடன்கொடுக்கிறான்.",
    "Proverbs 20": "மதுபானமும் நேர்மையும்: திராட்சரசம் பரியாசஞ்செய்யும், மதுபானம் கலக்கமுண்டாக்கும். 'பாலகன் தன் செய்கையினால் குணவான் என்று அறியப்படுவான்.' கள்ளத்தராசு கர்த்தருக்கு அருவருப்பானது.",
    "Proverbs 21": "இருதயத்தை ஆராய்பவர்: ராஜாவின் இருதயம் கர்த்தரின் கையில் நீர்க்கால்களைப் போலிருக்கிறது. 'பலியிடுவதைவிட நீதியையும் நியாயத்தையும் செய்வதே கர்த்தருக்குப் பிரியம்.'",
    "Proverbs 22": "நல்ல நாமம்: 'அநேக ஐசுவரியத்தைவிட நற்கீர்த்தியே தெரிந்துகொள்ளப்படத்தக்கது.' பிள்ளையை அவன் நடக்க வேண்டிய வழியில் நடத்து; அவன் முதிர்வயதிலும் அதை விடமாட்டான்.",
    "Proverbs 23": "மிதமானது: போஜனப்பிரியரோடும் மதுபானப்பிரியரோடும் சேராதே. 'உன் மகனே, உன் இருதயத்தை எனக்குத் தா.' உன் தகப்பனுக்கும் தாய்க்கும் மகிழ்ச்சியுண்டாக நட.",
    "Proverbs 24": "பராக்கிரமம்: 'ஆபத்துக்காலத்தில் நீ சோர்ந்துபோனால் உன் பெலன் குறைவானது.' உன் சத்துரு விழும்போது சந்தோஷப்படாதே. அறிவினால் வீடு கட்டப்பட்டு, விவேகத்தினால் நிலைநிறுத்தப்படும்.",
    "Proverbs 25": "ராஜசரிகை: எசேக்கியாவின் மனுஷர் தொகுத்தவை. 'சரியான நேரத்தில் சொல்லப்பட்ட வார்த்தை வெள்ளித் தட்டில் வைக்கப்பட்ட பொற்பழங்களுக்குச் சமம்.' உன் சத்துரு பசியாயிருந்தால் அவனுக்கு உணவளி.",
    "Proverbs 26": "மூடனின் நிலை: மூடன் தன் மதியீனத்திற்குத் திரும்புவது நாய் தான் கக்கினதைத் தின்னத் திரும்புவதற்குச் சமம். விறகில்லாத இடத்தில் நெருப்பு அணைந்துவிடும்; கோள்சொல்லி இல்லாத இடத்தில் சண்டை ஓயும்.",
    "Proverbs 27": "நட்பின் ஆலோசனைகள்: 'இரும்பு இரும்பைக் கருக்காக்கும்; மனுஷன் தன் நண்பனின் முகத்தைக் கருக்காக்குகிறான்.' அயலான் உன்னைப் புகழட்டும், உன் வாய் அல்ல. ஒருவன் தன் இடத்தை விட்டு அலைவது கூடுவிட்டலையும் பறவைக்குச் சமம்.",
    "Proverbs 28": "தைரியமும் பயமும்: துன்மார்க்கன் துரத்தாதிருந்தும் ஓடுகிறான்; நீதிமான்களோ சிங்கத்தைப் போலத் தைரியமாயிருக்கிறார்கள். தன் பாவங்களை மறைக்கிறவன் வாழ்வடையமாட்டான்; அவைகளை அறிக்கை செய்கிறவன் இரக்கம் பெறுவான்.",
    "Proverbs 29": "கண்டிப்பின் பயன்: அடிக்கடி கடிந்துகொள்ளப்பட்டும் தன் பிடரியைக் கடினப்படுத்துகிறவன் திடீரென அழிவான். 'தரிசனம் (Vision) இல்லாத இடத்தில் ஜனங்கள் சீர்கெட்டுப் போவார்கள்.' மனுஷனுக்குப் பயப்படும் பயம் கண்ணியை வருவிக்கும்.",
    "Proverbs 30": "ஆகூரின் மொழிகள்: 'என்னைத் தரித்திரனாக்கவும் வேண்டாம், ஐசுவரியவானாக்கவும் வேண்டாம்; என் படி அரிசியை எனக்குத் தந்தருளும்.' கர்த்தருடைய வார்த்தை எல்லாம் புடம் போடப்பட்டது.",
    "Proverbs 31": "குணவதி: லேமுவேல் ராஜாவின் தாயார் சொன்னது. மதுபானம் ராஜாக்களுக்குத் தகாது. 'குணவதியான ஸ்திரீயைக் கண்டடைபவர் யார்? அவளுடைய விலை முத்துக்களைவிட உயர்ந்தது.' அவள் கர்த்தருக்குப் பயப்படுகிறவள்; அவளுடைய கிரியைகளே அவளைப் புகழும்.",

    "Ecclesiastes 1": "எல்லாம் மாயை: 'மாயை, எல்லாம் மாயை' என்று பிரசங்கி கூறுகிறார். சூரியனுக்குக் கீழே ஒரு புதிய காரியமும் இல்லை. அதிக ஞானம் அதிக சலிப்பைத் தருகிறது; அறிவு பெருகினால் துக்கமும் பெருகும்.",
    "Ecclesiastes 2": "சிற்றின்பங்களின் ஆராய்ச்சி: மதுபானம், பெரும் கட்டடங்கள், செல்வம் மற்றும் இசை என எல்லாவற்றையும் பிரசங்கி முயன்று பார்த்தார். இறுதியில், இவை அனைத்தும் 'காற்றைப் பிடிக்க முயல்வது' போல வீணானது என்று கண்டார்.",
    "Ecclesiastes 3": "ஒவ்வொன்றிற்கும் ஒரு காலம்: 'ஒவ்வொன்றிற்கும் ஒரு காலமுண்டு; வானத்தின் கீழிருக்கிற ஒவ்வொரு காரியத்திற்கும் ஒரு நேரமுண்டு.' பிறக்க ஒரு காலம், இறக்க ஒரு காலம். தேவன் எல்லாவற்றையும் அந்தந்தக் காலத்தில் நேர்த்தியாகச் செய்திருக்கிறார்.",
    "Ecclesiastes 4": "தனிமையின் கஷ்டம்: ஒடுக்கப்படுகிறவர்களின் கண்ணீரைக் கண்டார். ஒருவனைவிட இருவர் மேலானவர்கள்; ஏனெனில் அவர்களுக்கு நற்பலன் உண்டு. முப்புரி நூல் சீக்கிரமாய் அறுபடாது.",
    "Ecclesiastes 5": "ஆலயத்தில் எச்சரிக்கை: தேவனுடைய ஆலயத்திற்குப் போகும்போது உன் கால்களைக் காத்துக்கொள்; பேசுகிறதைவிடக் கேட்பதே நலம். பணத்தை நேசிக்கிறவன் பணத்தினால் திருப்தியடைவதில்லை.",
    "Ecclesiastes 6": "திருப்தியற்ற செல்வம்: ஒருவன் செல்வம் பெற்றும் அதை அனுபவிக்கத் தேவன் அவனுக்கு அதிகாரம் கொடுக்காவிட்டால் அது பெரும் வேதனை. ஆத்துமாவின் ஆசை ஒருபோதும் நிறைவேறுவதில்லை.",
    "Ecclesiastes 7": "துக்கத்தின் மேன்மை: நல்ல நாமம் விலையேறப்பெற்ற தைலத்தைவிட மேலானது. விருந்து வீட்டுக்குப் போவதைவிடத் துக்க வீட்டுக்குப் போவது நலம்; அது மரணத்தை நினைவூட்டி இருதயத்தைச் செம்மைப்படுத்தும்.",
    "Ecclesiastes 8": "ராஜாவிற்கு அடங்குதல்: ராஜாவின் கட்டளைக்குக் கீழ்ப்படிய வேண்டும். உலகில் நீதிமான்களுக்குத் தீமையும், துன்மார்க்கருக்கு நன்மையும் நடப்பதைக் கண்டு பிரசங்கி வியக்கிறார். இதுவும் மாயையே.",
    "Ecclesiastes 9": "மரணத்தின் சமத்துவம்: நீதிமானுக்கும் துன்மார்க்கனுக்கும் ஒரே முடிவு (மரணம்) நேரிடுகிறது. 'உன் கையில் செய்யக் கிடைத்ததை உன் பெலத்தோடே செய்.' செத்த சிங்கத்தைவிட உயிருள்ள நாய் மேலானது.",
    "Ecclesiastes 10": "புத்தியீனத்தின் விளைவு: செத்த ஈக்கள் தைலக்காரனுடைய தைலத்தை நாறப்பண்ணுவதுபோல, ஒரு சிறிய புத்தியீனம் ஞானவானைக் கனவீனப்படுத்தும். மெதுவாய்ப் பேசுகிற ஞானியின் வார்த்தைகளே சிலாகிக்கப்படும்.",
    "Ecclesiastes 11": "நன்மை செய்தல்: உன் ஆகாரத்தைத் தண்ணீர்களின்மேல் போடு, பல நாட்களுக்குப் பின் அதைக் காண்பாய். வாலிபனே, உன் வாலிபத்திலே சந்தோஷமாயிரு, ஆனால் உன் செயல்களுக்காகத் தேவன் உன்னை நியாயந்தீர்ப்பார் என்பதை மறவாதே.",
    "Ecclesiastes 12": "முடிவுரை: 'உன் வாலிபப்பிராயத்திலே உன் சிருஷ்டிகரை நினை.' முதுமையின் கஷ்டங்களை உருவகமாக விவரித்தபின், 'தேவனுக்குப் பயந்து அவர் கற்பனைகளைக் கைக்கொள்; இதுவே மனுஷன் எல்லார்க்கும் விதிக்கப்பட்ட கடமை' என்று முடிக்கிறார்.",

    "Song 1": "நேசத்தின் ஆரம்பம்: மணவாட்டி தன் நேசரைக் குறித்துப் பேசுகிறாள். 'நீர் என்னைத் முத்தமிடுவீராக; உமது நேசம் திராட்சரசத்தைவிட மேலானது.' அவள் தன்னை ஒரு கருநிறமானவள் என்றும், கேதாரின் கூடாரங்களுக்கு ஒப்பானவள் என்றும் தாழ்மையுடன் கூறுகிறாள்.",
    "Song 2": "லீலி புஷ்பம்: 'நான் சாரோனின் ரோஜாவும், பள்ளத்தாக்குகளின் லீலிபுஷ்பமுமாயிருக்கிறேன்.' நேசர் அவளைத் தேடி வருகிறார். 'என் பிரியமே, என் ரூபவதியே, எழுந்திரு, வா! மாரிகாலம் கடந்தது, மழையும் பெய்து தீர்ந்தது.'",
    "Song 3": "நேசரைத் தேடுதல்: மணவாட்டி இரவில் தன் நேசரைத் தேடுகிறாள். அவள் அவரைக் கண்டு பிடித்துக்கொண்டு, அவரை விடாமல் தன் தாயின் வீட்டிற்கு அழைத்துச் செல்கிறாள். சாலொமோனின் அரச ஊர்வலம் விவரிக்கப்படுகிறது.",
    "Song 4": "மணவாட்டியின் அழகு: மணவாளன் தன் மணவாட்டியின் அழகை உச்சந்தலை முதல் உள்ளங்கால் வரை புகழ்கிறார். 'என் பிரியமே, நீ முற்றிலும் அழகியே, உன்னில் ஒரு குறையுமில்லை.' அவளை ஒரு 'அடைக்கப்பட்ட தோட்டம்' என்று அழைக்கிறார்.",
    "Song 5": "நேசரின் தரிசனம்: மணவாட்டி கதவைத் திறக்கத் தாமதித்ததால் நேசர் சென்றுவிடுகிறார். அவள் அவரைத் தேடி அலைகிறாள். எருசலேமின் குமாரத்திகளிடம் தன் நேசரின் அழகை (வெண்மையும் சிவப்பும் உடையவர்) விவரிக்கிறாள்.",
    "Song 6": "நேசத்தின் உறுதி: நேசர் மீண்டும் வருகிறார். 'என் புறாவே, என் உத்தமியே, நீ ஒருத்திதான்.' அவர் அவளைச் சந்திரனைப் போல அழகும், சூரியனைப் போலப் பிரகாசமும், கொடிகள் ஏந்திய சேனைபோலப் பயங்கரமுமானவள் என்கிறார்.",
    "Song 7": "அழகின் வர்ணனை: நேசர் மணவாட்டியின் நடையையும் அவளுடைய உருவத்தையும் மீண்டும் புகழ்கிறார். இருவரும் வயல்வெளிகளுக்கும் கிராமங்களுக்கும் சென்று தங்கள் நேசத்தைப் பகிர்ந்துகொள்ள அழைக்கிறார்கள்.",
    "Song 8": "மரணத்தைவிட வலிமையான நேசம்: 'நேசம் மரணத்தைப்போல வலிமையுள்ளது; அதின் ஜுவாலை அக்கினி ஜுவாலை.' மகா ஜலங்கள் நேசத்தை அணைக்க முடியாது. மணவாட்டி தன் நேசரைத் தன்னிடம் வரும்படி விரைவுபடுத்துகிறாள்.",

    "Isaiah 1": "தேவனுடைய வழக்கு: இஸ்ரவேலர் தேவனை விட்டு விலகிப்போனதை ஒரு வழக்கு போல ஏசாயா முன்வைக்கிறார். 'உங்கள் பாவங்கள் சுருதிசிவப்பாயிருந்தாலும் பனியைப்போல வெண்மையாகும்' என்ற மன்னிப்பின் அழைப்பு இங்கே விடுக்கப்படுகிறது.",
    "Isaiah 2": "கடைசி நாட்களின் மலை: தேவாலயம் உள்ள மலை எல்லா மலைகளுக்கும் மேலாக உயர்த்தப்படும். ஜாதிகள் தங்கள் பட்டயங்களை மழுக்களாகவும், தங்கள் ஈட்டிகளை அரிவாள்களாகவும் அடிப்பார்கள்; இனி யுத்தத்தைக் கற்கமாட்டார்கள்.",
    "Isaiah 3": "எருசலேமுக்கு நியாயத்தீர்ப்பு: தலைவர்களின் அநீதியால் எருசலேம் சீர்குலையும். ஆடம்பரத்திலும் பெருமையிலும் திளைக்கும் பெண்களுக்குக் கேடு வரும் என்று எச்சரிக்கப்படுகிறது.",
    "Isaiah 4": "கிளையின் மகிமை: நியாயத்தீர்ப்புக்குப் பின், 'கர்த்தரின் கிளை' (The Branch) மேன்மையாயிருக்கும். எஞ்சியிருப்பவர்கள் பரிசுத்தர் என்று அழைக்கப்படுவார்கள்; தேவன் அவர்களுக்கு ஒரு புகலிடமாக இருப்பார்.",
    "Isaiah 5": "திராட்சத்தோட்டப் பாட்டு: தேவன் இஸ்ரவேலை ஒரு நல்ல திராட்சத்தோட்டமாக வளர்த்தார், ஆனால் அது கசப்பான பழங்களையே தந்தது. அநீதி செய்யும் செல்வந்தர்களுக்கு 'ஐயோ' என்று சாபங்கள் கூறப்படுகின்றன.",
    "Isaiah 6": "ஏசாயாவின் அழைப்பு: உசியாராஜா மரணமடைந்த வருடத்தில், ஏசாயா தேவாலயத்தில் கர்த்தருடைய மகிமையைக் கண்டார். சேராபீன்கள் 'பரிசுத்தர், பரிசுத்தர், பரிசுத்தர்' என்று முழங்கின. ஏசாயா தன் பாவம் நீங்கி, 'இதோ அடியேன் இருக்கிறேன், என்னை அனுப்பும்' என்றார்.",
    "Isaiah 7": "இம்மானுவேல் அடையாளம்: ஆகாஸ் ராஜாவுக்கு ஒரு அடையாளம் கொடுக்கப்பட்டது: 'இதோ, ஒரு கன்னிகை கர்ப்பவதியாகி ஒரு குமாரனைப் பெறுவாள், அவருக்கு இம்மானுவேல் (தேவன் நம்மோடு இருக்கிறார்) என்று பேரிடுவாள்.'",
    "Isaiah 8": "மகேர்-ஷாலால்-அஷ்-பாஸ்: ஏசாயாவின் குமாரனுக்கு இந்தப் பெயரிடப்பட்டது (கொள்ளை அடிக்கத் தீவிரியும் என்பது பொருள்). அசிரியாவின் படையெடுப்பு எச்சரிக்கப்படுகிறது. மனுஷருக்குப் பயப்படாமல் கர்த்தருக்கே பயப்பட வேண்டும்.",
    "Isaiah 9": "சமாதானப் பிரபு: இருளில் நடக்கிற ஜனங்கள் பெரிய வெளிச்சத்தைக் கண்டார்கள். 'நமக்கு ஒரு பாலகன் பிறந்தார், நமக்கு ஒரு குமாரன் கொடுக்கப்பட்டார்... அவர் நாமம் அதிசயமானவர், ஆலோசனைக்கர்த்தா, வல்லமையுள்ள தேவன்.'",
    "Isaiah 10": "அசிரியாவின் வீழ்ச்சி: தேவன் அசிரியாவை ஒரு கருவியாகப் பயன்படுத்தினாலும், அவர்களின் பெருமைக்காக அவர்களைத் தண்டிப்பார். இஸ்ரவேலில் ஒரு 'மீதியான ஜனங்கள்' (Remnant) மட்டும் திரும்பி வருவார்கள்.",
    "Isaiah 20": "எகிப்துக்கு எதிரான அடையாளம்: எகிப்தும் எத்தியோப்பியாவும் அசிரியாவினால் வெல்லப்படும் என்பதற்கு அடையாளமாக, ஏசாயா மூன்று வருடம் ஆடையின்றியும் வெறுங்காலுமாய் நடந்து ஒரு தீர்க்கதரிசன அடையாளமாக இருந்தார்.",
    "Isaiah 21": "பாபிலோனின் வீழ்ச்சி: வனாந்தரத்துக்கடுத்த பாரம். 'பாபிலோன் விழுந்தது, விழுந்தது!' என்று ஏசாயா காவற்காரனைப் போல நின்று அறிவிக்கிறார். தூமா மற்றும் அரேபியாவுக்கு எதிரான எச்சரிக்கைகளும் இதில் உள்ளன.",
    "Isaiah 22": "தரிசனப் பள்ளத்தாக்கு: எருசலேம் தாக்கப்படும்போது ஜனங்கள் மனந்திரும்பாமல் கொண்டாடி மகிழ்ந்ததைக் கண்டித்தார். அரண்மனை அதிகாரியான செப்னா நீக்கப்பட்டு, எலியாக்கீம் உயர்த்தப்படுவார் என்ற முன்னறிவிப்பு.",
    "Isaiah 23": "தீருவின் பாரம்: உலகப் புகழ்பெற்ற வணிக நகரமான தீரு (Tyre) அழியும். அதன் பெருமை தாழ்த்தப்படும்; 70 வருடங்களுக்குப் பின் அது மீண்டும் நினைவு கூரப்படும்.",
    "Isaiah 24": "பூமியின்மேல் நியாயத்தீர்ப்பு: இது 'ஏசாயாவின் வெளிப்படுத்துதல்' என்று அழைக்கப்படுகிறது. பூமி முழுவதிலும் அக்கிரமம் பெருகியதால் அது தள்ளாடி விழும்; கர்த்தர் சீயோன் பர்வதத்தில் அரசாளுவார்.",
    "Isaiah 25": "மரணத்தின் வெற்றி: கர்த்தர் மரணத்தை நித்தியமாக விழுங்குவார். 'இவர் நம்முடைய தேவன், இவருக்காகக் காத்திருந்தோம்' என்று ஜனங்கள் பாடுவார்கள். அவர் எல்லா முகங்களிலிருந்தும் கண்ணீரைத் துடைப்பார்.",
    "Isaiah 26": "நிச்சயமான சமாதானம்: 'உம்மை உறுதியாய்ப் பற்றிக்கொண்ட மனதையுடையவன் உம்மையே நம்பியிருக்கிறபடியால், நீர் அவனைப் பூரண சமாதானத்துடன் காத்துக்கொள்வீர்.' கர்த்தரே நித்திய கன்மலை.",
    "Isaiah 27": "திராட்சத்தோட்டப் பாதுகாப்பு: கர்த்தர் லீவியாதானைத் தண்டிப்பார். இஸ்ரவேலை ஒரு விசேஷித்த திராட்சத்தோட்டமாகப் பாதுகாப்பார். அவர்கள் பூமி எங்கும் பரவி கனி கொடுப்பார்கள்.",
    "Isaiah 28": "மூலைக்கல்லின் வாக்குத்தத்தம்: எப்பிராயீமின் மதுபானப்பிரியர்களுக்கு எச்சரிக்கை. 'இதோ, நான் சீயோனிலே ஒரு கல்லை அஸ்திபாரமாக வைக்கிறேன்; அது சோதிக்கப்பட்டதும் விலையேறப்பெற்றதுமான மூலைக்கல்.'",
    "Isaiah 29": "ஆரியேலின் நெருக்கம்: எருசலேமுக்கு (ஆரியேல்) நெருக்கம் வரும், ஆனால் சத்துருக்கள் கனவைப் போல மறைவார்கள். ஜனங்கள் உதடுகளினால் தேவனைக் கனம்பண்ணி, இருதயத்தைத் தூரமாக்கினார்கள்.",
    "Isaiah 30": "வீணான எகிப்தின் உதவி: யூதா தேவன்மேல் நம்பிக்கையாயிராமல் எகிப்தின் உதவியைத் தேடியதைக் கண்டித்தார். 'அமைதலாயிருந்து தேவனையே நம்புவதே உங்கள் பெலன்.'",
    "Isaiah 31": "குதிரைகளை நம்பாதே: குதிரைகளையும் இரதங்களையும் நம்பி எகிப்துக்குப் போகிறவர்களுக்கு ஐயோ! கர்த்தர் ஒரு சிங்கம் தன் இரையைக் காப்பது போல எருசலேமைக் காப்பார்.",
    "Isaiah 32": "நீதியான ராஜ்யம்: ஒரு ராஜா நீதியாக அரசாளுவார். ஆவியானவர் உன்னதத்திலிருந்து ஊற்றப்படும்போது, வனாந்தரம் செழிப்பான வயலாகும்; நீதியின் விளைவு நித்திய சமாதானம்.",
    "Isaiah 33": "கொள்ளையடிப்பவனுக்கு ஐயோ: எருசலேமை அச்சுறுத்தும் அசிரியாவுக்குத் தண்டனை. கர்த்தரே நம்முடைய நியாயாதிபதி, கர்த்தரே நம்முடைய சட்டவல்லவர், கர்த்தரே நம்முடைய ராஜா; அவர் நம்மை இரட்சிப்பார்.",
    "Isaiah 34": "ஜாதிகளுக்கு நியாயத்தீர்ப்பு: ஏதோமுக்கும் மற்ற தேசங்களுக்கும் வரும் தண்டனை. கர்த்தருடைய நியாயத்தீர்ப்பின் பட்டயம் வானங்களில் திருப்தியடையும்.",
    "Isaiah 35": "மகிமையான வழி: வனாந்தரம் பூரித்து லீலிபுஷ்பத்தைப் போல மலரும். குருடரின் கண்கள் திறக்கப்படும், செவிடரின் காதுகள் கேட்கும். அங்கே 'பரிசுத்த வழி' என்ற ஒரு பாதை இருக்கும்.",
    "Isaiah 36": "அசிரியாவின் அச்சுறுத்தல்: அசிரிய ராஜாவின் தளபதி ரப்சாக்கே எருசலேமின் மதிலருகே வந்து, எசேக்கியா ராஜாவையும் தேவனையும் நிந்தித்துப் பேசினான்.",
    "Isaiah 37": "எசேக்கியாவின் ஜெபம்: ரப்சாக்கேயின் கடிதத்தை எசேக்கியா தேவாலயத்தில் கர்த்தருக்கு முன்பாக விரித்து ஜெபித்தார். ஒரே இரவில் கர்த்தருடைய தூதன் அசிரியப் படையில் 1,85,000 பேரைக் கொன்றார்.",
    "Isaiah 38": "எசேக்கியாவின் வியாதி: எசேக்கியா மரணத் தறுவாயிலிருந்தபோது அழுது வேண்டினார். தேவன் அவருக்கு 15 வருடங்கள் ஆயுசைக்கூட்டி, சூரிய கடியாரத்தில் நிழல் பத்து பாகை பின்னிட்டுச் செல்லச் செய்தார்.",
    "Isaiah 39": "பாபிலோனிய தூதுவர்: எசேக்கியா குணமான பின் பாபிலோனியர்களுக்குத் தன் பொக்கிஷங்களைக் காட்டினார். ஏசாயா வந்து, இந்தப் பொக்கிஷங்கள் அனைத்தும் பாபிலோனுக்குச் சிறையாகப் போகும் என்று எச்சரித்தார்.",
    "Isaiah 40": "ஆறுதல் சொல்லுங்கள்: 'என் ஜனத்தை ஆறுதல்படுத்துங்கள்.' கர்த்தருக்காக வழியை ஆயத்தப்படுத்துங்கள். 'கர்த்தருக்குக் காத்திருக்கிறவர்களோ புதுப் பெலன் அடைந்து, கழுகுகளைப் போலச் சிறகுகளை அடித்து எழும்புவார்கள்.'",
    "Isaiah 41": "தேவனின் பாதுகாப்பு: இஸ்ரவேலின் பகைவர்கள் அழியும் போது, தேவன் தன் ஜனத்தைப் பிடித்து, 'பயப்படாதே, நான் உனக்குச் சகாயம்பண்ணுகிறேன்' என்று ஆறுதல் கூறுகிறார். விக்கிரகங்களால் எதிர்காலத்தைச் சொல்ல முடியாது என்று சவால் விடுகிறார்.",
    "Isaiah 42": "மேசியாவின் மென்மை: 'இதோ, நான் தெரிந்துகொண்ட என் தாசன்.' அவர் உலகிற்கு நீதியைத் தருவார். அவர் கூக்குரலிடார், தெருக்களில் சத்தத்தைக் கேட்கப்பண்ணார். அவர் ஜாதிகளுக்கு ஒளியாக இருப்பார்.",
    "Isaiah 43": "விலையேறப்பெற்ற ஜனம்: 'நீ என் பார்வைக்கு அருமையானபடியால் கனம்பெற்றாய், நானும் உன்னை நேசித்தேன்.' தேவன் வனாந்தரத்தில் வழியையும் அவாந்தரவெளியில் ஆறுகளையும் உண்டாக்குகிறார்.",
    "Isaiah 44": "பரிசுத்த ஆவியின் வாக்குத்தத்தம்: 'தாகமுள்ளவன்மேல் தண்ணீரையும், வறண்ட நிலத்தின்மேல் ஆறுகளையும் ஊற்றுவேன்.' மரக்கட்டையைச் செதுக்கி அதற்குப் பூஜை செய்யும் விக்கிரக ஆராதனையின் மதியீனத்தை ஏசாயா கேலி செய்கிறார்.",
    "Isaiah 45": "கோரேசுக்கு அதிகாரம்: பெர்சிய ராஜாவாகிய கோரேசு பிறப்பதற்கு முன்பே, தேவன் அவனைப் பெயர் சொல்லி அழைத்து, அவன் மூலமாக எருசலேமைத் திரும்பக் கட்டப்போவதை அறிவிக்கிறார்.",
    "Isaiah 46": "சுமப்பவர் யார்?: பாபிலோனிய விக்கிரகங்களாகிய பெல் மற்றும் நேபோவை மிருகங்கள் சுமந்து செல்ல வேண்டும். ஆனால் தேவனோ தன் ஜனத்தைக் கருவிலே உருவானது முதல் முதிர்வயது வரை சுமக்கிறார்.",
    "Isaiah 47": "பாபிலோனின் வீழ்ச்சி: பாபிலோன் ஒரு ராஜகுமாரியைப் போலப் பெருமையாய் இருந்தது. ஆனால் அது திடீரென அழியும். அதன் மந்திரவாதிகளும் ஜோசியக்காரர்களும் அதைத் தப்புவிக்க முடியாது.",
    "Isaiah 48": "புதிய காரியங்கள்: இஸ்ரவேலரின் பிடிவாதத்தைக் கண்டித்தாலும், தேவன் தம்முடைய நாமத்தினிமித்தம் அவர்களை அழிக்கவில்லை. 'துன்மார்க்கருக்குச் சமாதானம் இல்லை' என்று எச்சரிக்கிறார்.",
    "Isaiah 49": "ஜாதிகளுக்கு ஒளி: மேசியா தன் தாயின் கர்ப்பத்திலிருந்தே அழைக்கப்பட்டார். அவர் இஸ்ரவேலை மீட்பது மட்டுமல்லாமல், பூமியின் எல்லைவரைக்கும் இரட்சிப்பைத் தரும்படியாக ஜாதிகளுக்கு ஒளியாக வைக்கப்பட்டார்.",
    "Isaiah 50": "கீழ்ப்படிதலுள்ள சீஷன்: மேசியா கற்றறிந்தவர்களின் நாவைப் பெற்றிருப்பார். 'அடிக்கிறவர்களுக்கு என் முதுகையும், மயிரைப் பிடுங்குகிறவர்களுக்கு என் தாடைகளையும் கொடுத்தேன்; அவமானத்திற்கும் உமிழ்நீருக்கும் என் முகத்தை மறைக்கவில்லை.'",
    "Isaiah 51": "ஆபிரகாமின் ஆசீர்வாதம்: உங்கள் தகப்பனாகிய ஆபிரகாமை நோக்கிப் பாருங்கள். தேவன் சீயோனைத் தேற்றுவார். மனுஷருடைய நிந்தைக்கும் பயப்பட வேண்டாம்; கர்த்தரின் புயம் வல்லமையுள்ளது.",
    "Isaiah 52": "அழகான பாதங்கள்: சீயோனே, விழித்துக்கொள்! சமாதானத்தைக் கூறி, நற்செய்தியைத் தெரிவிக்கிறவர்களின் பாதங்கள் பர்வதங்களின்மேல் எவ்வளவு அழகானவை! எருசலேமின் பாழான இடங்கள் கம்பீரித்துப் பாடும்.",
    "Isaiah 53": "கல்வாரிப் பலி: வேதாகமத்தின் மிக முக்கியமான அதிகாரம். 'அவர் நம்முடைய மீறுதல்களினிமித்தம் காயப்பட்டு, நம்முடைய அக்கிரமங்களினிமித்தம் நொறுக்கப்பட்டார்.' அவர் ஒரு ஆட்டுக்குட்டியைப் போல மௌனமாகப் பலியானார்.",
    "Isaiah 54": "நித்திய அன்பு: 'சிறிதுநேரம் உன்னைக் கைவிட்டேன்; ஆனால் மகா இரக்கங்களால் உன்னைச் சேர்த்துக்கொள்வேன்.' உனக்கு விரோதமாய் உருவாக்கப்படும் எந்த ஆயுதமும் வாய்க்காதே போகும்.",
    "Isaiah 55": "இலவச அழைப்பு: 'தாகமாயிருக்கிறவர்களே, தண்ணீர்களண்டைக்கு வாருங்கள்.' மனுஷருடைய நினைவுகளைவிட தேவனுடைய நினைவுகள் மிக உயர்ந்தவை. அவருடைய வார்த்தை தகுந்த பலனைத் தரும்.",
    "Isaiah 56": "அனைவருக்கும் இரட்சிப்பு: அந்நியர்களும் கர்த்தரைச் சேவிக்க வரலாம்; 'என் வீடு சகல ஜனங்களுக்கும் ஜெபவீடு எனப்படும்.' ஆனால் இஸ்ரவேலின் காவற்காரர்களோ (தலைவர்கள்) தூங்குகிற நாய்களைப் போல இருக்கிறார்கள்.",
    "Isaiah 57": "மனத்தாழ்மை: 'உன்னதமானவரும் பரிசுத்தருமானவர் தாழ்மையுள்ளவர்களோடும் நருங்குண்ட இருதயமுள்ளவர்களோடும் தங்குகிறார்.' ஆனால் துன்மார்க்கனோ கொந்தளிக்கிற கடலைப் போல இருக்கிறான்.",
    "Isaiah 58": "உண்மையான உபவாசம்: வெறும் வயிற்றைப் பட்டினி போடுவது உபவாசம் அல்ல; ஏழைகளுக்கு உணவளிப்பதும், ஒடுக்கப்பட்டவர்களை விடுவிப்பதுமே தேவன் விரும்பும் உபவாசம். அப்பொழுது உன் வெளிச்சம் விடியற்காலத்தைப் போல உதிக்கும்.",
    "Isaiah 59": "பாவத்தின் விளைவு: 'உங்கள் அக்கிரமங்களே உங்களுக்கும் உங்கள் தேவனுக்கும் நடுவாகப் பிரிவினை உண்டாக்குகிறது.' சத்தியம் வீதியிலே விழுந்து கிடக்கிறது. கர்த்தரே ஒரு போர்வீரனைப் போல நீதியை நிலைநாட்ட வருவார்.",
    "Isaiah 60": "சீயோனின் ஒளி: 'எழும்பிப் பிரகாசி; உன் ஒளி வந்தது.' ஜாதிகளின் செல்வம் உன்னிடம் வரும். இனி உன் தேசத்தில் கொடுமை ஒலியாது; உன் மதில்களுக்கு இரட்சிப்பு என்று பேரிடுவாய்.",
    "Isaiah 61": "மேசியாவின் ஊழியம்: 'கர்த்தருடைய ஆவி என்மேல் இருக்கிறது.' சிறுமைப்பட்டவர்களுக்குச் சுவிசேஷத்தைச் சொல்லவும், இருதயம் நொருங்குண்டவர்களுக்குக் காயக்கட்டவும் அவர் அனுப்பப்பட்டார்.",
    "Isaiah 62": "எருசலேமின் புதுப்பெயர்: நீ கர்த்தருடைய கையில் மகிமையான கிரீடமாயிருப்பாய். நீ 'கைவிடப்பட்டவள்' என்னப்படாமல் 'ஹெப்சிபா' (என் பிரியம் அவளில் இருக்கிறது) என்று அழைக்கப்படுவாய்.",
    "Isaiah 63": "தேவனின் நியாயத்தீர்ப்பு: ஏதோமிலிருந்து இரத்தம் தோய்ந்த ஆடையுடன் வருகிறவர் யார்? அவரே கர்த்தர். அவர் தமது ஜனத்திற்காகப் பரிந்துபேசி, பழைய நாட்களின் கிருபைகளை நினைவுகூருகிறார்.",
    "Isaiah 64": "மனமுருகும் ஜெபம்: 'கர்த்தாவே, நீர் வானங்களைக் கிழித்துக்கொண்டு இறங்கி வரமாட்டீரோ?' நாங்கள் அனைவரும் அசுத்தமானவர்கள்; ஆனாலும் நீர் எங்கள் குயவன், நாங்கள் உம்முடைய களிமண்.",
    "Isaiah 65": "புதிய சிருஷ்டி: பழைய காரியங்கள் மறக்கப்படும். தேவன் புதிய வானத்தையும் புதிய பூமியையும் சிருஷ்டிப்பார். அங்கே ஓநாயும் ஆட்டுக்குட்டியும் ஒருமித்து மேயும்; என் பரிசுத்த பர்வதமெங்கும் தீங்கு இருக்காது.",
    "Isaiah 66": "நித்திய முடிவு: 'வானம் எனக்குச் சிங்காசனம், பூமி எனக்குப் பாதப்படி.' தேவன் எருசலேமைத் தேற்றுவார். இறுதியில் சகல ஜாதிகளும் அவருடைய மகிமையைக் காண்பார்கள்; துன்மார்க்கருக்கோ நித்திய தண்டனை உண்டு.",

    "Jeremiah 1": "எரேமியாவின் அழைப்பு: 'நீ கர்ப்பத்தில் உருவாகுமுன்னே உன்னைத் தெரிந்துகொண்டேன்' என்று கர்த்தர் கூறினார். எரேமியா தான் ஒரு சிறுபிள்ளை என்று தயங்கினாலும், தேவன் அவன் வாயில் தம் வார்த்தைகளை வைத்தார்.",
    "Jeremiah 2": "முதல் அன்பு: இஸ்ரவேல் தன் இளவயதின் அன்பை மறந்துவிட்டது. 'ஜீவனுள்ள தண்ணீரின் ஊற்றாகிய என்னை விட்டுவிட்டு, தண்ணீர் நிற்காத வெடிப்புள்ள தொட்டிகளைத் தங்களுக்கு வெட்டிக்கொண்டார்கள்.'",
    "Jeremiah 3": "திரும்பி வாருங்கள்: விபசாரஞ் செய்த மனைவியைப் போல இஸ்ரவேல் அந்நிய தெய்வங்களைப் பின்பற்றியது. ஆனாலும், 'சீர்கெட்ட பிள்ளைகளே, திரும்பி வாருங்கள், உங்கள் சீர்கேடுகளைக் குணமாக்குவேன்' என்று தேவன் அழைக்கிறார்.",
    "Jeremiah 4": "வடதிசை ஆபத்து: பாபிலோனியப் படை ஒரு சிங்கத்தைப் போலக் காட்டை விட்டுப் புறப்பட்டு வருகிறது. எருசலேம் தன் இருதயத்தைக் கழுவாவிட்டால் அழிவு நிச்சயம். பூமி பாழும் வெறுமையுமாயிருப்பதை எரேமியா காண்கிறார்.",
    "Jeremiah 5": "நீதிமான் ஒருவன் உண்டா?: எருசலேமின் வீதிகளில் தேடினாலும் நீதியைச் செய்கிற ஒரு மனுஷனாகிலும் உண்டா? பெரியோர் முதல் சிறியோர் வரை எல்லாரும் தேவனை விட்டு விலகிப் போனார்கள்.",
    "Jeremiah 6": "பழைய பாதைகள்: 'பழைய பாதைகள் எவை என்று கேட்டு, அந்த நல்வழியில் நடங்கள்; அப்பொழுது உங்கள் ஆத்துமாவுக்கு இளைப்பாறுதல் கிடைக்கும்.' ஆனால் ஜனங்களோ, 'நாங்கள் அதில் நடக்க மாட்டோம்' என்றார்கள்.",
    "Jeremiah 7": "ஆலயப் பிரசங்கம்: 'இது கர்த்தருடைய ஆலயம், கர்த்தருடைய ஆலயம்' என்று சொல்லி ஏமாறாதீர்கள். நீங்கள் திருடிவிட்டு, கொலை செய்துவிட்டு இந்த ஆலயத்தில் வந்து நிற்பது தகுமா? இது 'கள்வர் குகை'யாய் மாறிவிட்டது.",
    "Jeremiah 8": "மருந்து இல்லையோ?: எருசலேம் குணமடைய மறுக்கிறது. 'கீலேயாத்திலே பிசின் தைலம் இல்லையோ? அங்கே வைத்தியன் இல்லையோ?' என் ஜனத்தின் அழிவைக் கண்டு என் இருதயம் நெகிழ்கிறது.",
    "Jeremiah 9": "கண்ணீர் ஆறு: 'என் ஜனத்தின் அழிவுக்காக நான் இரவும் பகலும் அழுவதற்கு என் தலை தண்ணீரும், என் கண்கள் கண்ணீர் ஊற்றுமாயிருந்தால் நலமாயிருக்கும்.' அறிவுள்ளவன் தன் அறிவில் மேன்மைபாராட்டாமல், கர்த்தரை அறிவதிலேயே மேன்மைபாராட்டட்டும்.",
    "Jeremiah 10": "உயிருள்ள தேவனும் விக்கிரகமும்: புறஜாதிகளின் தெய்வங்கள் மரத்தினால் செய்யப்பட்டு பொன்னால் அலங்கரிக்கப்பட்டவை; அவைகளால் பேசவோ நடக்கவோ முடியாது. கர்த்தரோ மெய்யான தெய்வம், நித்திய ராஜா.",
    "Jeremiah 11": "உடன்படிக்கை மீறல்: தேவன் சீனாய் மலையில் செய்த உடன்படிக்கையை இஸ்ரவேல் மீறிவிட்டது. அவர்கள் தங்கள் வீதிகளின் எண்ணிக்கைக்குத் தக்கதாக விக்கிரகங்களை வைத்துக் கொண்டார்கள்.",
    "Jeremiah 12": "எரேமியாவின் கேள்வி: 'துன்மார்க்கருடைய வழி ஏன் 형通ிக்கிறது?' என்று எரேமியா கேட்கிறார். தேவன் பதில் அளிக்கிறார்: 'நீ காலாட்களோடே ஓடும்போதே இளைத்துப் போனால், குதிரைகளோடே எப்படிப் பந்தயமிடுவாய்?'",
    "Jeremiah 13": "அழுக்கடைந்த கச்சை: கர்த்தர் எரேமியாவை ஒரு சணல் கச்சையை வாங்கி ஐபிராத்து நதியோரம் ஒழித்துவைக்கச் சொன்னார். பல நாட்களுக்குப் பின் அது மட்கிப்போயிருந்தது. அதுபோலவே இஸ்ரவேலின் பெருமையும் அழியும்.",
    "Jeremiah 14": "பஞ்சமும் பொய்யான தீர்க்கதரிசிகளும்: தேசத்தில் மழையில்லை, பூமி பிளந்து கிடக்கிறது. 'சமாதானம் வரும்' என்று பொய் சொல்லும் தீர்க்கதரிசிகளை நம்ப வேண்டாம் என்று கர்த்தர் எச்சரிக்கிறார்.",
    "Jeremiah 15": "தனிமையும் தைரியமும்: எரேமியா தன் ஊழியத்தின் நிமித்தம் எல்லாராலும் பகைக்கப்பட்டார். 'உம்முடைய வார்த்தைகள் கிடைத்தபோது அவைகளை உட்கொண்டேன்; அவை என் இருதயத்திற்கு மகிழ்ச்சியாயிருந்தது' என்று தேற்றி வருகிறார்.",
    "Jeremiah 16": "வாழ்க்கையே ஒரு அடையாளம்: எரேமியா திருமணம் செய்யக்கூடாது என்று தேவன் கட்டளையிட்டார். வரப்போகும் அழிவில் குழந்தைகளும் பெற்றோரும் மடிவார்கள் என்பதற்கு இது ஒரு எச்சரிக்கை அடையாளம்.",
    "Jeremiah 17": "இருதயத்தின் வஞ்சனை: 'எல்லாவற்றைப் பார்க்கிலும் இருதயமே திருக்குள்ளதும் மகா கேடுள்ளதுமாயிருக்கிறது; அதை அறியத்தக்கவன் யார்?' கர்த்தரை நம்புகிறவன் தண்ணீர்க்காலோரமாய் நடப்பட்ட மரத்தைப் போலிருப்பான்.",
    "Jeremiah 18": "குயவனும் களிமண்ணும்: 'குயவன் கையில் களிமண் எப்படியிருக்கிறதோ, அப்படியே நீங்கள் என் கையில் இருக்கிறீர்கள்.' களிமண் கெட்டுப்போனால் குயவன் அதைத் தனக்குச் சரி என்று தோன்றுகிற வேறொரு பாத்திரமாக வனைவார்.",
    "Jeremiah 19": "உடைந்த மட்குடம்: எரேமியா ஒரு மட்குடத்தை வாங்கி, அதை ஜனங்களுக்கு முன்பாக உடைத்தார். எருசலேம் திரும்ப ஒட்டவைக்க முடியாதபடி உடைக்கப்படும் என்பதற்கு இது அடையாளம்.",
    "Jeremiah 20": "எரேமியாவின் வேதனை: பஸ்கூர் என்னும் ஆசாரியன் எரேமியாவை அடித்துத் தொழுமரத்தில் போட்டான். எரேமியா துக்கத்தினால் தான் பிறந்த நாளைச் சபித்தார். ஆனாலும், 'தேவனுடைய வார்த்தை என் எலும்புகளில் அடைக்கப்பட்ட அக்கினியைப் போலிருக்கிறது' என்று ஊழியத்தைத் தொடர்ந்தார்.",
    "Jeremiah 21": "சிதேக்கியாவின் கேள்வி: எருசலேம் முற்றுகையிடப்பட்டபோது, சிதேக்கியா ராஜா எரேமியாவிடம் ஜெபிக்கக் கேட்டான். ஆனால் எரேமியா, 'பாபிலோனியர்களுக்குச் சரணடையுங்கள், அதுவே உயிர் பிழைக்க வழி' என்று கடினமான பதிலைச் சொன்னார்.",
    "Jeremiah 22": "ராஜவம்சத்திற்குத் தீர்ப்பு: எக்காலத்திற்கும் முன் இருந்த ராஜாக்களுக்கு (சல்லூம், யோயாக்கீம், கோனியா) வந்த தண்டனை. 'கோனியாவுக்குச் சந்ததி இராது' என்று சபிக்கப்பட்டது (இது மேசியாவின் வம்சாவளியில் ஒரு முக்கியமான திருப்பம்).",
    "Jeremiah 23": "நீதியின் கிளை: பொல்லாத மேய்ப்பர்களைக் கண்டித்த தேவன், 'யெகோவா சித்கேனு' (நமது நீதியாயிருக்கிற கர்த்தர்) என்னும் நாமமுள்ள ஒரு ராஜாவை (மேசியா) எழும்பப்பண்ணுவார் என்று வாக்களித்தார்.",
    "Jeremiah 24": "இரு கூடை அத்திப்பழங்கள்: நல்ல பழங்கள் பாபிலோனுக்குச் சிறைப்பட்டுப் போனவர்களையும், கெட்ட பழங்கள் எருசலேமில் மிஞ்சியிருப்பவர்களையும் குறிக்கும். எருசலேமில் இருப்பவர்களைவிடச் சிறையிருப்பவர்களுக்கே எதிர்காலம் உண்டு.",
    "Jeremiah 25": "70 வருடக் கணக்கு: இஸ்ரவேலரின் சிறையிருப்பு சரியாக 70 வருடங்கள் நீடிக்கும் என்று எரேமியா காலத்தைக் குறிப்பிட்டார். அதன்பின் பாபிலோன் தண்டிப்படும்.",
    "Jeremiah 26": "கொலை மிரட்டல்: ஆலயத்தில் எச்சரித்ததற்காக எரேமியாவைக் கொல்ல ஜனங்கள் முயன்றனர். ஆனால் மீகா தீர்க்கதரிசியின் பழைய எச்சரிக்கையை நினைவு கூர்ந்து, அகிக்காம் என்பவன் எரேமியாவைக் காப்பாற்றினான்.",
    "Jeremiah 27": "நுகத்தடி அடையாளம்: எரேமியா தன் கழுத்தில் ஒரு நுகத்தை (Yoke) மாட்டிக்கொண்டு, 'எல்லா ஜாதிகளும் பாபிலோன் நுகத்திற்குப் பணிய வேண்டும்' என்று தேவனுடைய கட்டளையைச் சொன்னார்.",
    "Jeremiah 28": "அனனியாவின் பொய்: அனனியா என்னும் பொய் தீர்க்கதரிசி எரேமியாவின் கழுத்திலிருந்த நுகத்தை உடைத்து, 'இரண்டு வருடத்தில் விடுதலை வரும்' என்றான். எரேமியா, 'தேவன் உன்னை அனுப்பவில்லை' என்றார்; அனனியா அதே வருடத்தில் இறந்தான்.",
    "Jeremiah 29": "சிறையிருப்பவர்களுக்குக் கடிதம்: பாபிலோனில் இருப்பவர்களுக்கு எரேமியா கடிதம் எழுதி, 'அங்கே வீடுகளைக் கட்டி வாழ்ந்து பலுகுங்கள். என் நினைவுகள் உங்களை ஆசீர்வதிக்கிற நினைவுகள்' (வசனம் 11) என்று ஆறுதல் கூறினார்.",
    "Jeremiah 30": "யாக்கோபின் இக்கட்டுக்காலம்: யூதர்கள் மீண்டும் தங்கள் தேசத்திற்குத் திரும்புவார்கள். அவர்கள் அனுபவிக்கும் வேதனை ஒரு பிரசவ வேதனை போன்றது; அதன் பின் ஒரு புதிய விடியல் வரும்.",
    "Jeremiah 31": "புதிய உடன்படிக்கை: 'அவர்கள் இருதயங்களில் என் பிரமாணத்தை எழுதுவேன்' என்ற மகத்தான வாக்குத்தத்தம். இஸ்ரவேல் மீண்டும் ஒரு ஜாதியாக நிலைநிறுத்தப்படும்.",
    "Jeremiah 32": "நிலம் வாங்குதல்: சிறையிலிருந்த எரேமியாவைத் தன் சொந்த ஊரான ஆனதோத்தில் ஒரு நிலத்தை வாங்கும்படி தேவன் சொன்னார். முற்றுகையின் நடுவிலும் நிலம் வாங்கியது, 'தேசத்தில் மீண்டும் வர்த்தகம் நடக்கும்' என்பதற்கான விசுவாசச் செயல்.",
    "Jeremiah 33": "எட்டாத காரியங்கள்: 'என்னை நோக்கிக் கூப்பிடு, நீ அறியாததும் உனக்கு எட்டாததுமான பெரிய காரியங்களை அறிவிப்பேன்.' தாவீதின் வம்சத்தில் நீதியின் கிளை தோன்றும்.",
    "Jeremiah 34": "விடுதலைப் பொய்: சிதேக்கியா ராஜா அடிமைகளை விடுதலை செய்வதாக உடன்படிக்கை செய்துவிட்டு, பின்பு அவர்களை மீண்டும் பிடித்துக் கொண்டான். இந்த வஞ்சகத்தினால் ராஜா சிறைப்பிடிக்கப்படுவான் என்று எச்சரிக்கப்பட்டது.",
    "Jeremiah 35": "ரேகாபியரின் கீழ்ப்படிதல்: ரேகாபியர் தங்கள் முன்னோரின் கட்டளைப்படி திராட்சரசம் குடிக்காமல் உண்மையாயிருந்தனர். அவர்கள் மனுஷருக்குக் கீழ்ப்படியும்போது, இஸ்ரவேல் தேவனுக்குக் கீழ்ப்படியவில்லையே என்று கர்த்தர் கண்டித்தார்.",
    "Jeremiah 36": "சுருள் எரிப்பு: எரேமியாவின் வார்த்தைகளை பாருக் ஒரு சுருளில் எழுதினான். யோயாக்கீம் ராஜா அதைக் கேட்டு, கோபமடைந்து அதை நெருப்பில் எரித்தான். தேவன் அதை மீண்டும் எழுதச் சொன்னார்.",
    "Jeremiah 37": "எரேமியா சிறையில்: பாபிலோனியர் தற்காலிகமாக முற்றுகையை நீக்கியபோது, எரேமியா தன் ஊருக்குப் போக முயன்றார். அவர் பகைவருக்கு உதவுகிறார் என்று குற்றம் சாட்டப்பட்டு அடித்திக் காவலில் வைக்கப்பட்டார்.",
    "Jeremiah 38": "சேற்றுக்குழி: பிரபுக்கள் எரேமியாவை ஒரு ஆழமான சேற்றுக்குழியில் போட்டனர். எபெத்மெலேக் என்னும் எத்தியோப்பியன் கயிறுகளைப் போட்டு அவரை அங்கிருந்து தூக்கி காப்பாற்றினான்.",
    "Jeremiah 39": "எருசலேமின் வீழ்ச்சி: எருசலேம் மதில்கள் தகர்க்கப்பட்டன. சிதேக்கியாவின் கண்கள் பிடுங்கப்பட்டு அவன் பாபிலோனுக்குக் கொண்டு செல்லப்பட்டான். எருசலேம் எரிக்கப்பட்டது. எரேமியா மட்டும் விடுவிக்கப்பட்டார்.",
    "Jeremiah 40": "கெதலியாவின் ஆளுமை: பாபிலோனியர் கெதலியாவை ஆளுநராக நியமித்தனர். எரேமியா அவனுடன் மிஸ்பாவிலே தங்கினார். சிதறிப்போன யூதர்கள் மீண்டும் தேசத்திற்குத் திரும்பத் தொடங்கினர்.",
    "Jeremiah 41": "கெதலியாவின் படுகொலை: இஸ்மவேல் என்பவன் யூத ஆளுநரான கெதலியாவையும் அவனோடிருந்தவர்களையும் வஞ்சகமாகக் கொன்று, எஞ்சியவர்களைச் சிறைபிடித்துச் செல்ல முயன்றான். யோகனான் என்பவன் வந்து ஜனங்களை மீட்டான்.",
    "Jeremiah 42": "எகிப்திற்கு எச்சரிக்கை: தப்பிப்பிழைத்த ஜனங்கள் எரேமியாவிடம் வந்து, 'நாங்கள் எங்கு செல்ல வேண்டும்?' என்று கேட்டனர். 'நீங்கள் எகிப்திற்குப் போகாமல் யூதாவிலேயே தங்கினால் வாழ்வீர்கள், போனால் அழிவீர்கள்' என்று தேவன் தடுத்தார்.",
    "Jeremiah 43": "கீழ்ப்படியாமையும் எகிப்தும்: ஜனங்கள் எரேமியாவை 'பொய்யன்' என்று நிந்தித்து, கர்த்தருடைய வார்த்தையை மீறி எகிப்திற்கு ஓடினர். அங்கே நேபுகாத்நேச்சார் வந்து எகிப்தின் விக்கிரகங்களை எரிப்பான் என்று எரேமியா அடையாளமாகச் சொன்னார்.",
    "Jeremiah 44": "வானத்து ராணி வழிபாடு: எகிப்தில் குடியேறிய யூதர்கள் மீண்டும் விக்கிரக ஆராதனையில் ஈடுபட்டனர். எரேமியா அவர்களின் பிடிவாதத்தைக் கண்டித்து, அங்கே சென்றவர்களில் ஒரு சிலரைத் தவிர மற்ற அனைவரும் அழிவார்கள் என்று எச்சரித்தார்.",
    "Jeremiah 45": "பாருக்குக்குச் செய்தி: எரேமியாவின் உதவியாளன் பாருக் தன் துயரத்தின் நிமித்தம் வருந்தியபோது, தேவன் அவனுக்குத் தனிப்பட்ட முறையில் ஆறுதல் கூறினார். 'உனக்காகப் பெரிய காரியங்களைத் தேடாதே; ஆனால் உன் உயிரைத் தப்புவிப்பேன்' என்று வாக்களித்தார்.",
    "Jeremiah 46": "எகிப்தின் வீழ்ச்சி: பார்வோன் நேகோவின் படைகள் பாபிலோனியர்களால் தோற்கடிக்கப்படும் என்று முன்னறிவிக்கப்பட்டது. எகிப்தின் பெருமை தாழ்த்தப்படும், ஆனால் இஸ்ரவேலைத் தேவன் முற்றாக அழிக்கமாட்டார்.",
    "Jeremiah 47": "பெலிஸ்தியரின் அழிவு: வடக்கேயிருந்து (பாபிலோன்) வரும் ஒரு வெள்ளம் பெலிஸ்தியரின் தேசத்தைப் புரட்டிப்போடும். காசா மற்றும் அஸ்கலோன் நகரங்களுக்கு வரும் அழிவை இது விவரிக்கிறது.",
    "Jeremiah 48": "மோவாபின் பாரம்: மோவாபின் பெருமை மற்றும் அதன் தெய்வமான காமோஸ் அவமானப்படும். மோவாப் ஒரு பாத்திரத்தைப் போல உடைக்கப்படும்; ஆனால் கடைசி நாட்களில் தேவன் அவர்களைத் திரும்பச் சேர்ப்பார்.",
    "Jeremiah 49": "அண்டை நாடுகளின் தண்டனை: அம்மோன், ஏதோம், தமஸ்கு, கேதார், ஆசோர் மற்றும் ஏலாம் ஆகிய தேசங்களுக்கு வரும் நியாயத்தீர்ப்பு. ஏதோமின் உயர்ந்த கோட்டைகள் தகர்க்கப்படும் என்று எச்சரிக்கப்பட்டது.",
    "Jeremiah 50": "பாபிலோனுக்குத் தீர்ப்பு: இஸ்ரவேலைத் தண்டித்த கருவியாகிய பாபிலோன், இப்போது அதன் சொந்த அக்கிரமத்திற்காகத் தண்டிப்படும். ஒரு மகா ஜாதி வடக்கேயிருந்து வந்து பாபிலோனைப் பாழாக்கும்.",
    "Jeremiah 51": "சுருள் ஆற்றில் எறியப்படுதல்: பாபிலோனின் அழிவு நித்தியமானது. எரேமியா இந்த வார்த்தைகளை ஒரு சுருளில் எழுதி, அதைச் செராயாவிடம் கொடுத்து பாபிலோனில் வாசிக்கச் சொன்னார். பிறகு அதை ஒரு கல்லோடு கட்டி ஐபிராத்து நதியில் எறியச் சொன்னார்.",
    "Jeremiah 52": "வரலாற்றுப் பின்னுரை: எருசலேம் எப்படி முற்றுகையிடப்பட்டது, ஆலயம் எப்படி எரிக்கப்பட்டது என்பது விவரிக்கப்படுகிறது. இறுதியாக, சிறைபிடிக்கப்பட்ட யூத ராஜா யோயாக்கீன் பாபிலோனில் சிறையிலிருந்து விடுவிக்கப்பட்டு கௌரவிக்கப்பட்டார்.",

    "Lamentations 1": "எருசலேமின் தனிமை: ஒரு காலத்தில் ஜனங்களால் நிறைந்திருந்த நகரம் இப்போது விதவையைப்போலத் தனித்திருக்கிறது. 'வழியே போகிறவர்களே, என் துக்கத்திற்குச் சமானமான துக்கம் உண்டோ?' என்று எருசலேம் புலம்புகிறது. தன் பாவத்தினிமித்தம் இந்த அழிவு வந்ததென்று ஒப்புக்கொள்கிறது.",
    "Lamentations 2": "கர்த்தரின் கோபம்: தேவனே எருசலேமுக்குச் சத்துருவைப்போல எழும்பினார். அவர் தமது ஆலயத்தை ஒரு தோட்டத்தின் கூடாரத்தைப்போல அழித்தார். சிறு பிள்ளைகள் பசியினால் வீதிகளில் மயங்கி விழுவதைக் கண்டு தீர்க்கதரிசியின் கண்கள் கண்ணீரால் மங்குகிறது.",
    "Lamentations 3": "நம்பிக்கையின் மையம்: புத்தகத்தின் மிக முக்கியமான பகுதி. 'கர்த்தருடைய கிருபைகளே நாம் நிர்மூலமாகாதிருக்கக் காரணம்; அவருடைய இரக்கங்களுக்கு முடிவில்லை; அவை காலைதோறும் புதியவைகள்.' கர்த்தர் என்றென்றைக்கும் கைவிடமாட்டார்.",
    "Lamentations 4": "மாறிய மகிமை: சுத்தப்பொன்னைப் போன்ற சீயோன் குமாரர்கள் மட்குடங்களைப் போல எண்ணப்படுகிறார்கள். ராஜாக்களும் பிரபுக்களும் பசியினால் அடையாளம் தெரியாதபடி மாறிப்போனார்கள். எருசலேமின் பாவத்தினிமித்தம் எதோம் மகிழ்ச்சியடைகிறது, ஆனால் அவளுக்கும் தண்டனை வரும்.",
    "Lamentations 5": "மன்னிப்புக்கான ஜெபம்: 'கர்த்தாவே, எங்களை உம்மிடத்தில் திருப்பிக்கொள்ளும், அப்பொழுது திரும்புவோம்; எங்கள் நாட்களைப் பூர்வகாலத்திலிருந்ததுபோலப் புதியவைகளாக்கும்.' எங்களை முற்றிலும் வெறுத்துவிட்டீரோ? என்று கேட்டு இந்தப் புலம்பல் முடிகிறது.",

    "Ezekiel 1": "தேவ மகிமையின் தரிசனம்: எசேக்கியேல் வானங்கள் திறக்கப்படக் கண்டார். நான்கு ஜீவன்களும், சுழலும் சக்கரங்களும், மின்னும் மேகங்களும் தெரிந்தன. சிங்காசனத்தின்மேல் கர்த்தருடைய மகிமையின் சாயலைக் கண்டு அவர் முகம் குப்புற விழுந்தார்.",
    "Ezekiel 2": "தீர்க்கதரிசியின் அழைப்பு: 'மனுபுத்திரனே, கால்கூன்றி நில்' என்று தேவன் சொன்னார். கலகக்காரராகிய இஸ்ரவேல் ஜனங்களிடத்தில் அவரை அனுப்பினார். அவர்கள் கேட்டாலும் கேட்காவிட்டாலும், ஒரு தீர்க்கதரிசி தங்களுக்குள் இருந்தான் என்று அவர்கள் அறியவேண்டும்.",
    "Ezekiel 3": "சுருளை உட்கொள்ளுதல்: தேவன் கொடுத்த சுருளை எசேக்கியேல் புசித்தார்; அது அவர் வாய்க்குத் தேனைப்போல இனித்தது. அவர் இஸ்ரவேல் வம்சத்தாருக்குக் 'காவற்காரனாக' (Watchman) நியமிக்கப்பட்டார்.",
    "Ezekiel 4": "எருசலேம் முற்றுகையின் அடையாளம்: எசேக்கியேல் ஒரு செங்கல்லை எடுத்து அதன்மேல் எருசலேமை வரைந்து முற்றுகையிடுவது போலச் செய்தார். 390 நாட்கள் ஒரு பக்கமாகவும், 40 நாட்கள் மறுபக்கமாகவும் படுத்து ஜனங்களின் பாவத்தைச் சுமந்தார்.",
    "Ezekiel 5": "சவரம் செய்த மயிர்: எசேக்கியேல் தன் தலைமயிரையும் தாடியையும் சவரம் செய்து, அதை மூன்று பங்காகப் பிரித்தார். ஒரு பங்கு தீயினால் எரிக்கப்படும், ஒரு பங்கு பட்டயத்தால் வெட்டப்படும், ஒரு பங்கு காற்றிலே சிதறடிக்கப்படும்.",
    "Ezekiel 6": "மலைகளுக்குத் தீர்ப்பு: இஸ்ரவேலின் மலைகளே, உங்கள் மேடைகள் அழிக்கப்படும். உங்கள் விக்கிரகங்கள் உடைக்கப்படும். நீங்கள் சிதறடிக்கப்படும்போது, நானே கர்த்தர் என்று அறிந்துகொள்வீர்கள்.",
    "Ezekiel 7": "முடிவு வந்தது: 'முடிவு வருகிறது, இதோ முடிவு வந்துவிட்டது!' எருசலேமின் அழிவு தவிர்க்க முடியாதது. பொன்னும் வெள்ளியும் அவர்களைத் தப்புவிக்க முடியாது; தேசம் அக்கிரமத்தினால் நிறைந்திருக்கிறது.",
    "Ezekiel 8": "ஆலயத்தின் அருவருப்புகள்: ஆவியானவர் எசேக்கியேலை எருசலேம் ஆலயத்திற்கு அழைத்துச் சென்றார். அங்கே ரகசியமாகச் செய்யப்பட்ட விக்கிரக ஆராதனையையும், சூரியனை வணங்குவதையும் தேவன் அவருக்குக் காட்டினார்.",
    "Ezekiel 9": "நெற்றியில் அடையாளம்: எருசலேமில் நடக்கும் அருவருப்புகளுக்காகத் துக்கித்து அழுகிறவர்களின் நெற்றியில் அடையாளம் இடப்பட்டது. அந்த அடையாளம் இல்லாதவர்கள் சங்காரத் தூதர்களால் அழிக்கப்பட்டனர்.",
    "Ezekiel 10": "தேவ மகிமை விலகுதல்: கேருபீன்களுக்கு மேலிருந்த கர்த்தருடைய மகிமை ஆலயத்தின் வாசற்படியை விட்டு விலகிச் சென்றது. எருசலேம் கைவிடப்படுவதை இது குறிக்கிறது.",
    "Ezekiel 11": "இதய மாற்றம்: தீய ஆலோசனை சொன்ன பிரபுக்களுக்குத் தீர்ப்பு. சிதறிப்போன இஸ்ரவேலரைத் தேவன் மீண்டும் சேர்ப்பார். 'கல்லான இருதயத்தை எடுத்துவிட்டு, அவர்களுக்குச் சதையான இருதயத்தைத் தருவேன்.'",
    "Ezekiel 12": "சிறையிருப்புப் பயணம்: எசேக்கியேல் தன் வீட்டுச் சுவரைத் துளைத்து, சிறைப்பட்டுப் போகிறவனைப் போல மூட்டையைச் சுமந்து சென்றார். சிதேக்கியா ராஜா எருசலேமை விட்டுத் தப்பி ஓடிப் பிடிபடுவார் என்பதற்கு இது அடையாளம்.",
    "Ezekiel 13": "பொய் தீர்க்கதரிசிகள்: சுவரில் சாந்து பூசி (Whitewash) 'சமாதானம்' என்று பொய் சொல்லும் தீர்க்கதரிசிகளுக்கு ஐயோ! பெருங்காற்றும் கல்மழையும் வந்து அந்தச் சுவரை இடித்துப்போடும்.",
    "Ezekiel 14": "இருதயத்தின் விக்கிரகங்கள்: விக்கிரகங்களை இருதயத்தில் வைத்துக்கொண்டு தேவனிடம் ஆலோசனை கேட்க வருபவர்களுக்குப் பதில் கிடைக்காது. நோவா, தானியேல், யோபு ஆகிய மூவர் இருந்தாலும் அந்தத் தேசத்தைத் தப்புவிக்க முடியாது.",
    "Ezekiel 15": "பயனற்ற திராட்சைக்கொடி: காட்டின் மரங்களுக்குள்ளே திராட்சைக்கொடி எதற்கும் உதவாது; அது எரிக்கப்படவே உதவும். எருசலேம் ஜனங்களும் அப்படியே நெருப்புக்கு இரையாவார்கள்.",
    "Ezekiel 16": "விபசாரஞ் செய்த மனைவி: எருசலேமை ஒரு அநாதை குழந்தையாக தேவன் எடுத்து வளர்த்தார். அவள் வளர்ந்தபின் அவளுக்கு ராஜ மரியாதையைத் தந்தார்; ஆனால் அவள் தன் அழகை நம்பி விக்கிரகங்களோடு விபசாரஞ் செய்தாள். இருப்பினும், தேவன் தமது உடன்படிக்கையை நினைவுகூருவார்.",
    "Ezekiel 17": "இரு கழுகுகள்: ஒரு பெரிய கழுகு (பாபிலோன்) கேதுரு மரத்தின் நுனியை ஒடித்தது. மற்றொரு கழுகு (எகிப்து) உதவியை யூதா நாடியது. இந்த அரசியல் சூழ்ச்சியால் நாடு அழியும், ஆனால் கர்த்தர் ஒரு மெல்லிய கிளையை (மேசியா) நட்டு அதை பெரிய மரமாக்குவார்.",
    "Ezekiel 18": "தனிநபர் பொறுப்பு: 'பிதாக்கள் திராட்சைப்பழம் தின்றார்கள், பிள்ளைகளின் பல் கூசிற்று' என்ற பழமொழியை இனிச் சொல்லாதே. பாவஞ்செய்கிற ஆத்துமாவே சாகும். நீதிமானின் நீதி அவனையே சாரும்; துன்மார்க்கன் மனந்திரும்பினால் பிழைப்பான்.",
    "Ezekiel 19": "சிங்கக்குட்டிகளுக்காகப் புலம்பல்: இஸ்ரவேலின் ராஜாக்கள் கூண்டில் அடைக்கப்பட்ட சிங்கக்குட்டிகளைப் போலப் பிடிக்கப்பட்டு எகிப்துக்கும் பாபிலோனுக்கும் கொண்டு செல்லப்பட்டனர். இது ஒரு துக்கப்பாட்டு.",
    "Ezekiel 20": "இஸ்ரவேலின் வரலாறு: எகிப்து முதல் வனாந்தரம் வரை இஸ்ரவேலர் கலகம் செய்த வரலாற்றை தேவன் விவரிக்கிறார். அவர்கள் தன் ஓய்வுநாட்களைத் தீட்டுப்படுத்தினார்கள். ஆயினும், தேவன் தம் நாமத்தினிமித்தம் அவர்களை முற்றிலும் அழிக்கவில்லை.",
    "Ezekiel 21": "உருவப்பட்ட பட்டயம்: கர்த்தருடைய பட்டயம் உறையிலிருந்து உருவப்பட்டது; அது எருசலேமை நோக்கி மின்னுகிறது. பாபிலோன் ராஜா கைகுறியைப் பார்த்து எருசலேமுக்கு விரோதமாய் வருவான்.",
    "Ezekiel 22": "இரத்தஞ்சிந்துதலால் நிறைந்த நகரம்: எருசலேமின் பாவங்கள் பட்டியலிடப்படுகின்றன. 'தேசத்திற்காகத் திறப்பில் நிற்கத்தக்க ஒரு மனுஷனைத் தேடினேன், ஒருவனையும் காணவில்லை' என்று தேவன் வருந்துகிறார்.",
    "Ezekiel 23": "ஒகோலா மற்றும் ஒகோலிபா: சமாரியா (ஒகோலா) மற்றும் எருசலேம் (ஒகோலிபா) என்ற இரு சகோதரிகளின் கதை. இருவரும் அசிரியாவையும் எகிப்தையும் காதலித்து விக்கிரகாராதனை செய்தார்கள். அவர்கள் செய்த அதே கொடுமை அவர்களுக்குத் தண்டனையாக வரும்.",
    "Ezekiel 24": "கொதிக்கிற கொப்பரை: எருசலேம் ஒரு துருப்பிடித்த கொப்பரையைப் போன்றது; அது நெருப்பிலே வைக்கப்படும். எசேக்கியேலின் மனைவி அன்றைய தினம் இறந்தார்; ஆனால் அவர் துக்கப்படக்கூடாது என்று தேவன் சொன்னார். இது எருசலேமின் அழியாத துக்கத்திற்கு அடையாளம்.",
    "Ezekiel 25": "அண்டை நாடுகளுக்குத் தீர்ப்பு: இஸ்ரவேலின் அழிவைக் கண்டு கைதட்டி மகிழ்ந்த அம்மோன், மோவாப், ஏதோம் மற்றும் பெலிஸ்தியர் தண்டிப்படுவார்கள்.",
    "Ezekiel 26": "தீருவின் வீழ்ச்சி: கடல் வர்த்தகத்தில் சிறந்து விளங்கிய தீரு நகரம் அலைகளால் மூழ்கடிக்கப்படும் பாறையைப் போலாகும். நேபுகாத்நேச்சார் அதை அழிப்பார்.",
    "Ezekiel 27": "கப்பல் உடைந்த கதை: தீரு ஒரு அழகான கப்பலைப் போல வர்ணிக்கப்படுகிறது. எல்லா தேசத்துச் செல்வங்களும் அதில் இருந்தன. ஆனால் அது பெருங்கடலின் நடுவே உடைந்து போகும்.",
    "Ezekiel 28": "தீரு ராஜாவின் வீழ்ச்சி: தீருவின் ராஜா தன்னை ஒரு தேவன் என்று எண்ணினான். அவனுடைய அழகும் ஞானமும் அவனைப் பெருமைப்படுத்தியது. (இந்த அதிகாரம் சாத்தானின் வீழ்ச்சிக்கும் ஒரு நிழலாகக் கருதப்படுகிறது).",
    "Ezekiel 29": "நைல் நதியின் முதலை: எகிப்தின் ராஜாவாகிய பார்வோன் தன்னை நைல் நதியின் சொந்தக்காரன் என்று பெருமை பேசினான். தேவன் அவனை ஒரு பெரிய முதலையைப்போலத் தூண்டிலால் பிடித்து வனாந்தரத்தில் எறிவார். எகிப்து 40 வருடங்கள் பாழாயிருக்கும்; அதன்பின் அது திரும்பச் சேர்க்கப்பட்டாலும், அது மற்ற ஜாதிகளை ஆள முடியாத ஒரு தாழ்ந்த ராஜ்யமாகவே இருக்கும்.",
    "Ezekiel 30": "எகிப்தின் அந்தகாரம்: எகிப்தின் அழிவுக்காகப் புலம்புங்கள்! 'கர்த்தருடைய நாள்' சமீபமாயிருக்கிறது. நேபுகாத்நேச்சாரின் கை எகிப்தின் கூட்டத்தை நிர்மூலமாக்கும். பத்ரோஸ், சோவான் மற்றும் நோ (தீப்ஸ்) போன்ற முக்கியமான நகரங்கள் தீயினால் எரிக்கப்படும். எகிப்தின் புயங்கள் முறிக்கப்படும்; அப்பொழுது நானே கர்த்தர் என்று அவர்கள் அறிந்துகொள்வார்கள்.",
    "Ezekiel 31": "கேதுரு மரத்தின் வீழ்ச்சி: எகிப்தின் பார்வோன் ஒரு உயரமான கேதுரு மரத்திற்கு ஒப்பிடப்படுகிறான். அதன் கிளைகள் மேகங்கள் வரை சென்றன. ஆனால் அதன் பெருமையினிமித்தம் அது வெட்டி வீழ்த்தப்பட்டது. அசீரியாவுக்கு நேர்ந்த அதே கதி எகிப்துக்கும் ஏற்படும்.",
    "Ezekiel 32": "பார்வோனுக்காகப் புலம்பல்: ஒரு பெரிய முதலையைப் போலிருந்த பார்வோன் வலையில் பிடிக்கப்பட்டு, அவனுடைய ரத்தம் மலைகளை நனைக்கும். அவன் பாதாளத்திற்கு இறங்கும்போது ஏதோம், ஏலாம் போன்ற மற்ற தேசங்கள் அவனைக் கண்டு திடுக்கிடும்.",
    "Ezekiel 33": "காவற்காரனின் கடமை: எருசலேம் வீழ்ந்த செய்தி எசேக்கியேலுக்கு வருகிறது. தேவன் மீண்டும் அவரை ஒரு காவற்காரனாக (Watchman) நியமிக்கிறார். 'துன்மார்க்கன் சாவதில் எனக்குப் பிரியமில்லை, அவன் மனந்திரும்பிப் பிழைப்பதிலேயே எனக்குப் பிரியம்' என்று தேவன் கூறுகிறார்.",
    "Ezekiel 34": "உண்மையான மேய்ப்பன்: சுயநலமுள்ள இஸ்ரவேலின் மேய்ப்பர்களுக்கு (தலைவர்கள்) ஐயோ! கர்த்தரே தமது ஆடுகளைத் தேடி வந்து அவற்றைக் காப்பார். அவர் 'தாவீது' என்னும் நாமமுள்ள ஒரு மேய்ப்பனை (மேசியா) அவர்களுக்குத் தருவார்.",
    "Ezekiel 35": "சேயீர் மலைக்குத் தீர்ப்பு: ஏதோம் தேசம் இஸ்ரவேலின் அழிவைக் கண்டு மகிழ்ச்சியடைந்து, அவர்களின் நிலத்தைக் கைப்பற்ற முயன்றது. இதினிமித்தம் சேயீர் மலை (ஏதோம்) பாழாக்கப்படும்.",
    "Ezekiel 36": "புது இருதயம்: இஸ்ரவேலின் மலைகள் மீண்டும் செழிக்கும். தேவன் தம்முடைய பரிசுத்த நாமத்தினிமித்தம் அவர்களைத் திரும்பச் சேர்ப்பார். 'உங்களுக்குப் புதிய இருதயத்தைத் தந்து, உங்கள் உள்ளத்திலே புதிய ஆவியைக் கட்டளையிடுவேன்.'",
    "Ezekiel 37": "உலர்ந்த எலும்புகள்: எசேக்கியேல் ஒரு பள்ளத்தாக்கு நிறைய உலர்ந்த எலும்புகளைக் கண்டார். தேவன் அந்த எலும்புகளுக்கு உயிர் கொடுத்தார்; அவை ஒரு பெரிய சேனையாக எழும்பின. இஸ்ரவேல் வம்சம் மீண்டும் உயிர்பெற்றுத் திரும்பும் என்பதற்கு இது அடையாளம்.",
    "Ezekiel 38": "கோகுவின் படையெடுப்பு: கடைசி நாட்களில் வடதிசை தேசங்களின் தலைவனான கோகு (Gog), மாகோகு தேசத்திலிருந்து ஒரு பெரிய கூட்டணியோடு இஸ்ரவேலுக்கு விரோதமாக வருவான். பாதுகாப்பில்லாமல் அமைதியாய் வாழும் ஜனங்களை அவர்கள் தாக்குவார்கள். ஆனால் தேவன் கோபமடைந்து, நிலநடுக்கம், கொள்ளைநோய் மற்றும் வானத்திலிருந்து அக்கினியை அனுப்பி அவர்களைத் தண்டிப்பார்.",
    "Ezekiel 39": "கோகுவின் வீழ்ச்சி: கோகுவின் வில்லும் அம்புகளும் முறிக்கப்படும். அவனது சேனைகள் இஸ்ரவேலின் மலைகள்மேல் விழும். அவர்களின் போர்க்கருவிகளை எரிப்பதற்கே இஸ்ரவேலருக்கு ஏழு வருடங்கள் ஆகும். இறந்தவர்களை அடக்கம் செய்ய ஏழு மாதங்கள் ஆகும். இதன் மூலம் புறஜாதிகள் யாவரும் 'நானே கர்த்தர்' என்று அறிந்துகொள்வார்கள்; தேவன் தம் ஜனத்தின்மேல் தம் ஆவியை ஊற்றுவார்.",
    "Ezekiel 40": "புதிய ஆலயத்தின் அளவீடு: எருசலேம் வீழ்ந்து 14 வருடங்களுக்குப் பின், எசேக்கியேல் ஒரு தரிசனத்தில் எருசலேமுக்குக் கொண்டு செல்லப்பட்டார். அங்கே ஒரு மனிதன் ஒரு அளவுகோலினால் புதிய ஆலயத்தின் வாசல்களையும் பிரகாரங்களையும் அளப்பதைக் கண்டார்.",
    "Ezekiel 41": "ஆலயத்தின் உட்புறம்: தேவன் எசேக்கியேலை ஆலயத்தின் மகா பரிசுத்த ஸ்தலத்திற்கு அழைத்துச் சென்றார். அதன் சுவர்கள், கதவுகள் மற்றும் பலிபீடம் ஆகியவற்றின் அளவுகள் விவரிக்கப்படுகின்றன. சுவர்களில் கேருபீன்களும் பேரீச்சமரங்களும் செதுக்கப்பட்டிருந்தன.",
    "Ezekiel 42": "ஆசாரியர்களின் அறைகள்: ஆலயத்தைச் சுற்றியிருந்த பரிசுத்த அறைகள் அளக்கப்பட்டன. ஆசாரியர்கள் பரிசுத்த ஆடைகளை அணியவும், பலிகளைப் புசிக்கவும் இந்த இடங்கள் ஒதுக்கப்பட்டன. பரிசுத்தமானதற்கும் சாதாரணமானதற்கும் இடையே ஒரு மதில் பிரிக்கப்பட்டிருந்தது.",
    "Ezekiel 43": "மகிமை திரும்புதல்: எசேக்கியேல் புத்தகத்தின் ஆரம்பத்தில் ஆலயத்தை விட்டு விலகிச் சென்ற கர்த்தருடைய மகிமை, இப்போது கிழக்கு வாசல் வழியாக மீண்டும் ஆலயத்திற்குள் நுழைந்தது. 'இந்த இடம் நான் என்றென்றைக்கும் தங்கும் இடம்' என்று கர்த்தர் கூறினார்.",
    "Ezekiel 44": "பரிசுத்தத்தின் விதிகள்: கர்த்தர் நுழைந்த கிழக்கு வாசல் அடைக்கப்பட வேண்டும். அந்நியர்கள் ஆலயத்திற்குள் வரக்கூடாது. ஆசாரியர்களாகிய சாதோக்கின் சந்ததியினர் மட்டுமே கர்த்தருக்குப் பணிவிடை செய்யத் தகுதியுள்ளவர்கள்.",
    "Ezekiel 45": "நிலத்தின் பங்கீடு: ஆலயத்தைச் சுற்றியுள்ள நிலம் பரிசுத்தப் பங்காகப் பிரிக்கப்பட்டது. இஸ்ரவேலின் பிரபுக்கள் ஜனங்களை ஒடுக்காமல் நீதியாக ஆள வேண்டும். பண்டிகை நாட்களுக்கான பலிகள் குறித்த விதிகள் கொடுக்கப்பட்டன.",
    "Ezekiel 46": "ஆராதனையின் முறைகள்: ஓய்வுநாட்களிலும் மாதப்பிறப்பிலும் ராஜா மற்றும் ஜனங்கள் எப்படி ஆராதிக்க வேண்டும் என்ற விதிகள். பலியிடப்படும் இடங்களும் சமையல் அறைகளும் எசேக்கியேலுக்குக் காட்டப்பட்டன.",
    "Ezekiel 47": "ஜீவநதி: ஆலயத்தின் வாசற்படியின் கீழிருந்து தண்ணீர் புறப்பட்டு ஓடியது. அது செல்லச் செல்ல ஆழமான ஆறாக மாறியது. அந்த நதி பாயுமிடமெல்லாம் ஜீவன் உண்டானது; சாக்கடல் (Dead Sea) நல்ல தண்ணீராக மாறியது. கரைகளில் கனி தரும் மரங்கள் வளர்ந்தன.",
    "Ezekiel 48": "கோத்திரங்களின் பங்கீடு: பன்னிரண்டு கோத்திரங்களுக்கும் நிலம் சமமாகப் பிரிக்கப்பட்டது. நகரத்திற்கு 12 வாசல்கள் இருந்தன. அந்த நகரத்தின் பெயர்: 'யெகோவா ஷம்மா' (கர்த்தர் அங்கே இருக்கிறார்).",
    
    "Hebrews 1": "பூர்வகாலங்களில் தீர்க்கதரிசிகள் மூலமாய்ப் பிதாக்களோடே பேசின தேவன், இந்தக் கடைசி நாட்களில் குமாரன் மூலமாய் நம்மோடே பேசினார்; அவர் தேவனுடைய மகிமையின் பிரகாசமும் அவருடைய தன்மையின் சொரூபமுமாயிருந்து, நம்முடைய பாவங்களைத் தம்மாலே நீக்கி, உன்னதத்திலுள்ள மகத்துவமானவருடைய வலதுபாரிசத்தில் உட்கார்ந்தார். குமாரன் தேவதூதரைப் பார்க்கிலும் மேன்மையுள்ளவர்; 'நீர் என்னுடைய குமாரன், இன்று நான் உம்மை ஜெநிப்பித்தேன்' என்றும், 'தேவனே, உம்முடைய சிங்காசனம் என்றென்றைக்குமுள்ளது' என்றும் வேதவாக்கியங்கள் அவரைக் குறித்துச் சொல்லுகின்றன. தூதர்களெல்லாரும் இரட்சிப்பைச் சுதந்தரிக்கப்போகிறவர்களினிமித்தம் ஊழியஞ்செய்யும்படிக்கு அனுப்பப்படும் பணிவிடை ஆவிகளாயிருக்கிறார்கள்.",
    "Hebrews 2": "ஆகையால், நாம் கேட்டவைகளைவிட்டு விலகாதபடிக்கு அவைகளை மிகுந்த ஜாக்கிரதையாய்க் கவனிக்கவேண்டும்; 'இவ்வளவு பெரிதான இரட்சிப்பைக்குறித்து நாம் கவலையற்றிருப்போமானால், தண்டனைக்கு எப்படித் தப்பித்துக்கொள்ளுவோம்?'. இயேசு தேவனுடைய கிருபையினால் எல்லாருக்காகவும் மரணத்தை ருசிபார்க்கும்படிக்குத் தேவதூதரிலும் சற்றுச் சிறியவராக்கப்பட்டு, மகிமையினாலும் கனத்தினாலும் முடிசூட்டப்பட்டார்; அநேகம் புத்திரரை மகிமைக்குக் கொண்டுவரும்படி, அவர்களுடைய இரட்சணியத்தின் அதிபதியைப் பாடுகளினாலே பூரணப்படுத்துவது தேவனுக்கு ஏற்றதாயிருந்தது. மரணத்துக்கு அதிகாரியாகிய பிசாசானவனைத் தம்முடைய மரணத்தினாலே அழிக்கும்படி அவர் மாம்சத்திலும் இரத்தத்திலும் பங்குள்ளவரானார்; அவர் தாமே சோதிக்கப்பட்டுப் பாடுபட்டதினாலே, சோதிக்கப்படுகிறவர்களுக்கு உதவிசெய்ய வல்லவராயிருக்கிறார்.",
    "Hebrews 3": "இயேசு மோசேயைவிட உயர்ந்தவர். வனாந்தரத்தில் இருந்த மக்கள் அவிசுவாசத்தினால் தேவனுடைய இளைப்பாறுதலுக்குள் நுழையவில்லை. ஆகவே நாம் தேவனை நம்பி, இருதயத்தைக் கடினப்படுத்தாமல், ஒவ்வொரு நாளும் ஒருவரையொருவர் உற்சாகப்படுத்த வேண்டும்.",
    "Hebrews 4": "அவருடைய இளைப்பாறுதலில் பிரவேசிப்பதற்கேதுவான வாக்குத்தத்தம் இன்னும் இருக்கிறபடியால், உங்களில் ஒருவனும் அதை அடையாமல் பின்வாங்கிப்போனவனாய்க் காணப்படாதபடிக்கு எச்சரிக்கையாயிருப்போமாக; விசுவாசித்திருக்கிற நாமோ அந்த இளைப்பாறுதலில் பிரவேசிக்கிறோம். 'தேவனுடைய வார்த்தையானது ஜீவனும் வல்லமையுமுள்ளதாயும், இருபுறமும் கருக்குள்ள எந்தப் பட்டயத்திலும் கருக்கானதாயும், இருதயத்தின் நினைவுகளையும் யோசனைகளையும் வகையறுக்கிறதாயும் இருக்கிறது'. வானங்களின் வழியாய்ப் போன தேவகுமாரனாகிய இயேசு என்னும் மகா பிரதான ஆசாரியர் நமக்கு இருக்கிறார்; அவர் எல்லாவிதத்திலும் நம்மைப்போலச் சோதிக்கப்பட்டும் பாவமில்லாதவராயிருந்தார்; ஆகையால் நாம் இரக்கத்தைப் பெறவும், ஏற்ற சமயத்தில் சகாயஞ்செய்யும் கிருபையை அடையவும், தைரியமாய்க் கிருபாசனத்தண்டையிலே சேரக்கடவோம்.",
    "Hebrews 5": "மனுஷரிலிருந்து தெரிந்துகொள்ளப்பட்ட பிரதான ஆசாரியன் பாவங்களுக்காகக் காணிக்கைகளையும் பலிகளையும் செலுத்தும்படி நியமிக்கப்படுகிறான்; ஒருவனும் இந்தக் கனமான ஊழியத்தைத் தானாய் எடுத்துக்கொள்ளாமல், ஆரோனைப்போலத் தேவனால் அழைக்கப்படவேண்டும்; கிறிஸ்துவும், 'நீர் மெல்கிசேதேக்கின் முறைமையின்படி என்றென்றைக்கும் ஆசாரியராயிருக்கிறீர்' என்று சொன்னவராலே நியமிக்கப்பட்டார். அவர் மாம்சத்திலிருந்த நாட்களில் பலத்த சத்தத்தோடும் கண்ணீரோடும் ஜெபம்பண்ணி, தாம் குமாரனாயிருந்தும் பட்ட பாடுகளினாலே கீழ்ப்படிதலைக் கற்றுக்கொண்டு, தமக்குக் கீழ்ப்படிகிற யாவருக்கும் நித்திய இரட்சிப்பைக் காரணரானார். நீங்கள் கேட்பதில் மந்தமுள்ளவர்களானதால், போதகராயிருக்கவேண்டிய நீங்கள் இன்னும் பாலுண்கிறவர்களாயிருக்கிறீர்கள்; பலமான ஆகாரமோ நன்மை தீமையின்னதென்று பகுத்தறியத்தக்கதாக அனுபவத்தினால் பழகின தேறினவர்களுக்கே ஏற்றது.",
    "Hebrews 6": "கிறிஸ்துவைப்பற்றிச் சொல்லிய மூல உபதேசங்களை நாம் விட்டு, பூரணராகும்படிக்குக் கடந்துபோவோமாக; ஒருதரம் பிரகாசிப்பிக்கப்பட்டும் மறுதலித்துப்போனவர்கள் தேவனுடைய குமாரனைத் தங்களுக்குத் தாங்களே மறுபடியும் சிலுவையில் அறைகிறவர்களாயிருக்கிறார்கள். ஆனாலும் உங்களைக்குறித்து நல்லவைகளை நம்பியிருக்கிறோம்; நீங்கள் பரிசுத்தவான்களுக்கு ஊழியஞ்செய்ததினாலும் செய்கிறதினாலும் அவருடைய நாமத்துக்காகக் காண்பித்த அன்பை மறந்துவிடுகிறதற்குத் தேவன் அநீதியுள்ளவரல்லவே; விசுவாசத்தினாலும் நீடிய பொறுமையினாலும் வாக்குத்தத்தங்களைச் சுதந்தரிக்கிறவர்களைப் பின்பற்றுங்கள். தேவன் ஆபிரகாமுக்குத் தம்முடைய பேரிலே ஆணையிட்டு வாக்குத்தத்தம் பண்ணினார்; மாறாத இந்த இரண்டு காரியங்களினாலே நமக்கு உறுதியான ஆறுதல் உண்டு; அந்த நம்பிக்கை நம்முடைய ஆத்துமாவுக்கு நிலையும் உறுதியுமான நங்கூரமாயிருக்கிறது; இயேசு நமக்காக முன்னோடினவராய்த் திரைக்குள்ளாகப் பிரவேசித்தார்.",
    "Hebrews 7": "சாலேமின் ராஜாவும் உன்னதமான தேவனுடைய ஆசாரியனுமாகிய மெல்கிசேதேக்கு ஆபிரகாமை ஆசீர்வதித்தான்; ஆபிரகாம் அவனுக்கு எல்லாவற்றிலும் தசமபாகம் கொடுத்தான்; அவன் தகப்பனும் தாயும் வம்சவரலாறும் இல்லாதவனாய், தேவனுடைய குமாரனுக்கு ஒப்பானவனாயிருக்கிறான். லேவி கோத்திர ஆசாரிய முறைமையினால் பூரணப்படுதல் உண்டாயிருந்தால், வேறொரு ஆசாரியர் எழும்பவேண்டியதில்லை; நம்முடைய கர்த்தர் யூதா கோத்திரத்தில் தோன்றினார்; அவர் அழியாத ஜீவனுடைய வல்லமையின்படியே ஆசாரியரானதால், அதிக விசேஷித்த உடன்படிக்கைக்குப் பிணையாளியானார். தம்மைக்கொண்டு தேவனிடத்தில் சேருகிறவர்களுக்காக வேண்டுதல் செய்யும்படிக்கு அவர் எப்பொழுதும் உயிரோடிருக்கிறவரானபடியால், அவர்களை முற்றுமுடிய இரட்சிக்க வல்லவராயுமிருக்கிறார்; அவர் பரிசுத்தரும் குற்றமற்றவருமாயிருந்து, தம்மைத்தாமே பலியிட்டதினாலே இதை ஒரேதரம் செய்துமுடித்தார்.",
    "Hebrews 8": "பரலோகத்தில் மகத்துவமுள்ளவருடைய சிங்காசனத்தின் வலதுபாரிசத்தில் உட்கார்ந்திருக்கிற பிரதான ஆசாரியர் நமக்கு உண்டு; அவர் மனுஷனால் அல்ல, கர்த்தரால் ஸ்தாபிக்கப்பட்ட மெய்யான கூடாரத்துக்கு ஊழியக்காரராயிருக்கிறார். பூமியிலுள்ள ஆசாரியர் பரலோகத்திலுள்ளவைகளின் சாயலுக்கும் நிழலுக்கும் ஆராதனை செய்கிறார்கள்; அவரோ விசேஷித்த வாக்குத்தத்தங்களின்பேரில் ஸ்தாபிக்கப்பட்ட மேன்மையான உடன்படிக்கைக்கு மத்தியஸ்தராயிருக்கிறார். 'என் பிரமாணங்களை அவர்கள் மனதிலே வைத்து, அவர்கள் இருதயங்களில் அவைகளை எழுதுவேன்; நான் அவர்களுக்குத் தேவனாயிருப்பேன், அவர்கள் எனக்கு ஜனங்களாயிருப்பார்கள்; அவர்களுடைய பாவங்களை இனி நினையாதிருப்பேன்' என்று புதிய உடன்படிக்கை வாக்களிக்கப்பட்டது; பழமையானதோ முதிர்ந்துபோய் ஒழிந்துபோகிறது.",
    "Hebrews 9": "முந்தின உடன்படிக்கையின் கூடாரத்தில் பரிசுத்த ஸ்தலமும் மகா பரிசுத்த ஸ்தலமும் இருந்தன; பிரதான ஆசாரியன் மாத்திரம் வருஷத்துக்கு ஒருதரம் இரத்தத்தோடே மகா பரிசுத்த ஸ்தலத்தில் பிரவேசித்தான்; அந்தப் பலிகள் ஆராதனை செய்கிறவனுடைய மனச்சாட்சியைப் பூரணப்படுத்தமாட்டாதவைகள். கிறிஸ்துவோ வரப்போகிற நன்மைகளுக்குரிய பிரதான ஆசாரியராய், வெள்ளாட்டுக்கடாக்கள் கன்றுக்குட்டிகளுடைய இரத்தத்தினாலே அல்ல, தம்முடைய சொந்த இரத்தத்தினாலே ஒரேதரம் மகா பரிசுத்த ஸ்தலத்திலே பிரவேசித்து, நித்திய மீட்பை உண்டுபண்ணினார்; அவருடைய இரத்தம் ஜீவனுள்ள தேவனுக்கு ஊழியஞ்செய்யும்படி நம்முடைய மனச்சாட்சியைச் செத்த கிரியைகளறச் சுத்திகரிக்கும். 'இரத்தஞ்சிந்துதலில்லாமல் மன்னிப்பு உண்டாகாது'; ஒரேதரம் மரிப்பதும் பின்பு நியாயத்தீர்ப்படைவதும் மனுஷருக்கு நியமிக்கப்பட்டிருக்கிறபடியே, கிறிஸ்துவும் அநேகருடைய பாவங்களைச் சுமந்து தீர்க்கும்படிக்கு ஒரேதரம் பலியிடப்பட்டு, தமக்காகக் காத்துக்கொண்டிருக்கிறவர்களுக்கு இரட்சிப்பை அருளும்படி இரண்டாந்தரம் பாவமில்லாமல் தரிசனமாவார்.",
    "Hebrews 10": "நியாயப்பிரமாணம் வரப்போகிற நன்மைகளின் நிழலாயிருப்பதால், வருஷந்தோறும் செலுத்தப்படும் பலிகளினால் ஆராதிக்க வருகிறவர்களைப் பூரணப்படுத்தமாட்டாது; காளை வெள்ளாட்டுக்கடா இவைகளுடைய இரத்தம் பாவங்களை நிவிர்த்திசெய்யமாட்டாதே. 'தேவனே, உம்முடைய சித்தத்தின்படி செய்ய இதோ, வருகிறேன்' என்று வந்த இயேசுகிறிஸ்து தம்முடைய சரீரத்தை ஒரேதரம் பலியிட்டதினாலே நாம் பரிசுத்தமாக்கப்பட்டிருக்கிறோம்; பரிசுத்தமாக்கப்படுகிறவர்களை ஒரே பலியினாலே என்றென்றைக்கும் பூரணப்படுத்தியிருக்கிறார். ஆகையால் அவர் பிரதிஷ்டைபண்ணின புதிதும் ஜீவனுமான மார்க்கத்தின் வழியாய்த் தைரியமாய்ப் பரிசுத்த ஸ்தலத்தில் பிரவேசித்து, சபைகூடிவருதலைச் சிலர் விட்டுவிடுகிறதுபோல நாம் விட்டுவிடாமல், ஒருவருக்கொருவர் புத்திசொல்லுவோமாக; மனப்பூர்வமாய்ப் பாவஞ்செய்கிறவர்களுக்கு இனி வேறொரு பலி இல்லை என்று எச்சரித்து, 'நீங்கள் தேவனுடைய சித்தத்தின்படி செய்து, வாக்குத்தத்தம் பண்ணப்பட்டதைப் பெறும்படிக்குப் பொறுமை உங்களுக்கு வேண்டியதாயிருக்கிறது; விசுவாசத்தினாலே நீதிமான் பிழைப்பான்' என்கிறான்.",
    "Hebrews 11": "'விசுவாசமானது நம்பப்படுகிறவைகளின் உறுதியும், காணப்படாதவைகளின் நிச்சயமுமாயிருக்கிறது'; 'விசுவாசமில்லாமல் தேவனுக்குப் பிரியமாயிருப்பது கூடாதகாரியம்'. விசுவாசத்தினாலே ஆபேல், ஏனோக்கு, நோவா, ஆபிரகாம், சாராள், ஈசாக்கு, யாக்கோபு, யோசேப்பு, மோசே, ராகாப் ஆகியோர் நற்சாட்சி பெற்றார்கள்; தேவன் கட்டி உண்டாக்கின அஸ்திபாரங்களுள்ள நகரத்துக்கு ஆபிரகாம் காத்திருந்தான், சோதிக்கப்பட்டபோது ஈசாக்கைப் பலியாக ஒப்புக்கொடுத்தான். கிதியோன், பாராக், சிம்சோன், யெப்தா, தாவீது, சாமுவேல், தீர்க்கதரிசிகள் விசுவாசத்தினாலே ராஜ்யங்களை ஜெயித்தார்கள்; மற்றவர்கள் நிந்தைகளையும் வாதைகளையும் மரணத்தையும் சகித்தார்கள், உலகம் அவர்களுக்குப் பாத்திரமாயிருக்கவில்லை; நாமில்லாமல் அவர்கள் பூரணராகாதபடிக்கு, தேவன் விசேஷித்த நன்மையானதொன்றை நமக்கென்று முன்னதாக நியமித்திருந்தார்.",
    "Hebrews 12": "மேகம்போன்ற இத்தனை திரளான சாட்சிகள் நம்மைச் சூழ்ந்துகொண்டிருக்க, 'பாரமான யாவற்றையும், நம்மைச் சுற்றிநெருக்குகிற பாவத்தையும் தள்ளிவிட்டு, விசுவாசத்தைத் துவக்குகிறவரும் முடிக்கிறவருமாயிருக்கிற இயேசுவை நோக்கி, நமக்கு நியமித்திருக்கிற ஓட்டத்தில் பொறுமையோடே ஓடக்கடவோம்'; அவர் தமக்குமுன் வைத்திருந்த சந்தோஷத்தினிமித்தம் அவமானத்தை எண்ணாமல் சிலுவையைச் சகித்தார். 'கர்த்தர் எவனிடத்தில் அன்புகூருகிறாரோ அவனைச் சிட்சிக்கிறார்'; சிட்சை அப்பொழுது துக்கமாய்க் காணப்பட்டாலும், பின்பு அதில் பழகினவர்களுக்கு நீதியாகிய சமாதான பலனைத் தரும்; தளர்ந்த கைகளைத் திடப்படுத்துங்கள்; பரிசுத்தமில்லாமல் ஒருவனும் கர்த்தரைத் தரிசிப்பதில்லை; ஏசாவைப்போல் சேஷ்டபுத்திரபாகத்தை விற்றுப்போடாதிருங்கள். நீங்கள் சீனாய் மலைக்கல்ல, சீயோன் மலைக்கும், ஜீவனுள்ள தேவனுடைய நகரமாகிய பரம எருசலேமுக்கும், புது உடன்படிக்கையின் மத்தியஸ்தராகிய இயேசுவினிடத்துக்கும் வந்து சேர்ந்தீர்கள்; ஆகையால் அசைவில்லாத ராஜ்யத்தைப் பெறுகிறவர்களாய், பயத்தோடும் பக்தியோடும் தேவனுக்குப் பிரியமாய் ஆராதனை செய்யக்கடவோம்; 'நம்முடைய தேவன் பட்சிக்கிற அக்கினியாயிருக்கிறாரே'.",
    "Hebrews 13": "சகோதர சிநேகம் நிலைத்திருக்கக்கடவது; அந்நியரை உபசரிக்க மறவாதிருங்கள், அதினாலே சிலர் அறியாமல் தேவதூதரையும் உபசரித்ததுண்டு; கட்டப்பட்டவர்களை நினைத்துக்கொள்ளுங்கள்; விவாகம் எல்லாருக்குள்ளும் கனமுள்ளதாயிருப்பதாக; 'நீங்கள் பண ஆசையில்லாதவர்களாய் நடந்து, உங்களுக்கு இருக்கிறவைகள் போதுமென்று எண்ணுங்கள்; நான் உன்னைவிட்டு விலகுவதுமில்லை, உன்னைக் கைவிடுவதுமில்லை என்று அவர் சொல்லியிருக்கிறாரே'. 'இயேசுகிறிஸ்து நேற்றும் இன்றும் என்றும் மாறாதவராயிருக்கிறார்'; அவர் நகரவாசலுக்குப் புறம்பே பாடுபட்டதால், நாமும் அவருடைய நிந்தையைச் சுமந்துகொண்டு பாளயத்துக்குப் புறம்பே அவரிடத்திற்குப் புறப்பட்டுப் போவோம்; தேவனுக்குத் துதிபலியையும், நன்மைசெய்வதையும், தானதர்மம் பண்ணுவதையும் செலுத்துவோம்; உங்களை நடத்துகிறவர்களுக்குக் கீழ்ப்படியுங்கள். 'நித்திய உடன்படிக்கையின் இரத்தத்தினாலே ஆடுகளின் பெரிய மேய்ப்பராகிய நம்முடைய கர்த்தராகிய இயேசுவை மரித்தோரிலிருந்து எழுப்பின சமாதானத்தின் தேவன், தமது சித்தத்தின்படி செய்கிறதற்கு உங்களை எல்லா நற்கிரியையிலும் சீர்பொருந்தினவர்களாக்குவாராக' என்று ஆசீர்வதித்து, தீமோத்தேயு விடுதலையானதை அறிவித்து, வாழ்த்துதல்களோடு நிருபத்தை முடிக்கிறான்.",
};

